import type { LearningEntityId } from "../../content";
import type { LearningProgressContext } from "../domain/types";
import { createLearningProgressPersistenceV2, migrateLearningProgressDocument } from "./schema";
import type {
  LearningProgressPersistenceV2,
  LearningProgressRestoreFailureReason,
  LearningProgressRestoreResult,
  RestoreLearningProgressOptions,
  SerializeLearningProgressOptions,
} from "./types";

function assertNonEmpty(value: string, label: string): string {
  const normalized = value.trim();
  if (normalized.length === 0) throw new TypeError(`${label} must be a non-empty string.`);
  return normalized;
}

function knownNodeIds(context: LearningProgressContext): ReadonlySet<LearningEntityId> {
  return new Set([
    ...Object.keys(context.subjectStatusById),
    ...Object.keys(context.conceptStatusById),
  ]);
}

function hasSameKeys(left: Readonly<Record<string, unknown>>, right: Readonly<Record<string, unknown>>): boolean {
  const leftKeys = Object.keys(left).sort();
  const rightKeys = Object.keys(right).sort();
  return leftKeys.length === rightKeys.length
    && leftKeys.every((key, index) => key === rightKeys[index]);
}

function documentMatchesPath(
  document: LearningProgressPersistenceV2,
  fallback: LearningProgressContext,
): boolean {
  if (!hasSameKeys(document.subjectStatusById, fallback.subjectStatusById)
    || !hasSameKeys(document.conceptStatusById, fallback.conceptStatusById)) return false;
  const known = knownNodeIds(fallback);
  return known.has(document.lastSafeNodeId)
    && document.visitedNodeIds.includes(document.lastSafeNodeId)
    && document.visitedNodeIds.every((nodeId) => known.has(nodeId));
}

function freezeStatusRecord<T extends string>(record: Readonly<Record<string, T>>): Readonly<Record<string, T>> {
  return Object.freeze({ ...record });
}

function freezeVisitedRecord(nodeIds: readonly LearningEntityId[]): Readonly<Record<LearningEntityId, true>> {
  return Object.freeze(Object.fromEntries(nodeIds.map((nodeId) => [nodeId, true] as const)));
}

/**
 * Removes every transient workflow field. This is used both for successful
 * restores and safe fallback, so a moving/recovering snapshot can never resume
 * an old command, card, intent, queue, or transaction after reload.
 */
function createIdleContext(
  fallback: LearningProgressContext,
  safeNodeId: LearningEntityId,
  persisted?: LearningProgressPersistenceV2,
): LearningProgressContext {
  const known = knownNodeIds(fallback);
  const resolvedSafeNodeId = known.has(safeNodeId) ? safeNodeId : fallback.currentNodeId;
  const visited = persisted?.visitedNodeIds ?? Object.keys(fallback.visitedNodeIds);
  const visitedWithSafeNode = visited.includes(resolvedSafeNodeId)
    ? visited
    : [...visited, resolvedSafeNodeId];
  return Object.freeze({
    ...fallback,
    currentNodeId: resolvedSafeNodeId,
    subjectStatusById: freezeStatusRecord(persisted?.subjectStatusById ?? fallback.subjectStatusById),
    conceptStatusById: freezeStatusRecord(persisted?.conceptStatusById ?? fallback.conceptStatusById),
    visitedNodeIds: freezeVisitedRecord(visitedWithSafeNode),
    celebrationSeen: persisted?.celebrationSeen ?? fallback.celebrationSeen,
    celebrationCount: persisted?.celebrationCount ?? fallback.celebrationCount,
    lastNavigationDecision: null,
    lastCatchUpResult: null,
    lastConceptAction: null,
    pendingLearningIntent: null,
    lastLearningLaunch: null,
    learningLaunchRevision: 0,
    pendingUnlockCommit: null,
    lastMovementCancellation: null,
    lastRejection: null,
  });
}

function fallbackResult(
  options: RestoreLearningProgressOptions,
  reason: LearningProgressRestoreFailureReason,
): LearningProgressRestoreResult {
  const safeNodeId = options.fallbackSafeNodeId ?? options.fallbackContext.currentNodeId;
  return Object.freeze({
    status: "fallback",
    context: createIdleContext(options.fallbackContext, safeNodeId),
    reason,
  });
}

/** Creates deterministic JSON containing only durable domain facts. */
export function serializeLearningProgress(
  context: LearningProgressContext,
  options: SerializeLearningProgressOptions,
): string {
  const pathRevision = assertNonEmpty(options.pathRevision, "pathRevision");
  const lastSafeNodeId = assertNonEmpty(options.lastSafeNodeId, "lastSafeNodeId");
  const known = knownNodeIds(context);
  if (!known.has(lastSafeNodeId)) throw new TypeError("lastSafeNodeId is not part of the learning path.");
  if (context.visitedNodeIds[lastSafeNodeId] !== true) {
    throw new TypeError("lastSafeNodeId must be present in visitedNodeIds.");
  }
  const document = createLearningProgressPersistenceV2({
    pathRevision,
    lastSafeNodeId,
    subjectStatusById: context.subjectStatusById,
    conceptStatusById: context.conceptStatusById,
    visitedNodeIds: Object.keys(context.visitedNodeIds).sort((left, right) => left.localeCompare(right)),
    celebrationSeen: context.celebrationSeen,
    celebrationCount: context.celebrationCount,
  });
  return JSON.stringify(document);
}

/**
 * Restores a durable projection into a newly-created context. Any invalid,
 * unknown, or stale payload returns a clean idle fallback instead of throwing.
 */
export function restoreLearningProgress(
  serialized: string | unknown,
  options: RestoreLearningProgressOptions,
): LearningProgressRestoreResult {
  assertNonEmpty(options.pathRevision, "pathRevision");
  let decoded: unknown = serialized;
  if (typeof serialized === "string") {
    if (serialized.trim().length === 0) return fallbackResult(options, "empty");
    try {
      decoded = JSON.parse(serialized) as unknown;
    } catch {
      return fallbackResult(options, "corrupt-json");
    }
  }
  const migration = migrateLearningProgressDocument(decoded);
  if (!migration.ok) return fallbackResult(options, migration.reason);
  if (migration.document.pathRevision !== options.pathRevision.trim()) {
    return fallbackResult(options, "path-revision-mismatch");
  }
  if (!documentMatchesPath(migration.document, options.fallbackContext)) {
    return fallbackResult(options, "path-shape-mismatch");
  }
  return Object.freeze({
    status: "restored",
    context: createIdleContext(
      options.fallbackContext,
      migration.document.lastSafeNodeId,
      migration.document,
    ),
    document: migration.document,
    migratedFromVersion: migration.migratedFromVersion,
  });
}
