import {
  assign,
  fromPromise,
  setup,
  type SnapshotFrom,
} from "xstate";
import type {
  LearningResourceContext,
  LearningResourceEvent,
  LearningResourceLaunchRequest,
  LearningResourceLaunchResult,
  LearningResourceMachineInput,
  LearningResourceNavigationResult,
  LearningResourceNavigatorPort,
} from "./contracts";

function requireSessionRevision(value: number): number {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError("sessionRevision must be a non-negative safe integer.");
  }
  return value;
}

function isSerializableBinding(
  binding: LearningResourceLaunchRequest["binding"],
): boolean {
  return typeof binding.nodeId === "string"
    && binding.nodeId.length > 0
    && typeof binding.actionId === "string"
    && binding.actionId.length > 0
    && typeof binding.resourceId === "string"
    && binding.resourceId.length > 0
    && typeof binding.href === "string"
    && binding.href.length > 0
    && (binding.target === "self" || binding.target === "blank");
}

function isLaunchRequestEvent(
  event: LearningResourceEvent,
): event is Extract<LearningResourceEvent, { readonly type: "RESOURCE.LAUNCH.REQUESTED" }> {
  return event.type === "RESOURCE.LAUNCH.REQUESTED";
}

function requestFromEvent(
  event: Extract<LearningResourceEvent, { readonly type: "RESOURCE.LAUNCH.REQUESTED" }>,
): LearningResourceLaunchRequest {
  return Object.freeze({
    binding: Object.freeze({ ...event.binding }),
    intent: event.intent,
    launchId: event.launchId,
    sessionRevision: event.sessionRevision,
  });
}

function isCurrentLaunchResult(
  context: LearningResourceContext,
  result: LearningResourceLaunchResult | undefined,
): result is LearningResourceLaunchResult {
  const active = context.activeLaunch;
  return result !== undefined
    && active !== null
    && result.launchId === active.launchId
    && result.sessionRevision === active.sessionRevision
    && result.sessionRevision === context.sessionRevision;
}

function launchResultFromEvent(event: unknown): LearningResourceLaunchResult | undefined {
  if (typeof event !== "object" || event === null || !("output" in event)) return undefined;
  return (event as { readonly output?: LearningResourceLaunchResult }).output;
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return typeof error === "string" ? error : "Learning resource navigation failed.";
}

function normalizeNavigationResult(
  output: LearningResourceNavigationResult,
): LearningResourceNavigationResult {
  if (output.status === "accepted"
    || output.status === "popup-blocked"
    || output.status === "invalid-url"
    || output.status === "failed") {
    return Object.freeze({ ...output });
  }
  return Object.freeze({
    status: "failed",
    message: "Navigator returned an unsupported result.",
  });
}

/**
 * Owns one session's resource-launch protocol. All host effects are delegated
 * to the injected navigator actor and are cooperatively cancellable.
 */
export function createLearningResourceMachine(navigator: LearningResourceNavigatorPort) {
  const navigateResource = fromPromise<LearningResourceLaunchResult, LearningResourceLaunchRequest>(
    async ({ input, signal }) => {
      try {
        const result = normalizeNavigationResult(
          await navigator.navigate(input, { signal }),
        );
        return Object.freeze({ ...input, ...result });
      } catch (error: unknown) {
        if (signal.aborted) throw error;
        return Object.freeze({
          ...input,
          status: "failed" as const,
          message: errorMessage(error),
        });
      }
    },
  );

  return setup({
    types: {} as {
      context: LearningResourceContext;
      events: LearningResourceEvent;
      input: LearningResourceMachineInput;
    },
    actors: { navigateResource },
    guards: {
      acceptsLaunch: ({ context, event }) => (
        isLaunchRequestEvent(event)
        && event.sessionRevision === context.sessionRevision
        && typeof event.launchId === "string"
        && event.launchId.length > 0
        && (event.intent === "start"
          || event.intent === "continue"
          || event.intent === "review")
        && !context.seenLaunchIds.includes(event.launchId)
        && isSerializableBinding(event.binding)
      ),
      acceptsRevision: ({ context, event }) => (
        event.type === "SESSION.REVISION.CHANGED"
        && Number.isSafeInteger(event.sessionRevision)
        && event.sessionRevision >= 0
        && event.sessionRevision > context.sessionRevision
      ),
      currentLaunchAccepted: ({ context, event }) => {
        const output = launchResultFromEvent(event);
        return isCurrentLaunchResult(context, output) && output.status === "accepted";
      },
      currentLaunchFailed: ({ context, event }) => {
        const output = launchResultFromEvent(event);
        return isCurrentLaunchResult(context, output) && output.status !== "accepted";
      },
    },
    actions: {
      beginLaunch: assign(({ context, event }) => {
        if (!isLaunchRequestEvent(event)) return {};
        const request = requestFromEvent(event);
        return {
          activeLaunch: request,
          seenLaunchIds: Object.freeze([...context.seenLaunchIds, event.launchId]),
        };
      }),
      acceptResult: assign(({ event }) => ({
        activeLaunch: null,
        lastResult: launchResultFromEvent(event) ?? null,
      })),
      advanceRevision: assign(({ event }) => {
        if (event.type !== "SESSION.REVISION.CHANGED") return {};
        return {
          sessionRevision: event.sessionRevision,
          activeLaunch: null,
          seenLaunchIds: Object.freeze([]),
          lastResult: null,
        };
      }),
    },
  }).createMachine({
    id: "learningResource",
    initial: "idle",
    context: ({ input }) => ({
      sessionRevision: requireSessionRevision(input.sessionRevision),
      activeLaunch: null,
      seenLaunchIds: Object.freeze([]),
      lastResult: null,
    }),
    on: {
      "SESSION.REVISION.CHANGED": {
        guard: "acceptsRevision",
        actions: "advanceRevision",
        target: ".idle",
      },
    },
    states: {
      idle: {
        on: {
          "RESOURCE.LAUNCH.REQUESTED": {
            guard: "acceptsLaunch",
            actions: "beginLaunch",
            target: "launching",
          },
        },
      },
      launching: {
        invoke: {
          id: "resourceNavigation",
          src: "navigateResource",
          input: ({ context }) => {
            if (!context.activeLaunch) {
              throw new Error("Resource navigation entered without an active launch.");
            }
            return context.activeLaunch;
          },
          onDone: [
            {
              guard: "currentLaunchAccepted",
              actions: "acceptResult",
              target: "accepted",
            },
            {
              guard: "currentLaunchFailed",
              actions: "acceptResult",
              target: "failed",
            },
          ],
        },
        on: {
          "RESOURCE.LAUNCH.REQUESTED": {
            guard: "acceptsLaunch",
            actions: "beginLaunch",
            target: "launching",
            reenter: true,
          },
        },
      },
      accepted: {
        on: {
          "RESOURCE.LAUNCH.REQUESTED": {
            guard: "acceptsLaunch",
            actions: "beginLaunch",
            target: "launching",
          },
        },
      },
      failed: {
        on: {
          "RESOURCE.LAUNCH.REQUESTED": {
            guard: "acceptsLaunch",
            actions: "beginLaunch",
            target: "launching",
          },
        },
      },
    },
  });
}

export type LearningResourceMachine = ReturnType<typeof createLearningResourceMachine>;
export type LearningResourceMachineSnapshot = SnapshotFrom<LearningResourceMachine>;
