import {
  createDynamicOverpassCatalog,
  type DynamicOverpassCatalogDiagnostics,
} from "./DynamicOverpassCatalog";
import type {
  EdgeId,
  LearningPathEdge,
  LearningPathGraph,
  LearningPathNode,
  NodeId,
  OverpassLearningPathEdge,
  StraightLearningPathEdge,
} from "./pathData";
import {
  validateLearningPathRuleConfig,
  type AuthoredLogicalPathEdge,
  type DynamicBridgeRuleSpec,
  type LearningPathRuleConfig,
  type SpecialPathZoneSpec,
} from "./pathRules";

export interface RuntimePathBundleInput {
  readonly nodes: readonly LearningPathNode[];
  readonly authoredStraightEdges: readonly StraightLearningPathEdge[];
  readonly sessionEntryStraightEdges: readonly StraightLearningPathEdge[];
  readonly specialZones: readonly SpecialPathZoneSpec[];
  readonly dynamicBridgeRule: DynamicBridgeRuleSpec;
  readonly initialNodeId: NodeId;
  readonly entryNodeId: NodeId;
  readonly goalNodeId: NodeId;
}

/** Structurally compatible with the legacy runtime diagnostics export. */
export interface DynamicOverpassRuntimeDiagnostics {
  readonly catalog: DynamicOverpassCatalogDiagnostics;
  /** Immutable authored-logical roads used by minimum-hop queries. */
  readonly authoredStraightEdgeCount: number;
  /** Physical straight meshes, including hidden session entry roads. */
  readonly runtimeStraightEdgeCount: number;
  readonly staticGeometryEdgeCount: number;
  readonly configuredSpecialBridgeIds: readonly EdgeId[];
  readonly configuredSpecialStraightEdgeIds: readonly EdgeId[];
  readonly configuredSpecialConnectorCount: number;
  readonly underpassAuditMode: "disabled";
  readonly physicalBridgeIdentity: "one-per-undirected-pair";
}

export type RuntimePathBundleDiagnostics = DynamicOverpassRuntimeDiagnostics;

export interface RuntimePathBundle {
  readonly nodes: readonly LearningPathNode[];
  readonly authoredStraightEdges: readonly StraightLearningPathEdge[];
  readonly authoredLogicalEdges: readonly AuthoredLogicalPathEdge[];
  readonly runtimeStraightEdges: readonly StraightLearningPathEdge[];
  readonly overpassCatalog: readonly OverpassLearningPathEdge[];
  readonly edges: readonly LearningPathEdge[];
  readonly graph: LearningPathGraph;
  readonly diagnostics: RuntimePathBundleDiagnostics;
  /** O(1) lookup backed by an instance-local index. */
  readonly getNode: (nodeId: NodeId | null) => LearningPathNode | null;
  /** Compatibility alias for the existing runtime helper. */
  readonly getNodeById: (nodeId: NodeId | null) => LearningPathNode | null;
  /** O(1) lookup backed by an instance-local index. */
  readonly getNodeIndex: (nodeId: NodeId) => number;
  /** O(1), undirected lookup backed by an instance-local pair index. */
  readonly getOverpassBetween: (
    firstNodeId: NodeId,
    secondNodeId: NodeId,
  ) => OverpassLearningPathEdge | null;
  /** Compatibility alias for the existing runtime helper. */
  readonly getOverpassEdgeBetween: (
    firstNodeId: NodeId,
    secondNodeId: NodeId,
  ) => OverpassLearningPathEdge | null;
}

interface ConfiguredSpecialConnectors {
  readonly bridgeIds: readonly EdgeId[];
  readonly straightEdgeIds: readonly EdgeId[];
  readonly connectorCount: number;
}

/**
 * Compiles one validated learning-path document into an immutable runtime
 * bundle. Every index lives in the returned bundle's closure: repeated calls
 * never share mutable state, even when they receive the same source objects.
 */
export function createRuntimePathBundle(
  input: RuntimePathBundleInput,
): RuntimePathBundle {
  const nodes = Object.freeze(input.nodes.map(freezeNode));
  const authoredStraightEdges = Object.freeze(
    input.authoredStraightEdges.map(freezeStraightEdge),
  );
  const sessionEntryStraightEdges = Object.freeze(
    input.sessionEntryStraightEdges.map(freezeStraightEdge),
  );
  const runtimeStraightEdges = Object.freeze([
    ...authoredStraightEdges,
    ...sessionEntryStraightEdges,
  ]);
  const authoredLogicalEdges = Object.freeze(
    authoredStraightEdges.map((edge): AuthoredLogicalPathEdge => Object.freeze({
      id: edge.id,
      fromNodeId: edge.fromNodeId,
      toNodeId: edge.toNodeId,
      connectionKind: "straight",
    })),
  );
  const rules: LearningPathRuleConfig = Object.freeze({
    dynamicBridge: input.dynamicBridgeRule,
    specialPathZones: input.specialZones,
  });

  validateLearningPathRuleConfig({
    nodes,
    straightEdges: runtimeStraightEdges,
    rules,
    authoredLogicalEdges,
    initialNodeId: input.initialNodeId,
  });

  const nodeIndexById = new Map<NodeId, number>();
  nodes.forEach((node, index) => nodeIndexById.set(node.id, index));
  assertGraphNodeId(nodeIndexById, input.initialNodeId, "initialNodeId");
  assertGraphNodeId(nodeIndexById, input.entryNodeId, "entryNodeId");
  assertGraphNodeId(nodeIndexById, input.goalNodeId, "goalNodeId");

  const catalogResult = createDynamicOverpassCatalog(
    nodes,
    runtimeStraightEdges,
  );

  const getNodeIndex = (nodeId: NodeId): number => (
    nodeIndexById.get(nodeId) ?? -1
  );
  const getNode = (nodeId: NodeId | null): LearningPathNode | null => {
    if (nodeId === null) return null;
    const index = getNodeIndex(nodeId);
    return index >= 0 ? nodes[index] ?? null : null;
  };
  const getOverpassBetween = (
    firstNodeId: NodeId,
    secondNodeId: NodeId,
  ): OverpassLearningPathEdge | null => {
    if (firstNodeId === secondNodeId) return null;
    return catalogResult.getOverpassBetween(firstNodeId, secondNodeId);
  };

  const configuredSpecialConnectors = validateConfiguredSpecialConnectors({
    specialZones: input.specialZones,
    sessionEntryStraightEdges,
    runtimeStraightEdges,
    getOverpassBetween,
  });
  const getEdges = (): readonly LearningPathEdge[] => Object.freeze([
    ...runtimeStraightEdges,
    ...catalogResult.getMaterializedEdges(),
  ]);
  const diagnostics = {
    catalog: catalogResult.diagnostics,
    authoredStraightEdgeCount: authoredStraightEdges.length,
    runtimeStraightEdgeCount: runtimeStraightEdges.length,
    configuredSpecialBridgeIds: configuredSpecialConnectors.bridgeIds,
    configuredSpecialStraightEdgeIds: configuredSpecialConnectors.straightEdgeIds,
    configuredSpecialConnectorCount: configuredSpecialConnectors.connectorCount,
    underpassAuditMode: "disabled",
    physicalBridgeIdentity: "one-per-undirected-pair",
  } as RuntimePathBundleDiagnostics;
  Object.defineProperty(diagnostics, "staticGeometryEdgeCount", {
    enumerable: true,
    get: () => getEdges().length,
  });
  Object.freeze(diagnostics);
  const graph = {
    nodes,
    initialNodeId: input.initialNodeId,
    entryNodeId: input.entryNodeId,
    goalNodeId: input.goalNodeId,
  } as LearningPathGraph;
  Object.defineProperty(graph, "edges", {
    enumerable: true,
    get: getEdges,
  });
  Object.freeze(graph);

  const bundle = {
    nodes,
    authoredStraightEdges,
    authoredLogicalEdges,
    runtimeStraightEdges,
    diagnostics,
    graph,
    getNode,
    getNodeById: getNode,
    getNodeIndex,
    getOverpassBetween,
    getOverpassEdgeBetween: getOverpassBetween,
  } as RuntimePathBundle;
  Object.defineProperties(bundle, {
    overpassCatalog: {
      enumerable: true,
      get: catalogResult.getMaterializedEdges,
    },
    edges: {
      enumerable: true,
      get: getEdges,
    },
  });
  return Object.freeze(bundle);
}

function freezeNode(node: LearningPathNode): LearningPathNode {
  return Object.freeze({
    ...node,
    position: Object.freeze({ ...node.position }),
  });
}

function freezeStraightEdge(
  edge: StraightLearningPathEdge,
): StraightLearningPathEdge {
  return Object.freeze({ ...edge });
}

function assertGraphNodeId(
  nodeIndexById: ReadonlyMap<NodeId, number>,
  nodeId: NodeId,
  fieldName: "initialNodeId" | "entryNodeId" | "goalNodeId",
): void {
  if (!nodeIndexById.has(nodeId)) {
    throw new Error(`Runtime path ${fieldName} references missing node "${nodeId}".`);
  }
}

function validateConfiguredSpecialConnectors(input: Readonly<{
  specialZones: readonly SpecialPathZoneSpec[];
  sessionEntryStraightEdges: readonly StraightLearningPathEdge[];
  runtimeStraightEdges: readonly StraightLearningPathEdge[];
  getOverpassBetween: RuntimePathBundle["getOverpassBetween"];
}>): ConfiguredSpecialConnectors {
  const bridgeIds = new Set<EdgeId>();
  const straightEdgeIds = new Set<EdgeId>();
  const straightEdgeById = new Map(
    input.runtimeStraightEdges.map((edge) => [edge.id, edge] as const),
  );
  let connectorCount = 0;

  for (const zone of input.specialZones) {
    const entryTemplateCount = zone.revealSequence.filter(
      (step) => step.kind === "session-entry-connector",
    ).length;
    if (entryTemplateCount !== 1) {
      throw new Error(
        `Special zone "${zone.id}" must declare exactly one session entry connector template.`,
      );
    }
    for (const connection of zone.entryConnections) {
      connectorCount += 1;
      if (connection.kind === "straight-edge") {
        const straight = straightEdgeById.get(connection.edgeId);
        if (!straight) {
          throw new Error(
            `Special zone "${zone.id}" is missing runtime entry straight "${connection.edgeId}".`,
          );
        }
        const endpointsMatch = (
          straight.fromNodeId === connection.activationNodeId
          && straight.toNodeId === zone.entryNodeId
        ) || (
          straight.fromNodeId === zone.entryNodeId
          && straight.toNodeId === connection.activationNodeId
        );
        if (
          !endpointsMatch
          || input.getOverpassBetween(
            connection.activationNodeId,
            zone.entryNodeId,
          ) !== null
        ) {
          throw new Error(
            `Special zone "${zone.id}" runtime straight ${connection.activationNodeId} <-> ${zone.entryNodeId} is mismatched or still has bridge geometry.`,
          );
        }
        straightEdgeIds.add(straight.id);
        continue;
      }

      const bridge = input.getOverpassBetween(
        connection.activationNodeId,
        zone.entryNodeId,
      );
      if (bridge === null) {
        throw new Error(
          `Special zone "${zone.id}" requires session entry bridge ${connection.activationNodeId} <-> ${zone.entryNodeId}, but that pair is straight-connected or missing.`,
        );
      }
      bridgeIds.add(bridge.id);
    }
  }

  const expectedConnectorCount = input.specialZones.reduce(
    (count, zone) => count + zone.activationNodeIds.length,
    0,
  );
  const configuredSessionStraightIds = new Set(
    input.sessionEntryStraightEdges.map((edge) => edge.id),
  );
  if (connectorCount !== expectedConnectorCount) {
    throw new Error(
      `Expected ${expectedConnectorCount} configured special entry connectors, got ${connectorCount}.`,
    );
  }
  if (
    straightEdgeIds.size !== configuredSessionStraightIds.size
    || [...configuredSessionStraightIds].some((edgeId) => !straightEdgeIds.has(edgeId))
  ) {
    throw new Error(
      `Configured special entries must use all ${configuredSessionStraightIds.size} session straight roads exactly once.`,
    );
  }
  if (bridgeIds.size !== expectedConnectorCount - configuredSessionStraightIds.size) {
    throw new Error(
      `Expected ${expectedConnectorCount - configuredSessionStraightIds.size} overpass entries, got ${bridgeIds.size}.`,
    );
  }

  return Object.freeze({
    bridgeIds: Object.freeze([...bridgeIds].sort(compareStrings)),
    straightEdgeIds: Object.freeze([...straightEdgeIds].sort(compareStrings)),
    connectorCount,
  });
}

function compareStrings(first: string, second: string): number {
  return first < second ? -1 : first > second ? 1 : 0;
}
