/**
 * JSON-safe handle stored by page-generation actors instead of compiled
 * runtime objects. Runtime bundles contain Maps and executable lookup helpers,
 * so they must remain behind this private revision-scoped boundary.
 */
export interface CompiledPageRuntimeDataReference {
  readonly kind: "compiled-page-runtime-data";
  readonly revision: string;
  readonly token: string;
}

interface CompiledPageRuntimeDataEntry {
  readonly token: string;
  readonly value: unknown;
}

const entryByRevision = new Map<string, CompiledPageRuntimeDataEntry>();
let tokenSequence = 0;

function assertRevision(revision: string): void {
  if (revision.trim().length === 0) {
    throw new Error("Compiled page runtime data requires a non-empty revision.");
  }
}

export function registerCompiledPageRuntimeData(
  revision: string,
  value: unknown,
): CompiledPageRuntimeDataReference {
  assertRevision(revision);
  const token = `${revision}:runtime:${++tokenSequence}`;
  entryByRevision.set(revision, Object.freeze({ token, value }));
  return Object.freeze({
    kind: "compiled-page-runtime-data",
    revision,
    token,
  });
}

export function isCompiledPageRuntimeDataReference(
  value: unknown,
): value is CompiledPageRuntimeDataReference {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<CompiledPageRuntimeDataReference>;
  return candidate.kind === "compiled-page-runtime-data"
    && typeof candidate.revision === "string"
    && candidate.revision.trim().length > 0
    && typeof candidate.token === "string"
    && candidate.token.length > 0;
}

/**
 * Resolves only the current token for a revision. Registering a replacement
 * revision invalidates every older handle without allowing an old actor to
 * release the replacement.
 */
export function resolveCompiledPageRuntimeData<T>(
  reference: CompiledPageRuntimeDataReference,
): T | null {
  const entry = entryByRevision.get(reference.revision);
  return entry?.token === reference.token ? entry.value as T : null;
}

export function releaseCompiledPageRuntimeData(
  reference: CompiledPageRuntimeDataReference | null | undefined,
): boolean {
  if (!reference) return false;
  const entry = entryByRevision.get(reference.revision);
  if (entry?.token !== reference.token) return false;
  return entryByRevision.delete(reference.revision);
}

/** Test-only diagnostics; production code never branches on registry size. */
export function compiledPageRuntimeDataRegistrySizeForTesting(): number {
  return entryByRevision.size;
}

/** Test-only isolation for deterministic module-level registry assertions. */
export function resetCompiledPageRuntimeDataRegistryForTesting(): void {
  entryByRevision.clear();
  tokenSequence = 0;
}
