export const LEARNING_PATH_PROTOCOL = "learning-path" as const;
export const LEARNING_PATH_VERSION = "1.0" as const;

export type LearningPathProtocol = typeof LEARNING_PATH_PROTOCOL;
export type LearningPathVersion = typeof LEARNING_PATH_VERSION;
export type LearningEntityId = string;
export type LearningCardId = string;
export type LearningActionId = string;
export type LearningResourceId = string;
export type LearningFlowGroupId = string;

export interface LearningPathMetadata {
  readonly title: string;
  readonly description?: string;
  readonly locale: string;
}

/**
 * Subjects and concepts contain only graph/content references. Display copy and
 * executable actions live in `data`, keeping authored structure independent
 * from presentation data.
 */
export interface LearningSubjectDefinition {
  readonly id: LearningEntityId;
  readonly cardRef: LearningCardId;
  /** Stable tie-breaker only; graph depth is always derived from `flow`. */
  readonly orderHint?: number;
}

export interface LearningConceptDefinition {
  readonly id: LearningEntityId;
  readonly subjectId: LearningEntityId;
  readonly cardRef: LearningCardId;
  readonly actionRef: LearningActionId;
  readonly orderHint?: number;
}

export interface LearningFlowSemantics {
  /** Present when the edge leaves a subject with multiple successors. */
  readonly splitGroupId?: LearningFlowGroupId;
  /** Present when the edge enters a subject with multiple prerequisites. */
  readonly joinGroupId?: LearningFlowGroupId;
}

/** The single source of truth for subject-to-subject connectivity. */
export interface LearningFlowDefinition {
  readonly id: string;
  readonly fromSubjectId: LearningEntityId;
  readonly toSubjectId: LearningEntityId;
  readonly semantics?: LearningFlowSemantics;
}

export interface LearningSplitGroupDefinition {
  readonly id: LearningFlowGroupId;
  readonly type: "split";
  readonly anchorSubjectId: LearningEntityId;
  /** Branches can be studied at the same time. */
  readonly policy: "parallel";
}

export interface LearningJoinGroupDefinition {
  readonly id: LearningFlowGroupId;
  readonly type: "join";
  readonly anchorSubjectId: LearningEntityId;
  /** All incoming prerequisites must be completed before the anchor unlocks. */
  readonly policy: "all-required";
}

export type LearningFlowGroupDefinition =
  | LearningSplitGroupDefinition
  | LearningJoinGroupDefinition;

export interface LearningPathStructure {
  readonly entrySubjectId: LearningEntityId;
  readonly goalSubjectIds: readonly LearningEntityId[];
  readonly subjects: readonly LearningSubjectDefinition[];
  readonly concepts: readonly LearningConceptDefinition[];
  readonly flow: readonly LearningFlowDefinition[];
  readonly flowGroups: readonly LearningFlowGroupDefinition[];
}

export interface LearningDetailsCard {
  readonly id: LearningCardId;
  readonly eyebrow?: string;
  readonly title: string;
  readonly summary: string;
  readonly body?: string;
  readonly tags?: readonly string[];
  readonly imageUrl?: string;
}

/** Explicit allowlist entry. Actions can reference a resource but cannot inject a URL. */
export interface LearningResource {
  readonly id: LearningResourceId;
  readonly href: string;
}

export interface LearningOpenResourceAction {
  readonly id: LearningActionId;
  readonly kind: "open-resource";
  readonly label: string;
  readonly resourceId: LearningResourceId;
  readonly target?: "self" | "blank";
}

export type LearningAction = LearningOpenResourceAction;

export interface LearningPathData {
  readonly cards: readonly LearningDetailsCard[];
  readonly resources: readonly LearningResource[];
  readonly actions: readonly LearningAction[];
}

export interface LearningPathLayoutPreferences {
  readonly direction: "top-to-bottom";
  readonly subjectGap?: number;
  readonly layerGap?: number;
  readonly conceptGap?: number;
  readonly conceptColumnGap?: number;
}

export interface LearningPathPresentation {
  readonly layout: LearningPathLayoutPreferences;
}

export interface LearningPathDocument {
  readonly protocol: LearningPathProtocol;
  readonly version: LearningPathVersion;
  readonly id: string;
  readonly metadata: LearningPathMetadata;
  readonly structure: LearningPathStructure;
  readonly data: LearningPathData;
  readonly presentation: LearningPathPresentation;
}

export type LearningPathValidationIssueCode =
  | "type_mismatch"
  | "missing_field"
  | "unknown_field"
  | "invalid_value"
  | "limit_exceeded"
  | "duplicate_id"
  | "invalid_reference"
  | "invalid_url"
  | "cycle_detected"
  | "unreachable_subject"
  | "no_goal_path"
  | "invalid_flow_semantics"
  | "invalid_concept_ownership"
  | "unused_data";

export interface LearningPathValidationIssue {
  readonly code: LearningPathValidationIssueCode;
  readonly path: string;
  readonly message: string;
}

export type LearningPathValidationResult =
  | {
      readonly ok: true;
      readonly document: LearningPathDocument;
      readonly issues: readonly [];
    }
  | {
      readonly ok: false;
      readonly issues: readonly LearningPathValidationIssue[];
    };

export interface CompiledPathPosition {
  readonly x: number;
  readonly z: number;
}

/**
 * A runtime-facing node deliberately mirrors the current LearningPathNode
 * fields while retaining semantic identity and resolved card/action data.
 */
export interface CompiledLearningPathNode {
  readonly id: LearningEntityId;
  readonly entityId: LearningEntityId;
  readonly entityKind: "subject" | "concept";
  readonly navigationOrder: number;
  readonly label: string;
  readonly position: CompiledPathPosition;
  readonly layer: number;
  readonly initiallyGreen: boolean;
  readonly initiallyVisible: boolean;
  readonly completionPolicy: "promote-to-green" | "preserve-variant";
  readonly activationGroupId?: string;
  readonly surfaceY: number;
  readonly variant: "green" | "brown";
  readonly card: LearningDetailsCard;
  readonly action?: LearningAction & { readonly resource: LearningResource };
  readonly ownerSubjectId?: LearningEntityId;
}

export interface CompiledLearningPathEdge {
  readonly id: string;
  readonly fromNodeId: LearningEntityId;
  readonly toNodeId: LearningEntityId;
  readonly pathKind: "straight";
  readonly initiallyVisible: boolean;
  readonly completionPolicy: "promote-to-green" | "preserve-variant";
  readonly activationGroupId?: string;
  /**
   * `parallel-peer` is a physical, bidirectional walking road between adjacent
   * subjects in one parallel split. It never becomes a learning prerequisite.
   */
  readonly sourceKind: "subject-flow" | "parallel-peer" | "concept-chain";
  readonly flowSemantics?: LearningFlowSemantics;
}

export interface CompiledConceptZone {
  readonly id: string;
  readonly activationSubjectNodeId: LearningEntityId;
  readonly entryConnection: {
    readonly fromSubjectNodeId: LearningEntityId;
    readonly toConceptNodeId: LearningEntityId;
    /** Compiler-owned physical intent; runtime adapters must not infer it again. */
    readonly preferredPathKind: "straight" | "overpass";
  };
  readonly memberConceptNodeIds: readonly LearningEntityId[];
  readonly memberEdgeIds: readonly string[];
  readonly revealOrder: readonly (
    | { readonly kind: "edge"; readonly id: string }
    | { readonly kind: "node"; readonly id: LearningEntityId }
  )[];
}

export interface CompiledLearningPathLayer {
  readonly index: number;
  readonly subjectNodeIds: readonly LearningEntityId[];
  readonly conceptNodeIds: readonly LearningEntityId[];
}

export interface CompiledLearningPath {
  readonly protocol: LearningPathProtocol;
  readonly version: LearningPathVersion;
  readonly sourceDocumentId: string;
  readonly initialNodeId: LearningEntityId;
  readonly entryNodeId: LearningEntityId;
  readonly goalNodeIds: readonly LearningEntityId[];
  readonly nodes: readonly CompiledLearningPathNode[];
  readonly edges: readonly CompiledLearningPathEdge[];
  readonly conceptZones: readonly CompiledConceptZone[];
  readonly layers: readonly CompiledLearningPathLayer[];
  readonly nodeById: ReadonlyMap<LearningEntityId, CompiledLearningPathNode>;
  readonly edgeById: ReadonlyMap<string, CompiledLearningPathEdge>;
}
