import {
  LEARNING_PATH_HOST_CONFIG_KEY,
  LEARNING_PATH_HOST_PROTOCOL,
  LEARNING_PATH_HOST_VERSION,
  type LearningPathBootstrapOptions,
} from "./contracts";
import {
  assertExactJsonKeys,
  assertPlainJsonRecord,
  cloneLearningPathJsonData,
  readJsonDataProperty,
} from "./jsonData";

/** Parses the stable, data-only window contract into the programmatic API. */
export function parseLearningPathWindowHostConfig(input: unknown): LearningPathBootstrapOptions {
  const configPath = `$window.${LEARNING_PATH_HOST_CONFIG_KEY}`;
  assertPlainJsonRecord(input, configPath);
  assertExactJsonKeys(input, ["protocol", "version", "source"], configPath);
  if (readJsonDataProperty(input, "protocol", configPath) !== LEARNING_PATH_HOST_PROTOCOL) {
    throw new TypeError(`宿主协议必须是 ${LEARNING_PATH_HOST_PROTOCOL}。`);
  }
  if (readJsonDataProperty(input, "version", configPath) !== LEARNING_PATH_HOST_VERSION) {
    throw new TypeError(`宿主协议版本必须是 ${LEARNING_PATH_HOST_VERSION}。`);
  }
  const sourcePath = "$window.__LEARNING_PATH_PAGE_CONFIG__.source";
  const source = readJsonDataProperty(input, "source", configPath);
  assertPlainJsonRecord(source, sourcePath);
  const kind = readJsonDataProperty(source, "kind", sourcePath);

  if (kind === "document") {
    assertExactJsonKeys(source, ["kind", "document"], sourcePath);
    return {
      document: cloneLearningPathJsonData(readJsonDataProperty(source, "document", sourcePath)),
    };
  }
  if (kind === "url") {
    assertExactJsonKeys(source, ["kind", "documentUrl"], sourcePath);
    const documentUrl = readJsonDataProperty(source, "documentUrl", sourcePath);
    if (typeof documentUrl !== "string" || documentUrl.trim() === "") {
      throw new TypeError("宿主 documentUrl 必须是非空字符串。");
    }
    return { documentUrl };
  }
  throw new TypeError("宿主 source.kind 只能是 document 或 url。");
}

export function readLearningPathWindowHostConfig(
  target: Window,
): LearningPathBootstrapOptions | null {
  const descriptor = Object.getOwnPropertyDescriptor(target, LEARNING_PATH_HOST_CONFIG_KEY);
  if (!descriptor) return null;
  if (!("value" in descriptor)) {
    throw new TypeError(`${LEARNING_PATH_HOST_CONFIG_KEY} 不能使用 getter/setter。`);
  }
  return parseLearningPathWindowHostConfig(descriptor.value);
}
