import type { LearningEntityId } from "../../content";
import type { ProgressGraph } from "./graph";
import { sortNodeIds } from "./graph";
import type {
  ConceptProgressStatus,
  LearningIntentKind,
  LearningNodeProgressStatus,
  LearningProgressContext,
  LearningProgressEvent,
  NavigationDecision,
  PendingUnlockCommit,
  ProgressRejectionReason,
  SubjectProgressStatus,
} from "./types";

export type MutableProgressContext = {
  -readonly [Key in keyof LearningProgressContext]: LearningProgressContext[Key];
};

export function freezeRecord<T extends string>(value: Record<string, T>): Readonly<Record<string, T>> {
  return Object.freeze({ ...value });
}

export function freezeTrueRecord(value: Record<string, true>): Readonly<Record<string, true>> {
  return Object.freeze({ ...value });
}

export function createInitialProgressContext(graph: ProgressGraph): LearningProgressContext {
  const subjectStatusById: Record<string, SubjectProgressStatus> = {};
  const conceptStatusById: Record<string, ConceptProgressStatus> = {};
  for (const id of graph.subjectIds) subjectStatusById[id] = "locked";
  for (const id of graph.conceptIds) conceptStatusById[id] = "locked";

  subjectStatusById[graph.path.entryNodeId] = "completed";
  for (const conceptId of graph.conceptsBySubjectId.get(graph.path.entryNodeId) ?? []) {
    conceptStatusById[conceptId] = "completed";
  }
  unlockEligibleSubjects(graph, subjectStatusById);

  return Object.freeze({
    currentNodeId: graph.path.entryNodeId,
    goalNodeIds: Object.freeze([...graph.path.goalNodeIds]),
    subjectStatusById: freezeRecord(subjectStatusById),
    conceptStatusById: freezeRecord(conceptStatusById),
    visitedNodeIds: freezeTrueRecord({ [graph.path.entryNodeId]: true }),
    celebrationSeen: false,
    celebrationCount: 0,
    lastNavigationDecision: null,
    lastCatchUpResult: null,
    lastConceptAction: null,
    pendingLearningIntent: null,
    lastLearningLaunch: null,
    learningLaunchRevision: 0,
    pendingUnlockCommit: null,
    lastMovementCancellation: null,
    lastRejection: null,
  });
}

export function cloneProgressContext(context: LearningProgressContext): MutableProgressContext {
  return {
    ...context,
    subjectStatusById: { ...context.subjectStatusById },
    conceptStatusById: { ...context.conceptStatusById },
    visitedNodeIds: { ...context.visitedNodeIds },
  };
}

export function finishProgressContext(context: MutableProgressContext): LearningProgressContext {
  return Object.freeze({
    ...context,
    subjectStatusById: freezeRecord({ ...context.subjectStatusById }),
    conceptStatusById: freezeRecord({ ...context.conceptStatusById }),
    visitedNodeIds: freezeTrueRecord({ ...context.visitedNodeIds }),
  });
}

export function unlockEligibleSubjects(
  graph: ProgressGraph,
  subjectStatusById: Record<string, SubjectProgressStatus>,
): void {
  for (const subjectId of graph.subjectIds) {
    if (subjectStatusById[subjectId] !== "locked") continue;
    const predecessors = graph.incomingBySubjectId.get(subjectId) ?? [];
    if (predecessors.length > 0 && predecessors.every((id) => subjectStatusById[id] === "completed")) {
      subjectStatusById[subjectId] = "available";
    }
  }
}

export function nodeStatus(
  graph: ProgressGraph,
  context: LearningProgressContext,
  nodeId: LearningEntityId,
): LearningNodeProgressStatus | null {
  const node = graph.nodeById.get(nodeId);
  if (!node) return null;
  return node.entityKind === "subject"
    ? context.subjectStatusById[nodeId] ?? null
    : context.conceptStatusById[nodeId] ?? null;
}

export function rejectProgressEvent(
  draft: MutableProgressContext,
  event: LearningProgressEvent,
  reason: ProgressRejectionReason,
  nodeId: LearningEntityId | null = "nodeId" in event ? event.nodeId ?? null : null,
): void {
  draft.lastRejection = Object.freeze({ eventType: event.type, nodeId, reason });
}

export function acceptNavigation(
  draft: MutableProgressContext,
  decision: NavigationDecision,
): void {
  draft.lastNavigationDecision = Object.freeze({
    ...decision,
    routeNodeIds: Object.freeze([...decision.routeNodeIds]),
    requiredCompletionNodeIds: Object.freeze([...decision.requiredCompletionNodeIds]),
  });
  if (decision.accepted) draft.lastRejection = null;
}

export function subjectForNode(graph: ProgressGraph, nodeId: LearningEntityId): LearningEntityId | null {
  const node = graph.nodeById.get(nodeId);
  if (!node) return null;
  return node.entityKind === "subject" ? node.id : node.ownerSubjectId ?? null;
}

export function findDirectedRoute(
  graph: ProgressGraph,
  fromSubjectId: LearningEntityId,
  toSubjectId: LearningEntityId,
): readonly LearningEntityId[] | null {
  if (fromSubjectId === toSubjectId) return Object.freeze([fromSubjectId]);
  const queue: LearningEntityId[][] = [[fromSubjectId]];
  const seen = new Set<LearningEntityId>([fromSubjectId]);
  while (queue.length > 0) {
    const route = queue.shift();
    const current = route?.at(-1);
    if (!route || !current) break;
    for (const next of graph.outgoingBySubjectId.get(current) ?? []) {
      if (seen.has(next)) continue;
      const nextRoute = [...route, next];
      if (next === toSubjectId) return Object.freeze(nextRoute);
      seen.add(next);
      queue.push(nextRoute);
    }
  }
  return null;
}

export function strictSubjectAncestors(
  graph: ProgressGraph,
  subjectId: LearningEntityId,
): readonly LearningEntityId[] {
  const result = new Set<LearningEntityId>();
  const visit = (id: LearningEntityId): void => {
    for (const parentId of graph.incomingBySubjectId.get(id) ?? []) {
      if (result.has(parentId)) continue;
      result.add(parentId);
      visit(parentId);
    }
  };
  visit(subjectId);
  return sortNodeIds(result, graph.nodeById);
}

export function routeForCatchUp(
  graph: ProgressGraph,
  context: LearningProgressContext,
  targetNodeId: LearningEntityId,
): readonly LearningEntityId[] | null {
  const targetSubjectId = subjectForNode(graph, targetNodeId);
  const sourceSubjectId = subjectForNode(graph, context.currentNodeId);
  if (!targetSubjectId || !sourceSubjectId) return null;
  const source = graph.nodeById.get(context.currentNodeId);
  const target = graph.nodeById.get(targetNodeId);
  if (!source || !target) return null;

  // Concepts are physical stops too. A catch-up plan must start at the
  // character's real platform, not silently replace it with the owner subject.
  // Within one subject, keep a forward concept journey on the authored chain.
  if (source.entityKind === "concept"
    && target.entityKind === "concept"
    && sourceSubjectId === targetSubjectId) {
    const concepts = graph.conceptsBySubjectId.get(sourceSubjectId) ?? [];
    const sourceIndex = concepts.indexOf(source.id);
    const targetIndex = concepts.indexOf(target.id);
    if (sourceIndex < 0 || targetIndex < 0) return null;
    if (sourceIndex <= targetIndex) {
      return Object.freeze(concepts.slice(sourceIndex, targetIndex + 1));
    }
    return Object.freeze([
      source.id,
      sourceSubjectId,
      ...concepts.slice(0, targetIndex + 1),
    ]);
  }

  const subjectRoute = findDirectedRoute(graph, sourceSubjectId, targetSubjectId)
    ?? findDirectedRoute(graph, graph.path.entryNodeId, targetSubjectId);
  if (!subjectRoute) return null;
  const routeFromPhysicalSource = source.entityKind === "concept"
    ? [source.id, ...subjectRoute]
    : [...subjectRoute];
  if (target.entityKind === "subject") return Object.freeze(routeFromPhysicalSource);
  const concepts = graph.conceptsBySubjectId.get(targetSubjectId) ?? [];
  const targetIndex = concepts.indexOf(targetNodeId);
  return targetIndex < 0
    ? null
    : Object.freeze([...routeFromPhysicalSource, ...concepts.slice(0, targetIndex + 1)]);
}

export function completeSubjectForCatchUp(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  subjectId: LearningEntityId,
  completedSubjects: LearningEntityId[],
  completedConcepts: LearningEntityId[],
): void {
  if (draft.subjectStatusById[subjectId] !== "completed") {
    draft.subjectStatusById = { ...draft.subjectStatusById, [subjectId]: "completed" };
    completedSubjects.push(subjectId);
  }
  for (const conceptId of graph.conceptsBySubjectId.get(subjectId) ?? []) {
    if (draft.conceptStatusById[conceptId] === "completed") continue;
    draft.conceptStatusById = { ...draft.conceptStatusById, [conceptId]: "completed" };
    completedConcepts.push(conceptId);
  }
}

export function exposeNextConcept(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  subjectId: LearningEntityId,
): void {
  const concepts = graph.conceptsBySubjectId.get(subjectId) ?? [];
  if (concepts.length === 0) return;
  const firstIncompleteIndex = concepts.findIndex((id) => draft.conceptStatusById[id] !== "completed");
  if (firstIncompleteIndex < 0) return;
  const nextId = concepts[firstIncompleteIndex];
  if (nextId && draft.conceptStatusById[nextId] === "locked") {
    draft.conceptStatusById = { ...draft.conceptStatusById, [nextId]: "available" };
  }
}

export function completeOwnerIfReady(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  ownerSubjectId: LearningEntityId,
): void {
  const concepts = graph.conceptsBySubjectId.get(ownerSubjectId) ?? [];
  if (concepts.length === 0 || !concepts.every((id) => draft.conceptStatusById[id] === "completed")) {
    exposeNextConcept(graph, draft, ownerSubjectId);
    return;
  }
  draft.subjectStatusById = { ...draft.subjectStatusById, [ownerSubjectId]: "completed" };
  unlockEligibleSubjects(graph, draft.subjectStatusById as Record<string, SubjectProgressStatus>);
}

export function unlockReachedNode(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  nodeId: LearningEntityId,
): boolean {
  const node = graph.nodeById.get(nodeId);
  if (!node) return false;
  if (node.entityKind === "subject") {
    if (draft.subjectStatusById[nodeId] === "locked") {
      draft.subjectStatusById = { ...draft.subjectStatusById, [nodeId]: "available" };
    }
  } else {
    const ownerSubjectId = node.ownerSubjectId;
    if (ownerSubjectId && draft.subjectStatusById[ownerSubjectId] === "locked") {
      draft.subjectStatusById = { ...draft.subjectStatusById, [ownerSubjectId]: "available" };
    }
    if (draft.conceptStatusById[nodeId] === "locked") {
      draft.conceptStatusById = { ...draft.conceptStatusById, [nodeId]: "available" };
    }
  }
  draft.visitedNodeIds = { ...draft.visitedNodeIds, [nodeId]: true };
  return true;
}

export function completeTraversedUnlockNode(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  nodeId: LearningEntityId,
  finalTargetNodeId: LearningEntityId,
): boolean {
  const node = graph.nodeById.get(nodeId);
  const target = graph.nodeById.get(finalTargetNodeId);
  if (!node) return false;

  if (node.entityKind === "subject") {
    draft.subjectStatusById = { ...draft.subjectStatusById, [nodeId]: "completed" };
    const targetIsOwnedConcept = target?.entityKind === "concept" && target.ownerSubjectId === nodeId;
    if (!targetIsOwnedConcept) {
      const completedConcepts = { ...draft.conceptStatusById };
      for (const conceptId of graph.conceptsBySubjectId.get(nodeId) ?? []) {
        completedConcepts[conceptId] = "completed";
      }
      draft.conceptStatusById = completedConcepts;
    }
  } else {
    draft.conceptStatusById = { ...draft.conceptStatusById, [nodeId]: "completed" };
  }

  draft.visitedNodeIds = { ...draft.visitedNodeIds, [nodeId]: true };
  unlockEligibleSubjects(graph, draft.subjectStatusById as Record<string, SubjectProgressStatus>);
  return true;
}

export function completeMissingUnlockCommitPrerequisites(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  commit: PendingUnlockCommit,
): void {
  for (const nodeId of commit.requiredCompletionNodeIds) {
    completeTraversedUnlockNode(graph, draft, nodeId, commit.targetNodeId);
  }
}

/**
 * Commits the required platform being left and any parallel prerequisites
 * that converge at its next authored join. `reachedNodeIds` remains a physical
 * journal and is never treated as evidence of completion.
 */
export function completeUnlockDeparture(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  commit: PendingUnlockCommit,
): void {
  const sourceNodeId = draft.currentNodeId;
  const sourceNode = graph.nodeById.get(sourceNodeId);
  const required = new Set(commit.requiredCompletionNodeIds);
  const departureNodeIds = new Set<LearningEntityId>();
  if (required.has(sourceNodeId)) departureNodeIds.add(sourceNodeId);

  if (sourceNode?.entityKind === "subject") {
    for (const successorId of graph.outgoingBySubjectId.get(sourceNodeId) ?? []) {
      for (const peerId of graph.incomingBySubjectId.get(successorId) ?? []) {
        if (required.has(peerId)) departureNodeIds.add(peerId);
      }
    }
  }

  for (const nodeId of sortNodeIds(departureNodeIds, graph.nodeById)) {
    completeTraversedUnlockNode(graph, draft, nodeId, commit.targetNodeId);
  }
}

/**
 * Before committing a physically traversed node, commits every authored
 * prerequisite that must already be complete at that point. This preserves
 * graph invariants even when a dynamic bridge skips a visual platform.
 */
export function completeUnlockPrefixBeforeNode(
  graph: ProgressGraph,
  draft: MutableProgressContext,
  commit: PendingUnlockCommit,
  nodeId: LearningEntityId,
): boolean {
  const node = graph.nodeById.get(nodeId);
  if (!node) return false;
  const required = new Set(commit.requiredCompletionNodeIds);
  const prefix = new Set<LearningEntityId>();
  const subjectId = subjectForNode(graph, nodeId);
  if (subjectId) {
    for (const ancestorId of strictSubjectAncestors(graph, subjectId)) {
      if (required.has(ancestorId)) prefix.add(ancestorId);
    }
  }
  if (node.entityKind === "concept" && node.ownerSubjectId) {
    const siblings = graph.conceptsBySubjectId.get(node.ownerSubjectId) ?? [];
    const nodeIndex = siblings.indexOf(nodeId);
    for (const priorConceptId of siblings.slice(0, Math.max(0, nodeIndex))) {
      if (required.has(priorConceptId)) prefix.add(priorConceptId);
    }
  }
  if (required.has(nodeId)) prefix.add(nodeId);

  for (const requiredNodeId of sortNodeIds(prefix, graph.nodeById)) {
    completeTraversedUnlockNode(graph, draft, requiredNodeId, commit.targetNodeId);
  }
  return true;
}

export function requiredCompletionNodesForUnlock(
  graph: ProgressGraph,
  targetNodeId: LearningEntityId,
  routeNodeIds: readonly LearningEntityId[],
): readonly LearningEntityId[] {
  const targetSubjectId = subjectForNode(graph, targetNodeId);
  if (!targetSubjectId) return Object.freeze([]);
  const required = new Set<LearningEntityId>(strictSubjectAncestors(graph, targetSubjectId));
  for (const nodeId of routeNodeIds) {
    if (nodeId === targetNodeId) break;
    required.add(nodeId);
  }
  return Object.freeze(sortNodeIds(required, graph.nodeById));
}

export function isIntentCompatible(
  graph: ProgressGraph,
  nodeId: LearningEntityId,
  kind: LearningIntentKind,
): boolean {
  const node = graph.nodeById.get(nodeId);
  if (!node) return false;
  return node.entityKind === "subject" ? kind === "subject-enter" : kind !== "subject-enter";
}
