import type {
  ConceptProgressStatus,
  SubjectProgressStatus,
} from "../domain/types";
import {
  LEARNING_PROGRESS_PERSISTENCE_SCHEMA,
  LEARNING_PROGRESS_PERSISTENCE_VERSION,
  type LearningProgressMigrationResult,
  type LearningProgressPersistenceV1,
  type LearningProgressPersistenceV2,
} from "./types";

const ROOT_KEYS = Object.freeze([
  "schema",
  "version",
  "pathRevision",
  "lastSafeNodeId",
  "subjectStatusById",
  "conceptStatusById",
  "visitedNodeIds",
  "celebrationSeen",
  "celebrationCount",
] as const);

const SUBJECT_STATUSES = new Set<SubjectProgressStatus>(["locked", "available", "completed"]);
const CONCEPT_STATUSES = new Set<ConceptProgressStatus>([
  "locked",
  "available",
  "in-progress",
  "completed",
]);

type PlainRecord = Record<string, unknown>;

function isPlainRecord(value: unknown): value is PlainRecord {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const prototype = Object.getPrototypeOf(value) as object | null;
  return prototype === Object.prototype || prototype === null;
}

function hasExactKeys(record: PlainRecord, keys: readonly string[]): boolean {
  const actual = Object.keys(record).sort();
  const expected = [...keys].sort();
  return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isStatusRecord<T extends string>(
  value: unknown,
  allowed: ReadonlySet<T>,
): value is Readonly<Record<string, T>> {
  if (!isPlainRecord(value)) return false;
  return Object.entries(value).every(([id, status]) => (
    isNonEmptyString(id) && allowed.has(status as T)
  ));
}

function hasValidCommonFields(record: PlainRecord): boolean {
  return record.schema === LEARNING_PROGRESS_PERSISTENCE_SCHEMA
    && isNonEmptyString(record.pathRevision)
    && isNonEmptyString(record.lastSafeNodeId)
    && isStatusRecord(record.subjectStatusById, SUBJECT_STATUSES)
    && isStatusRecord(record.conceptStatusById, CONCEPT_STATUSES)
    && typeof record.celebrationSeen === "boolean"
    && Number.isSafeInteger(record.celebrationCount)
    && (record.celebrationCount as number) >= 0
    && ((record.celebrationCount as number) === 0 || record.celebrationSeen === true);
}

function isV1(value: unknown): value is LearningProgressPersistenceV1 {
  if (!isPlainRecord(value) || !hasExactKeys(value, ROOT_KEYS) || value.version !== 1) return false;
  if (!hasValidCommonFields(value) || !isPlainRecord(value.visitedNodeIds)) return false;
  return Object.entries(value.visitedNodeIds).every(([id, visited]) => (
    isNonEmptyString(id) && visited === true
  ));
}

function isV2(value: unknown): value is LearningProgressPersistenceV2 {
  if (!isPlainRecord(value)
    || !hasExactKeys(value, ROOT_KEYS)
    || value.version !== LEARNING_PROGRESS_PERSISTENCE_VERSION) return false;
  if (!hasValidCommonFields(value) || !Array.isArray(value.visitedNodeIds)) return false;
  const visited = value.visitedNodeIds;
  return visited.every(isNonEmptyString) && new Set(visited).size === visited.length;
}

function freezeStatusRecord<T extends string>(
  value: Readonly<Record<string, T>>,
): Readonly<Record<string, T>> {
  return Object.freeze(Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right))));
}

function freezeV2(value: LearningProgressPersistenceV2): LearningProgressPersistenceV2 {
  return Object.freeze({
    schema: LEARNING_PROGRESS_PERSISTENCE_SCHEMA,
    version: LEARNING_PROGRESS_PERSISTENCE_VERSION,
    pathRevision: value.pathRevision,
    lastSafeNodeId: value.lastSafeNodeId,
    subjectStatusById: freezeStatusRecord(value.subjectStatusById),
    conceptStatusById: freezeStatusRecord(value.conceptStatusById),
    visitedNodeIds: Object.freeze([...value.visitedNodeIds]),
    celebrationSeen: value.celebrationSeen,
    celebrationCount: value.celebrationCount,
  });
}

/** Strictly validates current documents and performs the sole supported V1 -> V2 migration. */
export function migrateLearningProgressDocument(input: unknown): LearningProgressMigrationResult {
  if (!isPlainRecord(input) || input.schema !== LEARNING_PROGRESS_PERSISTENCE_SCHEMA) {
    return Object.freeze({ ok: false, reason: "invalid-document" });
  }
  if (input.version === LEARNING_PROGRESS_PERSISTENCE_VERSION) {
    return isV2(input)
      ? Object.freeze({ ok: true, document: freezeV2(input), migratedFromVersion: null })
      : Object.freeze({ ok: false, reason: "invalid-document" });
  }
  if (input.version === 1) {
    if (!isV1(input)) return Object.freeze({ ok: false, reason: "invalid-document" });
    const migrated: LearningProgressPersistenceV2 = {
      schema: LEARNING_PROGRESS_PERSISTENCE_SCHEMA,
      version: LEARNING_PROGRESS_PERSISTENCE_VERSION,
      pathRevision: input.pathRevision,
      lastSafeNodeId: input.lastSafeNodeId,
      subjectStatusById: input.subjectStatusById,
      conceptStatusById: input.conceptStatusById,
      visitedNodeIds: Object.keys(input.visitedNodeIds).sort((left, right) => left.localeCompare(right)),
      celebrationSeen: input.celebrationSeen,
      celebrationCount: input.celebrationCount,
    };
    return Object.freeze({ ok: true, document: freezeV2(migrated), migratedFromVersion: 1 });
  }
  return Object.freeze({ ok: false, reason: "unknown-version" });
}

export function createLearningProgressPersistenceV2(
  value: Omit<LearningProgressPersistenceV2, "schema" | "version">,
): LearningProgressPersistenceV2 {
  const candidate: LearningProgressPersistenceV2 = {
    schema: LEARNING_PROGRESS_PERSISTENCE_SCHEMA,
    version: LEARNING_PROGRESS_PERSISTENCE_VERSION,
    ...value,
  };
  const result = migrateLearningProgressDocument(candidate);
  if (!result.ok) throw new TypeError(`Invalid learning progress persistence payload: ${result.reason}`);
  return result.document;
}

