import {
  LEARNING_PATH_PROTOCOL,
  LEARNING_PATH_VERSION,
  type LearningFlowDefinition,
  type LearningFlowGroupDefinition,
  type LearningPathDocument,
  type LearningPathValidationIssue,
  type LearningPathValidationIssueCode,
  type LearningPathValidationResult,
  type LearningSubjectDefinition,
} from "./types";

export const LEARNING_PATH_LIMITS = Object.freeze({
  maxSubjects: 128,
  maxConcepts: 1024,
  maxConceptsPerSubject: 32,
  maxFlowEdges: 2048,
  maxFlowGroups: 256,
  maxCards: 1152,
  maxActions: 1024,
  maxResources: 1024,
  maxIdLength: 64,
  maxShortTextLength: 160,
  maxSummaryLength: 500,
  maxBodyLength: 4000,
  maxUrlLength: 2048,
  maxTagsPerCard: 12,
  maxIssues: 200,
} as const);

type UnknownRecord = Record<string, unknown>;

class ValidationContext {
  readonly issues: LearningPathValidationIssue[] = [];

  add(
    code: LearningPathValidationIssueCode,
    path: string,
    message: string,
  ): void {
    if (this.issues.length >= LEARNING_PATH_LIMITS.maxIssues) {
      return;
    }
    this.issues.push({ code, path, message });
  }
}

export class LearningPathValidationError extends Error {
  readonly issues: readonly LearningPathValidationIssue[];

  constructor(issues: readonly LearningPathValidationIssue[]) {
    super(`Learning path document is invalid (${issues.length} issue(s)).`);
    this.name = "LearningPathValidationError";
    this.issues = issues;
  }
}

export function validateLearningPathDocument(
  input: unknown,
): LearningPathValidationResult {
  const context = new ValidationContext();
  validateDocumentShape(input, context);

  if (context.issues.length > 0) {
    return { ok: false, issues: Object.freeze([...context.issues]) };
  }

  const document = input as LearningPathDocument;
  validateDocumentSemantics(document, context);
  if (context.issues.length > 0) {
    return { ok: false, issues: Object.freeze([...context.issues]) };
  }

  return { ok: true, document, issues: [] };
}

export function assertLearningPathDocument(input: unknown): LearningPathDocument {
  const result = validateLearningPathDocument(input);
  if (!result.ok) {
    throw new LearningPathValidationError(result.issues);
  }
  return result.document;
}

function validateDocumentShape(input: unknown, context: ValidationContext): void {
  const root = validateObject(
    input,
    "$",
    ["protocol", "version", "id", "metadata", "structure", "data", "presentation"],
    [],
    context,
  );
  if (!root) return;

  validateLiteral(root.protocol, "$.protocol", LEARNING_PATH_PROTOCOL, context);
  validateLiteral(root.version, "$.version", LEARNING_PATH_VERSION, context);
  validateId(root.id, "$.id", context);
  validateMetadata(root.metadata, "$.metadata", context);
  validateStructure(root.structure, "$.structure", context);
  validateData(root.data, "$.data", context);
  validatePresentation(root.presentation, "$.presentation", context);
}

function validateMetadata(
  input: unknown,
  path: string,
  context: ValidationContext,
): void {
  const value = validateObject(
    input,
    path,
    ["title", "locale"],
    ["description"],
    context,
  );
  if (!value) return;
  validateText(value.title, `${path}.title`, 1, LEARNING_PATH_LIMITS.maxShortTextLength, context);
  if (value.description !== undefined) {
    validateText(value.description, `${path}.description`, 1, LEARNING_PATH_LIMITS.maxSummaryLength, context);
  }
  if (validateText(value.locale, `${path}.locale`, 2, 16, context)
    && !/^[a-z]{2,3}(?:-[A-Z]{2})?$/.test(value.locale as string)) {
    context.add("invalid_value", `${path}.locale`, "Locale must use a language tag such as zh-CN or en.");
  }
}

function validateStructure(
  input: unknown,
  path: string,
  context: ValidationContext,
): void {
  const value = validateObject(
    input,
    path,
    ["entrySubjectId", "goalSubjectIds", "subjects", "concepts", "flow", "flowGroups"],
    [],
    context,
  );
  if (!value) return;
  validateId(value.entrySubjectId, `${path}.entrySubjectId`, context);
  validateIdArray(value.goalSubjectIds, `${path}.goalSubjectIds`, 1, LEARNING_PATH_LIMITS.maxSubjects, context);
  validateRecordArray(value.subjects, `${path}.subjects`, 1, LEARNING_PATH_LIMITS.maxSubjects, validateSubject, context);
  validateRecordArray(value.concepts, `${path}.concepts`, 0, LEARNING_PATH_LIMITS.maxConcepts, validateConcept, context);
  validateRecordArray(value.flow, `${path}.flow`, 0, LEARNING_PATH_LIMITS.maxFlowEdges, validateFlow, context);
  validateRecordArray(value.flowGroups, `${path}.flowGroups`, 0, LEARNING_PATH_LIMITS.maxFlowGroups, validateFlowGroup, context);
}

function validateSubject(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(input, path, ["id", "cardRef"], ["orderHint"], context);
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateId(value.cardRef, `${path}.cardRef`, context);
  if (value.orderHint !== undefined) {
    validateInteger(value.orderHint, `${path}.orderHint`, 0, 1_000_000, context);
  }
}

function validateConcept(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(
    input,
    path,
    ["id", "subjectId", "cardRef", "actionRef"],
    ["orderHint"],
    context,
  );
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateId(value.subjectId, `${path}.subjectId`, context);
  validateId(value.cardRef, `${path}.cardRef`, context);
  validateId(value.actionRef, `${path}.actionRef`, context);
  if (value.orderHint !== undefined) {
    validateInteger(value.orderHint, `${path}.orderHint`, 0, 1_000_000, context);
  }
}

function validateFlow(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(
    input,
    path,
    ["id", "fromSubjectId", "toSubjectId"],
    ["semantics"],
    context,
  );
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateId(value.fromSubjectId, `${path}.fromSubjectId`, context);
  validateId(value.toSubjectId, `${path}.toSubjectId`, context);
  if (value.semantics !== undefined) {
    const semantics = validateObject(
      value.semantics,
      `${path}.semantics`,
      [],
      ["splitGroupId", "joinGroupId"],
      context,
    );
    if (!semantics) return;
    if (semantics.splitGroupId === undefined && semantics.joinGroupId === undefined) {
      context.add("invalid_value", `${path}.semantics`, "Semantics must reference a split group, a join group, or both.");
    }
    if (semantics.splitGroupId !== undefined) {
      validateId(semantics.splitGroupId, `${path}.semantics.splitGroupId`, context);
    }
    if (semantics.joinGroupId !== undefined) {
      validateId(semantics.joinGroupId, `${path}.semantics.joinGroupId`, context);
    }
  }
}

function validateFlowGroup(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(input, path, ["id", "type", "anchorSubjectId", "policy"], [], context);
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateId(value.anchorSubjectId, `${path}.anchorSubjectId`, context);
  if (value.type === "split") {
    validateLiteral(value.policy, `${path}.policy`, "parallel", context);
  } else if (value.type === "join") {
    validateLiteral(value.policy, `${path}.policy`, "all-required", context);
  } else {
    context.add("invalid_value", `${path}.type`, "Flow group type must be split or join.");
  }
}

function validateData(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(input, path, ["cards", "resources", "actions"], [], context);
  if (!value) return;
  validateRecordArray(value.cards, `${path}.cards`, 1, LEARNING_PATH_LIMITS.maxCards, validateCard, context);
  validateRecordArray(value.resources, `${path}.resources`, 0, LEARNING_PATH_LIMITS.maxResources, validateResource, context);
  validateRecordArray(value.actions, `${path}.actions`, 0, LEARNING_PATH_LIMITS.maxActions, validateAction, context);
}

function validateCard(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(
    input,
    path,
    ["id", "title", "summary"],
    ["eyebrow", "body", "tags", "imageUrl"],
    context,
  );
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateText(value.title, `${path}.title`, 1, LEARNING_PATH_LIMITS.maxShortTextLength, context);
  validateText(value.summary, `${path}.summary`, 1, LEARNING_PATH_LIMITS.maxSummaryLength, context);
  if (value.eyebrow !== undefined) {
    validateText(value.eyebrow, `${path}.eyebrow`, 1, 80, context);
  }
  if (value.body !== undefined) {
    validateText(value.body, `${path}.body`, 1, LEARNING_PATH_LIMITS.maxBodyLength, context);
  }
  if (value.imageUrl !== undefined) {
    validateSafeUrl(value.imageUrl, `${path}.imageUrl`, context);
  }
  if (value.tags !== undefined) {
    validateTextArray(value.tags, `${path}.tags`, 0, LEARNING_PATH_LIMITS.maxTagsPerCard, 40, context);
  }
}

function validateResource(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(input, path, ["id", "href"], [], context);
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateSafeUrl(value.href, `${path}.href`, context);
}

function validateAction(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(input, path, ["id", "kind", "label", "resourceId"], ["target"], context);
  if (!value) return;
  validateId(value.id, `${path}.id`, context);
  validateLiteral(value.kind, `${path}.kind`, "open-resource", context);
  validateText(value.label, `${path}.label`, 1, 80, context);
  validateId(value.resourceId, `${path}.resourceId`, context);
  if (value.target !== undefined && value.target !== "self" && value.target !== "blank") {
    context.add("invalid_value", `${path}.target`, "Target must be self or blank.");
  }
}

function validatePresentation(input: unknown, path: string, context: ValidationContext): void {
  const value = validateObject(input, path, ["layout"], [], context);
  if (!value) return;
  const layout = validateObject(
    value.layout,
    `${path}.layout`,
    ["direction"],
    ["subjectGap", "layerGap", "conceptGap", "conceptColumnGap"],
    context,
  );
  if (!layout) return;
  validateLiteral(layout.direction, `${path}.layout.direction`, "top-to-bottom", context);
  for (const field of ["subjectGap", "layerGap", "conceptGap", "conceptColumnGap"] as const) {
    if (layout[field] !== undefined) {
      validateFiniteNumber(layout[field], `${path}.layout.${field}`, 1, 100, context);
    }
  }
}

function validateDocumentSemantics(document: LearningPathDocument, context: ValidationContext): void {
  const { subjects, concepts, flow, flowGroups, entrySubjectId, goalSubjectIds } = document.structure;
  const { cards, actions, resources } = document.data;

  const subjectById = indexUnique(subjects, "$.structure.subjects", "subject", context);
  const conceptById = indexUnique(concepts, "$.structure.concepts", "concept", context);
  const flowById = indexUnique(flow, "$.structure.flow", "flow", context);
  const groupById = indexUnique(flowGroups, "$.structure.flowGroups", "flow group", context);
  const cardById = indexUnique(cards, "$.data.cards", "card", context);
  const actionById = indexUnique(actions, "$.data.actions", "action", context);
  const resourceById = indexUnique(resources, "$.data.resources", "resource", context);
  void flowById;

  for (const [conceptId] of conceptById) {
    if (subjectById.has(conceptId)) {
      context.add("duplicate_id", "$.structure.concepts", `Entity ID ${quote(conceptId)} is shared by a subject and a concept.`);
    }
  }

  if (!subjectById.has(entrySubjectId)) {
    context.add("invalid_reference", "$.structure.entrySubjectId", `Entry subject ${quote(entrySubjectId)} does not exist.`);
  }
  validateUniqueStringList(goalSubjectIds, "$.structure.goalSubjectIds", context);
  for (const [index, goalId] of goalSubjectIds.entries()) {
    if (!subjectById.has(goalId)) {
      context.add("invalid_reference", `$.structure.goalSubjectIds[${index}]`, `Goal subject ${quote(goalId)} does not exist.`);
    }
  }

  const referencedCards = new Set<string>();
  for (const [index, subject] of subjects.entries()) {
    validateReference(cardById, subject.cardRef, `$.structure.subjects[${index}].cardRef`, "card", context);
    referencedCards.add(subject.cardRef);
  }

  const conceptCountBySubject = new Map<string, number>();
  const goalSubjectIdSet = new Set(goalSubjectIds);
  const referencedActions = new Set<string>();
  for (const [index, concept] of concepts.entries()) {
    if (!subjectById.has(concept.subjectId)) {
      context.add("invalid_concept_ownership", `$.structure.concepts[${index}].subjectId`, `Owner subject ${quote(concept.subjectId)} does not exist.`);
    } else if (goalSubjectIdSet.has(concept.subjectId)) {
      context.add(
        "invalid_concept_ownership",
        `$.structure.concepts[${index}].subjectId`,
        `Goal subject ${quote(concept.subjectId)} terminates the path and cannot own concept platforms.`,
      );
    }
    conceptCountBySubject.set(concept.subjectId, (conceptCountBySubject.get(concept.subjectId) ?? 0) + 1);
    validateReference(cardById, concept.cardRef, `$.structure.concepts[${index}].cardRef`, "card", context);
    validateReference(actionById, concept.actionRef, `$.structure.concepts[${index}].actionRef`, "action", context);
    referencedCards.add(concept.cardRef);
    referencedActions.add(concept.actionRef);
  }
  for (const [subjectId, count] of conceptCountBySubject) {
    if (count > LEARNING_PATH_LIMITS.maxConceptsPerSubject) {
      context.add("limit_exceeded", "$.structure.concepts", `Subject ${quote(subjectId)} has ${count} concepts; maximum is ${LEARNING_PATH_LIMITS.maxConceptsPerSubject}.`);
    }
  }

  const referencedResources = new Set<string>();
  for (const [index, action] of actions.entries()) {
    validateReference(resourceById, action.resourceId, `$.data.actions[${index}].resourceId`, "resource", context);
    referencedResources.add(action.resourceId);
  }
  reportUnused(cards, referencedCards, "$.data.cards", "card", context);
  reportUnused(actions, referencedActions, "$.data.actions", "action", context);
  reportUnused(resources, referencedResources, "$.data.resources", "resource", context);

  const outgoing = new Map<string, LearningFlowDefinition[]>();
  const incoming = new Map<string, LearningFlowDefinition[]>();
  const endpointPairs = new Set<string>();
  for (const [index, edge] of flow.entries()) {
    const basePath = `$.structure.flow[${index}]`;
    validateReference(subjectById, edge.fromSubjectId, `${basePath}.fromSubjectId`, "subject", context);
    validateReference(subjectById, edge.toSubjectId, `${basePath}.toSubjectId`, "subject", context);
    if (edge.fromSubjectId === edge.toSubjectId) {
      context.add("invalid_value", basePath, "A subject flow cannot point to itself.");
    }
    const pair = `${edge.fromSubjectId}\u0000${edge.toSubjectId}`;
    if (endpointPairs.has(pair)) {
      context.add("duplicate_id", basePath, `Duplicate directed flow ${quote(edge.fromSubjectId)} -> ${quote(edge.toSubjectId)}.`);
    }
    endpointPairs.add(pair);
    appendMapArray(outgoing, edge.fromSubjectId, edge);
    appendMapArray(incoming, edge.toSubjectId, edge);
    validateEdgeGroupReference(edge, index, groupById, context);
  }

  for (const [index, group] of flowGroups.entries()) {
    validateReference(subjectById, group.anchorSubjectId, `$.structure.flowGroups[${index}].anchorSubjectId`, "subject", context);
  }
  validateDegreeSemantics(subjects, outgoing, incoming, groupById, context);
  validateAcyclicReachability(subjects, outgoing, incoming, entrySubjectId, goalSubjectIds, context);
}

function validateDegreeSemantics(
  subjects: readonly LearningSubjectDefinition[],
  outgoing: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
  incoming: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
  groupById: ReadonlyMap<string, LearningFlowGroupDefinition>,
  context: ValidationContext,
): void {
  const usedGroups = new Set<string>();
  for (const subject of subjects) {
    const outgoingEdges = outgoing.get(subject.id) ?? [];
    validateGroupAcrossEdges(subject.id, "split", outgoingEdges, groupById, usedGroups, context);
    const incomingEdges = incoming.get(subject.id) ?? [];
    validateGroupAcrossEdges(subject.id, "join", incomingEdges, groupById, usedGroups, context);
  }
  for (const groupId of groupById.keys()) {
    if (!usedGroups.has(groupId)) {
      context.add("invalid_flow_semantics", "$.structure.flowGroups", `Flow group ${quote(groupId)} is declared but not used by a valid branch or merge.`);
    }
  }
}

function validateGroupAcrossEdges(
  subjectId: string,
  type: "split" | "join",
  edges: readonly LearningFlowDefinition[],
  groupById: ReadonlyMap<string, LearningFlowGroupDefinition>,
  usedGroups: Set<string>,
  context: ValidationContext,
): void {
  const property = type === "split" ? "splitGroupId" : "joinGroupId";
  const groupIds = edges.map((edge) => edge.semantics?.[property]);
  if (edges.length > 1) {
    const expected = groupIds[0];
    if (!expected || groupIds.some((value) => value !== expected)) {
      context.add("invalid_flow_semantics", "$.structure.flow", `${type} at ${quote(subjectId)} must put every participating edge in one explicit ${type} group.`);
      return;
    }
    const group = groupById.get(expected);
    if (!group || group.type !== type || group.anchorSubjectId !== subjectId) {
      context.add("invalid_flow_semantics", "$.structure.flowGroups", `${type} group ${quote(expected)} must be anchored at ${quote(subjectId)}.`);
      return;
    }
    usedGroups.add(expected);
  } else if (groupIds[0] !== undefined) {
    context.add("invalid_flow_semantics", "$.structure.flow", `A ${type} group cannot be attached at ${quote(subjectId)} because it has fewer than two participating edges.`);
  }
}

function validateEdgeGroupReference(
  edge: LearningFlowDefinition,
  index: number,
  groupById: ReadonlyMap<string, LearningFlowGroupDefinition>,
  context: ValidationContext,
): void {
  const semantics = edge.semantics;
  if (!semantics) return;
  const basePath = `$.structure.flow[${index}].semantics`;
  if (semantics.splitGroupId) {
    const group = groupById.get(semantics.splitGroupId);
    if (!group || group.type !== "split") {
      context.add("invalid_flow_semantics", `${basePath}.splitGroupId`, `Split group ${quote(semantics.splitGroupId)} does not exist or has the wrong type.`);
    } else if (group.anchorSubjectId !== edge.fromSubjectId) {
      context.add("invalid_flow_semantics", `${basePath}.splitGroupId`, "Split group anchor must equal the edge source.");
    }
  }
  if (semantics.joinGroupId) {
    const group = groupById.get(semantics.joinGroupId);
    if (!group || group.type !== "join") {
      context.add("invalid_flow_semantics", `${basePath}.joinGroupId`, `Join group ${quote(semantics.joinGroupId)} does not exist or has the wrong type.`);
    } else if (group.anchorSubjectId !== edge.toSubjectId) {
      context.add("invalid_flow_semantics", `${basePath}.joinGroupId`, "Join group anchor must equal the edge destination.");
    }
  }
}

function validateAcyclicReachability(
  subjects: readonly LearningSubjectDefinition[],
  outgoing: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
  incoming: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
  entrySubjectId: string,
  goalSubjectIds: readonly string[],
  context: ValidationContext,
): void {
  const ids = new Set(subjects.map((subject) => subject.id));
  const indegree = new Map([...ids].map((id) => [id, incoming.get(id)?.length ?? 0] as const));
  const queue = [...ids].filter((id) => indegree.get(id) === 0).sort();
  let visitedCount = 0;
  while (queue.length > 0) {
    const id = queue.shift();
    if (!id) break;
    visitedCount += 1;
    for (const edge of outgoing.get(id) ?? []) {
      const nextDegree = (indegree.get(edge.toSubjectId) ?? 0) - 1;
      indegree.set(edge.toSubjectId, nextDegree);
      if (nextDegree === 0) insertSorted(queue, edge.toSubjectId);
    }
  }
  if (visitedCount !== ids.size) {
    context.add("cycle_detected", "$.structure.flow", "Subject flow must be a directed acyclic graph.");
    return;
  }

  if ((incoming.get(entrySubjectId)?.length ?? 0) > 0) {
    context.add("invalid_value", "$.structure.entrySubjectId", "Entry subject must not have prerequisites.");
  }

  const reachable = traverse(entrySubjectId, outgoing, (edge) => edge.toSubjectId);
  for (const id of ids) {
    if (!reachable.has(id)) {
      context.add("unreachable_subject", "$.structure.flow", `Subject ${quote(id)} is not reachable from entry ${quote(entrySubjectId)}.`);
    }
  }

  const goalSet = new Set(goalSubjectIds);
  for (const goalId of goalSet) {
    if ((outgoing.get(goalId)?.length ?? 0) > 0) {
      context.add("invalid_value", "$.structure.goalSubjectIds", `Goal subject ${quote(goalId)} must be terminal.`);
    }
  }
  for (const id of ids) {
    if ((outgoing.get(id)?.length ?? 0) === 0 && !goalSet.has(id)) {
      context.add("invalid_value", "$.structure.goalSubjectIds", `Terminal subject ${quote(id)} must be listed as a goal.`);
    }
  }

  const reverseEdges = new Map<string, LearningFlowDefinition[]>();
  for (const edges of outgoing.values()) {
    for (const edge of edges) appendMapArray(reverseEdges, edge.toSubjectId, edge);
  }
  const canReachGoal = new Set<string>();
  const stack = [...goalSet];
  while (stack.length > 0) {
    const id = stack.pop();
    if (!id || canReachGoal.has(id)) continue;
    canReachGoal.add(id);
    for (const edge of reverseEdges.get(id) ?? []) stack.push(edge.fromSubjectId);
  }
  for (const id of ids) {
    if (!canReachGoal.has(id)) {
      context.add("no_goal_path", "$.structure.flow", `Subject ${quote(id)} cannot reach any declared goal.`);
    }
  }
}

function traverse(
  start: string,
  edgesBySource: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
  next: (edge: LearningFlowDefinition) => string,
): ReadonlySet<string> {
  const visited = new Set<string>();
  const stack = [start];
  while (stack.length > 0) {
    const id = stack.pop();
    if (!id || visited.has(id)) continue;
    visited.add(id);
    for (const edge of edgesBySource.get(id) ?? []) stack.push(next(edge));
  }
  return visited;
}

function indexUnique<T extends { readonly id: string }>(
  values: readonly T[],
  path: string,
  label: string,
  context: ValidationContext,
): ReadonlyMap<string, T> {
  const result = new Map<string, T>();
  for (const [index, value] of values.entries()) {
    if (result.has(value.id)) {
      context.add("duplicate_id", `${path}[${index}].id`, `Duplicate ${label} ID ${quote(value.id)}.`);
    } else {
      result.set(value.id, value);
    }
  }
  return result;
}

function validateReference<T>(
  index: ReadonlyMap<string, T>,
  id: string,
  path: string,
  label: string,
  context: ValidationContext,
): void {
  if (!index.has(id)) {
    context.add("invalid_reference", path, `Referenced ${label} ${quote(id)} does not exist.`);
  }
}

function reportUnused<T extends { readonly id: string }>(
  values: readonly T[],
  referenced: ReadonlySet<string>,
  path: string,
  label: string,
  context: ValidationContext,
): void {
  for (const [index, value] of values.entries()) {
    if (!referenced.has(value.id)) {
      context.add("unused_data", `${path}[${index}].id`, `${label} ${quote(value.id)} is not referenced.`);
    }
  }
}

function validateUniqueStringList(values: readonly string[], path: string, context: ValidationContext): void {
  const seen = new Set<string>();
  for (const [index, value] of values.entries()) {
    if (seen.has(value)) context.add("duplicate_id", `${path}[${index}]`, `Duplicate ID ${quote(value)}.`);
    seen.add(value);
  }
}

function appendMapArray<T>(map: Map<string, T[]>, key: string, value: T): void {
  const values = map.get(key);
  if (values) values.push(value);
  else map.set(key, [value]);
}

function insertSorted(values: string[], value: string): void {
  let index = 0;
  while (index < values.length && (values[index] ?? "") < value) index += 1;
  values.splice(index, 0, value);
}

function validateObject(
  input: unknown,
  path: string,
  required: readonly string[],
  optional: readonly string[],
  context: ValidationContext,
): UnknownRecord | undefined {
  if (!isRecord(input)) {
    context.add("type_mismatch", path, "Expected an object.");
    return undefined;
  }
  const allowed = new Set([...required, ...optional]);
  for (const key of Object.keys(input)) {
    if (!allowed.has(key)) context.add("unknown_field", `${path}.${key}`, `Field ${quote(key)} is not allowed in protocol v1.`);
  }
  for (const key of required) {
    if (!Object.hasOwn(input, key)) context.add("missing_field", `${path}.${key}`, `Required field ${quote(key)} is missing.`);
  }
  return input;
}

function validateRecordArray(
  input: unknown,
  path: string,
  min: number,
  max: number,
  validateItem: (input: unknown, path: string, context: ValidationContext) => void,
  context: ValidationContext,
): void {
  if (!Array.isArray(input)) {
    context.add("type_mismatch", path, "Expected an array.");
    return;
  }
  validateArrayLength(input, path, min, max, context);
  for (let index = 0; index < Math.min(input.length, max + 1); index += 1) {
    validateItem(input[index], `${path}[${index}]`, context);
  }
}

function validateIdArray(
  input: unknown,
  path: string,
  min: number,
  max: number,
  context: ValidationContext,
): void {
  if (!Array.isArray(input)) {
    context.add("type_mismatch", path, "Expected an array.");
    return;
  }
  validateArrayLength(input, path, min, max, context);
  for (let index = 0; index < Math.min(input.length, max + 1); index += 1) {
    validateId(input[index], `${path}[${index}]`, context);
  }
}

function validateTextArray(
  input: unknown,
  path: string,
  min: number,
  max: number,
  maxTextLength: number,
  context: ValidationContext,
): void {
  if (!Array.isArray(input)) {
    context.add("type_mismatch", path, "Expected an array.");
    return;
  }
  validateArrayLength(input, path, min, max, context);
  for (let index = 0; index < Math.min(input.length, max + 1); index += 1) {
    validateText(input[index], `${path}[${index}]`, 1, maxTextLength, context);
  }
}

function validateArrayLength(
  value: readonly unknown[],
  path: string,
  min: number,
  max: number,
  context: ValidationContext,
): void {
  if (value.length < min) context.add("invalid_value", path, `Array must contain at least ${min} item(s).`);
  if (value.length > max) context.add("limit_exceeded", path, `Array exceeds the ${max}-item protocol limit.`);
}

function validateId(input: unknown, path: string, context: ValidationContext): input is string {
  if (!validateText(input, path, 1, LEARNING_PATH_LIMITS.maxIdLength, context)) return false;
  if (!/^[a-z][a-z0-9]*(?:[-_.:][a-z0-9]+)*$/.test(input)) {
    context.add("invalid_value", path, "ID must start with a lowercase letter and contain only lowercase letters, digits, -, _, . or : separators.");
    return false;
  }
  return true;
}

function validateText(
  input: unknown,
  path: string,
  minLength: number,
  maxLength: number,
  context: ValidationContext,
): input is string {
  if (typeof input !== "string") {
    context.add("type_mismatch", path, "Expected a string.");
    return false;
  }
  if (input.length < minLength || input.length > maxLength) {
    context.add(input.length > maxLength ? "limit_exceeded" : "invalid_value", path, `String length must be between ${minLength} and ${maxLength}.`);
    return false;
  }
  if (input.trim() !== input || /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(input)) {
    context.add("invalid_value", path, "String must be trimmed and cannot contain control characters.");
    return false;
  }
  return true;
}

function validateLiteral(
  input: unknown,
  path: string,
  expected: string,
  context: ValidationContext,
): void {
  if (input !== expected) context.add("invalid_value", path, `Expected literal ${quote(expected)}.`);
}

function validateInteger(
  input: unknown,
  path: string,
  min: number,
  max: number,
  context: ValidationContext,
): void {
  if (typeof input !== "number" || !Number.isSafeInteger(input)) {
    context.add("type_mismatch", path, "Expected a safe integer.");
  } else if (input < min || input > max) {
    context.add("invalid_value", path, `Integer must be between ${min} and ${max}.`);
  }
}

function validateFiniteNumber(
  input: unknown,
  path: string,
  min: number,
  max: number,
  context: ValidationContext,
): void {
  if (typeof input !== "number" || !Number.isFinite(input)) {
    context.add("type_mismatch", path, "Expected a finite number.");
  } else if (input < min || input > max) {
    context.add("invalid_value", path, `Number must be between ${min} and ${max}.`);
  }
}

function validateSafeUrl(input: unknown, path: string, context: ValidationContext): void {
  if (!validateText(input, path, 1, LEARNING_PATH_LIMITS.maxUrlLength, context)) return;
  const url = input;
  if (url.startsWith("#")) {
    if (!/^#[a-zA-Z][a-zA-Z0-9_-]*$/.test(url)) context.add("invalid_url", path, "Invalid in-page URL.");
    return;
  }
  if (url.startsWith("/") && !url.startsWith("//")) {
    if (url.includes("\\") || url.split(/[?#]/u, 1)[0]?.split("/").includes("..")) {
      context.add("invalid_url", path, "Root-relative URL cannot contain backslashes or parent traversal.");
    }
    return;
  }
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "https:" || parsed.username || parsed.password) {
      context.add("invalid_url", path, "External URL must use HTTPS and cannot contain credentials.");
    }
  } catch {
    context.add("invalid_url", path, "URL must be HTTPS, root-relative, or an in-page hash.");
  }
}

function isRecord(input: unknown): input is UnknownRecord {
  return typeof input === "object" && input !== null && !Array.isArray(input);
}

function quote(value: string): string {
  return `"${value}"`;
}
