import type { LearningEntityId } from "../../content";

/** Stable reference carried by DOM actions so replaced cards cannot be closed. */
export interface NodeCardInstanceReference {
  readonly nodeId: LearningEntityId;
  readonly revision: number;
}

/** Action identifiers currently authored by the learning-path card UI. */
export const NODE_CARD_ACTION_IDS = Object.freeze([
  "unlock:go",
  "subject:enter",
  "learn:start",
  "learn:continue",
  "learn:review",
  "concept:defer",
  "concept:complete",
] as const);

export type KnownNodeCardActionId = (typeof NODE_CARD_ACTION_IDS)[number];

export type NodeCardActionId = KnownNodeCardActionId;

const NODE_CARD_ACTION_ID_SET: ReadonlySet<string> = new Set(NODE_CARD_ACTION_IDS);

/** Runtime boundary for DOM/host strings before they can close the active card. */
export function isNodeCardActionId(value: string): value is NodeCardActionId {
  return NODE_CARD_ACTION_ID_SET.has(value);
}

export interface NodeCardActionDiagnostic extends NodeCardInstanceReference {
  readonly actionId: NodeCardActionId;
}

export type NodeCardCloseReason = "dismiss" | "action-requested" | "session-reset";

export interface NodeCardCloseDiagnostic extends NodeCardInstanceReference {
  readonly reason: NodeCardCloseReason;
  readonly actionId: NodeCardActionId | null;
}

/**
 * Card mode is represented only by the machine state. Context contains data
 * and diagnostics; it never contains an `open`, `visible`, or similar flag.
 */
export interface NodeCardContext {
  readonly nodeId: LearningEntityId | null;
  readonly revision: number;
  readonly lastClose: NodeCardCloseDiagnostic | null;
  readonly lastAction: NodeCardActionDiagnostic | null;
}

export interface NodeCardMachineInput {
  /** Allows a restored session to preserve monotonically increasing revisions. */
  readonly initialRevision?: number;
}

export type NodeCardEvent =
  | {
      readonly type: "NODE_CARD.PIN";
      readonly nodeId: LearningEntityId;
    }
  | {
      readonly type: "NODE_CARD.REOPEN";
      readonly nodeId: LearningEntityId;
    }
  | {
      readonly type: "NODE_CARD.DISMISS";
      readonly instance: NodeCardInstanceReference;
    }
  | {
      readonly type: "NODE_CARD.ACTION_REQUESTED";
      readonly instance: NodeCardInstanceReference;
      /** Raw boundary value; the machine accepts only NODE_CARD_ACTION_IDS. */
      readonly actionId: string;
      /** A defensive host gate. Omitted means the already-validated legacy path. */
      readonly enabled?: boolean;
    }
  | {
      readonly type: "SESSION.RESET";
    };

export interface NodeCardViewSnapshot {
  readonly mode: "hidden" | "visible";
  readonly nodeId: LearningEntityId | null;
  readonly revision: number;
  readonly instance: NodeCardInstanceReference | null;
  readonly lastClose: NodeCardCloseDiagnostic | null;
  readonly lastAction: NodeCardActionDiagnostic | null;
}
