const ROW_EPSILON = 0.000_001;

export interface BridgeEndpoints {
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
}

/**
 * The connection from one activating green platform to its row's first brown
 * platform. Immediate horizontal neighbours use a hidden ground road; only
 * non-adjacent pairs use generated overpass geometry.
 */
export type ZoneEntryConnectionSpec =
  | {
    readonly activationNodeId: NodeId;
    readonly kind: "straight-edge";
    readonly edgeId: EdgeId;
  }
  | {
    readonly activationNodeId: NodeId;
    readonly kind: "overpass";
  };

/** Immutable hop decisions exclude every generated or session entry bridge. */
export interface DynamicBridgeRuleSpec {
  readonly id: string;
  readonly distanceMetric: "minimum-hop-count";
  readonly distanceGraph: "authored-logical";
  readonly hopThresholdExclusive: number;
  readonly dynamicBridgesAffectDistance: false;
  readonly routeBehavior: "direct-current-to-target";
  readonly ordinaryBridgeLimit: number;
  readonly outgoingBridgeLimitPerAnchor: number;
  readonly endpointPairIdentity: "undirected";
  readonly reuseExistingEndpointPair: true;
  readonly waitForBridgeBeforeTraversal: true;
}

/** Declarative reveal template. The entry source is resolved per session. */
export type SpecialRevealStep =
  | { readonly kind: "node"; readonly nodeId: NodeId }
  | { readonly kind: "straight-edge"; readonly edgeId: EdgeId }
  | { readonly kind: "session-entry-connector" };

/** Fully resolved steps exposed by the coordinator to the view. */
export type ResolvedSpecialRevealStep =
  | Exclude<SpecialRevealStep, { readonly kind: "session-entry-connector" }>
  | { readonly kind: "bridge"; readonly endpoints: BridgeEndpoints };

/** One horizontal row owns one reusable four-platform brown chain. */
export interface SpecialPathZoneSpec {
  readonly id: string;
  readonly activationNodeIds: readonly NodeId[];
  readonly entryNodeId: NodeId;
  /** One or more hidden brown concept platforms; activation greens are not members. */
  readonly memberNodeIds: readonly NodeId[];
  /** A connected chain joining every brown concept platform. */
  readonly memberStraightEdgeIds: readonly EdgeId[];
  /** One and only one connector declaration for every activationNodeId. */
  readonly entryConnections: readonly ZoneEntryConnectionSpec[];
  readonly revealSequence: readonly SpecialRevealStep[];
  readonly entryConnectorRevealPolicy: "first";
  readonly activationTrigger: "idle-at-any-activation-node";
  readonly unlockPolicy: "repeatable-session";
  readonly retention: "retain-inside-session-envelope";
  readonly externalBridgeReplacement: "retire-entry-overpass-before-ensure";
  readonly dismissalTrigger: "departure-from-session-envelope";
  readonly dismissalBridgeOrder: "entry-left-to-right-preclear";
  readonly dismissalConstructOrder: "reverse-reveal-right-to-left";
  readonly lockHiddenMembersAfterDismissal: true;
  /**
   * Symmetric activation <-> member routing for one active row session.
   * Data-driven learning paths use `entry-then-existing-chain`: the subject
   * always reaches the first concept through its declared entry connector and
   * then follows the visible concept roads. The legacy direct policy remains
   * available for authored experiences that explicitly opt into a transient
   * activation-to-far-member overpass.
   */
  readonly activationMemberRoutingPolicy:
    | "entry-then-existing-chain"
    | "direct-only-from-activation-to-far-member-otherwise-existing-chain";
  readonly recomputeRemainingHopsAtEntry: true;
  /** The activation-to-entry road or bridge stays for the brown-chain session. */
  readonly retainEntryConnectorDuringMemberRoutes: true;
  /** The one allowed activation-to-far-member bridge retires at physical arrival. */
  readonly memberDynamicBridgeLifetime: "retire-at-physical-arrival";
  readonly retainedEntryOverpassCountsTowardOrdinaryLimit: false;
  /** Session entry overlays never modify immutable hop truth. */
  readonly entryConnectorAffectsAuthoredHopDistance: false;
}

export interface AuthoredLogicalPathEdge {
  readonly id: EdgeId;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  readonly connectionKind: "straight";
}

export interface LearningPathRuleConfig {
  readonly dynamicBridge: DynamicBridgeRuleSpec;
  readonly specialPathZones: readonly SpecialPathZoneSpec[];
}

export interface PathRuleValidationInput {
  readonly nodes: readonly LearningPathNode[];
  readonly straightEdges: readonly StraightLearningPathEdge[];
  readonly rules: LearningPathRuleConfig;
  readonly authoredLogicalEdges: readonly AuthoredLogicalPathEdge[];
  /** Dynamic documents do not have to use the legacy node-1 identifier. */
  readonly initialNodeId?: NodeId;
}

