import type { CompiledLearningPathRuntime } from "../../app/compileLearningPathRuntime";
import type { LearningPathSessionSnapshot } from "../../app/LearningPathSession";
import type { LearningProgressViewSnapshot } from "../../progression";
import type { LearningEntityId } from "../../content";
import type { ContextualNodeCardViewModel } from "../ContextualCardContracts";

export interface CreateNodeCardViewModelInput {
  readonly runtime: CompiledLearningPathRuntime;
  readonly nodeId: LearningEntityId;
  readonly progress: Pick<LearningProgressViewSnapshot, "nodeStatusById">;
  readonly session: LearningPathSessionSnapshot;
  /** Stable identity supplied by the card-lifecycle owner. */
  readonly instanceId: string;
  /** Host-specific copy for the existing subject action; action identity stays stable. */
  readonly subjectActionLabel?: string;
}

/**
 * Pure projection from domain/session read models into the DOM card contract.
 * It deliberately owns no lifecycle state and performs no DOM or actor work.
 */
export function createNodeCardViewModel(
  input: CreateNodeCardViewModelInput,
): ContextualNodeCardViewModel | null {
  const nodeId = input.nodeId;

  const node = input.runtime.source.nodeById.get(nodeId);
  const status = input.progress.nodeStatusById[nodeId];
  if (!node || !status) return null;

  const tone = status === "completed"
    ? (node.entityKind === "concept" ? "brown" : "green")
    : status === "in-progress" ? "brown" : "gray";
  const statusLabel = status === "locked"
    ? "未解锁"
    : status === "available"
      ? "可学习"
      : status === "in-progress"
        ? "学习中"
        : "已完成";
  const primaryActionDefinition = status === "locked"
    ? Object.freeze({ id: "unlock:go", label: "解锁并前往" })
    : node.entityKind === "subject"
      ? Object.freeze({
          id: "subject:enter",
          label: input.subjectActionLabel?.trim()
            || (status === "completed" ? "复习本学科" : "开始学习"),
        })
      : status === "available"
        ? Object.freeze({ id: "learn:start", label: "进入学习" })
        : status === "in-progress"
          ? Object.freeze({ id: "learn:continue", label: "继续学习" })
          : Object.freeze({ id: "learn:review", label: "开始复习" });
  const secondaryActionDefinition = node.entityKind === "concept"
    ? status === "available"
      ? Object.freeze({ id: "concept:defer", label: "稍后选择" })
      : status === "in-progress"
        ? Object.freeze({ id: "concept:complete", label: "标记为已完成" })
        : undefined
    : undefined;
  const interactionBusy = !input.session.interactionEnabled;
  const primaryAction = Object.freeze({
    ...primaryActionDefinition,
    enabled: !interactionBusy,
    busy: interactionBusy,
  });
  const secondaryAction = secondaryActionDefinition
    ? Object.freeze({
        ...secondaryActionDefinition,
        enabled: !interactionBusy,
        busy: interactionBusy,
      })
    : undefined;

  return Object.freeze({
    instanceId: input.instanceId,
    nodeId,
    kind: node.entityKind,
    tone,
    title: node.card.title,
    description: node.card.summary,
    eyebrow: node.id === input.runtime.source.entryNodeId
      ? "学习导览"
      : node.card.eyebrow ?? (node.entityKind === "subject" ? "学科" : "概念"),
    statusLabel,
    visible: true,
    primaryAction,
    ...(secondaryAction ? { secondaryAction } : {}),
  });
}

export interface NodeCardViewModelFactoryInput {
  readonly runtime: CompiledLearningPathRuntime;
  readonly nodeId: LearningEntityId;
  readonly progress: Pick<LearningProgressViewSnapshot, "nodeStatusById">;
  readonly session: LearningPathSessionSnapshot;
  readonly subjectActionLabel?: string;
}

/**
 * Compatibility identity adapter while the page composition root migrates to
 * the dedicated node-card actor. Presentation rules remain in the pure
 * function above; this class only assigns a stable instance id.
 */
export class NodeCardViewModelFactory {
  private sequence = 0;
  private currentKey: string | null = null;
  private currentInstanceId: string | null = null;

  public create(input: NodeCardViewModelFactoryInput): ContextualNodeCardViewModel | null {
    const nodeId = input.nodeId;
    const status = input.progress.nodeStatusById[nodeId];
    if (!status) return null;
    const key = `${nodeId}:${status}`;
    if (this.currentKey !== key || this.currentInstanceId === null) {
      this.currentKey = key;
      this.currentInstanceId = `node-card-${++this.sequence}-${nodeId}-${status}`;
    }
    return createNodeCardViewModel({
      ...input,
      instanceId: this.currentInstanceId,
    });
  }

  public getCurrentInstanceId(): string | null {
    return this.currentInstanceId;
  }

  public reset(): void {
    this.currentKey = null;
    this.currentInstanceId = null;
  }
}
