export interface LearningPathDomElements {
  readonly root: HTMLElement;
  readonly viewport: HTMLElement;
  readonly canvas: HTMLCanvasElement;
  readonly statusLabel: HTMLElement;
  readonly interactionHint: HTMLElement;
  readonly loadingPanel: HTMLElement;
  readonly loadingLabel: HTMLElement;
  readonly toast: HTMLElement;
  readonly screenReaderStatus: HTMLElement;
  readonly nodeOptions: HTMLOListElement;
}

function requireElement<T extends Element>(
  document: Document,
  id: string,
  constructor: { new(): T },
): T {
  const element = document.getElementById(id);
  if (!(element instanceof constructor)) {
    throw new Error(`Missing learning-path page element #${id}.`);
  }
  return element;
}

/** Resolves the fixed markup used only by the standalone Demo/QA page. */
export function resolveStandaloneLearningPathDom(
  document: Document,
): LearningPathDomElements {
  const root = requireElement(document, "app", HTMLElement);
  root.dataset.learningPathRoot = "standalone";
  return Object.freeze({
    root,
    viewport: requireElement(document, "learning-path-viewport", HTMLElement),
    canvas: requireElement(document, "learning-path-canvas", HTMLCanvasElement),
    statusLabel: requireElement(document, "status-label", HTMLElement),
    interactionHint: requireElement(document, "interaction-hint", HTMLElement),
    loadingPanel: requireElement(document, "loading-panel", HTMLElement),
    loadingLabel: requireElement(document, "loading-label", HTMLElement),
    toast: requireElement(document, "toast", HTMLElement),
    screenReaderStatus: requireElement(document, "screen-reader-status", HTMLElement),
    nodeOptions: requireElement(document, "path-node-options", HTMLOListElement),
  });
}

export function normalizeLearningPathInstanceId(instanceId: string): string {
  const value = instanceId.trim();
  if (!/^[a-zA-Z][a-zA-Z0-9_-]{0,63}$/.test(value)) {
    throw new Error(
      "Learning-path instanceId must start with a letter and contain only letters, numbers, '_' or '-'.",
    );
  }
  return value;
}

/** Creates one self-owned DOM subtree without clearing or mutating the host mount. */
export function createLearningPathDom(
  mount: HTMLElement,
  instanceId: string,
): LearningPathDomElements {
  const id = normalizeLearningPathInstanceId(instanceId);
  const document = mount.ownerDocument;
  const prefix = `learning-path-${id}`;
  const root = document.createElement("section");
  root.className = "learning-path-root";
  root.dataset.learningPathRoot = id;
  root.dataset.pagePhase = "generating";
  root.dataset.hud = "visible";
  root.setAttribute("aria-busy", "true");
  root.setAttribute("aria-label", "3D 学习路径");

  const workspace = document.createElement("div");
  workspace.className = "learning-path-workspace";

  const viewport = document.createElement("div");
  viewport.id = `${prefix}-viewport`;
  viewport.className = "learning-path-viewport";

  const canvas = document.createElement("canvas");
  canvas.id = `${prefix}-canvas`;
  canvas.className = "learning-path-canvas";
  canvas.tabIndex = 0;
  canvas.setAttribute("role", "application");
  canvas.setAttribute(
    "aria-label",
    "3D 学习路径。使用方向键选择圆台，按回车查看详情。",
  );

  const statusChip = document.createElement("section");
  statusChip.className = "status-chip";
  statusChip.setAttribute("aria-label", "学习路径状态");
  const statusDot = document.createElement("span");
  statusDot.className = "status-dot";
  statusDot.setAttribute("aria-hidden", "true");
  const statusLabel = document.createElement("span");
  statusLabel.id = `${prefix}-status-label`;
  statusLabel.textContent = "准备学习路径";
  statusChip.append(statusDot, statusLabel);

  const interactionHint = document.createElement("p");
  interactionHint.id = `${prefix}-interaction-hint`;
  interactionHint.className = "interaction-hint";
  const pointerCopy = document.createElement("span");
  pointerCopy.className = "pointer-copy";
  pointerCopy.textContent = "点击圆台查看 · 卡片内学习或解锁后移动 · 拖动或滚轮浏览";
  const keyboardCopy = document.createElement("span");
  keyboardCopy.className = "keyboard-copy";
  keyboardCopy.textContent = "← ↑ → ↓ 选择 · Enter 确认";
  interactionHint.append(pointerCopy, keyboardCopy);

  const loadingPanel = document.createElement("section");
  loadingPanel.id = `${prefix}-loading-panel`;
  loadingPanel.className = "loading-panel";
  loadingPanel.dataset.state = "hidden";
  loadingPanel.setAttribute("aria-live", "polite");
  const loadingMark = document.createElement("span");
  loadingMark.className = "loading-mark";
  loadingMark.setAttribute("aria-hidden", "true");
  const loadingLabel = document.createElement("span");
  loadingLabel.id = `${prefix}-loading-label`;
  loadingLabel.textContent = "正在召唤刘看山…";
  loadingPanel.append(loadingMark, loadingLabel);

  const toast = document.createElement("p");
  toast.id = `${prefix}-toast`;
  toast.className = "toast";
  toast.setAttribute("role", "status");
  toast.setAttribute("aria-live", "polite");

  const screenReaderStatus = document.createElement("p");
  screenReaderStatus.id = `${prefix}-screen-reader-status`;
  screenReaderStatus.className = "sr-only";
  screenReaderStatus.setAttribute("role", "status");
  screenReaderStatus.setAttribute("aria-live", "polite");
  screenReaderStatus.setAttribute("aria-atomic", "true");

  const nodeOptions = document.createElement("ol");
  nodeOptions.id = `${prefix}-node-options`;
  nodeOptions.className = "sr-only";
  nodeOptions.setAttribute("role", "listbox");
  nodeOptions.setAttribute("aria-label", "学习路径节点");

  canvas.setAttribute("aria-describedby", interactionHint.id);
  canvas.setAttribute("aria-controls", nodeOptions.id);
  canvas.setAttribute("aria-owns", nodeOptions.id);
  viewport.append(canvas, statusChip, interactionHint, loadingPanel, toast);
  workspace.append(viewport);
  root.append(workspace, screenReaderStatus, nodeOptions);
  mount.append(root);

  return Object.freeze({
    root,
    viewport,
    canvas,
    statusLabel,
    interactionHint,
    loadingPanel,
    loadingLabel,
    toast,
    screenReaderStatus,
    nodeOptions,
  });
}
