import { createLearningPathPageRuntime } from "../app/bootstrapLearningPathPage";
import {
  createLearningPathDom,
  normalizeLearningPathInstanceId,
  type LearningPathDomElements,
} from "../ui/LearningPathDom";
import type { CharacterAssetUrls } from "../render/objects/CharacterRig";
import type {
  LearningPathModule,
  MountLearningPathOptions,
} from "./contracts";
import { createScenePositionStorage } from "./scenePositionStorage";
import { reserveLearningPathInstance } from "./instanceRegistry";

function resolveCharacterAssets(options: MountLearningPathOptions): CharacterAssetUrls {
  if (options.characterAssets) return options.characterAssets;
  if (!options.assetBaseUrl) {
    throw new Error("mountLearningPath requires assetBaseUrl or characterAssets.");
  }
  const base = new URL(options.assetBaseUrl, options.mount.ownerDocument.baseURI);
  const resolve = (fileName: string): string => new URL(fileName, base).href;
  return Object.freeze({
    run: resolve("liu-kanshan-run.glb"),
    runStop: resolve("liu-kanshan-run-stop.glb"),
    idle: resolve("liu-kanshan-idle.glb"),
    turn: resolve("liu-kanshan-turn.glb"),
  });
}

function assertMountOptions(options: MountLearningPathOptions): void {
  const HTMLElementConstructor = options.mount?.ownerDocument.defaultView?.HTMLElement;
  if (!HTMLElementConstructor || !(options.mount instanceof HTMLElementConstructor)) {
    throw new TypeError("mountLearningPath requires a host HTMLElement.");
  }
  if (!options.instanceId.trim()) {
    throw new Error("mountLearningPath requires a non-empty instanceId.");
  }
  normalizeLearningPathInstanceId(options.instanceId);
  const progressKeyParts = options.progressKey.split(":");
  if (progressKeyParts.length < 4
    || progressKeyParts.length % 2 !== 0
    || progressKeyParts.some((part) => part.trim().length === 0 || /\s/.test(part))) {
    throw new Error(
      "mountLearningPath progressKey must use at least two non-empty namespace:value pairs.",
    );
  }
  const hasSource = Object.prototype.hasOwnProperty.call(options, "document")
    || Object.prototype.hasOwnProperty.call(options, "documentUrl")
    || Object.prototype.hasOwnProperty.call(options, "documentProvider");
  if (!hasSource) {
    throw new Error("mountLearningPath requires document, documentUrl or documentProvider.");
  }
  if (typeof options.assetBaseUrl === "string" && !options.assetBaseUrl.trim()) {
    throw new Error("mountLearningPath requires a non-empty assetBaseUrl.");
  }
  if (options.characterAssets) {
    for (const [name, url] of Object.entries(options.characterAssets)) {
      if (!url.trim()) {
        throw new Error(`mountLearningPath characterAssets.${name} must be non-empty.`);
      }
    }
  }
}

/** Framework-neutral mount API. The returned handle owns exactly one DOM subtree. */
export async function mountLearningPath(
  options: MountLearningPathOptions,
): Promise<LearningPathModule> {
  assertMountOptions(options);
  const releaseInstance = reserveLearningPathInstance(
    options.mount.ownerDocument,
    options.instanceId,
  );
  let elements: LearningPathDomElements | null = null;
  let runtime: Awaited<ReturnType<typeof createLearningPathPageRuntime>> | null = null;
  let disposed = false;
  let handingOff = false;
  let sceneStorage: Awaited<ReturnType<typeof createScenePositionStorage>> | null = null;
  try {
    sceneStorage = options.progressionMode === "open"
      ? await createScenePositionStorage(options.storage, options.progressKey, options.launchMode === "reset")
      : null;
    elements = createLearningPathDom(options.mount, options.instanceId);
    runtime = await createLearningPathPageRuntime(options, {
      mode: "module",
      instanceId: options.instanceId,
      elements,
      learningResource: options.navigator,
      learningProgressStorage: sceneStorage?.progressStorage ?? options.storage,
      initialSceneNodeId: sceneStorage?.initialPosition ?? undefined,
      lastLearningNodeId: sceneStorage?.lastLearningNodeId ?? undefined,
      onScenePositionChanged: sceneStorage ? nodeId => { if (handingOff) return; void sceneStorage!.setPosition(nodeId).catch(error => {
        options.onError?.({ phase: "runtime", message: "Scene position could not be saved.", error });
      }); } : undefined,
      progressStorageKey: options.progressKey,
      launchMode: options.launchMode ?? "continue",
      characterAssetUrls: resolveCharacterAssets(options),
      reducedMotion: options.reducedMotion,
      diagnostics: options.diagnostics ?? false,
      exposeGlobalDebug: false,
      subjectCardTrigger: options.subjectCardTrigger ?? "activate",
      progressionMode: options.progressionMode ?? "gated",
      nodeBadgeIconById: options.nodeBadgeIconById,
      onReady: options.onReady,
      onProgressChange: options.onProgressChange,
      onComplete: options.onComplete,
      onError: options.onError,
    });
  } catch (error) {
    elements?.root.remove();
    releaseInstance();
    options.onError?.(Object.freeze({
      phase: "host",
      error,
      message: error instanceof Error ? error.message : String(error),
    }));
    throw error;
  }

  if (!elements || !runtime) {
    releaseInstance();
    throw new Error("Learning-path module failed to create a runtime handle.");
  }
  const activeRuntime = runtime;
  const activeElements = elements;
  return Object.freeze({
    getSnapshot: () => activeRuntime.getSnapshot(),
    focusNode: (nodeId: string) => activeRuntime.focusNode(nodeId),
    rememberLearningNode: async (nodeId: string) => {
      if (disposed || handingOff || !sceneStorage || !activeRuntime.isConceptNode(nodeId)) return false;
      handingOff = true;
      activeRuntime.pause();
      try {
        await sceneStorage.rememberLearningNode(nodeId);
        if (!disposed) activeRuntime.markLastLearningNode(nodeId);
        return true;
      } finally {
        handingOff = false;
        if (!disposed) activeRuntime.resume();
      }
    },
    pause: () => activeRuntime.pause(),
    resume: () => activeRuntime.resume(),
    dispose: () => {
      if (disposed) return;
      disposed = true;
      activeRuntime.dispose();
      activeElements.root.remove();
      releaseInstance();
    },
  });
}
