import type {
  LearningPathBootstrapOptions,
  LearningPathTemplateLoadContext,
} from "./contracts";
import { cloneLearningPathJsonData } from "./jsonData";

const JSON_CONTENT_TYPE_PATTERN = /^(?:application|text)\/(?:[a-z0-9!#$&^_.+-]+\+)?json$/i;

function hasOwn(value: object, key: PropertyKey): boolean {
  return Object.prototype.hasOwnProperty.call(value, key);
}

export function validateLearningPathBootstrapOptions(options: LearningPathBootstrapOptions): void {
  const sourceCount = ["document", "documentUrl", "documentProvider"]
    .filter((key) => hasOwn(options, key)).length;
  if (sourceCount > 1) throw new TypeError("document、documentUrl、documentProvider 只能配置一个。");
  if (hasOwn(options, "documentUrl")
    && (typeof options.documentUrl !== "string" || options.documentUrl.trim() === "")) {
    throw new TypeError("documentUrl 必须是非空字符串。");
  }
  if (hasOwn(options, "documentProvider") && typeof options.documentProvider !== "function") {
    throw new TypeError("documentProvider 必须是函数。");
  }
}

function normalizeAllowedOrigins(origins: readonly string[] | undefined, baseUrl: URL): Set<string> {
  if (!origins) return new Set([baseUrl.origin]);
  const normalized = new Set<string>([baseUrl.origin]);
  for (const origin of origins) {
    if (typeof origin !== "string" || origin.trim() === "") {
      throw new TypeError("allowedDocumentOrigins 只能包含非空 URL 字符串。");
    }
    const parsed = new URL(origin, baseUrl);
    if (!/^https?:$/.test(parsed.protocol) || parsed.username || parsed.password) {
      throw new TypeError(`不允许的 JSON 来源：${origin}`);
    }
    normalized.add(parsed.origin);
  }
  return normalized;
}

/** Loads data only. Every result is cloned before the existing validator sees it. */
export async function loadLearningPathTemplate(
  options: LearningPathBootstrapOptions,
  context: LearningPathTemplateLoadContext,
): Promise<unknown> {
  validateLearningPathBootstrapOptions(options);
  if (context.signal.aborted) throw new DOMException("Template request cancelled.", "AbortError");

  if (hasOwn(options, "document")) return cloneLearningPathJsonData(options.document);
  if (hasOwn(options, "documentProvider")) {
    const provider = options.documentProvider;
    if (typeof provider !== "function") throw new TypeError("documentProvider 必须是函数。");
    const provided = await provider({ signal: context.signal });
    if (context.signal.aborted) throw new DOMException("Template request cancelled.", "AbortError");
    return cloneLearningPathJsonData(provided);
  }

  const baseUrl = new URL(context.baseUrl);
  const requestedUrl = hasOwn(options, "documentUrl")
    ? options.documentUrl
    : context.defaultDocumentUrl;
  if (typeof requestedUrl !== "string") throw new TypeError("documentUrl 必须是非空字符串。");
  const documentUrl = new URL(requestedUrl, baseUrl);
  if (!/^https?:$/.test(documentUrl.protocol) || documentUrl.username || documentUrl.password) {
    throw new TypeError(`学习路径 JSON 只允许 http(s) URL：${documentUrl.href}`);
  }
  const allowedOrigins = normalizeAllowedOrigins(options.allowedDocumentOrigins, baseUrl);
  if (!allowedOrigins.has(documentUrl.origin)) {
    throw new TypeError(`学习路径 JSON 来源未列入白名单：${documentUrl.origin}`);
  }

  const response = await (context.fetcher ?? fetch)(documentUrl.href, {
    signal: context.signal,
    headers: { Accept: "application/json" },
    credentials: documentUrl.origin === baseUrl.origin ? "same-origin" : "omit",
  });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const contentType = response.headers.get("content-type")?.split(";", 1)[0]?.trim();
  if (!contentType || !JSON_CONTENT_TYPE_PATTERN.test(contentType)) {
    throw new TypeError(`学习路径响应必须使用 JSON Content-Type，当前为 ${contentType || "缺失"}。`);
  }
  return cloneLearningPathJsonData(await response.json());
}

export function createDefaultLearningPathTemplateUrl(pageUrl: string): string {
  const environment = (import.meta as ImportMeta & { env?: { readonly BASE_URL?: string } }).env;
  const assetBaseUrl = new URL(environment?.BASE_URL ?? "./", pageUrl);
  return new URL("data/default-learning-path.json", assetBaseUrl).href;
}
