type PageGenerationLogic = ReturnType<typeof createPageGenerationMachine>;
type PageGenerationSnapshot = SnapshotFrom<PageGenerationLogic>;
type JourneyLogic = ReturnType<typeof createJourneyMachine>;
type JourneySnapshot = SnapshotFrom<JourneyLogic>;

interface ReconcileProgressInput {
  readonly identity: ActiveExperienceIdentity;
  readonly safeNodeId: string;
}

interface ReconcileProgressResult extends ReconcileProgressInput {}

const STABLE_PROGRESS_BOUNDARY_EVENTS: ReadonlySet<LearningProgressEvent["type"]> = new Set([
  "UNLOCK.DEPARTED",
  "NODE.TRAVERSED",
  "NODE.ARRIVED",
  "MOVEMENT.CANCELLED",
  "LEARNING.SETTLED",
  "CONCEPT.START.REQUESTED",
  "CONCEPT.CONTINUE.REQUESTED",
  "CONCEPT.MARK_COMPLETED",
  "CONCEPT.DEFERRED",
  "CONCEPT.REVIEW.REQUESTED",
]);

function pageSnapshotFromEvent(event: unknown): PageGenerationSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<PageGenerationSnapshot>).snapshot;
}

function pageContextFromEvent(event: unknown): PageGenerationMachineContext | null {
  return pageSnapshotFromEvent(event)?.context ?? null;
}

function journeySnapshotFromEvent(event: unknown): JourneySnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<JourneySnapshot>).snapshot;
}

function sceneSessionSnapshotFromEvent(event: unknown): SceneSessionSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<SceneSessionSnapshot>).snapshot;
}

function progressSnapshotFromEvent(event: unknown) {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<SnapshotFrom<ReturnType<typeof createRevisionProgressActorLogic>>>).snapshot;
}

function persistenceSnapshotFromEvent(
  event: unknown,
): LearningProgressPersistenceMachineSnapshot | null {
  if (typeof event !== "object" || event === null || !("snapshot" in event)) return null;
  return (event as SnapshotEvent<LearningProgressPersistenceMachineSnapshot>).snapshot;
}

function reconcileResultFromEvent(event: unknown): ReconcileProgressResult | null {
  if (typeof event !== "object" || event === null || !("output" in event)) return null;
  return (event as Readonly<{ output?: ReconcileProgressResult }>).output ?? null;
}

/**
 * Pure protocol translation owned by the application root. Runtime adapters
 * publish only gateway ACKs; path orchestration receives only domain events.
 */
export function mapSceneRuntimeAckToPathEvent(
  ack: SceneRuntimeGatewayAck,
): LearningPathEvent | null {
  switch (ack.type) {
    case "PRESENTATION.STARTED":
      return { type: "PRESENTATION.STARTED", token: ack.attemptId };
    case "PRESENTATION.SETTLED":
      return {
        type: "PRESENTATION.SETTLED",
        token: ack.attemptId,
        transactionId: ack.transactionId,
        operationId: ack.operationId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
      };
    case "PRESENTATION.FAILED":
      return {
        type: ack.timedOut ? "PRESENTATION.TIMED_OUT" : "PRESENTATION.FAILED",
        token: ack.attemptId,
        operationId: ack.operationId,
        transactionId: ack.transactionId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
        error: ack.error,
      };
    case "MOTION.DEPARTED":
      return ack.nodeId
        ? {
            type: "MOTION.DEPARTED",
            token: ack.attemptId,
            fromNodeId: ack.nodeId,
            transactionId: ack.transactionId,
            operationId: ack.operationId,
            attemptId: ack.attemptId,
            attempt: ack.attempt,
          }
        : null;
    case "MOTION.ARRIVED":
      return {
        type: "MOTION.ARRIVED",
        token: ack.attemptId,
        nodeId: ack.nodeId,
        transactionId: ack.transactionId,
        operationId: ack.operationId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
      };
    case "MOTION.VISUAL_IDLE":
      return {
        type: "MOTION.VISUAL_IDLE",
        token: ack.attemptId,
        nodeId: ack.nodeId,
        transactionId: ack.transactionId,
        operationId: ack.operationId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
      };
    case "MOTION.FAILED":
      return {
        type: ack.timedOut ? "MOTION.TIMED_OUT" : "MOTION.FAILED",
        token: ack.attemptId,
        operationId: ack.operationId,
        transactionId: ack.transactionId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
        error: ack.error,
      };
    case "CHARACTER.SETTLED":
      return {
        type: "CHARACTER.SETTLED",
        token: ack.attemptId,
        transactionId: ack.transactionId,
        operationId: ack.operationId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
      };
    case "CHARACTER.FAILED":
      return {
        type: "CHARACTER.FAILED",
        token: ack.attemptId,
        transactionId: ack.transactionId,
        operationId: ack.operationId,
        attemptId: ack.attemptId,
        attempt: ack.attempt,
        error: ack.error,
        timedOut: ack.timedOut,
      };
    default:
      return null;
  }
}

function fallbackCompiledPathResolver(page: CompiledLearningPathPage): CompiledLearningPath {
  const data = page.data
    ? resolveCompiledPageRuntimeData<unknown>(page.data)
    : null;
  if (typeof data !== "object" || data === null || !("source" in data)) {
    throw new Error(
      `No current CompiledLearningPath runtime data is registered for page revision "${page.revision}".`,
    );
  }
  const source = (data as { readonly source?: unknown }).source;
  if (typeof source !== "object" || source === null
    || !("nodeById" in source) || !("edges" in source)) {
    throw new Error(
      `Page revision "${page.revision}" does not expose a valid data.source progression model.`,
    );
  }
  return source as CompiledLearningPath;
}

function isExperienceScopedEvent(
  event: LearningPathApplicationEvent,
): event is ExperienceScopedApplicationEvent {
  return event.type === "APP.PROGRESS.EVENT"
    || event.type === "APP.JOURNEY.EVENT"
    || event.type === "APP.NODE_CARD.EVENT"
    || event.type === "APP.COMPLETION_CELEBRATION.EVENT"
    || event.type === "APP.SCENE_RUNTIME.COMMAND"
    || event.type === "APP.SCENE_SESSION.EVENT"
    || event.type === "APP.LEARNING_RESOURCE.EVENT"
    || event.type === "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED"
    || event.type === "APP.PERSISTENCE.FLUSH.REQUESTED";
}

function ignoredEventDiagnostic(
  context: LearningPathApplicationContext,
  event: LearningPathApplicationEvent,
): IgnoredApplicationEvent {
  const sessionRevision = "sessionRevision" in event
    ? event.sessionRevision ?? null
    : null;
  const transactionId = event.type === "APP.PAGE.EVENT" && "transactionId" in event.event
    ? event.event.transactionId
    : event.type === "APP.JOURNEY.EVENT" && "transactionId" in event.event
      ? event.event.transactionId
      : event.type === "APP.SCENE_RUNTIME.COMMAND"
        ? event.command.transactionId
        : null;
  return Object.freeze({
    eventType: event.type,
    reason: context.activeExperience === null
      ? "inactive-experience"
      : event.type === "APP.PAGE.EVENT"
        ? "stale-generation-transaction"
        : "stale-session-revision",
    sessionRevision,
    transactionId,
  });
}

/**
 * Creates the single application root for one page. Only serializable identity,
 * failure, and diagnostics data live in root context. Renderer ports, actor
 * refs, compiled graph indexes, and DOM/Three.js objects stay in injected
 * services or invoked actors.
 */
export function createLearningPathApplicationMachine(
  dependencies: LearningPathApplicationDependencies,
) {
  const compiledPathByRevision = new Map<string, CompiledLearningPath>();
  const resolveCompiledPath = dependencies.resolveCompiledLearningPath
    ?? (({ page }: { readonly page: CompiledLearningPathPage }) => (
      fallbackCompiledPathResolver(page)
    ));

  const pageGeneration = createPageGenerationMachine({
    ...dependencies.pageGeneration,
    onGenerationReady: (notice) => {
      const source = resolveCompiledPath({
        revision: notice.revision,
        transactionId: notice.transactionId,
        page: notice.compiledPath,
      });
      compiledPathByRevision.clear();
      compiledPathByRevision.set(notice.revision, source);
      dependencies.pageGeneration.onGenerationReady?.(notice);
    },
  });
  const progress = createRevisionProgressActorLogic((revision) => {
    const path = compiledPathByRevision.get(revision);
    if (!path) throw new Error(`No progression model registered for revision "${revision}".`);
    return path;
  });
  const journey = createJourneyMachine(dependencies.journey);
  const experienceBySessionRevision = new Map<number, ActiveExperienceIdentity>();
  const sceneRuntimeInputBySessionRevision = new Map<
    number,
    ReturnType<LearningPathApplicationDependencies["createSceneRuntimeInput"]>
  >();
  const pathOrchestrationBindingBySessionRevision = new Map<
    number,
    PathOrchestrationRuntimeBinding
  >();
  const resolveActivePathOrchestrationBinding = (): PathOrchestrationRuntimeBinding => {
    const binding = [...pathOrchestrationBindingBySessionRevision.values()][0];
    if (!binding) throw new Error("No active path-orchestration runtime binding is registered.");
    return binding;
  };
  const pathOrchestration = createPathOrchestrationChildLogic(
    resolveActivePathOrchestrationBinding,
  );
  const sceneSession = createSceneSessionMachine((sessionRevision) => {
    const identity = experienceBySessionRevision.get(sessionRevision);
    if (!identity) {
      throw new Error(`No active experience registered for scene session ${sessionRevision}.`);
    }
    const runtime = sceneRuntimeInputBySessionRevision.get(sessionRevision);
    if (!runtime) {
      throw new Error(`No runtime input registered for scene session ${sessionRevision}.`);
    }
    return {
      sessionRevision,
      runtimePort: runtime.port,
      gatewayTimeoutMs: runtime.defaultTimeoutMs,
      gatewayScheduler: runtime.scheduler,
    };
  });
  const learningResource = createLearningResourceMachine(dependencies.learningResource);
  const persistence = createLearningProgressPersistenceMachine(
    dependencies.learningProgressStorage,
  );
  const reconcileRestoredProgress = fromPromise<
    ReconcileProgressResult,
    ReconcileProgressInput
  >(async ({ input, signal }) => {
    await dependencies.reconcileRestoredProgress({
      ...input.identity,
      safeNodeId: input.safeNodeId,
      signal,
    });
    if (signal.aborted) {
      throw new DOMException("Restored progress reconciliation was aborted.", "AbortError");
    }
    return Object.freeze({ ...input });
  });

  return setup({
    types: {} as {
      context: LearningPathApplicationContext;
      events: LearningPathApplicationEvent;
      input: LearningPathApplicationInput;
    },
    actors: {
      pageGeneration,
      progress,
      journey,
      nodeCard: nodeCardMachine,
      completionCelebration: completionCelebrationMachine,
      sceneSession,
      learningResource,
      pathOrchestration,
      persistence,
      reconcileRestoredProgress,
    },
    guards: {
      pageSnapshotIsNewReadyExperience: ({ context, event }) => {
        const snapshot = pageSnapshotFromEvent(event);
        if (!snapshot?.matches("ready")) return false;
        const page = snapshot.context;
        return page.revision !== null
          && page.transactionId !== null
          && page.compiledPath !== null
          && (
            context.activeExperience?.revision !== page.revision
            || context.activeExperience.transactionId !== page.transactionId
          );
      },
      pageSnapshotHasNewFailure: ({ context, event }) => {
        const failure = pageContextFromEvent(event)?.lastError;
        if (!failure) return false;
        const previous = context.lastGenerationFailure;
        return !previous
          || previous.transactionId !== failure.transactionId
          || previous.revision !== failure.revision
          || previous.kind !== failure.kind
          || previous.message !== failure.message;
      },
      pageEventMatchesGeneration: ({ context, event }) => {
        if (event.type !== "APP.PAGE.EVENT") return false;
        if (!("transactionId" in event.event)) return true;
        return context.generationTransactionId !== null
          && event.event.transactionId === context.generationTransactionId
          && (
            !("revision" in event.event)
            || context.generationRevision === null
            || event.event.revision === context.generationRevision
          );
      },
      experienceRevisionMatches: ({ context, event }) => (
        isExperienceScopedEvent(event)
        && context.activeExperience !== null
        && event.sessionRevision === context.activeExperience.sessionRevision
        && (event.type !== "APP.SCENE_RUNTIME.COMMAND"
          || event.command.sessionRevision === event.sessionRevision)
        && (event.type !== "APP.SCENE_SESSION.EVENT"
          || event.event.sessionRevision === event.sessionRevision)
        && (event.type !== "APP.LEARNING_RESOURCE.EVENT"
          || event.event.sessionRevision === event.sessionRevision)
        && (event.type !== "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED"
          || event.event.sessionRevision === event.sessionRevision)
      ),
      degradationMatches: ({ context, event }) => (
        event.type === "APP.RUNTIME.DEGRADED"
        && (
          event.sessionRevision === undefined
          || context.activeExperience?.sessionRevision === event.sessionRevision
        )
      ),
      recoveryMatches: ({ context, event }) => (
        event.type === "APP.RUNTIME.RECOVERED"
        && context.activeExperience !== null
        && (
          event.sessionRevision === undefined
          || event.sessionRevision === context.activeExperience.sessionRevision
        )
      ),
      hasActiveExperience: ({ context }) => context.activeExperience !== null,
      journeyReadyRequiresNavigation: ({ context, event }) => {
        const snapshot = journeySnapshotFromEvent(event);
        const plan = snapshot?.context.plan;
        const transactionId = snapshot?.context.transactionId;
        return Boolean(
          snapshot?.matches("ready")
          && plan
          && transactionId
          && plan.sourceNodeId !== plan.targetNodeId
          && context.lastDispatchedJourneyTransactionId !== transactionId,
        );
      },
      journeyReadyIsAlreadyAtTarget: ({ context, event }) => {
        const snapshot = journeySnapshotFromEvent(event);
        const plan = snapshot?.context.plan;
        const transactionId = snapshot?.context.transactionId;
        return Boolean(
          snapshot?.matches("ready")
          && plan
          && transactionId
          && plan.sourceNodeId === plan.targetNodeId
          && context.lastDispatchedJourneyTransactionId !== transactionId,
        );
      },
      sceneSessionSnapshotHasNewMappableGatewayAck: ({ context, event }) => {
        const scene = sceneSessionSnapshotFromEvent(event);
        const ack = scene?.context.lastGatewayAck;
        return Boolean(
          scene
          && ack
          && scene.context.gatewayAckSequence > context.lastRoutedGatewayAckSequence
          && mapSceneRuntimeAckToPathEvent(ack) !== null,
        );
      },
      sceneSessionSnapshotHasNewGatewayAck: ({ context, event }) => {
        const scene = sceneSessionSnapshotFromEvent(event);
        return Boolean(
          scene?.context.lastGatewayAck
          && scene.context.gatewayAckSequence > context.lastRoutedGatewayAckSequence,
        );
      },
      persistenceLoadedForActiveExperience: ({ context, event }) => {
        const active = context.activeExperience;
        const persisted = persistenceSnapshotFromEvent(event)?.context;
        return Boolean(
          active
          && context.hydratedProgressContext === null
          && persisted?.loadResult
          && persisted.sessionRevision === active.sessionRevision
          && persisted.pathRevision === active.revision,
        );
      },
      reconciliationMatchesActiveExperience: ({ context, event }) => {
        const active = context.activeExperience;
        const result = reconcileResultFromEvent(event);
        return Boolean(
          active
          && result
          && result.identity.sessionRevision === active.sessionRevision
          && result.identity.revision === active.revision
          && result.identity.transactionId === active.transactionId,
        );
      },
      stableProgressEventMatchesExperience: ({ context, event }) => (
        event.type === "APP.PROGRESS.EVENT"
        && context.activeExperience !== null
        && event.sessionRevision === context.activeExperience.sessionRevision
        && STABLE_PROGRESS_BOUNDARY_EVENTS.has(event.event.type)
      ),
      hasHydratedProgress: ({ context }) => (
        context.activeExperience !== null
        && context.hydratedProgressContext !== null
      ),
      progressSnapshotHasPendingPersistenceSave: ({ context, event }) => {
        const active = context.activeExperience;
        const progressSnapshot = progressSnapshotFromEvent(event);
        return Boolean(
          active
          && context.pendingPersistenceOperationId
          && progressSnapshot
          && progressSnapshot.context.revision === active.revision,
        );
      },
      persistenceSnapshotHasNewFailure: ({ context, event }) => {
        const failure = persistenceSnapshotFromEvent(event)?.context.lastFailure;
        const previous = context.lastPersistenceFailure;
        return Boolean(
          failure
          && (
            previous === null
            || failure.correlation.operationId !== previous.correlation.operationId
            || failure.code !== previous.code
            || failure.phase !== previous.phase
          ),
        );
      },
      persistenceCompletedPendingLearningResourceLaunch: ({ context, event }) => {
        const pending = context.pendingLearningResourceLaunch;
        const completed = persistenceSnapshotFromEvent(event)?.context.lastCompletedCorrelation;
        return Boolean(
          pending
          && completed
          && completed.operationId === pending.persistenceOperationId
          && completed.sessionRevision === context.activeExperience?.sessionRevision,
        );
      },
      persistenceSnapshotHasNewCompletion: ({ context, event }) => {
        const completed = persistenceSnapshotFromEvent(event)?.context.lastCompletedCorrelation;
        return Boolean(
          completed
          && completed.sessionRevision === context.activeExperience?.sessionRevision
          && completed.operationId !== context.lastCompletedPersistenceOperationId,
        );
      },
      deferredLearningResourceLaunchAlreadyPersisted: ({ context, event }) => (
        event.type === "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED"
        && context.activeExperience !== null
        && event.sessionRevision === context.activeExperience.sessionRevision
        && event.event.sessionRevision === event.sessionRevision
        && context.lastPersistenceOperationId !== null
        && context.lastPersistenceOperationId === context.lastCompletedPersistenceOperationId
      ),
    },
    actions: {
      recordLaunchRequest: assign(({ event }) => {
        if (event.type !== "APP.GENERATE.REQUESTED") return {};
        const progressStorageKey = event.progressStorageKey?.trim() || null;
        return {
          pendingLaunchMode: event.launchMode ?? "generate",
          pendingProgressStorageKey: progressStorageKey,
        };
      }),
      sendGenerateRequest: sendTo("pageGeneration", ({ event }) => {
        if (event.type !== "APP.GENERATE.REQUESTED") {
          return { type: "PAGE.GENERATE.REQUESTED" } as const;
        }
        return {
          type: "PAGE.GENERATE.REQUESTED" as const,
          ...(event.template === undefined ? {} : { template: event.template }),
          ...(event.reducedMotion === undefined ? {} : { reducedMotion: event.reducedMotion }),
        };
      }),
      sendGenerateRetry: sendTo("pageGeneration", {
        type: "PAGE.GENERATE.RETRY_REQUESTED",
      }),
      routePageEvent: sendTo("pageGeneration", ({ event }) => (
        event.type === "APP.PAGE.EVENT"
          ? event.event
          : { type: "PAGE.GENERATE.RETRY_REQUESTED" }
      )),
      routeProgressEvent: sendTo("progress", ({ event }) => (
        event.type === "APP.PROGRESS.EVENT"
          ? event.event
          : { type: "NAVIGATION.REQUESTED", nodeId: "invalid-node" }
      )),
      routeJourneyEvent: sendTo("journey", ({ event }) => (
        event.type === "APP.JOURNEY.EVENT" ? event.event : { type: "RESET" }
      )),
      routeJourneyNavigation: sendTo("pathOrchestration", ({ event }) => {
        const plan = journeySnapshotFromEvent(event)?.context.plan;
        return {
          type: "NAVIGATION.REQUESTED" as const,
          targetNodeId: plan?.targetNodeId ?? "invalid-node",
        };
      }),
      beginSettledJourney: sendTo("journey", ({ event }) => ({
        type: "MOVEMENT_STARTED" as const,
        transactionId: journeySnapshotFromEvent(event)?.context.transactionId ?? "invalid-transaction",
      })),
      arriveSettledJourney: sendTo("journey", ({ event }) => {
        const snapshot = journeySnapshotFromEvent(event);
        return {
          type: "NODE_ARRIVED" as const,
          transactionId: snapshot?.context.transactionId ?? "invalid-transaction",
          nodeId: snapshot?.context.plan?.targetNodeId ?? "invalid-node",
        };
      }),
      visuallySettleJourney: sendTo("journey", ({ event }) => ({
        type: "VISUAL_SETTLED" as const,
        transactionId: journeySnapshotFromEvent(event)?.context.transactionId ?? "invalid-transaction",
      })),
      recordJourneyDispatch: assign(({ event }) => ({
        lastDispatchedJourneyTransactionId:
          journeySnapshotFromEvent(event)?.context.transactionId ?? null,
      })),
      routeNodeCardEvent: sendTo("nodeCard", ({ event }) => (
        event.type === "APP.NODE_CARD.EVENT" ? event.event : { type: "SESSION.RESET" }
      )),
      routeCompletionCelebrationEvent: sendTo("completionCelebration", ({ event }) => (
        event.type === "APP.COMPLETION_CELEBRATION.EVENT"
          ? event.event
          : { type: "SESSION.RESET" }
      )),
      routeProgressCelebrationCount: sendTo("completionCelebration", ({ event }) => ({
        type: "PROGRESS.CELEBRATION_RECORDED" as const,
        count: progressSnapshotFromEvent(event)?.context.model.celebrationCount ?? 0,
      })),
      routeSceneRuntimeCommand: sendTo("sceneSession", ({ event }) => (
        event.type === "APP.SCENE_RUNTIME.COMMAND"
          ? event.command
          : ({ type: "MOTION.ABORT" } as unknown as SceneRuntimeGatewayCommand)
      )),
      routeSceneSessionEvent: sendTo("sceneSession", ({ event }) => (
        event.type === "APP.SCENE_SESSION.EVENT"
          ? event.event
          : ({ type: "SESSION.STOP", sessionRevision: -1 } as const)
      )),
      routeSceneRuntimeAck: sendTo("pathOrchestration", ({ event }) => {
        const ack = sceneSessionSnapshotFromEvent(event)?.context.lastGatewayAck;
        const mapped = ack ? mapSceneRuntimeAckToPathEvent(ack) : null;
        if (!mapped) {
          throw new Error("Cannot route an unmappable scene-runtime ACK.");
        }
        return mapped;
      }),
      recordSceneRuntimeAckSequence: assign(({ event }) => ({
        lastRoutedGatewayAckSequence:
          sceneSessionSnapshotFromEvent(event)?.context.gatewayAckSequence ?? 0,
      })),
      routeLearningResourceEvent: sendTo("learningResource", ({ event }) => (
        event.type === "APP.LEARNING_RESOURCE.EVENT"
          ? event.event
          : ({ type: "SESSION.REVISION.CHANGED", sessionRevision: -1 } as const)
      )),
      queueLearningResourceAfterPersistence: assign(({ context, event }) => {
        if (event.type !== "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED"
          || !context.lastPersistenceOperationId) return {};
        return {
          pendingLearningResourceLaunch: Object.freeze({
            persistenceOperationId: context.lastPersistenceOperationId,
            event: Object.freeze({
              ...event.event,
              binding: Object.freeze({ ...event.event.binding }),
            }),
          }),
        };
      }),
      routePersistedLearningResourceLaunch: sendTo("learningResource", ({ context }) => {
        const pending = context.pendingLearningResourceLaunch;
        if (!pending) {
          throw new Error("Cannot launch a learning resource without a persisted request.");
        }
        return pending.event;
      }),
      routeAlreadyPersistedLearningResourceLaunch: sendTo("learningResource", ({ event }) => {
        if (event.type !== "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED") {
          throw new Error("Cannot route an unrelated event as a learning resource launch.");
        }
        return event.event;
      }),
      clearPendingLearningResourceLaunch: assign({
        pendingLearningResourceLaunch: null,
      }),
      recordCompletedPersistenceOperation: assign(({ event }) => ({
        lastCompletedPersistenceOperationId:
          persistenceSnapshotFromEvent(event)?.context.lastCompletedCorrelation?.operationId ?? null,
      })),
      armStablePersistenceSave: assign(({ context, event }) => {
        if (event.type !== "APP.PROGRESS.EVENT" || !context.activeExperience) return {};
        const progressRevision = context.persistenceProgressRevision + 1;
        return {
          persistenceProgressRevision: progressRevision,
          pendingPersistenceOperationId:
            `progress:${context.activeExperience.sessionRevision}:${progressRevision}:${event.event.type}`,
        };
      }),
      persistProgressSnapshot: sendTo("persistence", ({ context, event }) => {
        const active = context.activeExperience;
        const progressSnapshot = progressSnapshotFromEvent(event);
        if (!active || !progressSnapshot || !context.pendingPersistenceOperationId) {
          throw new Error("Cannot persist an uncorrelated progress snapshot.");
        }
        return {
          type: "PERSISTENCE.SAVE.REQUESTED" as const,
          sessionRevision: active.sessionRevision,
          pathRevision: active.revision,
          progressRevision: context.persistenceProgressRevision,
          operationId: context.pendingPersistenceOperationId,
          context: progressSnapshot.context.model,
          lastSafeNodeId: progressSnapshot.context.model.currentNodeId,
        };
      }),
      recordPersistenceSaveDispatch: assign(({ context }) => ({
        lastPersistenceOperationId: context.pendingPersistenceOperationId,
        pendingPersistenceOperationId: null,
      })),
      flushPersistence: sendTo("persistence", ({ context }) => {
        const active = context.activeExperience;
        const operationId = context.lastPersistenceOperationId
          ?? `persistence-load:${active?.sessionRevision ?? -1}:none`;
        return {
          type: "PERSISTENCE.FLUSH.REQUESTED" as const,
          sessionRevision: active?.sessionRevision ?? -1,
          pathRevision: active?.revision ?? "invalid-revision",
          progressRevision: context.persistenceProgressRevision,
          operationId,
        };
      }),
      acceptHydratedProgress: assign(({ context, event }) => {
        const persisted = persistenceSnapshotFromEvent(event)?.context;
        const loadResult = persisted?.loadResult;
        if (!persisted || !loadResult) return {};
        return {
          hydratedProgressContext: loadResult.context,
          lastPersistenceFailure: persisted.lastFailure,
          lastPersistenceOperationId: persisted.pendingWrite?.operationId
            ?? context.lastPersistenceOperationId,
        };
      }),
      prepareInteractiveBindings: ({ context }) => {
        const active = context.activeExperience;
        if (!active) throw new Error("Interactive bindings require an active experience.");
        const runtime = dependencies.createSceneRuntimeInput(active);
        const pathOrchestrationBinding = dependencies.createPathOrchestrationBinding(active);
        sceneRuntimeInputBySessionRevision.clear();
        sceneRuntimeInputBySessionRevision.set(active.sessionRevision, runtime);
        pathOrchestrationBindingBySessionRevision.clear();
        pathOrchestrationBindingBySessionRevision.set(
          active.sessionRevision,
          pathOrchestrationBinding,
        );
      },
      recordPersistenceFailure: assign(({ event }) => ({
        lastPersistenceFailure:
          persistenceSnapshotFromEvent(event)?.context.lastFailure ?? null,
      })),
      recordReconciliationFailure: assign(({ event }) => ({
        degradedReason: typeof event === "object" && event !== null && "error" in event
          ? `Progress scene reconciliation failed: ${String(event.error)}`
          : "Progress scene reconciliation failed.",
      })),
      bindPathOrchestrationActor: ({ self }) => {
        const actor = self.getSnapshot().children.pathOrchestration as
          | PathOrchestrationActor
          | undefined;
        if (actor) resolveActivePathOrchestrationBinding().bindActor(actor);
      },
      unbindPathOrchestrationActor: ({ self }) => {
        const binding = [...pathOrchestrationBindingBySessionRevision.values()][0];
        const actor = self.getSnapshot().children.pathOrchestration as
          | PathOrchestrationActor
          | undefined;
        binding?.unbindActor(actor);
      },
      activateExperience: assign(({ context, event }) => {
        const page = pageContextFromEvent(event);
        if (!page?.revision || !page.transactionId || !page.compiledPath) return {};
        const next: ActiveExperienceIdentity = Object.freeze({
          revision: page.revision,
          transactionId: page.transactionId,
          initialNodeId: page.compiledPath.initialNodeId,
          sessionRevision: context.activationCount + 1,
          launchMode: context.pendingLaunchMode,
          progressStorageKey: context.pendingProgressStorageKey
            ?? `learning-path-progress:${page.revision}`,
        });
        experienceBySessionRevision.clear();
        experienceBySessionRevision.set(next.sessionRevision, next);
        sceneRuntimeInputBySessionRevision.clear();
        pathOrchestrationBindingBySessionRevision.clear();
        return {
          generationTransactionId: page.transactionId,
          generationRevision: page.revision,
          activeExperience: next,
          activationCount: context.activationCount + 1,
          pendingLaunchMode: next.launchMode,
          pendingProgressStorageKey: next.progressStorageKey,
          hydratedProgressContext: null,
          persistenceProgressRevision: 0,
          pendingPersistenceOperationId: null,
          lastPersistenceOperationId: null,
          lastCompletedPersistenceOperationId: null,
          lastPersistenceFailure: null,
          pendingLearningResourceLaunch: null,
          lastDispatchedJourneyTransactionId: null,
          lastRoutedGatewayAckSequence: 0,
          lastGenerationFailure: null,
          degradedReason: null,
        };
      }),
      recordGenerationFailure: assign(({ event }) => ({
        generationTransactionId: pageContextFromEvent(event)?.transactionId ?? null,
        generationRevision: pageContextFromEvent(event)?.revision ?? null,
        lastGenerationFailure: pageContextFromEvent(event)?.lastError ?? null,
      })),
      observePageSnapshot: assign(({ event }) => {
        const page = pageContextFromEvent(event);
        return page
          ? {
              generationTransactionId: page.transactionId,
              generationRevision: page.revision,
            }
          : {};
      }),
      recordIgnoredEvent: assign(({ context, event }) => ({
        ignoredEventCount: context.ignoredEventCount + 1,
        lastIgnoredEvent: ignoredEventDiagnostic(context, event),
      })),
      recordDegraded: assign(({ event }) => ({
        degradedReason: event.type === "APP.RUNTIME.DEGRADED"
          ? event.reason
          : "runtime-degraded",
      })),
      clearDegraded: assign({ degradedReason: null }),
      resetApplication: assign(() => {
        experienceBySessionRevision.clear();
        sceneRuntimeInputBySessionRevision.clear();
        pathOrchestrationBindingBySessionRevision.clear();
        compiledPathByRevision.clear();
        return {
          activeExperience: null,
          pendingLaunchMode: "generate",
          pendingProgressStorageKey: null,
          hydratedProgressContext: null,
          persistenceProgressRevision: 0,
          pendingPersistenceOperationId: null,
          lastPersistenceOperationId: null,
          lastCompletedPersistenceOperationId: null,
          lastPersistenceFailure: null,
          pendingLearningResourceLaunch: null,
          generationTransactionId: null,
          generationRevision: null,
          lastDispatchedJourneyTransactionId: null,
          lastRoutedGatewayAckSequence: 0,
          lastGenerationFailure: null,
          degradedReason: null,
        };
      }),
    },
  }).createMachine({
    id: "learning-path-application",
    initial: "gate",
    context: ({ input }) => ({
      pageGenerationInput: Object.freeze({ ...input }),
      generationTransactionId: null,
      generationRevision: null,
      activeExperience: null,
      activationCount: 0,
      pendingLaunchMode: "generate",
      pendingProgressStorageKey: null,
      hydratedProgressContext: null,
      persistenceProgressRevision: 0,
      pendingPersistenceOperationId: null,
      lastPersistenceOperationId: null,
      lastCompletedPersistenceOperationId: null,
      lastPersistenceFailure: null,
      pendingLearningResourceLaunch: null,
      lastDispatchedJourneyTransactionId: null,
      lastRoutedGatewayAckSequence: 0,
      lastGenerationFailure: null,
      degradedReason: null,
      ignoredEventCount: 0,
      lastIgnoredEvent: null,
    }),
    invoke: {
      id: "pageGeneration",
      src: "pageGeneration",
      input: ({ context }) => context.pageGenerationInput,
      onSnapshot: [
        {
          guard: "pageSnapshotIsNewReadyExperience",
          target: ".active",
          actions: "activateExperience",
        },
        {
          guard: "pageSnapshotHasNewFailure",
          target: ".generationFailed",
          actions: "recordGenerationFailure",
        },
        { actions: "observePageSnapshot" },
      ],
    },
    on: {
      "APP.PAGE.EVENT": [
        { guard: "pageEventMatchesGeneration", actions: "routePageEvent" },
        { actions: "recordIgnoredEvent" },
      ],
      "APP.RUNTIME.DEGRADED": [
        {
          guard: "degradationMatches",
          target: ".degraded",
          actions: "recordDegraded",
        },
        { actions: "recordIgnoredEvent" },
      ],
      "APP.RESET": {
        target: ".gate",
        actions: "resetApplication",
      },
    },
    states: {
      gate: {
        on: {
          "APP.GENERATE.REQUESTED": {
            target: "generating",
            actions: ["recordLaunchRequest", "sendGenerateRequest"],
          },
          "APP.GENERATE.RETRY_REQUESTED": {
            target: "generating",
            actions: "sendGenerateRetry",
          },
          "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
          "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
          "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
          "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
          "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
        },
      },
      generating: {
        on: {
          "APP.GENERATE.REQUESTED": { actions: "sendGenerateRequest" },
          "APP.GENERATE.RETRY_REQUESTED": { actions: "sendGenerateRetry" },
          "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
          "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
          "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
          "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
          "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
        },
      },
      active: {
        initial: "hydrating",
        exit: "unbindPathOrchestrationActor",
        invoke: {
          id: "persistence",
          src: "persistence",
          input: ({ context }) => {
            const active = context.activeExperience;
            if (!active) throw new Error("Persistence requires an active experience.");
            return {
              storageKey: active.progressStorageKey
                || dependencies.resolveLearningProgressStorageKey?.(active)
                || `learning-path-progress:${active.revision}`,
              sessionRevision: active.sessionRevision,
              pathRevision: active.revision,
              fallbackContext: createRevisionInitialProgressContext(
                (revision) => {
                  const path = compiledPathByRevision.get(revision);
                  if (!path) {
                    throw new Error(
                      `No progression model registered for persistence revision "${revision}".`,
                    );
                  }
                  return path;
                },
                active.revision,
              ),
              fallbackSafeNodeId: active.initialNodeId,
              loadOperationId:
                `persistence-load:${active.sessionRevision}:${active.revision}`,
              debounceMs: dependencies.persistenceDebounceMs,
            };
          },
          onSnapshot: [
            {
              guard: "persistenceLoadedForActiveExperience",
              actions: "acceptHydratedProgress",
            },
            {
              guard: "persistenceCompletedPendingLearningResourceLaunch",
              actions: [
                "recordCompletedPersistenceOperation",
                "routePersistedLearningResourceLaunch",
                "clearPendingLearningResourceLaunch",
              ],
            },
            {
              guard: "persistenceSnapshotHasNewCompletion",
              actions: "recordCompletedPersistenceOperation",
            },
            {
              guard: "persistenceSnapshotHasNewFailure",
              actions: "recordPersistenceFailure",
            },
          ],
        },
        on: {
          "APP.GENERATE.REQUESTED": {
            target: ".draining",
            actions: ["recordLaunchRequest", "flushPersistence", "sendGenerateRequest"],
          },
          "APP.GENERATE.RETRY_REQUESTED": {
            target: ".draining",
            actions: ["flushPersistence", "sendGenerateRetry"],
          },
          "APP.PERSISTENCE.FLUSH.REQUESTED": [
            { guard: "experienceRevisionMatches", actions: "flushPersistence" },
            { actions: "recordIgnoredEvent" },
          ],
        },
        states: {
          draining: {
            on: {
              "APP.GENERATE.REQUESTED": {
                actions: ["recordLaunchRequest", "flushPersistence", "sendGenerateRequest"],
              },
              "APP.GENERATE.RETRY_REQUESTED": {
                actions: ["flushPersistence", "sendGenerateRetry"],
              },
              "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
              "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
              "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
              "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
              "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
              "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
              "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
              "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
            },
          },
          hydrating: {
            always: {
              guard: "hasHydratedProgress",
              target: "reconciling",
            },
            on: {
              "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
              "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
              "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
              "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
              "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
              "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
              "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
              "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
            },
          },
          reconciling: {
            invoke: {
              id: "reconcileRestoredProgress",
              src: "reconcileRestoredProgress",
              input: ({ context }) => {
                const active = context.activeExperience;
                const restored = context.hydratedProgressContext;
                if (!active || !restored) {
                  throw new Error("Restored progress reconciliation requires hydrated progress.");
                }
                return {
                  identity: active,
                  safeNodeId: restored.currentNodeId,
                };
              },
              onDone: {
                guard: "reconciliationMatchesActiveExperience",
                actions: "prepareInteractiveBindings",
                target: "interactive",
              },
              onError: {
                actions: "recordReconciliationFailure",
                target: "#learning-path-application.degraded",
              },
            },
            on: {
              "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
              "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
              "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
              "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
              "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
              "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
              "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
              "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
            },
          },
          interactive: {
            invoke: [
              {
                id: "progress",
                src: "progress",
                input: ({ context }) => ({
                  revision: context.activeExperience?.revision ?? "invalid-revision",
                  initialContext: context.hydratedProgressContext ?? undefined,
                }),
                onSnapshot: [
                  {
                    guard: "progressSnapshotHasPendingPersistenceSave",
                    actions: [
                      "persistProgressSnapshot",
                      "recordPersistenceSaveDispatch",
                      "routeProgressCelebrationCount",
                    ],
                  },
                  { actions: "routeProgressCelebrationCount" },
                ],
              },
              {
                id: "journey",
                src: "journey",
                input: ({ context }) => ({
                  currentNodeId: context.hydratedProgressContext?.currentNodeId
                    ?? context.activeExperience?.initialNodeId
                    ?? "invalid-node",
                }),
                onSnapshot: [
                  {
                    guard: "journeyReadyRequiresNavigation",
                    actions: ["recordJourneyDispatch", "routeJourneyNavigation"],
                  },
                  {
                    guard: "journeyReadyIsAlreadyAtTarget",
                    actions: [
                      "recordJourneyDispatch",
                      "beginSettledJourney",
                      "arriveSettledJourney",
                      "visuallySettleJourney",
                    ],
                  },
                ],
              },
              {
                id: "nodeCard",
                src: "nodeCard",
                input: {},
              },
              {
                id: "completionCelebration",
                src: "completionCelebration",
                input: ({ context }) => ({
                  restoredCount: context.hydratedProgressContext?.celebrationCount ?? 0,
                }),
              },
              {
                id: "sceneSession",
                src: "sceneSession",
                input: ({ context }) => {
                  const active = context.activeExperience;
                  if (!active) throw new Error("Scene session requires an active experience.");
                  const runtime = sceneRuntimeInputBySessionRevision.get(active.sessionRevision);
                  if (!runtime) {
                    throw new Error(
                      `No runtime input registered for scene session ${active.sessionRevision}.`,
                    );
                  }
                  return {
                    sessionRevision: active.sessionRevision,
                    runtimePort: runtime.port,
                    gatewayTimeoutMs: runtime.defaultTimeoutMs,
                    gatewayScheduler: runtime.scheduler,
                  };
                },
                onSnapshot: [
                  {
                    guard: "sceneSessionSnapshotHasNewMappableGatewayAck",
                    actions: ["routeSceneRuntimeAck", "recordSceneRuntimeAckSequence"],
                  },
                  {
                    guard: "sceneSessionSnapshotHasNewGatewayAck",
                    actions: "recordSceneRuntimeAckSequence",
                  },
                ],
              },
              {
                id: "learningResource",
                src: "learningResource",
                input: ({ context }) => ({
                  sessionRevision: context.activeExperience?.sessionRevision ?? -1,
                }),
              },
              {
                id: "pathOrchestration",
                src: "pathOrchestration",
                // The binding reflects the reconciled physical scene. In open mode,
                // browsing position may differ from learning progress.
                input: () => resolveActivePathOrchestrationBinding().input,
                onSnapshot: {
                  actions: "bindPathOrchestrationActor",
                },
              },
            ],
            on: {
              "APP.PROGRESS.EVENT": [
                {
                  guard: "stableProgressEventMatchesExperience",
                  actions: ["armStablePersistenceSave", "routeProgressEvent"],
                },
                { guard: "experienceRevisionMatches", actions: "routeProgressEvent" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.COMPLETION_CELEBRATION.EVENT": [
                { guard: "experienceRevisionMatches", actions: "routeCompletionCelebrationEvent" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.JOURNEY.EVENT": [
                { guard: "experienceRevisionMatches", actions: "routeJourneyEvent" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.NODE_CARD.EVENT": [
                { guard: "experienceRevisionMatches", actions: "routeNodeCardEvent" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.SCENE_RUNTIME.COMMAND": [
                { guard: "experienceRevisionMatches", actions: "routeSceneRuntimeCommand" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.SCENE_SESSION.EVENT": [
                { guard: "experienceRevisionMatches", actions: "routeSceneSessionEvent" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.LEARNING_RESOURCE.EVENT": [
                { guard: "experienceRevisionMatches", actions: "routeLearningResourceEvent" },
                { actions: "recordIgnoredEvent" },
              ],
              "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": [
                {
                  guard: "deferredLearningResourceLaunchAlreadyPersisted",
                  actions: "routeAlreadyPersistedLearningResourceLaunch",
                },
                {
                  guard: "experienceRevisionMatches",
                  actions: ["queueLearningResourceAfterPersistence", "flushPersistence"],
                },
                { actions: "recordIgnoredEvent" },
              ],
            },
          },
        },
      },
      generationFailed: {
        on: {
          "APP.GENERATE.REQUESTED": {
            target: "generating",
            actions: ["recordLaunchRequest", "sendGenerateRequest"],
          },
          "APP.GENERATE.RETRY_REQUESTED": {
            target: "generating",
            actions: "sendGenerateRetry",
          },
          "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
          "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
          "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
          "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
          "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
        },
      },
      degraded: {
        on: {
          "APP.RUNTIME.RECOVERED": [
            {
              guard: "recoveryMatches",
              target: "active",
              actions: "clearDegraded",
            },
            { actions: "recordIgnoredEvent" },
          ],
          "APP.GENERATE.REQUESTED": {
            target: "generating",
            actions: ["recordLaunchRequest", "sendGenerateRequest"],
          },
          "APP.GENERATE.RETRY_REQUESTED": {
            target: "generating",
            actions: "sendGenerateRetry",
          },
          "APP.PROGRESS.EVENT": { actions: "recordIgnoredEvent" },
          "APP.JOURNEY.EVENT": { actions: "recordIgnoredEvent" },
          "APP.NODE_CARD.EVENT": { actions: "recordIgnoredEvent" },
          "APP.COMPLETION_CELEBRATION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.SCENE_RUNTIME.COMMAND": { actions: "recordIgnoredEvent" },
          "APP.SCENE_SESSION.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.EVENT": { actions: "recordIgnoredEvent" },
          "APP.LEARNING_RESOURCE.AFTER_PERSISTENCE.REQUESTED": { actions: "recordIgnoredEvent" },
        },
      },
    },
  });
}

export type LearningPathApplicationMachine = ReturnType<
  typeof createLearningPathApplicationMachine
>;
export type LearningPathApplicationSnapshot = SnapshotFrom<LearningPathApplicationMachine>;

export function createLearningPathApplicationActor(
  dependencies: LearningPathApplicationDependencies,
  options: CreateLearningPathApplicationActorOptions = {},
) {
  const actor = createActor(createLearningPathApplicationMachine(dependencies), {
    input: options.input ?? {},
    ...(options.inspect ? { inspect: options.inspect } : {}),
  });
  actor.start();
  return actor;
}
