import type { InspectionEvent, Observer } from "xstate";

export const XSTATE_INSPECT_QUERY_PARAMETER = "xstate-inspect";

export interface LearningPathXStateInspector {
  readonly inspect: Observer<InspectionEvent>;
  start(): void;
  stop(): void;
}

/**
 * Loads the official Stately Inspector only for an explicit development URL.
 * Keeping the package behind a dynamic import avoids adding its transport and
 * serializer code to the normal learning-path startup chunk.
 */
export async function createLearningPathXStateInspector(
  search: string,
): Promise<LearningPathXStateInspector | null> {
  const enabled = import.meta.env.DEV
    && new URLSearchParams(search).get(XSTATE_INSPECT_QUERY_PARAMETER) === "1";
  if (!enabled) return null;

  const { createBrowserInspector } = await import("@statelyai/inspect");
  const inspector = createBrowserInspector({
    autoStart: false,
    maxDeferredEvents: 2_000,
    serializationDepthLimit: 8,
  });
  return Object.freeze({
    inspect: inspector.inspect,
    start: () => inspector.start(),
    stop: () => inspector.stop(),
  });
}
