import {
  GENERATION_GATE_EVENT,
  type GenerateRequestedEventDetail,
  type GenerationGateViewModel,
  type LearningPathGateAction,
} from "./GenerationGateContracts";
import {
  acquireLearningPathUIStyles,
  dispatchViewEvent,
  nowTimestamp,
} from "./domViewUtils";

export interface GenerationGateViewOptions {
  readonly onLaunchRequested?: (detail: GenerateRequestedEventDetail) => void;
}

/** Explicit first-screen choice between a new, continued or reset path. */
export class GenerationGateView {
  private readonly document: Document;
  private readonly root: HTMLDivElement;
  private readonly title: HTMLHeadingElement;
  private readonly buttons: Readonly<Record<LearningPathGateAction, HTMLButtonElement>>;
  private readonly error: HTMLParagraphElement;
  private readonly releaseStyles: () => void;
  private readonly onLaunchRequested?: (detail: GenerateRequestedEventDetail) => void;
  private disposed = false;

  public constructor(
    mount: HTMLElement,
    options: GenerationGateViewOptions = {},
  ) {
    this.document = mount.ownerDocument;
    this.releaseStyles = acquireLearningPathUIStyles(this.document);
    this.onLaunchRequested = options.onLaunchRequested;

    this.root = this.document.createElement("div");
    this.root.className = "lp-ui-generation-gate";
    this.root.dataset.phase = "ready";
    this.root.setAttribute("role", "dialog");
    this.root.setAttribute("aria-labelledby", `learning-path-gate-title-${GenerationGateView.nextId}`);
    this.root.setAttribute("aria-modal", "true");

    const panel = this.document.createElement("section");
    panel.className = "lp-ui-generation-gate__panel";
    this.title = this.document.createElement("h1");
    this.title.className = "lp-ui-generation-gate__title";
    this.title.id = `learning-path-gate-title-${GenerationGateView.nextId}`;
    this.title.textContent = "选择学习路径";
    const description = this.document.createElement("p");
    description.className = "lp-ui-generation-gate__description";
    description.textContent = "创建一条新路径、接着上次进度，或清空当前路径重新开始。";
    const actionGroup = this.document.createElement("div");
    actionGroup.className = "lp-ui-generation-gate__actions";
    const createButton = (
      action: LearningPathGateAction,
      label: string,
      tone: "primary" | "secondary" | "quiet",
    ): HTMLButtonElement => {
      const button = this.document.createElement("button");
      button.className = "lp-ui-generation-gate__button";
      button.dataset.action = action;
      button.dataset.tone = tone;
      button.type = "button";
      button.textContent = label;
      button.addEventListener("click", this.handleLaunchRequest);
      return button;
    };
    this.buttons = Object.freeze({
      generate: createButton("generate", "生成学习路径", "primary"),
      continue: createButton("continue", "继续学习路径", "secondary"),
      reset: createButton("reset", "重置学习路径", "quiet"),
    });
    actionGroup.append(
      this.buttons.generate,
      this.buttons.continue,
      this.buttons.reset,
    );

    this.error = this.document.createElement("p");
    this.error.className = "lp-ui-generation-gate__error";
    this.error.id = `learning-path-generation-error-${GenerationGateView.nextId++}`;
    this.error.setAttribute("role", "alert");
    this.error.hidden = true;

    panel.append(this.title, description, actionGroup, this.error);
    this.root.append(panel);
    mount.append(this.root);
  }

  public setViewModel(viewModel: GenerationGateViewModel): void {
    if (this.disposed) return;

    const isBusy = viewModel.phase === "requested" || viewModel.phase === "generating";
    const isHidden = viewModel.phase === "hidden" || isBusy;
    const isError = viewModel.phase === "error";
    const fallbackLabel = isBusy
      ? "正在生成学习路径…"
      : isError
        ? "重新生成学习路径"
        : "生成学习路径";

    this.root.hidden = isHidden;
    this.root.dataset.phase = viewModel.phase;
    this.root.setAttribute("aria-busy", String(isBusy));
    Object.values(this.buttons).forEach((button) => {
      button.disabled = isBusy;
    });
    this.buttons.continue.disabled = isBusy || viewModel.canContinue !== true;
    this.buttons.generate.textContent = viewModel.buttonLabel?.trim() || fallbackLabel;
    this.buttons.continue.textContent = "继续学习路径";
    this.buttons.reset.textContent = "重置学习路径";

    const errorMessage = isError ? viewModel.errorMessage?.trim() ?? "生成失败，请重试。" : "";
    this.error.hidden = errorMessage.length === 0;
    if (this.error.textContent !== errorMessage) this.error.textContent = errorMessage;
    if (errorMessage.length > 0) {
      Object.values(this.buttons).forEach((button) => {
        button.setAttribute("aria-describedby", this.error.id);
      });
    } else {
      Object.values(this.buttons).forEach((button) => {
        button.removeAttribute("aria-describedby");
      });
    }

    if (!isHidden && !isBusy) {
      this.document.defaultView?.requestAnimationFrame(() => {
        if (!this.disposed && !this.root.hidden) {
          const target = viewModel.canContinue
            ? this.buttons.continue
            : this.buttons.generate;
          target.focus({ preventScroll: true });
        }
      });
    }
  }

  public focus(): void {
    if (!this.disposed && !this.root.hidden) {
      const target = this.buttons.continue.disabled
        ? this.buttons.generate
        : this.buttons.continue;
      target.focus({ preventScroll: true });
    }
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    Object.values(this.buttons).forEach((button) => {
      button.removeEventListener("click", this.handleLaunchRequest);
    });
    this.root.remove();
    this.releaseStyles();
  }

  private readonly handleLaunchRequest = (event: Event): void => {
    const button = event.currentTarget;
    if (this.disposed || !(button instanceof HTMLButtonElement) || button.disabled) return;
    const action = button.dataset.action as LearningPathGateAction | undefined;
    if (action !== "generate" && action !== "continue" && action !== "reset") return;

    const detail: GenerateRequestedEventDetail = Object.freeze({
      type: "path.launch",
      action,
      source: "generation-gate",
      occurredAt: nowTimestamp(this.document),
    });
    const launchEvent = dispatchViewEvent(
      this.root,
      this.document,
      GENERATION_GATE_EVENT,
      detail,
    );
    if (launchEvent.defaultPrevented) return;

    Object.values(this.buttons).forEach((candidate) => {
      candidate.disabled = true;
    });
    this.root.dataset.phase = "requested";
    this.root.setAttribute("aria-busy", "true");
    button.textContent = action === "continue"
      ? "正在恢复学习路径…"
      : action === "reset"
        ? "正在重置学习路径…"
        : "正在生成学习路径…";
    this.root.hidden = true;
    this.onLaunchRequested?.(detail);
  };

  private static nextId = 1;
}
