export interface ActorSelectorSubscription {
  unsubscribe(): void;
}

export interface SelectableActor<TSnapshot> {
  getSnapshot(): TSnapshot;
  subscribe(listener: (snapshot: TSnapshot) => void): ActorSelectorSubscription;
}

export interface ActorSelectorOptions<TSelected> {
  /** Defaults to reference equality. */
  readonly equals?: (previous: TSelected, next: TSelected) => boolean;
  /** Emits the actor's current selection before listening for later changes. */
  readonly emitInitial?: boolean;
}

/**
 * Small framework boundary equivalent to React/XState selector subscriptions.
 * Consumers only wake when their selected slice changes according to the
 * supplied equality function; unrelated actor transitions remain invisible.
 */
export function subscribeActorSelector<TSnapshot, TSelected>(
  actor: SelectableActor<TSnapshot>,
  selector: (snapshot: TSnapshot) => TSelected,
  listener: (selected: TSelected, previous: TSelected | null) => void,
  options: ActorSelectorOptions<TSelected> = {},
): ActorSelectorSubscription {
  const equals = options.equals ?? Object.is;
  let selected = selector(actor.getSnapshot());
  if (options.emitInitial) listener(selected, null);

  return actor.subscribe((snapshot) => {
    const next = selector(snapshot);
    if (equals(selected, next)) return;
    const previous = selected;
    selected = next;
    listener(next, previous);
  });
}
