import type {
  ConceptProgressStatus,
  LearningProgressContext,
  NodeLearningState,
  SubjectProgressStatus,
} from "../domain/types";

export interface NodeLearningProjection {
  readonly goalNodeIds: readonly string[];
  readonly subjectStatusById: Readonly<Record<string, SubjectProgressStatus>>;
  readonly conceptStatusById: Readonly<Record<string, ConceptProgressStatus>>;
}

export interface NodeLearningPresentationChange {
  readonly nodeId: string;
  readonly learningState: NodeLearningState;
}

export type NodeLearningPresentationUpdate = Readonly<
  | {
      readonly type: "replace";
      readonly changes: readonly NodeLearningPresentationChange[];
    }
  | {
      readonly type: "patch";
      readonly changes: readonly NodeLearningPresentationChange[];
    }
>;

type ProgressSnapshotLike = Readonly<{
  context: Readonly<{
    model: LearningProgressContext;
  }>;
}>;

export function selectNodeLearningProjection(
  snapshot: ProgressSnapshotLike,
): NodeLearningProjection {
  const model = snapshot.context.model;
  return Object.freeze({
    goalNodeIds: model.goalNodeIds,
    subjectStatusById: model.subjectStatusById,
    conceptStatusById: model.conceptStatusById,
  });
}

function equalStatusRecord<TStatus extends string>(
  previous: Readonly<Record<string, TStatus>>,
  next: Readonly<Record<string, TStatus>>,
): boolean {
  if (previous === next) return true;
  const previousIds = Object.keys(previous);
  const nextIds = Object.keys(next);
  if (previousIds.length !== nextIds.length) return false;
  return previousIds.every((nodeId) => previous[nodeId] === next[nodeId]);
}

/** Ignores selection, cards, navigation decisions and every other UI field. */
export function areNodeLearningProjectionsEqual(
  previous: NodeLearningProjection,
  next: NodeLearningProjection,
): boolean {
  const sameGoalIds = previous.goalNodeIds === next.goalNodeIds
    || (
      previous.goalNodeIds.length === next.goalNodeIds.length
      && previous.goalNodeIds.every((nodeId, index) => nodeId === next.goalNodeIds[index])
    );
  return sameGoalIds
    && equalStatusRecord(previous.subjectStatusById, next.subjectStatusById)
    && equalStatusRecord(previous.conceptStatusById, next.conceptStatusById);
}

function sameNodeLearningState(
  previous: NodeLearningState | undefined,
  next: NodeLearningState,
): boolean {
  return previous?.kind === next.kind && previous.status === next.status;
}

/**
 * Stateful projection boundary for one generated path revision.
 *
 * The first projection is an explicit full replace. Later projections emit
 * only the k nodes whose renderer-facing kind/status changed. A projector is
 * deliberately revision-scoped: callers create a fresh instance whenever a
 * generated learning-path session is replaced.
 */
export class NodeLearningPatchProjector {
  private readonly presentedByNodeId = new Map<string, NodeLearningState>();
  private initialized = false;

  public project(projection: NodeLearningProjection): NodeLearningPresentationUpdate {
    const goalNodeIds = new Set(projection.goalNodeIds);
    const changes: NodeLearningPresentationChange[] = [];

    for (const [nodeId, status] of Object.entries(projection.subjectStatusById)) {
      const learningState = Object.freeze({
        kind: goalNodeIds.has(nodeId) ? "goal" : "subject",
        status,
      }) as NodeLearningState;
      if (!this.initialized || !sameNodeLearningState(this.presentedByNodeId.get(nodeId), learningState)) {
        this.presentedByNodeId.set(nodeId, learningState);
        changes.push(Object.freeze({ nodeId, learningState }));
      }
    }
    for (const [nodeId, status] of Object.entries(projection.conceptStatusById)) {
      const learningState = Object.freeze({ kind: "concept", status }) as NodeLearningState;
      if (!this.initialized || !sameNodeLearningState(this.presentedByNodeId.get(nodeId), learningState)) {
        this.presentedByNodeId.set(nodeId, learningState);
        changes.push(Object.freeze({ nodeId, learningState }));
      }
    }

    const type = this.initialized ? "patch" : "replace";
    this.initialized = true;
    return Object.freeze({ type, changes: Object.freeze(changes) });
  }
}
