export type ContextualCardNodeKind = "subject" | "concept";
export type ContextualCardTone = "green" | "brown" | "gray";
export type ContextualCardActionSlot = "primary" | "secondary";

/**
 * This is deliberately a presentation contract. Progression policy decides
 * whether an action exists, its label and whether it is enabled before the
 * view receives it.
 */
export interface ContextualCardActionViewModel {
  readonly id: string;
  readonly label: string;
  readonly enabled?: boolean;
  readonly busy?: boolean;
  readonly ariaLabel?: string;
}

export interface ContextualNodeCardViewModel {
  /** Correlates a click with the exact card render that produced it. */
  readonly instanceId: string;
  readonly nodeId: string;
  readonly kind: ContextualCardNodeKind;
  readonly tone: ContextualCardTone;
  readonly title: string;
  readonly description?: string;
  readonly eyebrow?: string;
  readonly statusLabel?: string;
  readonly visible?: boolean;
  readonly primaryAction?: ContextualCardActionViewModel;
  readonly secondaryAction?: ContextualCardActionViewModel;
}

/** Client-viewport coordinates; the view converts these into mount-local CSS pixels. */
export interface ContextualCardPlacement {
  readonly anchorClientX: number;
  readonly anchorClientY: number;
  readonly viewportRect?: Pick<DOMRectReadOnly, "left" | "top" | "width" | "height">;
  readonly gap?: number;
  readonly margin?: number;
}

/** Read-only viewport geometry used by the camera composition policy. */
export interface ContextualCardLayoutMetrics {
  readonly visible: boolean;
  readonly placed: boolean;
  readonly top: number;
  readonly bottom: number;
  readonly width: number;
  readonly height: number;
  readonly centerX: number;
}

export interface ContextualCardActionRequestedDetail {
  readonly type: "contextual-card.action";
  readonly source: "contextual-node-card";
  readonly instanceId: string;
  readonly nodeId: string;
  readonly actionId: string;
  readonly slot: ContextualCardActionSlot;
  readonly occurredAt: number;
}

export const CONTEXTUAL_CARD_EVENT = Object.freeze({
  actionRequested: "learning-path:contextual-card-action",
} as const);

export interface CompletionCelebrationViewModel {
  /** Monotonic value owned by progression state; equal values never replay. */
  readonly playCount: number;
  readonly title: string;
  readonly message?: string;
  readonly reducedMotion?: boolean;
  readonly visible?: boolean;
}

export interface CompletionCelebrationSettledDetail {
  readonly type: "completion-celebration.settled";
  readonly playCount: number;
  readonly occurredAt: number;
}

export const COMPLETION_CELEBRATION_EVENT = Object.freeze({
  settled: "learning-path:completion-celebration-settled",
} as const);
