import {
  assign,
  setup,
  type SnapshotFrom,
} from "xstate";
import type {
  NodeCardCloseDiagnostic,
  NodeCardContext,
  NodeCardEvent,
  NodeCardMachineInput,
} from "./types";
import { isNodeCardActionId } from "./types";

function normalizeInitialRevision(value: number | undefined): number {
  if (value === undefined || !Number.isFinite(value)) return 0;
  return Math.max(0, Math.trunc(value));
}

function matchesCurrentInstance(
  context: NodeCardContext,
  event: NodeCardEvent,
): boolean {
  if (event.type !== "NODE_CARD.DISMISS"
    && event.type !== "NODE_CARD.ACTION_REQUESTED") return false;
  return context.nodeId !== null
    && event.instance.nodeId === context.nodeId
    && event.instance.revision === context.revision;
}

function isAcceptedActionRequest(
  context: NodeCardContext,
  event: NodeCardEvent,
): boolean {
  return event.type === "NODE_CARD.ACTION_REQUESTED"
    && event.enabled !== false
    && isNodeCardActionId(event.actionId)
    && matchesCurrentInstance(context, event);
}

export const nodeCardMachine = setup({
  types: {} as {
    context: NodeCardContext;
    events: NodeCardEvent;
    input: NodeCardMachineInput;
  },
  guards: {
    targetsCurrentInstance: ({ context, event }) => (
      matchesCurrentInstance(context, event)
    ),
    acceptsActionRequest: ({ context, event }) => (
      isAcceptedActionRequest(context, event)
    ),
  },
  actions: {
    openCard: assign(({ context, event }) => {
      if (event.type !== "NODE_CARD.PIN" && event.type !== "NODE_CARD.REOPEN") {
        return {};
      }
      return {
        nodeId: event.nodeId,
        revision: context.revision + 1,
      };
    }),
    dismissCard: assign(({ event }) => {
      if (event.type !== "NODE_CARD.DISMISS") return {};
      const lastClose: NodeCardCloseDiagnostic = Object.freeze({
        ...event.instance,
        reason: "dismiss",
        actionId: null,
      });
      return { nodeId: null, lastClose };
    }),
    closeForAction: assign(({ event }) => {
      if (event.type !== "NODE_CARD.ACTION_REQUESTED"
        || !isNodeCardActionId(event.actionId)) return {};
      const lastAction = Object.freeze({
        ...event.instance,
        actionId: event.actionId,
      });
      const lastClose: NodeCardCloseDiagnostic = Object.freeze({
        ...event.instance,
        reason: "action-requested",
        actionId: event.actionId,
      });
      return {
        nodeId: null,
        lastAction,
        lastClose,
      };
    }),
    resetSession: assign(({ context }) => {
      if (context.nodeId === null) return {};
      const lastClose: NodeCardCloseDiagnostic = Object.freeze({
        nodeId: context.nodeId,
        revision: context.revision,
        reason: "session-reset",
        actionId: null,
      });
      return { nodeId: null, lastClose };
    }),
  },
}).createMachine({
  id: "nodeCard",
  initial: "hidden",
  context: ({ input }) => ({
    nodeId: null,
    revision: normalizeInitialRevision(input.initialRevision),
    lastClose: null,
    lastAction: null,
  }),
  states: {
    hidden: {
      on: {
        "NODE_CARD.PIN": {
          actions: "openCard",
          target: "visible",
        },
        "NODE_CARD.REOPEN": {
          actions: "openCard",
          target: "visible",
        },
      },
    },
    visible: {
      on: {
        "NODE_CARD.PIN": {
          actions: "openCard",
        },
        "NODE_CARD.REOPEN": {
          actions: "openCard",
        },
        "NODE_CARD.DISMISS": {
          guard: "targetsCurrentInstance",
          actions: "dismissCard",
          target: "hidden",
        },
        "NODE_CARD.ACTION_REQUESTED": {
          guard: "acceptsActionRequest",
          actions: "closeForAction",
          target: "hidden",
        },
        "SESSION.RESET": {
          actions: "resetSession",
          target: "hidden",
        },
      },
    },
  },
});

export type NodeCardMachine = typeof nodeCardMachine;
export type NodeCardMachineSnapshot = SnapshotFrom<NodeCardMachine>;
