const DANGEROUS_JSON_KEYS = new Set(["__proto__", "constructor", "prototype"]);

export function assertPlainJsonRecord(
  value: unknown,
  path: string,
): asserts value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${path} 必须是普通 JSON 对象。`);
  }
  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError(`${path} 不能包含类实例或自定义原型。`);
  }
}

export function assertExactJsonKeys(
  value: Record<string, unknown>,
  allowed: readonly string[],
  path: string,
): void {
  const allowedKeys = new Set(allowed);
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string" || !allowedKeys.has(key)) {
      throw new TypeError(`${path} 包含未列入白名单的字段 ${String(key)}。`);
    }
  }
}

export function readJsonDataProperty(
  value: Record<string, unknown>,
  key: string,
  path: string,
): unknown {
  const descriptor = Object.getOwnPropertyDescriptor(value, key);
  if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) {
    throw new TypeError(`${path}.${key} 必须是可枚举的数据属性。`);
  }
  return descriptor.value;
}

/**
 * Copies only RFC 8259-compatible data properties. Accessors, functions,
 * symbols, sparse arrays, cycles and special object prototypes are rejected.
 */
export function cloneLearningPathJsonData(input: unknown): unknown {
  const ancestors = new WeakSet<object>();

  const visit = (value: unknown, path: string): unknown => {
    if (value === null || typeof value === "string" || typeof value === "boolean") return value;
    if (typeof value === "number") {
      if (!Number.isFinite(value)) throw new TypeError(`${path} 包含非有限数值。`);
      return value;
    }
    if (typeof value !== "object") throw new TypeError(`${path} 不是合法 JSON 值。`);
    if (ancestors.has(value)) throw new TypeError(`${path} 包含循环引用。`);
    ancestors.add(value);

    try {
      if (Array.isArray(value)) {
        const keys = Reflect.ownKeys(value);
        for (const key of keys) {
          if (key === "length") continue;
          if (typeof key !== "string" || !/^(?:0|[1-9]\d*)$/.test(key)) {
            throw new TypeError(`${path} 包含非 JSON 数组字段 ${String(key)}。`);
          }
        }
        const clone: unknown[] = [];
        for (let index = 0; index < value.length; index += 1) {
          const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
          if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) {
            throw new TypeError(`${path}[${index}] 必须是可枚举的数据属性。`);
          }
          clone.push(visit(descriptor.value, `${path}[${index}]`));
        }
        return clone;
      }

      assertPlainJsonRecord(value, path);
      const clone: Record<string, unknown> = Object.create(null) as Record<string, unknown>;
      for (const key of Reflect.ownKeys(value)) {
        if (typeof key !== "string" || DANGEROUS_JSON_KEYS.has(key)) {
          throw new TypeError(`${path} 包含不安全字段 ${String(key)}。`);
        }
        const descriptor = Object.getOwnPropertyDescriptor(value, key);
        if (!descriptor || !("value" in descriptor) || !descriptor.enumerable) {
          throw new TypeError(`${path}.${key} 必须是可枚举的数据属性。`);
        }
        clone[key] = visit(descriptor.value, `${path}.${key}`);
      }
      return clone;
    } finally {
      ancestors.delete(value);
    }
  };

  return visit(input, "$document");
}
