import type {
  GenerationPresentationCommand,
  PageGenerationEvent,
} from "../statecharts/page/contracts";

export type PageGenerationPresentationResult = Extract<
  PageGenerationEvent,
  {
    readonly type:
      | "PAGE.PATH_STEP.SETTLED"
      | "PAGE.CHARACTER.SETTLED"
      | "PAGE.PRESENTATION.FAILED";
  }
>;

export type GenerationRevealOperation = (
  objectId: string,
  reducedMotion: boolean,
  signal?: AbortSignal,
) => void | PromiseLike<void>;

/**
 * Renderer-facing operations. Implementations may use Three.js, the DOM, or a
 * deterministic test double; this bridge deliberately knows nothing about any
 * of them.
 */
export interface PageGenerationPresentationPorts {
  readonly revealNode: GenerationRevealOperation;
  readonly revealEdge: GenerationRevealOperation;
  readonly revealCharacter: GenerationRevealOperation;
}

/**
 * Installed only after both the presentation surface and the page actor are
 * ready. Commands received before installation remain queued.
 */
export interface PageGenerationPresenterRuntime {
  readonly presentation: PageGenerationPresentationPorts;
  readonly send: (event: PageGenerationPresentationResult) => void;
}

interface QueuedPresentationCommand {
  readonly command: GenerationPresentationCommand;
  readonly key: string;
  readonly generation: number;
}

interface ActivePresentationCommand extends QueuedPresentationCommand {
  readonly controller: AbortController;
}

function commandKey(command: GenerationPresentationCommand): string {
  return `${command.transactionId}\u0000${command.revision}\u0000${command.token}`;
}

function snapshotCommand(
  command: GenerationPresentationCommand,
): GenerationPresentationCommand {
  if (command.type === "PAGE.PRESENTATION.REVEAL_PATH_STEP") {
    return Object.freeze({
      ...command,
      step: Object.freeze({ ...command.step }),
    });
  }
  return Object.freeze({ ...command });
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === "string") return error;
  return "Unknown page presentation failure.";
}

function resultFor(
  command: GenerationPresentationCommand,
): PageGenerationPresentationResult {
  if (command.type === "PAGE.PRESENTATION.REVEAL_PATH_STEP") {
    return Object.freeze({
      type: "PAGE.PATH_STEP.SETTLED",
      transactionId: command.transactionId,
      revision: command.revision,
      token: command.token,
    });
  }
  return Object.freeze({
    type: "PAGE.CHARACTER.SETTLED",
    transactionId: command.transactionId,
    revision: command.revision,
    token: command.token,
  });
}

function failureFor(
  command: GenerationPresentationCommand,
  error: unknown,
): PageGenerationPresentationResult {
  return Object.freeze({
    type: "PAGE.PRESENTATION.FAILED",
    transactionId: command.transactionId,
    revision: command.revision,
    token: command.token,
    error: errorMessage(error),
  });
}

/**
 * Serial presentation bridge for the page-generation machine.
 *
 * - `executePresentation` is safe to pass directly to PageGenerationServices.
 * - commands are snapshotted and deduplicated by transaction/revision/token;
 * - no command starts until the previous operation has settled;
 * - cancellation aborts cooperative adapters and suppresses stale ACKs;
 * - disposal permanently suppresses queued and in-flight results.
 */
export class PageGenerationPresenter {
  private readonly queue: QueuedPresentationCommand[] = [];
  private readonly pendingKeys = new Set<string>();
  private readonly finalizedKeys = new Set<string>();
  private runtime: PageGenerationPresenterRuntime | null = null;
  private active: ActivePresentationCommand | null = null;
  private generation = 0;
  private draining = false;
  private disposed = false;

  constructor(runtime?: PageGenerationPresenterRuntime) {
    if (runtime) this.runtime = runtime;
  }

  /** Stable callback suitable for `PageGenerationServices.executePresentation`. */
  readonly executePresentation = (command: GenerationPresentationCommand): void => {
    if (this.disposed) return;
    const key = commandKey(command);
    if (this.pendingKeys.has(key) || this.finalizedKeys.has(key)) return;

    this.pendingKeys.add(key);
    this.queue.push(Object.freeze({
      command: snapshotCommand(command),
      key,
      generation: this.generation,
    }));
    this.requestDrain();
  };

  /**
   * Atomically installs presentation operations and the actor event sink.
   * Replacing an installed runtime first cancels its outstanding generation so
   * an old adapter can never acknowledge a new actor.
   */
  installRuntime(runtime: PageGenerationPresenterRuntime): void {
    if (this.disposed) {
      throw new Error("Cannot install a runtime on a disposed PageGenerationPresenter.");
    }
    if (this.runtime && this.runtime !== runtime) this.cancel();
    this.runtime = runtime;
    this.requestDrain();
  }

  /**
   * Cancels queued work and suppresses the active operation's eventual result.
   * New commands are still accepted and remain serialized behind a
   * non-cooperative active adapter until its promise settles.
   */
  cancel(): void {
    if (this.disposed) return;
    this.generation += 1;
    this.active?.controller.abort();

    if (this.active) this.finalizeWithoutResult(this.active.key);
    for (const item of this.queue) this.finalizeWithoutResult(item.key);
    this.queue.length = 0;
  }

  /** Permanently cancels all work and releases the installed runtime. */
  dispose(): void {
    if (this.disposed) return;
    this.cancel();
    this.disposed = true;
    this.runtime = null;
  }

  get pendingCommandCount(): number {
    return this.queue.length + (this.active ? 1 : 0);
  }

  get isDisposed(): boolean {
    return this.disposed;
  }

  private requestDrain(): void {
    if (this.draining || this.disposed || !this.runtime) return;
    this.draining = true;
    void this.drain();
  }

  private async drain(): Promise<void> {
    try {
      while (!this.disposed && this.runtime && this.queue.length > 0) {
        const queued = this.queue.shift();
        if (!queued) continue;
        if (queued.generation !== this.generation || this.finalizedKeys.has(queued.key)) {
          this.finalizeWithoutResult(queued.key);
          continue;
        }

        const runtime = this.runtime;
        const controller = new AbortController();
        const active: ActivePresentationCommand = Object.freeze({
          ...queued,
          controller,
        });
        this.active = active;

        let result: PageGenerationPresentationResult;
        try {
          await this.perform(runtime.presentation, active.command, controller.signal);
          result = resultFor(active.command);
        } catch (error) {
          result = failureFor(active.command, error);
        }

        const remainsCurrent = !this.disposed
          && active.generation === this.generation
          && !controller.signal.aborted
          && this.runtime === runtime
          && !this.finalizedKeys.has(active.key);

        this.active = null;
        this.pendingKeys.delete(active.key);
        this.finalizedKeys.add(active.key);
        if (remainsCurrent) this.emit(runtime, result);
      }
    } finally {
      this.draining = false;
      if (!this.disposed && this.runtime && this.queue.length > 0) this.requestDrain();
    }
  }

  private perform(
    ports: PageGenerationPresentationPorts,
    command: GenerationPresentationCommand,
    signal: AbortSignal,
  ): void | PromiseLike<void> {
    const reduced = command.motionPreference === "reduced";
    if (command.type === "PAGE.PRESENTATION.REVEAL_CHARACTER") {
      return ports.revealCharacter(command.nodeId, reduced, signal);
    }
    if (command.step.kind === "node") {
      return ports.revealNode(command.step.nodeId, reduced, signal);
    }
    return ports.revealEdge(command.step.edgeId, reduced, signal);
  }

  private finalizeWithoutResult(key: string): void {
    this.pendingKeys.delete(key);
    this.finalizedKeys.add(key);
  }

  private emit(
    runtime: PageGenerationPresenterRuntime,
    result: PageGenerationPresentationResult,
  ): void {
    try {
      runtime.send(result);
    } catch {
      // Actor disposal may race the last animation frame. The page machine's
      // ACK timeout remains the recovery boundary; never leak an unhandled task.
    }
  }
}
