import type { JourneyContext, JourneyPhase } from "./types";

export interface JourneySnapshotLike {
  readonly context: JourneyContext;
  matches(state: JourneyPhase): boolean;
}

const PHASES: readonly JourneyPhase[] = Object.freeze([
  "idle",
  "planning",
  "ready",
  "moving",
  "settling",
  "rejected",
  "cancelled",
]);

export function selectJourneyPhase(snapshot: JourneySnapshotLike): JourneyPhase {
  return PHASES.find((phase) => snapshot.matches(phase)) ?? "idle";
}

export function selectJourneyIsActive(snapshot: JourneySnapshotLike): boolean {
  const phase = selectJourneyPhase(snapshot);
  return phase === "planning" || phase === "ready" || phase === "moving" || phase === "settling";
}

export function selectJourneyCanStartMovement(snapshot: JourneySnapshotLike): boolean {
  return snapshot.matches("ready") && snapshot.context.transactionId !== null;
}

export function selectJourneyTransactionId(snapshot: JourneySnapshotLike): string | null {
  return snapshot.context.transactionId;
}

export function selectJourneyPlan(snapshot: JourneySnapshotLike) {
  return snapshot.context.plan;
}

export function selectJourneyReachedNodeIds(snapshot: JourneySnapshotLike) {
  return snapshot.context.reachedNodeIds;
}

export function selectJourneyLastOutcome(snapshot: JourneySnapshotLike) {
  return snapshot.context.lastOutcome;
}

