import {
  assign,
  fromPromise,
  setup,
  type SnapshotFrom,
} from "xstate";
import type { LearningProgressContext } from "../domain/types";
import { restoreLearningProgress, serializeLearningProgress } from "./codec";
import type {
  LearningProgressPersistenceContext,
  LearningProgressPersistenceCorrelation,
  LearningProgressPersistenceEvent,
  LearningProgressPersistenceLoadResult,
  LearningProgressPersistenceMachineInput,
  LearningProgressPersistenceWriteOperation,
} from "./machineTypes";
import {
  normalizeLearningProgressStorageError,
  type LearningProgressStoragePort,
} from "./storagePort";

const DEFAULT_DEBOUNCE_MS = 250;
const MAX_SEEN_OPERATION_IDS = 128;

interface LoadRequest extends LearningProgressPersistenceCorrelation {
  readonly storageKey: string;
  readonly fallbackContext: LearningProgressContext;
  readonly fallbackSafeNodeId: string;
}

interface LoadActorResult {
  readonly correlation: LearningProgressPersistenceCorrelation;
  readonly loadResult: LearningProgressPersistenceLoadResult;
  readonly canonicalJson: string | null;
  readonly migrationWrite: LearningProgressPersistenceWriteOperation | null;
  readonly failure: LearningProgressPersistenceContext["lastFailure"];
}

interface WriteActorResult {
  readonly correlation: LearningProgressPersistenceCorrelation;
  readonly failure: LearningProgressPersistenceContext["lastFailure"];
}

function nonEmpty(value: string, label: string): string {
  const normalized = value.trim();
  if (normalized.length === 0) throw new TypeError(`${label} must be a non-empty string.`);
  return normalized;
}

function nonNegativeRevision(value: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${label} must be a non-negative safe integer.`);
  }
  return value;
}

function debounceDelay(value: number | undefined): number {
  if (value === undefined) return DEFAULT_DEBOUNCE_MS;
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError("debounceMs must be a non-negative safe integer.");
  }
  return value;
}

function correlationOf(
  value: LearningProgressPersistenceCorrelation,
): LearningProgressPersistenceCorrelation {
  return Object.freeze({
    sessionRevision: value.sessionRevision,
    pathRevision: value.pathRevision,
    progressRevision: value.progressRevision,
    operationId: value.operationId,
  });
}

function sameCorrelation(
  left: LearningProgressPersistenceCorrelation | null,
  right: LearningProgressPersistenceCorrelation | null,
): boolean {
  return left !== null
    && right !== null
    && left.sessionRevision === right.sessionRevision
    && left.pathRevision === right.pathRevision
    && left.progressRevision === right.progressRevision
    && left.operationId === right.operationId;
}

function resultFromDoneEvent<T>(event: unknown): T | null {
  if (typeof event !== "object" || event === null || !("output" in event)) return null;
  return (event as Readonly<{ output?: T }>).output ?? null;
}

function safeFallback(
  request: LoadRequest,
): LearningProgressContext {
  return restoreLearningProgress("", {
    pathRevision: request.pathRevision,
    fallbackContext: request.fallbackContext,
    fallbackSafeNodeId: request.fallbackSafeNodeId,
  }).context;
}

function saveOperationFromEvent(
  event: Extract<LearningProgressPersistenceEvent, { type: "PERSISTENCE.SAVE.REQUESTED" }>,
): LearningProgressPersistenceWriteOperation {
  return Object.freeze({
    ...correlationOf(event),
    serialized: serializeLearningProgress(event.context, {
      pathRevision: event.pathRevision,
      lastSafeNodeId: event.lastSafeNodeId,
    }),
  });
}

function appendSeenOperationId(
  values: readonly string[],
  operationId: string,
): readonly string[] {
  return Object.freeze([...values, operationId].slice(-MAX_SEEN_OPERATION_IDS));
}

/**
 * Focused persistence protocol. Debounce and cancellation are statechart
 * lifecycle concerns; the injected storage port and AbortSignals stay outside
 * JSON-safe Context.
 */
export function createLearningProgressPersistenceMachine(
  storage: LearningProgressStoragePort,
) {
  const loadProgress = fromPromise<LoadActorResult, LoadRequest>(async ({ input, signal }) => {
    try {
      const raw = await storage.read({ key: input.storageKey }, { signal });
      if (signal.aborted) throw new DOMException("Persistence read aborted.", "AbortError");
      const restored = restoreLearningProgress(raw ?? "", {
        pathRevision: input.pathRevision,
        fallbackContext: input.fallbackContext,
        fallbackSafeNodeId: input.fallbackSafeNodeId,
      });
      if (restored.status === "fallback") {
        return Object.freeze({
          correlation: correlationOf(input),
          loadResult: Object.freeze({
            status: "fallback" as const,
            context: restored.context,
            reason: restored.reason,
          }),
          canonicalJson: null,
          migrationWrite: null,
          failure: null,
        });
      }
      const canonicalJson = serializeLearningProgress(restored.context, {
        pathRevision: input.pathRevision,
        lastSafeNodeId: restored.document.lastSafeNodeId,
      });
      return Object.freeze({
        correlation: correlationOf(input),
        loadResult: Object.freeze({
          status: "restored" as const,
          context: restored.context,
          migratedFromVersion: restored.migratedFromVersion,
        }),
        canonicalJson,
        migrationWrite: restored.migratedFromVersion === 1
          ? Object.freeze({
            ...correlationOf({
              ...input,
              operationId: `${input.operationId}:migrate-v2`,
            }),
            serialized: canonicalJson,
          })
          : null,
        failure: null,
      });
    } catch (error: unknown) {
      const normalized = normalizeLearningProgressStorageError(error, "read-failed");
      const correlation = correlationOf(input);
      const fallback = safeFallback(input);
      return Object.freeze({
        correlation,
        loadResult: Object.freeze({
          status: "fallback" as const,
          context: fallback,
          reason: "read-error" as const,
        }),
        canonicalJson: null,
        migrationWrite: null,
        failure: Object.freeze({
          phase: "read" as const,
          ...normalized,
          correlation,
        }),
      });
    }
  });

  const writeProgress = fromPromise<WriteActorResult, Readonly<{
    storageKey: string;
    operation: LearningProgressPersistenceWriteOperation;
  }>>(async ({ input, signal }) => {
    try {
      await storage.write({
        key: input.storageKey,
        value: input.operation.serialized,
      }, { signal });
      if (signal.aborted) throw new DOMException("Persistence write aborted.", "AbortError");
      return Object.freeze({
        correlation: correlationOf(input.operation),
        failure: null,
      });
    } catch (error: unknown) {
      const normalized = normalizeLearningProgressStorageError(error, "write-failed");
      const correlation = correlationOf(input.operation);
      return Object.freeze({
        correlation,
        failure: Object.freeze({
          phase: "write" as const,
          ...normalized,
          correlation,
        }),
      });
    }
  });

  return setup({
    types: {} as {
      context: LearningProgressPersistenceContext;
      events: LearningProgressPersistenceEvent;
      input: LearningProgressPersistenceMachineInput;
    },
    actors: { loadProgress, writeProgress },
    delays: {
      debounce: ({ context }) => context.debounceMs,
    },
    guards: {
      currentSaveRequest: ({ context, event }) => (
        event.type === "PERSISTENCE.SAVE.REQUESTED"
        && event.sessionRevision === context.sessionRevision
        && event.pathRevision === context.pathRevision
        && Number.isSafeInteger(event.progressRevision)
        && event.progressRevision > context.latestProgressRevision
        && event.operationId.trim().length > 0
        && !context.seenOperationIds.includes(event.operationId)
      ),
      currentFlushRequest: ({ context, event }) => (
        event.type === "PERSISTENCE.FLUSH.REQUESTED"
        && sameCorrelation(context.pendingWrite, event)
      ),
      currentLoadResult: ({ context, event }) => {
        const result = resultFromDoneEvent<LoadActorResult>(event);
        return result !== null && sameCorrelation(result.correlation, {
          sessionRevision: context.sessionRevision,
          pathRevision: context.pathRevision,
          progressRevision: 0,
          operationId: context.loadOperationId,
        });
      },
      currentWriteSucceeded: ({ context, event }) => {
        const result = resultFromDoneEvent<WriteActorResult>(event);
        return result !== null
          && result.failure === null
          && sameCorrelation(context.activeWrite, result.correlation);
      },
      currentWriteFailed: ({ context, event }) => {
        const result = resultFromDoneEvent<WriteActorResult>(event);
        return result !== null
          && result.failure !== null
          && sameCorrelation(context.activeWrite, result.correlation);
      },
      hasPendingWrite: ({ context }) => context.pendingWrite !== null,
      hasNoPendingWrite: ({ context }) => context.pendingWrite === null,
    },
    actions: {
      acceptLoadResult: assign(({ context, event }) => {
        const result = resultFromDoneEvent<LoadActorResult>(event);
        if (!result) return {};
        const pendingAlreadyPersisted = context.pendingWrite !== null
          && result.loadResult.status === "restored"
          && result.loadResult.migratedFromVersion === null
          && context.pendingWrite.serialized === result.canonicalJson;
        const queuedWrite = pendingAlreadyPersisted ? null : context.pendingWrite;
        const pendingWrite = queuedWrite ?? result.migrationWrite;
        const schedulesMigration = queuedWrite === null
          && !pendingAlreadyPersisted
          && result.migrationWrite !== null;
        return {
          restoredContext: result.loadResult.context,
          loadResult: result.loadResult,
          pendingWrite,
          lastPersistedJson: result.loadResult.status === "restored"
            ? result.canonicalJson
            : null,
          lastFailure: result.failure,
          lastCompletedCorrelation: pendingAlreadyPersisted && context.pendingWrite
            ? correlationOf(context.pendingWrite)
            : context.lastCompletedCorrelation,
          seenOperationIds: schedulesMigration && result.migrationWrite
            ? appendSeenOperationId(context.seenOperationIds, result.migrationWrite.operationId)
            : context.seenOperationIds,
        };
      }),
      queueSave: assign(({ context, event }) => {
        if (event.type !== "PERSISTENCE.SAVE.REQUESTED") return {};
        try {
          const operation = saveOperationFromEvent(event);
          const persistedMatches = context.activeWrite === null
            && context.lastPersistedJson === operation.serialized;
          return {
            latestProgressRevision: operation.progressRevision,
            seenOperationIds: appendSeenOperationId(context.seenOperationIds, operation.operationId),
            // A semantically identical update is still a completed durability
            // barrier for its own correlation. When an equal write is already
            // active, queue the newest correlation so it receives a later ACK;
            // when the JSON is already durable, acknowledge it without I/O.
            pendingWrite: persistedMatches ? null : operation,
            lastCompletedCorrelation: persistedMatches
              ? correlationOf(operation)
              : context.lastCompletedCorrelation,
            lastFailure: null,
          };
        } catch (error: unknown) {
          const correlation = correlationOf(event);
          return {
            latestProgressRevision: event.progressRevision,
            seenOperationIds: appendSeenOperationId(context.seenOperationIds, event.operationId),
            pendingWrite: null,
            lastFailure: Object.freeze({
              phase: "request" as const,
              code: "invalid-request" as const,
              message: error instanceof Error ? error.message : String(error),
              correlation,
            }),
          };
        }
      }),
      promotePendingWrite: assign(({ context }) => ({
        activeWrite: context.pendingWrite,
        pendingWrite: null,
      })),
      commitWrite: assign(({ context, event }) => {
        const result = resultFromDoneEvent<WriteActorResult>(event);
        if (!result || !context.activeWrite) return {};
        const coalescedPending = context.pendingWrite?.serialized === context.activeWrite.serialized
          ? context.pendingWrite
          : null;
        return {
          lastPersistedJson: context.activeWrite.serialized,
          // The active write durably covers any newer request with identical
          // canonical JSON. Retire that request under its own correlation so
          // callers waiting on the newer durability barrier cannot deadlock.
          lastCompletedCorrelation: correlationOf(coalescedPending ?? context.activeWrite),
          pendingWrite: coalescedPending ? null : context.pendingWrite,
          activeWrite: null,
          lastFailure: null,
        };
      }),
      failWrite: assign(({ context, event }) => {
        const result = resultFromDoneEvent<WriteActorResult>(event);
        if (!result?.failure || !context.activeWrite) return {};
        return {
          pendingWrite: context.pendingWrite ?? context.activeWrite,
          activeWrite: null,
          lastFailure: result.failure,
        };
      }),
    },
  }).createMachine({
    id: "learningProgressPersistence",
    initial: "loading",
    context: ({ input }) => {
      const sessionRevision = nonNegativeRevision(input.sessionRevision, "sessionRevision");
      const pathRevision = nonEmpty(input.pathRevision, "pathRevision");
      const storageKey = nonEmpty(input.storageKey, "storageKey");
      const loadOperationId = nonEmpty(input.loadOperationId, "loadOperationId");
      const fallbackSafeNodeId = input.fallbackSafeNodeId ?? input.fallbackContext.currentNodeId;
      return {
        storageKey,
        sessionRevision,
        pathRevision,
        debounceMs: debounceDelay(input.debounceMs),
        fallbackContext: input.fallbackContext,
        fallbackSafeNodeId,
        restoredContext: input.fallbackContext,
        loadOperationId,
        loadResult: null,
        latestProgressRevision: 0,
        seenOperationIds: Object.freeze([]),
        pendingWrite: null,
        activeWrite: null,
        lastPersistedJson: null,
        lastCompletedCorrelation: null,
        lastFailure: null,
      };
    },
    states: {
      loading: {
        invoke: {
          id: "loadLearningProgress",
          src: "loadProgress",
          input: ({ context }) => ({
            storageKey: context.storageKey,
            sessionRevision: context.sessionRevision,
            pathRevision: context.pathRevision,
            progressRevision: 0,
            operationId: context.loadOperationId,
            fallbackContext: context.fallbackContext,
            fallbackSafeNodeId: context.fallbackSafeNodeId,
          }),
          onDone: [
            {
              guard: ({ context, event }) => (
                (context.pendingWrite !== null
                  || resultFromDoneEvent<LoadActorResult>(event)?.migrationWrite !== null)
                && sameCorrelation(
                  resultFromDoneEvent<LoadActorResult>(event)?.correlation ?? null,
                  {
                    sessionRevision: context.sessionRevision,
                    pathRevision: context.pathRevision,
                    progressRevision: 0,
                    operationId: context.loadOperationId,
                  },
                )
              ),
              actions: "acceptLoadResult",
              target: "debouncing",
            },
            {
              guard: "currentLoadResult",
              actions: "acceptLoadResult",
              target: "idle",
            },
          ],
        },
        on: {
          "PERSISTENCE.SAVE.REQUESTED": {
            guard: "currentSaveRequest",
            actions: "queueSave",
          },
        },
      },
      idle: {
        on: {
          "PERSISTENCE.SAVE.REQUESTED": {
            guard: "currentSaveRequest",
            actions: "queueSave",
            target: "debouncing",
          },
        },
      },
      debouncing: {
        always: {
          guard: "hasNoPendingWrite",
          target: "idle",
        },
        after: {
          debounce: {
            guard: "hasPendingWrite",
            target: "preparingWrite",
          },
        },
        on: {
          "PERSISTENCE.SAVE.REQUESTED": {
            guard: "currentSaveRequest",
            actions: "queueSave",
            target: "debouncing",
            reenter: true,
          },
          "PERSISTENCE.FLUSH.REQUESTED": {
            guard: "currentFlushRequest",
            target: "preparingWrite",
          },
        },
      },
      preparingWrite: {
        entry: "promotePendingWrite",
        always: "writing",
      },
      writing: {
        invoke: {
          id: "writeLearningProgress",
          src: "writeProgress",
          input: ({ context }) => {
            if (!context.activeWrite) throw new Error("Persistence write entered without an operation.");
            return {
              storageKey: context.storageKey,
              operation: context.activeWrite,
            };
          },
          onDone: [
            {
              guard: "currentWriteSucceeded",
              actions: "commitWrite",
              target: "writeSettled",
            },
            {
              guard: "currentWriteFailed",
              actions: "failWrite",
              target: "writeFailed",
            },
          ],
        },
        on: {
          "PERSISTENCE.SAVE.REQUESTED": {
            guard: "currentSaveRequest",
            actions: "queueSave",
          },
        },
      },
      writeSettled: {
        always: [
          { guard: "hasPendingWrite", target: "preparingWrite" },
          { target: "idle" },
        ],
      },
      writeFailed: {
        on: {
          "PERSISTENCE.SAVE.REQUESTED": {
            guard: "currentSaveRequest",
            actions: "queueSave",
            target: "debouncing",
          },
          "PERSISTENCE.FLUSH.REQUESTED": {
            guard: "currentFlushRequest",
            target: "preparingWrite",
          },
        },
      },
    },
  });
}

export type LearningProgressPersistenceMachine = ReturnType<
  typeof createLearningProgressPersistenceMachine
>;
export type LearningProgressPersistenceMachineSnapshot = SnapshotFrom<
  LearningProgressPersistenceMachine
>;
