import type { LearningEntityId } from "../../content";
import type { ProgressGraph } from "./graph";
import {
  acceptNavigation,
  cloneProgressContext as cloneContext,
  completeMissingUnlockCommitPrerequisites,
  completeUnlockDeparture,
  completeUnlockPrefixBeforeNode,
  completeOwnerIfReady,
  completeSubjectForCatchUp,
  exposeNextConcept,
  finishProgressContext as finishContext,
  isIntentCompatible,
  nodeStatus,
  rejectProgressEvent as reject,
  requiredCompletionNodesForUnlock,
  routeForCatchUp,
  strictSubjectAncestors,
  subjectForNode,
  unlockEligibleSubjects,
  unlockReachedNode,
} from "./policies";
import type {
  CatchUpResult,
  ConceptActionKind,
  ConceptActionResult,
  LearningProgressContext,
  LearningProgressEvent,
  ProgressRejectionReason,
  SubjectProgressStatus,
} from "./types";
import { createPendingUnlockCommit } from "./unlockCommit";

function applyCatchUp(
  graph: ProgressGraph,
  context: LearningProgressContext,
  event: Extract<LearningProgressEvent, { readonly type: "CATCH_UP.REQUESTED" }>,
): LearningProgressContext {
  const draft = cloneContext(context);
  const target = graph.nodeById.get(event.nodeId);
  if (!target) {
    reject(draft, event, "unknown-node");
    draft.lastCatchUpResult = Object.freeze({
      accepted: false,
      sourceNodeId: context.currentNodeId,
      targetNodeId: event.nodeId,
      routeNodeIds: Object.freeze([]),
      completedSubjectNodeIds: Object.freeze([]),
      completedConceptNodeIds: Object.freeze([]),
      targetStatus: null,
      reason: "unknown-node",
    });
    return finishContext(draft);
  }

  const routeNodeIds = routeForCatchUp(graph, context, event.nodeId);
  if (!routeNodeIds) {
    reject(draft, event, "no-authored-route");
    draft.lastCatchUpResult = Object.freeze({
      accepted: false,
      sourceNodeId: context.currentNodeId,
      targetNodeId: event.nodeId,
      routeNodeIds: Object.freeze([]),
      completedSubjectNodeIds: Object.freeze([]),
      completedConceptNodeIds: Object.freeze([]),
      targetStatus: nodeStatus(graph, context, event.nodeId),
      reason: "no-authored-route",
    });
    return finishContext(draft);
  }

  const targetSubjectId = subjectForNode(graph, event.nodeId);
  if (!targetSubjectId) {
    reject(draft, event, "unknown-node");
    return finishContext(draft);
  }
  const completedSubjects: LearningEntityId[] = [];
  const completedConcepts: LearningEntityId[] = [];
  for (const ancestorId of strictSubjectAncestors(graph, targetSubjectId)) {
    completeSubjectForCatchUp(graph, draft, ancestorId, completedSubjects, completedConcepts);
  }
  unlockEligibleSubjects(graph, draft.subjectStatusById as Record<string, SubjectProgressStatus>);

  if (target.entityKind === "concept") {
    if (draft.subjectStatusById[targetSubjectId] === "locked") {
      draft.subjectStatusById = { ...draft.subjectStatusById, [targetSubjectId]: "available" };
    }
    const concepts = graph.conceptsBySubjectId.get(targetSubjectId) ?? [];
    const targetIndex = concepts.indexOf(target.id);
    for (const priorConceptId of concepts.slice(0, Math.max(0, targetIndex))) {
      if (draft.conceptStatusById[priorConceptId] === "completed") continue;
      draft.conceptStatusById = { ...draft.conceptStatusById, [priorConceptId]: "completed" };
      completedConcepts.push(priorConceptId);
    }
    if (draft.conceptStatusById[target.id] === "locked") {
      draft.conceptStatusById = { ...draft.conceptStatusById, [target.id]: "available" };
    }
  }

  const result: CatchUpResult = Object.freeze({
    accepted: true,
    sourceNodeId: context.currentNodeId,
    targetNodeId: event.nodeId,
    routeNodeIds: Object.freeze([...routeNodeIds]),
    completedSubjectNodeIds: Object.freeze(completedSubjects),
    completedConceptNodeIds: Object.freeze(completedConcepts),
    targetStatus: nodeStatus(graph, draft, event.nodeId),
  });
  draft.lastCatchUpResult = result;
  acceptNavigation(draft, {
    accepted: true,
    sourceNodeId: context.currentNodeId,
    targetNodeId: event.nodeId,
    mode: "catch-up",
    routeNodeIds,
    requiredCompletionNodeIds: Object.freeze([]),
  });
  return finishContext(draft);
}

function conceptAction(
  graph: ProgressGraph,
  context: LearningProgressContext,
  event: Extract<LearningProgressEvent, {
    readonly type:
      | "CONCEPT.START.REQUESTED"
      | "CONCEPT.CONTINUE.REQUESTED"
      | "CONCEPT.MARK_COMPLETED"
      | "CONCEPT.DEFERRED"
      | "CONCEPT.REVIEW.REQUESTED";
  }>,
  kind: ConceptActionKind,
): LearningProgressContext {
  const draft = cloneContext(context);
  const node = graph.nodeById.get(event.nodeId);
  const status = context.conceptStatusById[event.nodeId] ?? null;
  const fail = (reason: ProgressRejectionReason): LearningProgressContext => {
    const result: ConceptActionResult = Object.freeze({
      accepted: false,
      kind,
      nodeId: event.nodeId,
      status,
      reason,
    });
    draft.lastConceptAction = result;
    reject(draft, event, reason);
    return finishContext(draft);
  };
  if (!node) return fail("unknown-node");
  if (node.entityKind !== "concept") return fail("not-a-concept");
  // Deferring and explicitly finishing an already in-progress concept are
  // card-level decisions, so both remain valid for a remote platform. A remote
  // available concept cannot be skipped by forging the completion event, and
  // actions that launch learning or review still require physical arrival.
  const canCompleteRemotely = kind === "mark-completed" && status === "in-progress";
  if (kind !== "defer" && !canCompleteRemotely && context.currentNodeId !== event.nodeId) {
    return fail("not-current-node");
  }

  let nextStatus = status;
  let accepted = false;
  if (kind === "start") {
    accepted = status === "available" || status === "in-progress";
    if (accepted) nextStatus = "in-progress";
  } else if (kind === "continue") {
    accepted = status === "in-progress";
  } else if (kind === "mark-completed") {
    accepted = status === "available" || status === "in-progress" || status === "completed";
    if (accepted) nextStatus = "completed";
  } else if (kind === "defer") {
    accepted = status === "available";
  } else {
    accepted = status === "completed";
  }
  if (!accepted || !nextStatus) return fail("invalid-concept-status");

  if (nextStatus !== status) {
    draft.conceptStatusById = { ...draft.conceptStatusById, [event.nodeId]: nextStatus };
  }
  if (kind === "mark-completed" && node.ownerSubjectId) {
    completeOwnerIfReady(graph, draft, node.ownerSubjectId);
  }
  draft.lastConceptAction = Object.freeze({
    accepted: true,
    kind,
    nodeId: event.nodeId,
    status: nextStatus,
  });
  draft.lastRejection = null;
  return finishContext(draft);
}

function applyUnlockRequest(
  graph: ProgressGraph,
  context: LearningProgressContext,
  event: Extract<LearningProgressEvent, { readonly type: "UNLOCK.REQUESTED" }>,
): LearningProgressContext {
  const draft = cloneContext(context);
  const target = graph.nodeById.get(event.nodeId);
  if (!target) {
    reject(draft, event, "unknown-node");
    acceptNavigation(draft, {
      accepted: false,
      sourceNodeId: context.currentNodeId,
      targetNodeId: event.nodeId,
      mode: "catch-up",
      routeNodeIds: [],
      requiredCompletionNodeIds: Object.freeze([]),
      reason: "unknown-node",
    });
    return finishContext(draft);
  }
  const routeNodeIds = routeForCatchUp(graph, context, event.nodeId);
  if (!routeNodeIds) {
    reject(draft, event, "no-authored-route");
    acceptNavigation(draft, {
      accepted: false,
      sourceNodeId: context.currentNodeId,
      targetNodeId: event.nodeId,
      mode: "catch-up",
      routeNodeIds: [],
      requiredCompletionNodeIds: Object.freeze([]),
      reason: "no-authored-route",
    });
    return finishContext(draft);
  }
  const requiredCompletionNodeIds = requiredCompletionNodesForUnlock(
    graph,
    event.nodeId,
    routeNodeIds,
  );
  draft.lastMovementCancellation = null;
  acceptNavigation(draft, {
    accepted: true,
    sourceNodeId: context.currentNodeId,
    targetNodeId: event.nodeId,
    mode: "catch-up",
    routeNodeIds,
    requiredCompletionNodeIds,
  });
  return finishContext(draft);
}

function applyLearningRequest(
  graph: ProgressGraph,
  context: LearningProgressContext,
  event: Extract<LearningProgressEvent, { readonly type: "LEARNING.REQUESTED" }>,
): LearningProgressContext {
  const draft = cloneContext(context);
  const target = graph.nodeById.get(event.nodeId);
  const status = nodeStatus(graph, context, event.nodeId);
  if (!target) {
    reject(draft, event, "unknown-node");
  } else if (status === "locked") {
    reject(draft, event, "locked-node");
  } else if (!isIntentCompatible(graph, event.nodeId, event.kind)) {
    reject(draft, event, "invalid-concept-status");
  } else {
    draft.pendingLearningIntent = Object.freeze({ nodeId: event.nodeId, kind: event.kind });
    acceptNavigation(draft, {
      accepted: true,
      sourceNodeId: context.currentNodeId,
      targetNodeId: event.nodeId,
      mode: "direct",
      routeNodeIds: Object.freeze([context.currentNodeId, event.nodeId]),
      requiredCompletionNodeIds: Object.freeze([]),
    });
    return finishContext(draft);
  }
  acceptNavigation(draft, {
    accepted: false,
    sourceNodeId: context.currentNodeId,
    targetNodeId: event.nodeId,
    mode: "direct",
    routeNodeIds: [],
    requiredCompletionNodeIds: Object.freeze([]),
    reason: draft.lastRejection?.reason ?? "unknown-node",
  });
  return finishContext(draft);
}

function settleLearningIntent(
  graph: ProgressGraph,
  context: LearningProgressContext,
  event: Extract<LearningProgressEvent, { readonly type: "LEARNING.SETTLED" }>,
): LearningProgressContext {
  const intent = context.pendingLearningIntent;
  const revision = context.learningLaunchRevision + 1;
  if (!intent || intent.nodeId !== event.nodeId || context.currentNodeId !== event.nodeId) {
    const draft = cloneContext(context);
    draft.lastLearningLaunch = Object.freeze({
      accepted: false,
      nodeId: event.nodeId,
      kind: intent?.kind ?? "subject-enter",
      revision,
      reason: "not-current-node",
    });
    draft.learningLaunchRevision = revision;
    reject(draft, event, "not-current-node");
    return finishContext(draft);
  }

  if (intent.kind === "subject-enter") {
    const draft = cloneContext(context);
    draft.pendingLearningIntent = null;
    draft.lastLearningLaunch = Object.freeze({ ...intent, accepted: true, revision });
    draft.learningLaunchRevision = revision;
    draft.lastRejection = null;
    return finishContext(draft);
  }

  const conceptEvent = intent.kind === "concept-start"
    ? { type: "CONCEPT.START.REQUESTED" as const, nodeId: intent.nodeId }
    : intent.kind === "concept-continue"
      ? { type: "CONCEPT.CONTINUE.REQUESTED" as const, nodeId: intent.nodeId }
      : { type: "CONCEPT.REVIEW.REQUESTED" as const, nodeId: intent.nodeId };
  const conceptResult = conceptAction(
    graph,
    context,
    conceptEvent,
    intent.kind === "concept-start"
      ? "start"
      : intent.kind === "concept-continue" ? "continue" : "review",
  );
  const draft = cloneContext(conceptResult);
  const accepted = conceptResult.lastConceptAction?.accepted === true;
  draft.pendingLearningIntent = null;
  draft.lastLearningLaunch = Object.freeze({
    ...intent,
    accepted,
    revision,
    ...(accepted ? {} : { reason: conceptResult.lastConceptAction?.reason ?? "invalid-concept-status" }),
  });
  draft.learningLaunchRevision = revision;
  return finishContext(draft);
}

export function reduceLearningProgress(
  graph: ProgressGraph,
  context: LearningProgressContext,
  event: LearningProgressEvent,
): LearningProgressContext {
  if (event.type === "CATCH_UP.REQUESTED") return applyCatchUp(graph, context, event);
  if (event.type === "UNLOCK.REQUESTED") return applyUnlockRequest(graph, context, event);
  if (event.type === "LEARNING.REQUESTED") return applyLearningRequest(graph, context, event);
  if (event.type === "LEARNING.SETTLED") return settleLearningIntent(graph, context, event);
  if (event.type === "CONCEPT.START.REQUESTED") return conceptAction(graph, context, event, "start");
  if (event.type === "CONCEPT.CONTINUE.REQUESTED") return conceptAction(graph, context, event, "continue");
  if (event.type === "CONCEPT.MARK_COMPLETED") return conceptAction(graph, context, event, "mark-completed");
  if (event.type === "CONCEPT.DEFERRED") return conceptAction(graph, context, event, "defer");
  if (event.type === "CONCEPT.REVIEW.REQUESTED") return conceptAction(graph, context, event, "review");

  const draft = cloneContext(context);
  const activeUnlockTransactionIsStale = (
    eventTransactionId: string,
  ): boolean => {
    const activeTransactionId = context.pendingUnlockCommit?.transactionId;
    return activeTransactionId !== undefined && eventTransactionId !== activeTransactionId;
  };
  if (event.type === "UNLOCK.COMMIT.REGISTERED") {
    const decision = context.lastNavigationDecision;
    const commit = event.commit;
    const requiredNodesMatch = decision?.requiredCompletionNodeIds.length
      === commit.requiredCompletionNodeIds.length
      && decision.requiredCompletionNodeIds.every(
        (nodeId, index) => commit.requiredCompletionNodeIds[index] === nodeId,
      );
    const valid = commit.transactionId.trim().length > 0
      && decision?.accepted === true
      && decision.mode === "catch-up"
      && decision.targetNodeId === commit.targetNodeId
      && requiredNodesMatch
      && commit.requiredCompletionNodeIds.every((nodeId) => graph.nodeById.has(nodeId));
    if (!valid
      || (context.pendingUnlockCommit !== null
        && context.pendingUnlockCommit.transactionId !== commit.transactionId)) {
      reject(draft, event, "stale-transaction");
    } else {
      draft.pendingUnlockCommit = createPendingUnlockCommit(commit);
      draft.lastMovementCancellation = null;
      draft.lastRejection = null;
    }
  } else if (event.type === "UNLOCK.DEPARTED") {
    if (activeUnlockTransactionIsStale(event.transactionId)) {
      reject(draft, event, "stale-transaction");
    } else {
      draft.lastMovementCancellation = null;
      if (draft.pendingUnlockCommit) completeUnlockDeparture(graph, draft, draft.pendingUnlockCommit);
      draft.lastRejection = null;
    }
  } else if (event.type === "MOVEMENT.CANCELLED") {
    if (activeUnlockTransactionIsStale(event.transactionId)) {
      reject(draft, event, "stale-transaction");
      return finishContext(draft);
    }
    const safeNode = graph.nodeById.get(event.safeNodeId);
    const safeStatus = nodeStatus(graph, draft, event.safeNodeId);
    const targetNodeId = draft.pendingUnlockCommit?.targetNodeId
      ?? draft.pendingLearningIntent?.nodeId
      ?? draft.lastNavigationDecision?.targetNodeId
      ?? null;
    // Runtime recovery has already restored the scene. Reconcile the pure
    // progress machine to the same stable node and terminate every pending
    // domain transaction; no arrival side effects are committed here.
    if (safeNode && safeStatus !== null && safeStatus !== "locked") {
      draft.currentNodeId = event.safeNodeId;
      draft.visitedNodeIds = { ...draft.visitedNodeIds, [event.safeNodeId]: true };
    }
    draft.pendingUnlockCommit = null;
    draft.pendingLearningIntent = null;
    draft.lastMovementCancellation = Object.freeze({
      reason: event.reason,
      safeNodeId: event.safeNodeId,
      targetNodeId,
    });
    draft.lastRejection = null;
  } else if (event.type === "NODE.TRAVERSED") {
    if (activeUnlockTransactionIsStale(event.transactionId)) {
      reject(draft, event, "stale-transaction");
      return finishContext(draft);
    }
    const commit = context.pendingUnlockCommit;
    const isIntermediateUnlockNode = commit?.targetNodeId !== event.nodeId
      && commit?.requiredCompletionNodeIds.includes(event.nodeId);
    const traversedStatus = nodeStatus(graph, context, event.nodeId);
    const accepted = isIntermediateUnlockNode && commit
      ? completeUnlockPrefixBeforeNode(graph, draft, commit, event.nodeId)
      : traversedStatus !== null && traversedStatus !== "locked"
        ? unlockReachedNode(graph, draft, event.nodeId)
        : false;
    if (!accepted) {
      reject(draft, event, traversedStatus === "locked" ? "locked-node" : "unknown-node");
    } else draft.lastRejection = null;
  } else if (event.type === "NAVIGATION.REQUESTED") {
    const target = graph.nodeById.get(event.nodeId);
    const status = nodeStatus(graph, context, event.nodeId);
    if (!target) {
      reject(draft, event, "unknown-node");
      acceptNavigation(draft, {
        accepted: false,
        sourceNodeId: context.currentNodeId,
        targetNodeId: event.nodeId,
        mode: "direct",
        routeNodeIds: [],
        requiredCompletionNodeIds: Object.freeze([]),
        reason: "unknown-node",
      });
    } else if (status === "locked") {
      reject(draft, event, "locked-node");
      acceptNavigation(draft, {
        accepted: false,
        sourceNodeId: context.currentNodeId,
        targetNodeId: event.nodeId,
        mode: "direct",
        routeNodeIds: [],
        requiredCompletionNodeIds: Object.freeze([]),
        reason: "locked-node",
      });
      draft.lastRejection = Object.freeze({
        eventType: event.type,
        nodeId: event.nodeId,
        reason: "locked-node",
      });
    } else {
      acceptNavigation(draft, {
        accepted: true,
        sourceNodeId: context.currentNodeId,
        targetNodeId: event.nodeId,
        mode: "direct",
        routeNodeIds: Object.freeze([context.currentNodeId, event.nodeId]),
        requiredCompletionNodeIds: Object.freeze([]),
      });
    }
  } else if (event.type === "NODE.ARRIVED") {
    if (activeUnlockTransactionIsStale(event.transactionId)) {
      reject(draft, event, "stale-transaction");
      return finishContext(draft);
    }
    const target = graph.nodeById.get(event.nodeId);
    const unlockArrival = context.pendingUnlockCommit?.targetNodeId === event.nodeId;
    if (unlockArrival && context.pendingUnlockCommit) {
      // A dynamic bridge can physically skip authored prerequisite platforms.
      // Close the same XState-owned unlock transaction by committing any
      // missing route prefix before making the destination available.
      completeMissingUnlockCommitPrerequisites(graph, draft, context.pendingUnlockCommit);
      unlockReachedNode(graph, draft, event.nodeId);
    }
    const status = nodeStatus(graph, draft, event.nodeId);
    if (!target) {
      reject(draft, event, "unknown-node");
    } else if (status === "locked") {
      reject(draft, event, "locked-node");
    } else {
      draft.currentNodeId = event.nodeId;
      draft.lastMovementCancellation = null;
      draft.visitedNodeIds = { ...draft.visitedNodeIds, [event.nodeId]: true };
      if (unlockArrival) draft.pendingUnlockCommit = null;
      draft.lastRejection = null;
      if (graph.goalIds.has(event.nodeId)) {
        if (draft.subjectStatusById[event.nodeId] !== "completed") {
          draft.subjectStatusById = { ...draft.subjectStatusById, [event.nodeId]: "completed" };
        }
        if (!context.celebrationSeen) {
          draft.celebrationSeen = true;
          draft.celebrationCount = context.celebrationCount + 1;
        }
      } else {
        if (target.entityKind === "subject" && draft.subjectStatusById[event.nodeId] === "available") {
          const concepts = graph.conceptsBySubjectId.get(event.nodeId) ?? [];
          if (concepts.length === 0) {
            draft.subjectStatusById = { ...draft.subjectStatusById, [event.nodeId]: "completed" };
            unlockEligibleSubjects(graph, draft.subjectStatusById as Record<string, SubjectProgressStatus>);
          } else {
            exposeNextConcept(graph, draft, event.nodeId);
          }
        }
      }
    }
  }
  return finishContext(draft);
}
