import type {
  EdgeId,
  LearningPathNode,
  NodeId,
  OverpassLearningPathEdge,
  StraightLearningPathEdge,
} from "./pathData";
import {
  createAdaptiveOverpassProfile,
  type AdaptiveOverpassProfile,
} from "./overpassSpec";

const GEOMETRY_EPSILON = 0.000_001;

export interface OverpassCatalogBridgeDiagnostic {
  readonly edgeId: EdgeId;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  readonly chordLength: number;
  readonly straightApproachLength: number;
  readonly bridgeSurfaceY: number;
  readonly predictedMaximumSurfacePitchDegrees: number;
}

export interface DynamicOverpassCatalogDiagnostics {
  readonly nodeCount: number;
  readonly authoredStraightEdgeCount: number;
  readonly totalUnorderedPairCount: number;
  readonly directlyConnectedPairCount: number;
  readonly catalogBridgeCount: number;
  /** Bridges whose immutable specifications have actually been requested. */
  readonly materializedBridgeCount: number;
  readonly shortenedApproachCount: number;
  readonly loweredCrownCount: number;
  readonly minimumChordLength: number;
  readonly maximumChordLength: number;
  readonly maximumPredictedSurfacePitchDegrees: number;
  readonly shortestBridge: OverpassCatalogBridgeDiagnostic | null;
}

export interface DynamicOverpassCatalogResult {
  /**
   * Compatibility view of the complete catalogue. Reading this property is an
   * explicit opt-in to O(V²) materialisation; normal runtimes should use
   * getOverpassBetween() and getMaterializedEdges().
   */
  readonly edges: readonly OverpassLearningPathEdge[];
  readonly diagnostics: DynamicOverpassCatalogDiagnostics;
  readonly getOverpassBetween: (
    firstNodeId: NodeId,
    secondNodeId: NodeId,
  ) => OverpassLearningPathEdge | null;
  readonly getMaterializedEdges: () => readonly OverpassLearningPathEdge[];
}

interface CatalogEntry {
  readonly edge: OverpassLearningPathEdge;
  readonly profile: AdaptiveOverpassProfile;
}

/**
 * Validates the graph in O(V + E) and lazily materialises one immutable bridge
 * specification for each requested unordered, non-straight node pair.
 *
 * The edge direction is a stable DAG-facing canonical direction based on
 * navigationOrder (then node ID as a tie-break). Runtime lookup is undirected,
 * so reverse traversal always reuses the same edge and physical mesh.
 */
export function createDynamicOverpassCatalog(
  nodes: readonly LearningPathNode[],
  authoredStraightEdges: readonly StraightLearningPathEdge[],
): DynamicOverpassCatalogResult {
  const stableNodes = validateAndSortNodes(nodes);
  const nodeById = new Map(stableNodes.map((node) => [node.id, node] as const));
  const {
    directPairKeys,
    existingEdgeIds,
  } = validateStraightEdges(authoredStraightEdges, nodeById);
  const entriesByPairKey = new Map<string, CatalogEntry>();
  const expectedBridgeCount = (
    stableNodes.length * (stableNodes.length - 1) / 2
    - directPairKeys.size
  );

  const getMaterializedEntries = (): readonly CatalogEntry[] => Object.freeze(
    [...entriesByPairKey.values()].sort(compareCatalogEntries),
  );
  const getMaterializedEdges = (): readonly OverpassLearningPathEdge[] => (
    Object.freeze(getMaterializedEntries().map((entry) => entry.edge))
  );
  const getOverpassBetween = (
    firstNodeId: NodeId,
    secondNodeId: NodeId,
  ): OverpassLearningPathEdge | null => {
    if (firstNodeId === secondNodeId) return null;
    const first = nodeById.get(firstNodeId);
    const second = nodeById.get(secondNodeId);
    if (!first || !second) return null;
    const pairKey = createUndirectedNodePairKey(firstNodeId, secondNodeId);
    if (directPairKeys.has(pairKey)) return null;
    const cached = entriesByPairKey.get(pairKey);
    if (cached) return cached.edge;

    const [canonicalFrom, canonicalTo] = compareNodesForCanonicalDirection(
      first,
      second,
    ) <= 0
      ? [first, second]
      : [second, first];

    const chordLength = Math.hypot(
      canonicalTo.position.x - canonicalFrom.position.x,
      canonicalTo.position.z - canonicalFrom.position.z,
    );
    const profile = createAdaptiveOverpassProfile(
      chordLength,
      Math.max(canonicalFrom.surfaceY, canonicalTo.surfaceY),
    );
    const edgeId = createOverpassEdgeId(canonicalFrom.id, canonicalTo.id);
    if (existingEdgeIds.has(edgeId)) {
      throw new Error(
        `Dynamic bridge ID "${edgeId}" collides with an authored straight edge.`,
      );
    }
    const entry = Object.freeze({
      edge: createEdge(canonicalFrom, canonicalTo, edgeId, profile),
      profile,
    });
    entriesByPairKey.set(pairKey, entry);
    return entry.edge;
  };
  const materializeAll = (): readonly CatalogEntry[] => {
    for (let firstIndex = 0; firstIndex < stableNodes.length; firstIndex += 1) {
      for (
        let secondIndex = firstIndex + 1;
        secondIndex < stableNodes.length;
        secondIndex += 1
      ) {
        getOverpassBetween(
          stableNodes[firstIndex]!.id,
          stableNodes[secondIndex]!.id,
        );
      }
    }
    return getMaterializedEntries();
  };

  const diagnostics = createLazyDiagnostics({
    stableNodes,
    authoredStraightEdgeCount: authoredStraightEdges.length,
    directPairCount: directPairKeys.size,
    expectedBridgeCount,
    entriesByPairKey,
  });
  const result = {
    diagnostics,
    getOverpassBetween,
    getMaterializedEdges,
  } as DynamicOverpassCatalogResult;
  Object.defineProperty(result, "edges", {
    enumerable: true,
    get: () => {
      materializeAll();
      return getMaterializedEdges();
    },
  });
  return Object.freeze(result);
}

/** Stable key for an unordered physical pair. */
export function createUndirectedNodePairKey(
  firstNodeId: NodeId,
  secondNodeId: NodeId,
): string {
  if (firstNodeId === secondNodeId) {
    throw new Error(`A bridge cannot connect node "${firstNodeId}" to itself.`);
  }
  const [first, second] = compareStrings(firstNodeId, secondNodeId) <= 0
    ? [firstNodeId, secondNodeId]
    : [secondNodeId, firstNodeId];
  return `pair:${encodeURIComponent(first)}|${encodeURIComponent(second)}`;
}

function validateAndSortNodes(
  nodes: readonly LearningPathNode[],
): readonly LearningPathNode[] {
  if (nodes.length < 1) {
    throw new Error("Dynamic bridge catalogue requires at least one node.");
  }
  const nodeIds = new Set<NodeId>();
  nodes.forEach((node, index) => {
    if (node.id.trim().length === 0 || nodeIds.has(node.id)) {
      throw new Error(`Dynamic bridge catalogue has an invalid or duplicate node at index ${index}.`);
    }
    if (!Number.isFinite(node.navigationOrder)) {
      throw new Error(`Node "${node.id}" has a non-finite navigation order.`);
    }
    if (
      !Number.isFinite(node.position.x)
      || !Number.isFinite(node.position.z)
      || !Number.isFinite(node.surfaceY)
    ) {
      throw new Error(`Node "${node.id}" has non-finite bridge geometry.`);
    }
    nodeIds.add(node.id);
  });
  return Object.freeze([...nodes].sort(compareNodesForCanonicalDirection));
}

function validateStraightEdges(
  edges: readonly StraightLearningPathEdge[],
  nodeById: ReadonlyMap<NodeId, LearningPathNode>,
): {
  readonly directPairKeys: ReadonlySet<string>;
  readonly existingEdgeIds: ReadonlySet<EdgeId>;
} {
  const directPairKeys = new Set<string>();
  const existingEdgeIds = new Set<EdgeId>();
  edges.forEach((edge, index) => {
    if (edge.pathKind !== "straight") {
      throw new Error(`Authored edge at index ${index} is not straight.`);
    }
    if (edge.id.trim().length === 0 || existingEdgeIds.has(edge.id)) {
      throw new Error(`Authored graph has an invalid or duplicate edge at index ${index}.`);
    }
    if (!nodeById.has(edge.fromNodeId) || !nodeById.has(edge.toNodeId)) {
      throw new Error(`Authored edge "${edge.id}" references a missing node.`);
    }
    const pairKey = createUndirectedNodePairKey(
      edge.fromNodeId,
      edge.toNodeId,
    );
    if (directPairKeys.has(pairKey)) {
      throw new Error(`Authored graph repeats physical pair "${pairKey}".`);
    }
    directPairKeys.add(pairKey);
    existingEdgeIds.add(edge.id);
  });
  return { directPairKeys, existingEdgeIds };
}

function createEdge(
  first: LearningPathNode,
  second: LearningPathNode,
  edgeId: EdgeId,
  profile: AdaptiveOverpassProfile,
): OverpassLearningPathEdge {
  const from = compareNodesForCanonicalDirection(first, second) <= 0
    ? first
    : second;
  const to = from === first ? second : first;
  const bridge = profile.bridge;
  return Object.freeze({
    id: edgeId,
    fromNodeId: from.id,
    toNodeId: to.id,
    pathKind: "overpass",
    initiallyVisible: false,
    completionPolicy: "preserve-variant",
    curveStyle: bridge.curveStyle,
    width: bridge.width,
    deckThickness: bridge.deckThickness,
    platformEdgeOffset: bridge.platformEdgeOffset,
    straightApproachLength: bridge.straightApproachLength,
    bridgeSurfaceY: bridge.bridgeSurfaceY,
    maximumSurfacePitchDegrees: bridge.maximumSurfacePitchDegrees,
    routingCost: bridge.routingCost,
    // This version intentionally does not audit or reserve bridge-under space.
    underpassEdgeIds: Object.freeze([]),
    requiredClearance: bridge.requiredClearance,
  });
}

function createOverpassEdgeId(
  fromNodeId: NodeId,
  toNodeId: NodeId,
): EdgeId {
  return (
    `edge-overpass:${encodeURIComponent(fromNodeId)}:${encodeURIComponent(toNodeId)}`
  );
}

function findShortestEntry(entries: readonly CatalogEntry[]): CatalogEntry | null {
  let shortest = entries[0] ?? null;
  if (shortest === null) return null;
  for (let index = 1; index < entries.length; index += 1) {
    const candidate = entries[index]!;
    if (
      candidate.profile.chordLength
      < shortest.profile.chordLength - GEOMETRY_EPSILON
    ) {
      shortest = candidate;
    }
  }
  return shortest;
}

function compareCatalogEntries(first: CatalogEntry, second: CatalogEntry): number {
  return compareStrings(first.edge.id, second.edge.id);
}

function createLazyDiagnostics(input: Readonly<{
  stableNodes: readonly LearningPathNode[];
  authoredStraightEdgeCount: number;
  directPairCount: number;
  expectedBridgeCount: number;
  entriesByPairKey: ReadonlyMap<string, CatalogEntry>;
}>): DynamicOverpassCatalogDiagnostics {
  const getMaterializedEntries = (): readonly CatalogEntry[] => (
    [...input.entriesByPairKey.values()]
  );
  const diagnostics = {
    nodeCount: input.stableNodes.length,
    authoredStraightEdgeCount: input.authoredStraightEdgeCount,
    totalUnorderedPairCount: input.stableNodes.length * (input.stableNodes.length - 1) / 2,
    directlyConnectedPairCount: input.directPairCount,
    catalogBridgeCount: input.expectedBridgeCount,
  } as DynamicOverpassCatalogDiagnostics;
  Object.defineProperties(diagnostics, {
    materializedBridgeCount: {
      enumerable: true,
      get: () => input.entriesByPairKey.size,
    },
    shortenedApproachCount: {
      enumerable: true,
      get: () => getMaterializedEntries().filter(
        (entry) => entry.profile.approachWasShortened,
      ).length,
    },
    loweredCrownCount: {
      enumerable: true,
      get: () => getMaterializedEntries().filter(
        (entry) => entry.profile.crownWasLowered,
      ).length,
    },
    minimumChordLength: {
      enumerable: true,
      get: () => findShortestEntry(getMaterializedEntries())?.profile.chordLength ?? 0,
    },
    maximumChordLength: {
      enumerable: true,
      get: () => Math.max(
        0,
        ...getMaterializedEntries().map((entry) => entry.profile.chordLength),
      ),
    },
    maximumPredictedSurfacePitchDegrees: {
      enumerable: true,
      get: () => Math.max(
        0,
        ...getMaterializedEntries().map(
          (entry) => entry.profile.predictedMaximumSurfacePitchDegrees,
        ),
      ),
    },
    shortestBridge: {
      enumerable: true,
      get: () => {
        const shortest = findShortestEntry(getMaterializedEntries());
        return shortest ? freezeBridgeDiagnostic(shortest) : null;
      },
    },
  });
  return Object.freeze(diagnostics);
}

function freezeBridgeDiagnostic(
  entry: CatalogEntry,
): OverpassCatalogBridgeDiagnostic {
  return Object.freeze({
    edgeId: entry.edge.id,
    fromNodeId: entry.edge.fromNodeId,
    toNodeId: entry.edge.toNodeId,
    chordLength: entry.profile.chordLength,
    straightApproachLength: entry.edge.straightApproachLength,
    bridgeSurfaceY: entry.edge.bridgeSurfaceY,
    predictedMaximumSurfacePitchDegrees: (
      entry.profile.predictedMaximumSurfacePitchDegrees
    ),
  });
}

function compareNodesForCanonicalDirection(
  first: LearningPathNode,
  second: LearningPathNode,
): number {
  return (
    first.navigationOrder - second.navigationOrder
    || compareStrings(first.id, second.id)
  );
}

function compareStrings(first: string, second: string): number {
  return first < second ? -1 : first > second ? 1 : 0;
}
