import {
  assign,
  sendTo,
  setup,
  type SnapshotFrom,
} from "xstate";
import {
  createSceneRuntimeGateway,
  type SceneRuntimeGatewayAck,
  type SceneRuntimeGatewayCommand,
} from "../../runtime/gateway";
import type {
  SceneSessionContext,
  SceneSessionEvent,
  SceneSessionGatewayAck,
  SceneSessionInput,
  SceneSessionReadiness,
} from "./types";

const GATEWAY_COMMAND_TYPES = new Set<SceneRuntimeGatewayCommand["type"]>([
  "PRESENTATION.EXECUTE",
  "PRESENTATION.CANCEL_TRANSACTION",
  "MOTION.EXECUTE",
  "MOTION.ABORT",
  "CHARACTER.FORCE_SETTLE",
]);

const GATEWAY_ACK_TYPES = new Set<SceneRuntimeGatewayAck["type"]>([
  "PRESENTATION.ACCEPTED",
  "PRESENTATION.DEFERRED",
  "PRESENTATION.STARTED",
  "PRESENTATION.SETTLED",
  "PRESENTATION.FAILED",
  "MOTION.ACCEPTED",
  "MOTION.DEPARTED",
  "MOTION.ARRIVED",
  "MOTION.VISUAL_IDLE",
  "MOTION.FAILED",
  "CHARACTER.ACCEPTED",
  "CHARACTER.SETTLED",
  "CHARACTER.FAILED",
  "SCENE_RUNTIME.COMMAND_REJECTED",
]);

function isGatewayCommand(
  event: SceneSessionEvent,
): event is SceneRuntimeGatewayCommand {
  return GATEWAY_COMMAND_TYPES.has(event.type as SceneRuntimeGatewayCommand["type"]);
}

function isGatewayAck(
  event: SceneSessionEvent,
): event is SceneRuntimeGatewayAck {
  if (!GATEWAY_ACK_TYPES.has(event.type as SceneRuntimeGatewayAck["type"])) {
    return false;
  }
  // PRESENTATION.STARTED and PRESENTATION.FAILED are also session lifecycle
  // events. Only gateway ACKs carry the complete correlation envelope.
  return "transactionId" in event
    && "operationId" in event
    && "attemptId" in event
    && "attempt" in event;
}

function isLifecyclePresentationEvent(
  event: SceneSessionEvent,
): boolean {
  return (event.type === "PRESENTATION.STARTED"
      || event.type === "PRESENTATION.FAILED")
    && !("transactionId" in event);
}

function snapshotGatewayAck(ack: SceneRuntimeGatewayAck): SceneSessionGatewayAck {
  if (ack.type === "PRESENTATION.SETTLED") {
    const { result: _imperativeResult, ...diagnostic } = ack;
    return Object.freeze(diagnostic);
  }
  return Object.freeze({ ...ack });
}

function mergedReadiness(
  context: SceneSessionContext,
  patch: Partial<SceneSessionReadiness>,
): SceneSessionReadiness {
  return Object.freeze({ ...context.readiness, ...patch });
}

function frozenError(
  stage: "model" | "presentation",
  message: string,
) {
  return Object.freeze({ stage, message });
}

/**
 * Builds a scene-session machine bound to a concrete runtime input or a
 * revision resolver. The invoked gateway receives the non-serializable port
 * without placing that port, a Three.js object, or an ActorRef in context.
 */
export type SceneSessionInputResolver = (
  sessionRevision: number,
) => SceneSessionInput;

/**
 * A concrete input keeps the standalone API concise. An input resolver lets a
 * long-lived application machine invoke fresh session revisions without ever
 * storing the runtime port in parent or child context.
 */
export function createSceneSessionMachine(
  configuredInputOrResolver: SceneSessionInput | SceneSessionInputResolver,
) {
  const configuredInput = typeof configuredInputOrResolver === "function"
    ? null
    : configuredInputOrResolver;
  if (configuredInput && !Number.isFinite(configuredInput.sessionRevision)) {
    throw new Error("sceneSessionMachine requires a finite sessionRevision.");
  }
  const resolveInput: SceneSessionInputResolver = typeof configuredInputOrResolver === "function"
    ? configuredInputOrResolver
    : () => configuredInputOrResolver;

  const runtimeInputFor = (sessionRevision: number): SceneSessionInput => {
    const resolved = resolveInput(sessionRevision);
    if (!Number.isFinite(resolved.sessionRevision)
      || resolved.sessionRevision !== sessionRevision) {
      throw new Error("sceneSessionMachine resolver returned a mismatched sessionRevision.");
    }
    return resolved;
  };

  const gateway = createSceneRuntimeGateway();
  const gatewayInvoke = {
    id: "sceneRuntimeGateway",
    src: "sceneRuntimeGateway" as const,
    input: ({ context }: { readonly context: SceneSessionContext }) => {
      const resolved = runtimeInputFor(context.sessionRevision);
      return {
        sessionRevision: context.sessionRevision,
        port: resolved.runtimePort,
        defaultTimeoutMs: resolved.gatewayTimeoutMs,
        scheduler: resolved.gatewayScheduler,
      };
    },
  };

  return setup({
    types: {} as {
      context: SceneSessionContext;
      events: SceneSessionEvent;
      input: SceneSessionInput;
    },
    actors: {
      sceneRuntimeGateway: gateway,
    },
    guards: {
      currentSession: ({ context, event }) => (
        event.sessionRevision === context.sessionRevision
      ),
      currentLifecyclePresentationEvent: ({ context, event }) => (
        event.sessionRevision === context.sessionRevision
        && isLifecyclePresentationEvent(event)
      ),
      currentGatewayCommand: ({ context, event }) => (
        event.sessionRevision === context.sessionRevision
        && isGatewayCommand(event)
      ),
      currentGatewayAck: ({ context, event }) => (
        event.sessionRevision === context.sessionRevision
        && isGatewayAck(event)
      ),
      presentationReady: ({ context }) => context.readiness.presentationReady,
      modelReady: ({ context }) => context.readiness.modelReady,
    },
    actions: {
      beginModelLoad: assign(({ context }) => ({
        readiness: mergedReadiness(context, {
          modelReady: false,
          presentationStarted: false,
          presentationReady: false,
          contextAvailable: true,
        }),
        error: null,
      })),
      markModelReady: assign(({ context }) => ({
        readiness: mergedReadiness(context, { modelReady: true }),
        error: null,
      })),
      markPresentationStarted: assign(({ context }) => ({
        readiness: mergedReadiness(context, { presentationStarted: true }),
        error: null,
      })),
      markPresentationReady: assign(({ context }) => ({
        readiness: mergedReadiness(context, {
          presentationStarted: true,
          presentationReady: true,
          contextAvailable: true,
        }),
        error: null,
      })),
      markContextLost: assign(({ context }) => ({
        readiness: mergedReadiness(context, { contextAvailable: false }),
      })),
      markContextRestored: assign(({ context }) => ({
        readiness: mergedReadiness(context, { contextAvailable: true }),
        error: null,
      })),
      recordModelFailure: assign(({ context, event }) => ({
        readiness: mergedReadiness(context, {
          modelReady: false,
          presentationStarted: false,
          presentationReady: false,
        }),
        error: event.type === "MODEL.FAILED"
          ? frozenError("model", event.error)
          : context.error,
      })),
      recordPresentationFailure: assign(({ context, event }) => ({
        readiness: mergedReadiness(context, { presentationReady: false }),
        error: event.type === "PRESENTATION.FAILED" && !isGatewayAck(event)
          ? frozenError("presentation", event.error)
          : context.error,
      })),
      recordGatewayAck: assign(({ context, event }) => ({
        lastGatewayAck: isGatewayAck(event)
          ? snapshotGatewayAck(event)
          : null,
        gatewayAckSequence: isGatewayAck(event)
          ? context.gatewayAckSequence + 1
          : context.gatewayAckSequence,
      })),
      forwardGatewayCommand: sendTo(
        "sceneRuntimeGateway",
        ({ event }) => event as SceneRuntimeGatewayCommand,
      ),
    },
  }).createMachine({
    id: "sceneSession",
    initial: "preparing",
    context: ({ input }) => {
      if (configuredInput && input.sessionRevision !== configuredInput.sessionRevision) {
        throw new Error(
          "sceneSessionMachine actor input must match its configured sessionRevision.",
        );
      }
      return {
        sessionRevision: input.sessionRevision,
        readiness: Object.freeze({
          modelReady: false,
          presentationStarted: false,
          presentationReady: false,
          contextAvailable: true,
        }),
        error: null,
        lastGatewayAck: null,
        gatewayAckSequence: 0,
      };
    },
    on: {
      "SESSION.STOP": {
        guard: "currentSession",
        target: ".disposed",
      },
      "*": [
        {
          guard: "currentGatewayAck",
          actions: "recordGatewayAck",
        },
      ],
    },
    states: {
      preparing: {
        on: {
          "MODEL.LOAD_STARTED": {
            guard: "currentSession",
            actions: "beginModelLoad",
            target: "loadingModel",
          },
          "CONTEXT.LOST": {
            guard: "currentSession",
            actions: "markContextLost",
            target: "contextLost",
          },
        },
      },
      loadingModel: {
        on: {
          "MODEL.READY": {
            guard: "currentSession",
            actions: "markModelReady",
            target: "presenting",
          },
          "MODEL.FAILED": {
            guard: "currentSession",
            actions: "recordModelFailure",
            target: "degraded",
          },
          "CONTEXT.LOST": {
            guard: "currentSession",
            actions: "markContextLost",
            target: "contextLost",
          },
        },
      },
      presenting: {
        invoke: gatewayInvoke,
        on: {
          "PRESENTATION.STARTED": [
            {
              guard: "currentLifecyclePresentationEvent",
              actions: "markPresentationStarted",
            },
            {
              guard: "currentGatewayAck",
              actions: "recordGatewayAck",
            },
          ],
          "PRESENTATION.READY": {
            guard: "currentSession",
            actions: "markPresentationReady",
            target: "active",
          },
          "PRESENTATION.FAILED": [
            {
              guard: "currentLifecyclePresentationEvent",
              actions: "recordPresentationFailure",
              target: "degraded",
            },
            {
              guard: "currentGatewayAck",
              actions: "recordGatewayAck",
            },
          ],
          "CONTEXT.LOST": {
            guard: "currentSession",
            actions: "markContextLost",
            target: "contextLost",
          },
          "*": {
            guard: "currentGatewayCommand",
            actions: "forwardGatewayCommand",
          },
        },
      },
      active: {
        invoke: gatewayInvoke,
        on: {
          "PRESENTATION.FAILED": [
            {
              guard: "currentLifecyclePresentationEvent",
              actions: "recordPresentationFailure",
              target: "degraded",
            },
            {
              guard: "currentGatewayAck",
              actions: "recordGatewayAck",
            },
          ],
          "CONTEXT.LOST": {
            guard: "currentSession",
            actions: "markContextLost",
            target: "contextLost",
          },
          "*": {
            guard: "currentGatewayCommand",
            actions: "forwardGatewayCommand",
          },
        },
      },
      contextLost: {
        on: {
          "CONTEXT.RESTORED": [
            {
              guard: ({ context, event }) => (
                event.sessionRevision === context.sessionRevision
                && context.readiness.presentationReady
              ),
              actions: "markContextRestored",
              target: "active",
            },
            {
              guard: ({ context, event }) => (
                event.sessionRevision === context.sessionRevision
                && context.readiness.modelReady
              ),
              actions: "markContextRestored",
              target: "presenting",
            },
            {
              guard: "currentSession",
              actions: "markContextRestored",
              target: "loadingModel",
            },
          ],
          "PRESENTATION.FAILED": [
            {
              guard: "currentLifecyclePresentationEvent",
              actions: "recordPresentationFailure",
              target: "degraded",
            },
            {
              guard: "currentGatewayAck",
              actions: "recordGatewayAck",
            },
          ],
        },
      },
      degraded: {
        on: {
          "MODEL.LOAD_STARTED": {
            guard: "currentSession",
            actions: "beginModelLoad",
            target: "loadingModel",
          },
          "MODEL.READY": {
            guard: "currentSession",
            actions: "markModelReady",
            target: "presenting",
          },
          "PRESENTATION.STARTED": {
            guard: ({ context, event }) => (
              event.sessionRevision === context.sessionRevision
              && isLifecyclePresentationEvent(event)
              && context.readiness.modelReady
            ),
            actions: "markPresentationStarted",
            target: "presenting",
          },
          "CONTEXT.RESTORED": [
            {
              guard: ({ context, event }) => (
                event.sessionRevision === context.sessionRevision
                && context.readiness.presentationReady
              ),
              actions: "markContextRestored",
              target: "active",
            },
            {
              guard: ({ context, event }) => (
                event.sessionRevision === context.sessionRevision
                && context.readiness.modelReady
              ),
              actions: "markContextRestored",
              target: "presenting",
            },
          ],
        },
      },
      disposed: {
        type: "final",
      },
    },
  });
}

export type SceneSessionMachine = ReturnType<typeof createSceneSessionMachine>;
export type SceneSessionSnapshot = SnapshotFrom<SceneSessionMachine>;
