import type { ActorLogic, ActorRefFrom } from "xstate";
import {
  createLearningPathMachine,
  type LearningPathEvent,
  type LearningPathMachineInput,
  type LearningPathMachineSnapshot,
  type OrchestrationServices,
} from "../../statecharts/learningPathMachine";

export type PathOrchestrationChildLogic = ActorLogic<
  LearningPathMachineSnapshot,
  LearningPathEvent,
  LearningPathMachineInput
>;

export type PathOrchestrationActor = ActorRefFrom<PathOrchestrationChildLogic>;

/**
 * Narrow ownership boundary between the application actor and the imperative
 * Three.js runtime. The application root owns the actor lifecycle; the runtime
 * only contributes ports/input and receives a temporary actor binding.
 */
export interface PathOrchestrationRuntimeBinding {
  readonly input: LearningPathMachineInput;
  readonly services: OrchestrationServices;
  bindActor(actor: PathOrchestrationActor): void;
  unbindActor(actor?: PathOrchestrationActor): void;
}

export type ResolvePathOrchestrationBinding = () => PathOrchestrationRuntimeBinding;

/** One stable machine logic whose injected services delegate to the active session binding. */
export function createPathOrchestrationChildLogic(
  resolveBinding: ResolvePathOrchestrationBinding,
): PathOrchestrationChildLogic {
  const resolveServices = (): OrchestrationServices => resolveBinding().services;
  const services: OrchestrationServices = {
    planNavigation: (...args) => resolveServices().planNavigation(...args),
    planZoneReveal: (...args) => resolveServices().planZoneReveal(...args),
    planZoneDismiss: (...args) => resolveServices().planZoneDismiss(...args),
    commitNavigationBeforeAction: (...args) => (
      resolveServices().commitNavigationBeforeAction(...args)
    ),
    commitNavigationStageStarted: (...args) => (
      resolveServices().commitNavigationStageStarted(...args)
    ),
    commitNavigationAfterAction: (...args) => (
      resolveServices().commitNavigationAfterAction(...args)
    ),
    commitNavigationStageArrived: (...args) => (
      resolveServices().commitNavigationStageArrived(...args)
    ),
    cancelNavigationPlan: (...args) => resolveServices().cancelNavigationPlan?.(...args),
    commitZoneRevealBeforeAction: (...args) => (
      resolveServices().commitZoneRevealBeforeAction(...args)
    ),
    commitZoneRevealStep: (...args) => resolveServices().commitZoneRevealStep(...args),
    commitZoneDismissStep: (...args) => resolveServices().commitZoneDismissStep(...args),
    executePresentation: (...args) => resolveServices().executePresentation(...args),
    executeMotion: (...args) => resolveServices().executeMotion(...args),
    executeCharacterForceSettle: (...args) => (
      resolveServices().executeCharacterForceSettle?.(...args)
    ),
    get characterNaturalSettleTimeoutMs() {
      return resolveServices().characterNaturalSettleTimeoutMs;
    },
    get characterForceSettleAckTimeoutMs() {
      return resolveServices().characterForceSettleAckTimeoutMs;
    },
    onRecoveryStarted: (...args) => resolveServices().onRecoveryStarted?.(...args),
    prepareRecoveryInput: (...args) => resolveServices().prepareRecoveryInput(...args),
    executeRecoveryCommand: (...args) => resolveServices().executeRecoveryCommand(...args),
    finalizeRecovery: (...args) => resolveServices().finalizeRecovery(...args),
    cancelRecovery: (...args) => resolveServices().cancelRecovery(...args),
    get recoveryCommandTimeoutMs() {
      return resolveServices().recoveryCommandTimeoutMs;
    },
    get recoveryCharacterIdleTimeoutMs() {
      return resolveServices().recoveryCharacterIdleTimeoutMs;
    },
    onOperationRetry: (...args) => resolveServices().onOperationRetry?.(...args),
    onNavigationTransactionSettled: (...args) => (
      resolveServices().onNavigationTransactionSettled?.(...args)
    ),
    onNavigationSettled: (...args) => resolveServices().onNavigationSettled?.(...args),
    onStandaloneZoneTransactionSettled: (...args) => (
      resolveServices().onStandaloneZoneTransactionSettled?.(...args)
    ),
    onNavigationRejected: (...args) => resolveServices().onNavigationRejected?.(...args),
  };

  type PathMachine = ReturnType<typeof createLearningPathMachine>;
  const machineByActor = new WeakMap<object, PathMachine>();
  const resolveMachine = (actorScope: { readonly self: object }): PathMachine => {
    const active = machineByActor.get(actorScope.self);
    if (active) return active;
    // Machine setup reads recovery timeout policy while it is constructed.
    // Delaying construction until XState starts the invoked child preserves
    // per-session options without requiring a binding during graph analysis.
    const machine = createLearningPathMachine(services);
    machineByActor.set(actorScope.self, machine);
    return machine;
  };

  return {
    transition: (snapshot, event, actorScope) => (
      resolveMachine(actorScope).transition(snapshot, event, actorScope)
    ),
    getInitialSnapshot: (actorScope, input) => (
      resolveMachine(actorScope).getInitialSnapshot(actorScope, input)
    ),
    restoreSnapshot: (persistedState, actorScope) => (
      resolveMachine(actorScope).restoreSnapshot(persistedState, actorScope)
    ),
    start: (snapshot, actorScope) => {
      // `start` runs before the invoked actor can emit an onSnapshot event to
      // its parent. Bind here so a session activated by the parent's first
      // observable active snapshot can never race the runtime's first frame.
      resolveBinding().bindActor(actorScope.self as PathOrchestrationActor);
      resolveMachine(actorScope).start(snapshot);
    },
    getPersistedSnapshot: (snapshot, options) => (
      snapshot.machine.getPersistedSnapshot(snapshot, options)
    ),
  };
}
