import type {
  CompiledLearningPath,
  CompiledLearningPathNode,
  LearningEntityId,
} from "../../content";

/** Immutable authored-graph index used by progression policies and reducers. */
export interface ProgressGraph {
  readonly path: CompiledLearningPath;
  readonly nodeById: ReadonlyMap<LearningEntityId, CompiledLearningPathNode>;
  readonly subjectIds: readonly LearningEntityId[];
  readonly conceptIds: readonly LearningEntityId[];
  readonly goalIds: ReadonlySet<LearningEntityId>;
  readonly incomingBySubjectId: ReadonlyMap<LearningEntityId, readonly LearningEntityId[]>;
  readonly outgoingBySubjectId: ReadonlyMap<LearningEntityId, readonly LearningEntityId[]>;
  readonly conceptsBySubjectId: ReadonlyMap<LearningEntityId, readonly LearningEntityId[]>;
}

export function sortNodeIds(
  ids: Iterable<LearningEntityId>,
  nodeById: ReadonlyMap<LearningEntityId, CompiledLearningPathNode>,
): readonly LearningEntityId[] {
  return [...ids].sort((left, right) => {
    const leftNode = nodeById.get(left);
    const rightNode = nodeById.get(right);
    const order = (leftNode?.navigationOrder ?? Number.MAX_SAFE_INTEGER)
      - (rightNode?.navigationOrder ?? Number.MAX_SAFE_INTEGER);
    return order || left.localeCompare(right);
  });
}

export function buildProgressGraph(path: CompiledLearningPath): ProgressGraph {
  const subjects = path.nodes.filter((node) => node.entityKind === "subject");
  const concepts = path.nodes.filter((node) => node.entityKind === "concept");
  const subjectIds = sortNodeIds(subjects.map((node) => node.id), path.nodeById);
  const conceptIds = sortNodeIds(concepts.map((node) => node.id), path.nodeById);
  const incoming = new Map<LearningEntityId, LearningEntityId[]>();
  const outgoing = new Map<LearningEntityId, LearningEntityId[]>();
  for (const subjectId of subjectIds) {
    incoming.set(subjectId, []);
    outgoing.set(subjectId, []);
  }
  for (const edge of path.edges) {
    if (edge.sourceKind !== "subject-flow") continue;
    incoming.get(edge.toNodeId)?.push(edge.fromNodeId);
    outgoing.get(edge.fromNodeId)?.push(edge.toNodeId);
  }

  const conceptsBySubject = new Map<LearningEntityId, LearningEntityId[]>();
  for (const subjectId of subjectIds) conceptsBySubject.set(subjectId, []);
  for (const concept of concepts) {
    if (!concept.ownerSubjectId) continue;
    conceptsBySubject.get(concept.ownerSubjectId)?.push(concept.id);
  }

  return Object.freeze({
    path,
    nodeById: path.nodeById,
    subjectIds,
    conceptIds,
    goalIds: new Set(path.goalNodeIds),
    incomingBySubjectId: new Map([...incoming].map(([id, ids]) => (
      [id, sortNodeIds(ids, path.nodeById)] as const
    ))),
    outgoingBySubjectId: new Map([...outgoing].map(([id, ids]) => (
      [id, sortNodeIds(ids, path.nodeById)] as const
    ))),
    conceptsBySubjectId: new Map([...conceptsBySubject].map(([id, ids]) => (
      [id, sortNodeIds(ids, path.nodeById)] as const
    ))),
  });
}
