export type NodeId = string;
export type EdgeId = string;

export interface PathPosition {
  readonly x: number;
  readonly z: number;
}

export type NodeVariant = "green" | "gray" | "brown";
export type PathKind = "straight" | "overpass";

/**
 * Completion is construct-local. In particular, an edge marked
 * `promote-to-green` can never override a destination node whose own policy is
 * `preserve-variant`.
 */
export type CompletionPolicy = "promote-to-green" | "preserve-variant";

export interface LearningPathNode {
  readonly id: NodeId;
  readonly navigationOrder: number;
  readonly label: string;
  readonly position: PathPosition;
  readonly initiallyGreen: boolean;
  readonly initiallyVisible: boolean;
  readonly completionPolicy: CompletionPolicy;
  /** Optional declarative owner for a group revealed by a path rule. */
  readonly activationGroupId?: string;
  /** Occupied top surface. Most nodes use .523; interchange/lift nodes may be higher. */
  readonly surfaceY: number;
  /** Stable visual identity; completion state must not recolor fixed gray/brown nodes. */
  readonly variant: NodeVariant;
}

/**
 * `fromNodeId -> toNodeId` describes authored learning progression. Character
 * traversal treats an active road as bidirectional so every visible node stays
 * clickable. Visibility is independent from whether the definition is part of
 * the authored graph.
 */
interface LearningPathEdgeBase {
  readonly id: EdgeId;
  readonly fromNodeId: NodeId;
  readonly toNodeId: NodeId;
  readonly initiallyVisible: boolean;
  readonly completionPolicy: CompletionPolicy;
  /** Optional declarative owner for a group revealed by a path rule. */
  readonly activationGroupId?: string;
}

export interface StraightLearningPathEdge extends LearningPathEdgeBase {
  readonly pathKind: "straight";
}

export interface OverpassLearningPathEdge extends LearningPathEdgeBase {
  readonly pathKind: "overpass";
  /** A mirrored eased arch with horizontal tangents at both landings and the crown. */
  readonly curveStyle: "symmetric-eased-arch";
  readonly width: number;
  readonly deckThickness: number;
  /** Distance from each node centre to the bridge seam at the inner rim. */
  readonly platformEdgeOffset: number;
  /** Visible flat landing between each platform rim and the raised arch. */
  readonly straightApproachLength: number;
  /** Top-surface elevation at the exact midpoint of the symmetric arch. */
  readonly bridgeSurfaceY: number;
  /** Maximum pitch the character rig is allowed to follow on this deck. */
  readonly maximumSurfacePitchDegrees: number;
  /** Route-planning cost; movement still uses the real three-dimensional length. */
  readonly routingCost: number;
  /** Ground routes whose swept width lies below the bridge deck. */
  readonly underpassEdgeIds: readonly EdgeId[];
  readonly requiredClearance: number;
}

export type LearningPathEdge =
  | StraightLearningPathEdge
  | OverpassLearningPathEdge;

export interface LearningPathGraph {
  readonly nodes: readonly LearningPathNode[];
  readonly edges: readonly LearningPathEdge[];
  readonly initialNodeId: NodeId;
  readonly entryNodeId: NodeId;
  readonly goalNodeId: NodeId;
}

