import { fromTransition } from "xstate";
import type { CompiledLearningPath } from "../../content";
import { buildProgressGraph, type ProgressGraph } from "../../progression/domain/graph";
import { createInitialProgressContext } from "../../progression/domain/policies";
import { reduceLearningProgress } from "../../progression/domain/reducer";
import type { LearningProgressEvent } from "../../progression/domain/types";
import type {
  RevisionProgressContext,
  RevisionProgressInput,
} from "./types";

export type ResolveProgressPath = (revision: string) => CompiledLearningPath;

/**
 * Adapts the path-closed progression reducer to an invoked, revision-bound
 * actor. Its context stays serializable; immutable graph indexes live only in
 * this factory's private cache.
 */
export function createRevisionProgressActorLogic(resolvePath: ResolveProgressPath) {
  const graphByRevision = new Map<string, ProgressGraph>();
  const resolveGraph = (revision: string): ProgressGraph => {
    const cached = graphByRevision.get(revision);
    if (cached) return cached;
    const graph = buildProgressGraph(resolvePath(revision));
    // Only the current revision is routable. Bound this private cache across
    // repeated generation sessions instead of retaining every historic graph.
    graphByRevision.clear();
    graphByRevision.set(revision, graph);
    return graph;
  };

  return fromTransition<
    RevisionProgressContext,
    LearningProgressEvent,
    never,
    RevisionProgressInput
  >(
    (context, event) => Object.freeze({
      revision: context.revision,
      model: reduceLearningProgress(resolveGraph(context.revision), context.model, event),
    }),
    ({ input }) => Object.freeze({
      revision: input.revision,
      model: input.initialContext
        ?? createInitialProgressContext(resolveGraph(input.revision)),
    }),
  );
}

export function createRevisionInitialProgressContext(
  resolvePath: ResolveProgressPath,
  revision: string,
) {
  return createInitialProgressContext(buildProgressGraph(resolvePath(revision)));
}
