/** A JSON value with no host objects, executable values, or lossy primitives. */
export type JsonPrimitive = string | number | boolean | null;

export type JsonValue =
  | JsonPrimitive
  | readonly JsonValue[]
  | { readonly [key: string]: JsonValue };

export interface JsonSafetyFailure {
  readonly path: string;
  readonly reason: string;
  readonly receivedType: string;
}

export type JsonSafetyResult =
  | Readonly<{ safe: true }>
  | Readonly<{ safe: false; failure: JsonSafetyFailure }>;

export class JsonSafetyError extends TypeError {
  public readonly failure: JsonSafetyFailure;

  public constructor(failure: JsonSafetyFailure) {
    super(
      `Value at ${failure.path} is not JSON-safe: ${failure.reason} `
      + `(received ${failure.receivedType}).`,
    );
    this.name = "JsonSafetyError";
    this.failure = failure;
  }
}

function valueType(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "Array";

  const primitiveType = typeof value;
  if (primitiveType !== "object") return primitiveType;

  const constructor = Object.getPrototypeOf(value) === null
    ? null
    : (value as { readonly constructor?: { readonly name?: string } }).constructor;
  return constructor?.name ?? "object";
}

function propertyPath(parent: string, key: string): string {
  return /^[A-Za-z_$][\w$]*$/u.test(key)
    ? `${parent}.${key}`
    : `${parent}[${JSON.stringify(key)}]`;
}

function failure(path: string, reason: string, value: unknown): JsonSafetyResult {
  return Object.freeze({
    safe: false,
    failure: Object.freeze({ path, reason, receivedType: valueType(value) }),
  });
}

/**
 * Recursively checks the exact runtime value that will enter an actor context.
 *
 * JSON.stringify is intentionally not used as the validator: it silently drops
 * undefined/functions, coerces non-finite numbers, invokes toJSON, and accepts
 * class instances. This guard rejects every such lossy case and reports the
 * first precise property path.
 */
export function inspectJsonSafety(value: unknown): JsonSafetyResult {
  const ancestors = new Map<object, string>();

  const visit = (candidate: unknown, path: string): JsonSafetyResult => {
    if (candidate === null) return Object.freeze({ safe: true });

    switch (typeof candidate) {
      case "string":
      case "boolean":
        return Object.freeze({ safe: true });
      case "number":
        return Number.isFinite(candidate)
          ? Object.freeze({ safe: true })
          : failure(path, "numbers must be finite", candidate);
      case "undefined":
        return failure(path, "undefined is omitted or coerced by JSON.stringify", candidate);
      case "bigint":
      case "symbol":
      case "function":
        return failure(path, `${typeof candidate} values are not JSON data`, candidate);
      case "object":
        break;
      default:
        return failure(path, "unsupported JavaScript value", candidate);
    }

    const object = candidate as object;
    const ancestorPath = ancestors.get(object);
    if (ancestorPath) {
      return failure(path, `cyclic reference to ${ancestorPath}`, candidate);
    }

    const prototype = Object.getPrototypeOf(object);
    const isArray = Array.isArray(object);
    if (!isArray && prototype !== Object.prototype && prototype !== null) {
      return failure(
        path,
        "only arrays and plain objects may cross the actor serialization boundary",
        candidate,
      );
    }

    const symbolKeys = Object.getOwnPropertySymbols(object);
    if (symbolKeys.length > 0) {
      return failure(path, "symbol-keyed properties are not representable in JSON", candidate);
    }

    ancestors.set(object, path);
    try {
      if (isArray) {
        const array = object as readonly unknown[];
        for (let index = 0; index < array.length; index += 1) {
          if (!Object.hasOwn(array, index)) {
            return failure(
              `${path}[${index}]`,
              "sparse array entries are coerced to null by JSON.stringify",
              undefined,
            );
          }
          const result = visit(array[index], `${path}[${index}]`);
          if (!result.safe) return result;
        }

        const nonIndexKeys = Object.getOwnPropertyNames(array).filter((key) => {
          if (key === "length") return false;
          const index = Number(key);
          return !Number.isInteger(index) || index < 0 || index >= array.length || String(index) !== key;
        });
        if (nonIndexKeys.length > 0) {
          return failure(
            propertyPath(path, nonIndexKeys[0] ?? "<unknown>"),
            "custom array properties are ignored by JSON.stringify",
            array[nonIndexKeys[0] as keyof typeof array],
          );
        }
        return Object.freeze({ safe: true });
      }

      for (const key of Object.getOwnPropertyNames(object)) {
        const descriptor = Object.getOwnPropertyDescriptor(object, key);
        if (!descriptor) continue;
        if (descriptor.get || descriptor.set) {
          return failure(
            propertyPath(path, key),
            "accessor properties are executable behavior, not inert JSON data",
            candidate,
          );
        }
        if (!descriptor.enumerable) {
          return failure(
            propertyPath(path, key),
            "non-enumerable properties are ignored by JSON.stringify",
            descriptor.value,
          );
        }
        const result = visit(descriptor.value, propertyPath(path, key));
        if (!result.safe) return result;
      }
      return Object.freeze({ safe: true });
    } finally {
      ancestors.delete(object);
    }
  };

  return visit(value, "$");
}

export function assertJsonSafe(value: unknown): asserts value is JsonValue {
  const result = inspectJsonSafety(value);
  if (!result.safe) throw new JsonSafetyError(result.failure);
}
