import type {
  CompletionCelebrationSettledDetail,
  CompletionCelebrationViewModel,
  ContextualCardActionRequestedDetail,
  ContextualCardLayoutMetrics,
  ContextualCardPlacement,
  ContextualNodeCardViewModel,
} from "./ContextualCardContracts";
import { CompletionCelebrationView } from "./CompletionCelebrationView";
import type {
  GenerateRequestedEventDetail,
  GenerationGateViewModel,
} from "./GenerationGateContracts";
import { GenerationGateView } from "./GenerationGateView";
import { ContextualNodeCardView } from "./ContextualNodeCardView";
import { acquireLearningPathUIStyles } from "./domViewUtils";

export interface LearningPathPageViewModel {
  readonly generation: GenerationGateViewModel;
  readonly card?: ContextualNodeCardViewModel | null;
  readonly celebration?: CompletionCelebrationViewModel | null;
}

export interface LearningPathPageShellOptions {
  readonly onLaunchRequested?: (detail: GenerateRequestedEventDetail) => void;
  readonly onCardActionRequested?: (detail: ContextualCardActionRequestedDetail) => void;
  readonly onCelebrationSettled?: (detail: CompletionCelebrationSettledDetail) => void;
}

/** DOM-only overlay root: generation gate, one contextual card and celebration. */
export class LearningPathPageShell {
  private readonly root: HTMLDivElement;
  private readonly generationGate: GenerationGateView;
  private readonly card: ContextualNodeCardView;
  private readonly celebration: CompletionCelebrationView;
  private readonly releaseStyles: () => void;
  private disposed = false;

  public constructor(mount: HTMLElement, options: LearningPathPageShellOptions = {}) {
    const document = mount.ownerDocument;
    this.releaseStyles = acquireLearningPathUIStyles(document);
    this.root = document.createElement("div");
    this.root.className = "lp-ui-shell";
    this.root.dataset.generationPhase = "ready";

    const gateMount = document.createElement("div");
    gateMount.className = "lp-ui-shell__gate";
    const cardMount = document.createElement("div");
    cardMount.className = "lp-ui-shell__context-card";
    const celebrationMount = document.createElement("div");
    celebrationMount.className = "lp-ui-shell__celebration";
    this.root.append(gateMount, cardMount, celebrationMount);
    mount.append(this.root);

    this.generationGate = new GenerationGateView(gateMount, {
      onLaunchRequested: options.onLaunchRequested,
    });
    this.card = new ContextualNodeCardView(cardMount, {
      onActionRequested: options.onCardActionRequested,
    });
    this.celebration = new CompletionCelebrationView(celebrationMount, {
      onSettled: options.onCelebrationSettled,
    });
  }

  public setViewModel(viewModel: LearningPathPageViewModel): void {
    if (this.disposed) return;
    this.root.dataset.generationPhase = viewModel.generation.phase;
    this.root.setAttribute(
      "aria-busy",
      String(viewModel.generation.phase === "requested" || viewModel.generation.phase === "generating"),
    );
    this.generationGate.setViewModel(viewModel.generation);
    this.card.setViewModel(viewModel.card ?? null);
    this.celebration.setViewModel(viewModel.celebration ?? null);
  }

  public setCardPlacement(placement: ContextualCardPlacement | null): void {
    this.card.setPlacement(placement);
  }

  public getCardLayoutMetrics(): ContextualCardLayoutMetrics {
    return this.card.getLayoutMetrics();
  }

  public containsCardEventPath(event: Event): boolean {
    return this.card.containsEventPath(event);
  }

  public focusCard(): void {
    this.card.focus();
  }

  public focusGenerationAction(): void {
    this.generationGate.focus();
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.generationGate.dispose();
    this.card.dispose();
    this.celebration.dispose();
    this.root.remove();
    this.releaseStyles();
  }
}
