const instanceRegistry = new WeakMap<Document, Set<string>>();

/**
 * Reserves one instance identity per owner document. The idempotent release
 * callback is deliberately compatible with React StrictMode's mount → cleanup
 * → remount probe.
 */
export function reserveLearningPathInstance(
  document: Document,
  instanceId: string,
): () => void {
  let instances = instanceRegistry.get(document);
  if (!instances) {
    instances = new Set();
    instanceRegistry.set(document, instances);
  }
  if (instances.has(instanceId)) {
    throw new Error(`Learning-path instance "${instanceId}" is already mounted.`);
  }
  instances.add(instanceId);
  let released = false;
  return () => {
    if (released) return;
    released = true;
    instances?.delete(instanceId);
    if (instances?.size === 0) instanceRegistry.delete(document);
  };
}
