import type { SceneSessionLifecycleEvent } from "./types";

export type SceneSessionLifecycleFactEvent =
  | Readonly<{ type: "MODEL.LOAD_STARTED" }>
  | Readonly<{ type: "MODEL.READY" }>
  | Readonly<{ type: "MODEL.FAILED"; error: string }>
  | Readonly<{ type: "PRESENTATION.STARTED" }>
  | Readonly<{ type: "PRESENTATION.READY" }>
  | Readonly<{ type: "PRESENTATION.FAILED"; error: string }>
  | Readonly<{ type: "CONTEXT.LOST" }>
  | Readonly<{ type: "CONTEXT.RESTORED" }>;

export interface SceneSessionLifecycleFactsSnapshot {
  readonly modelPhase: "not-started" | "loading" | "ready" | "failed";
  readonly modelError: string | null;
  readonly presentationPhase: "not-started" | "presenting" | "ready" | "failed";
  readonly presentationError: string | null;
  readonly contextAvailable: boolean;
}

export interface SceneSessionLifecycleSource {
  getSceneSessionLifecycleSnapshot(): SceneSessionLifecycleFactsSnapshot;
  subscribeSceneSessionLifecycle(
    listener: (event: SceneSessionLifecycleFactEvent) => void,
  ): { unsubscribe(): void };
}

export interface SceneSessionLifecycleBindingOptions {
  readonly sessionRevision: number;
  readonly source: SceneSessionLifecycleSource;
  readonly isCurrentSession: () => boolean;
  readonly send: (event: SceneSessionLifecycleEvent) => void;
}

/**
 * Binds a renderer lifecycle source to one application revision. Facts settled
 * before the application child exists are replayed from the source snapshot;
 * all later facts use the same immutable revision and are cut off by cleanup.
 */
export function bindSceneSessionLifecycle(
  options: SceneSessionLifecycleBindingOptions,
): { unsubscribe(): void } {
  let active = true;
  const dispatch = (event: SceneSessionLifecycleFactEvent): void => {
    if (!active || !options.isCurrentSession()) return;
    switch (event.type) {
      case "MODEL.LOAD_STARTED":
      case "MODEL.READY":
      case "PRESENTATION.STARTED":
      case "PRESENTATION.READY":
      case "CONTEXT.LOST":
      case "CONTEXT.RESTORED":
        options.send({ type: event.type, sessionRevision: options.sessionRevision });
        break;
      case "MODEL.FAILED":
      case "PRESENTATION.FAILED":
        options.send({
          type: event.type,
          sessionRevision: options.sessionRevision,
          error: event.error,
        });
        break;
    }
  };

  // Subscribe first. JavaScript's run-to-completion semantics then make the
  // immediate snapshot replay and the future edge stream race-free.
  const sourceSubscription = options.source.subscribeSceneSessionLifecycle(dispatch);
  const snapshot = options.source.getSceneSessionLifecycleSnapshot();
  if (snapshot.modelPhase !== "not-started") {
    dispatch({ type: "MODEL.LOAD_STARTED" });
  }
  if (snapshot.modelPhase === "ready") {
    dispatch({ type: "MODEL.READY" });
  } else if (snapshot.modelPhase === "failed") {
    dispatch({
      type: "MODEL.FAILED",
      error: snapshot.modelError ?? "Character model loading failed.",
    });
  }
  if (snapshot.presentationPhase !== "not-started") {
    dispatch({ type: "PRESENTATION.STARTED" });
  }
  if (snapshot.presentationPhase === "ready") {
    dispatch({ type: "PRESENTATION.READY" });
  } else if (snapshot.presentationPhase === "failed") {
    dispatch({
      type: "PRESENTATION.FAILED",
      error: snapshot.presentationError ?? "Generation presentation failed.",
    });
  }
  if (!snapshot.contextAvailable) dispatch({ type: "CONTEXT.LOST" });

  return Object.freeze({
    unsubscribe: () => {
      if (!active) return;
      active = false;
      sourceSubscription.unsubscribe();
    },
  });
}

