import type {
  CompiledLearningPathPage,
  PathRevealStep,
} from "./contracts";

export interface RevealOrderValidation {
  readonly valid: boolean;
  readonly error: string | null;
}

function invalid(error: string): RevealOrderValidation {
  return Object.freeze({ valid: false, error });
}

/**
 * Protects the renderer from partially ordered compiler output. The full path
 * visible construct must be represented exactly once, `initialNodeId` must be
 * first, and a road may only be revealed after both endpoint platforms have
 * settled. Hidden concepts stay in the compiled graph for later reveals.
 */
export function validateCompiledRevealOrder(
  compiled: CompiledLearningPathPage,
): RevealOrderValidation {
  if (typeof compiled.revision !== "string" || compiled.revision.trim().length === 0) {
    return invalid("Compiled revision must be a non-empty string.");
  }
  if (!Array.isArray(compiled.nodes)
    || !Array.isArray(compiled.edges)
    || !Array.isArray(compiled.revealOrder)) {
    return invalid("Compiled nodes, edges, and revealOrder must be arrays.");
  }
  const first = compiled.revealOrder[0];
  if (!first || first.kind !== "node" || first.nodeId !== compiled.initialNodeId) {
    return invalid(`revealOrder must begin with initialNodeId "${compiled.initialNodeId}".`);
  }

  const nodeIds = new Set<string>();
  const initiallyVisibleNodeIds = new Set<string>();
  for (const node of compiled.nodes) {
    if (nodeIds.has(node.id)) return invalid(`Duplicate compiled node "${node.id}".`);
    if (typeof node.initiallyVisible !== "boolean") {
      return invalid(`Node "${node.id}" must declare initiallyVisible.`);
    }
    nodeIds.add(node.id);
    if (node.initiallyVisible) initiallyVisibleNodeIds.add(node.id);
  }
  if (!nodeIds.has(compiled.initialNodeId)) {
    return invalid(`Compiled nodes do not contain initialNodeId "${compiled.initialNodeId}".`);
  }
  if (!initiallyVisibleNodeIds.has(compiled.initialNodeId)) {
    return invalid(`Initial node "${compiled.initialNodeId}" must be initially visible.`);
  }

  const edgesById = new Map(compiled.edges.map((edge) => [edge.id, edge] as const));
  if (edgesById.size !== compiled.edges.length) {
    return invalid("Compiled edges contain duplicate IDs.");
  }
  const initiallyVisibleEdgeIds = new Set<string>();
  for (const edge of compiled.edges) {
    if (typeof edge.initiallyVisible !== "boolean") {
      return invalid(`Edge "${edge.id}" must declare initiallyVisible.`);
    }
    if (!nodeIds.has(edge.fromNodeId) || !nodeIds.has(edge.toNodeId)) {
      return invalid(`Edge "${edge.id}" references an unknown endpoint node.`);
    }
    if (edge.initiallyVisible) initiallyVisibleEdgeIds.add(edge.id);
  }

  const revealedNodes = new Set<string>();
  const revealedEdges = new Set<string>();
  for (const step of compiled.revealOrder) {
    if (step.kind === "node") {
      if (!nodeIds.has(step.nodeId)) {
        return invalid(`Reveal order references unknown node "${step.nodeId}".`);
      }
      if (!initiallyVisibleNodeIds.has(step.nodeId)) {
        return invalid(`Reveal order includes hidden node "${step.nodeId}".`);
      }
      if (revealedNodes.has(step.nodeId)) {
        return invalid(`Reveal order repeats node "${step.nodeId}".`);
      }
      revealedNodes.add(step.nodeId);
      continue;
    }

    const edge = edgesById.get(step.edgeId);
    if (!edge) return invalid(`Reveal order references unknown edge "${step.edgeId}".`);
    if (!initiallyVisibleEdgeIds.has(step.edgeId)) {
      return invalid(`Reveal order includes hidden edge "${step.edgeId}".`);
    }
    if (revealedEdges.has(step.edgeId)) {
      return invalid(`Reveal order repeats edge "${step.edgeId}".`);
    }
    if (edge.fromNodeId !== step.fromNodeId || edge.toNodeId !== step.toNodeId) {
      return invalid(`Reveal step endpoints do not match edge "${step.edgeId}".`);
    }
    if (!revealedNodes.has(step.fromNodeId) || !revealedNodes.has(step.toNodeId)) {
      return invalid(`Edge "${step.edgeId}" appears before both endpoint nodes.`);
    }
    revealedEdges.add(step.edgeId);
  }

  if (revealedNodes.size !== initiallyVisibleNodeIds.size) {
    return invalid("Reveal order does not contain every initially visible node exactly once.");
  }
  if (revealedEdges.size !== initiallyVisibleEdgeIds.size) {
    return invalid("Reveal order does not contain every initially visible edge exactly once.");
  }

  return Object.freeze({ valid: true, error: null });
}

export function pathStepIdentity(step: PathRevealStep): string {
  return step.kind === "node" ? `node:${step.nodeId}` : `edge:${step.edgeId}`;
}
