import {
  CONTEXTUAL_CARD_EVENT,
  type ContextualCardActionRequestedDetail,
  type ContextualCardActionSlot,
  type ContextualCardActionViewModel,
  type ContextualCardLayoutMetrics,
  type ContextualCardPlacement,
  type ContextualNodeCardViewModel,
} from "./ContextualCardContracts";

const STYLE_ATTRIBUTE = "data-contextual-learning-card-styles";
const styleRegistry = new WeakMap<Document, { element: HTMLStyleElement; owners: number }>();

