export interface ContextualNodeCardViewOptions {
  readonly onActionRequested?: (detail: ContextualCardActionRequestedDetail) => void;
}

export class ContextualNodeCardView {
  private readonly document: Document;
  private readonly mount: HTMLElement;
  private readonly root: HTMLElement;
  private readonly panel: HTMLElement;
  private readonly eyebrow: HTMLParagraphElement;
  private readonly title: HTMLHeadingElement;
  private readonly status: HTMLSpanElement;
  private readonly description: HTMLParagraphElement;
  private readonly actions: HTMLDivElement;
  private readonly primaryButton: HTMLButtonElement;
  private readonly secondaryButton: HTMLButtonElement;
  private readonly releaseStyles: () => void;
  private readonly onActionRequested?: (detail: ContextualCardActionRequestedDetail) => void;
  private readonly resizeObserver: ResizeObserver | null;
  private readonly layoutMetrics: ContextualCardLayoutMetrics & {
    visible: boolean;
    placed: boolean;
    top: number;
    bottom: number;
    width: number;
    height: number;
    centerX: number;
  } = {
    visible: false,
    placed: false,
    top: 0,
    bottom: 0,
    width: 0,
    height: 0,
    centerX: 0,
  };
  private viewModel: ContextualNodeCardViewModel | null = null;
  private placement: ContextualCardPlacement | null = null;
  private openingFrame = 0;
  private disposed = false;

  public constructor(mount: HTMLElement, options: ContextualNodeCardViewOptions = {}) {
    this.document = mount.ownerDocument;
    this.mount = mount;
    this.releaseStyles = acquireStyles(this.document);
    this.onActionRequested = options.onActionRequested;

    this.root = this.document.createElement("aside");
    this.root.className = "lp-context-card";
    this.root.hidden = true;
    this.root.dataset.placed = "false";
    this.root.setAttribute("role", "dialog");
    this.root.setAttribute("aria-modal", "false");
    this.root.setAttribute("aria-live", "polite");
    this.root.tabIndex = -1;

    const arrowDepth = this.document.createElement("span");
    arrowDepth.className = "lp-context-card__arrow-depth";
    arrowDepth.setAttribute("aria-hidden", "true");
    const arrowFace = this.document.createElement("span");
    arrowFace.className = "lp-context-card__arrow-face";
    arrowFace.setAttribute("aria-hidden", "true");

    this.panel = this.document.createElement("section");
    this.panel.className = "lp-context-card__panel";

    const header = this.document.createElement("header");
    header.className = "lp-context-card__header";
    const heading = this.document.createElement("div");
    heading.className = "lp-context-card__heading";
    this.eyebrow = this.document.createElement("p");
    this.eyebrow.className = "lp-context-card__eyebrow";
    this.title = this.document.createElement("h2");
    this.title.className = "lp-context-card__title";
    this.title.id = `lp-context-card-title-${ContextualNodeCardView.nextId++}`;
    this.root.setAttribute("aria-labelledby", this.title.id);
    heading.append(this.eyebrow, this.title);

    this.status = this.document.createElement("span");
    this.status.className = "lp-context-card__status";
    this.status.hidden = true;
    header.append(heading, this.status);

    this.description = this.document.createElement("p");
    this.description.className = "lp-context-card__description";
    this.description.hidden = true;

    this.actions = this.document.createElement("div");
    this.actions.className = "lp-context-card__actions";
    this.actions.hidden = true;
    this.primaryButton = this.createButton("primary");
    this.secondaryButton = this.createButton("secondary");
    this.actions.append(this.primaryButton, this.secondaryButton);

    this.panel.append(header, this.description, this.actions);
    this.root.append(arrowDepth, arrowFace, this.panel);
    mount.append(this.root);

    this.root.addEventListener("pointerdown", this.stopEventPropagation);
    this.root.addEventListener("pointerup", this.stopEventPropagation);
    this.root.addEventListener("click", this.stopEventPropagation);
    this.root.addEventListener("dblclick", this.stopEventPropagation);
    this.root.addEventListener("contextmenu", this.stopEventPropagation);
    this.root.addEventListener("wheel", this.stopEventPropagation);
    this.root.addEventListener("animationend", this.handleOpeningMotionEnd);

    const ResizeObserverConstructor = this.document.defaultView?.ResizeObserver;
    this.resizeObserver = ResizeObserverConstructor
      ? new ResizeObserverConstructor(() => this.applyPlacement())
      : null;
    this.resizeObserver?.observe(this.root);
  }

  public setViewModel(viewModel: ContextualNodeCardViewModel | null): void {
    if (this.disposed) return;
    const previousViewModel = this.viewModel;
    if (sameViewModel(previousViewModel, viewModel)) return;
    const wasVisible = previousViewModel !== null && previousViewModel.visible !== false;
    this.viewModel = viewModel;
    const visible = viewModel !== null && viewModel.visible !== false;
    this.root.hidden = !visible;
    this.root.setAttribute("aria-hidden", String(!visible));

    if (!visible || viewModel === null) {
      this.root.removeAttribute("data-node-id");
      this.root.removeAttribute("data-instance-id");
      this.root.dataset.placed = "false";
      this.root.removeAttribute("data-opening");
      return;
    }

    this.root.dataset.nodeId = viewModel.nodeId;
    this.root.dataset.instanceId = viewModel.instanceId;
    this.root.dataset.kind = viewModel.kind;
    this.root.dataset.tone = viewModel.tone;
    this.eyebrow.textContent = viewModel.eyebrow?.trim() ?? "";
    this.eyebrow.hidden = this.eyebrow.textContent.length === 0;
    this.title.textContent = viewModel.title;
    this.setOptionalText(this.status, viewModel.statusLabel);
    this.setOptionalText(this.description, viewModel.description);
    this.configureButton(this.primaryButton, viewModel.primaryAction, "primary");
    this.configureButton(this.secondaryButton, viewModel.secondaryAction, "secondary");
    this.actions.hidden = !viewModel.primaryAction && !viewModel.secondaryAction;
    this.panel.setAttribute(
      "aria-busy",
      String(viewModel.primaryAction?.busy === true || viewModel.secondaryAction?.busy === true),
    );
    this.applyPlacement();
    if (!wasVisible || previousViewModel?.instanceId !== viewModel.instanceId) {
      this.playOpeningMotion();
    }
  }

  public setPlacement(placement: ContextualCardPlacement | null): void {
    if (this.disposed) return;
    if (samePlacement(this.placement, placement)) return;
    this.placement = placement;
    this.applyPlacement();
  }

  /** The object is reused; callers must consume it synchronously. */
  public getLayoutMetrics(): ContextualCardLayoutMetrics {
    const rect = this.root.getBoundingClientRect();
    this.layoutMetrics.visible = !this.root.hidden;
    this.layoutMetrics.placed = this.root.dataset.placed === "true";
    this.layoutMetrics.top = rect.top;
    this.layoutMetrics.bottom = rect.bottom;
    this.layoutMetrics.width = rect.width;
    this.layoutMetrics.height = rect.height;
    this.layoutMetrics.centerX = rect.left + rect.width / 2;
    return this.layoutMetrics;
  }

  public focus(): void {
    if (this.disposed || this.root.hidden) return;
    const preferred = [this.primaryButton, this.secondaryButton]
      .find((button) => !button.hidden && !button.disabled);
    (preferred ?? this.root).focus({ preventScroll: true });
  }

  public containsEventPath(eventOrPath: Event | readonly EventTarget[] | EventTarget | null): boolean {
    if (eventOrPath === null) return false;
    if (Array.isArray(eventOrPath)) return eventOrPath.includes(this.root);

    const window = this.document.defaultView;
    if (window && eventOrPath instanceof window.Event) {
      const path = typeof eventOrPath.composedPath === "function"
        ? eventOrPath.composedPath()
        : [];
      if (path.includes(this.root)) return true;
      const target = eventOrPath.target;
      return target instanceof window.Node && this.root.contains(target);
    }

    return window !== null && eventOrPath instanceof window.Node
      && this.root.contains(eventOrPath);
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.cancelOpeningFrame();
    this.resizeObserver?.disconnect();
    this.primaryButton.removeEventListener("click", this.handleActionClick);
    this.secondaryButton.removeEventListener("click", this.handleActionClick);
    this.root.removeEventListener("pointerdown", this.stopEventPropagation);
    this.root.removeEventListener("pointerup", this.stopEventPropagation);
    this.root.removeEventListener("click", this.stopEventPropagation);
    this.root.removeEventListener("dblclick", this.stopEventPropagation);
    this.root.removeEventListener("contextmenu", this.stopEventPropagation);
    this.root.removeEventListener("wheel", this.stopEventPropagation);
    this.root.removeEventListener("animationend", this.handleOpeningMotionEnd);
    this.root.remove();
    this.releaseStyles();
  }

  private createButton(slot: ContextualCardActionSlot): HTMLButtonElement {
    const button = this.document.createElement("button");
    button.className = "lp-context-card__button";
    button.type = "button";
    button.dataset.slot = slot;
    button.hidden = true;
    button.addEventListener("click", this.handleActionClick);
    return button;
  }

  private configureButton(
    button: HTMLButtonElement,
    action: ContextualCardActionViewModel | undefined,
    slot: ContextualCardActionSlot,
  ): void {
    button.hidden = action === undefined;
    if (!action) {
      button.disabled = true;
      button.removeAttribute("data-action-id");
      button.removeAttribute("data-instance-id");
      button.removeAttribute("aria-label");
      button.removeAttribute("aria-busy");
      button.textContent = "";
      return;
    }
    button.dataset.slot = slot;
    button.dataset.actionId = action.id;
    button.dataset.instanceId = this.viewModel?.instanceId ?? "";
    button.textContent = action.label;
    button.disabled = action.enabled === false || action.busy === true;
    button.setAttribute("aria-busy", String(action.busy === true));
    button.setAttribute("aria-label", action.ariaLabel?.trim() || action.label);
  }

  private setOptionalText(element: HTMLElement, value: string | undefined): void {
    const text = value?.trim() ?? "";
    element.textContent = text;
    element.hidden = text.length === 0;
  }

  private applyPlacement(): void {
    if (this.disposed || this.root.hidden || !this.placement) {
      this.root.dataset.placed = "false";
      return;
    }

    const placement = this.placement;
    if (!Number.isFinite(placement.anchorClientX) || !Number.isFinite(placement.anchorClientY)) {
      this.root.dataset.placed = "false";
      return;
    }

    const viewport = placement.viewportRect ?? this.mount.getBoundingClientRect();
    const margin = Math.max(8, placement.margin ?? 12);
    const gap = Math.max(9, placement.gap ?? 18);
    this.root.style.setProperty(
      "--lp-card-available-width",
      `${Math.max(180, viewport.width - margin * 2)}px`,
    );
    this.root.style.setProperty(
      "--lp-card-max-height",
      `${Math.max(150, viewport.height - margin * 2 - gap)}px`,
    );
    const mountRect = this.mount.getBoundingClientRect();
    const cardRect = this.root.getBoundingClientRect();
    const width = cardRect.width || Math.min(366, Math.max(180, viewport.width - margin * 2));
    const unclampedClientLeft = placement.anchorClientX - width / 2;
    const minimumClientLeft = viewport.left + margin;
    const maximumClientLeft = Math.max(
      minimumClientLeft,
      viewport.left + viewport.width - margin - width,
    );
    const clientLeft = Math.min(
      maximumClientLeft,
      Math.max(minimumClientLeft, unclampedClientLeft),
    );
    const clientTop = placement.anchorClientY + gap;
    const localLeft = clientLeft - mountRect.left + this.mount.scrollLeft;
    const localTop = clientTop - mountRect.top + this.mount.scrollTop;

    const arrowPercent = Math.min(
      92,
      Math.max(8, ((placement.anchorClientX - clientLeft) / width) * 100),
    );
    this.root.style.setProperty("--lp-card-arrow-x", `${arrowPercent}%`);
    this.root.style.transform = `translate3d(${cssPixel(localLeft)}, ${cssPixel(localTop)}, 0)`;
    this.root.dataset.anchorClientX = String(placement.anchorClientX);
    this.root.dataset.anchorClientY = String(placement.anchorClientY);
    this.root.dataset.placed = "true";
  }

  private playOpeningMotion(): void {
    this.cancelOpeningFrame();
    this.root.removeAttribute("data-opening");
    const requestAnimationFrame = this.document.defaultView?.requestAnimationFrame;
    if (!requestAnimationFrame) return;
    this.openingFrame = requestAnimationFrame(() => {
      this.openingFrame = 0;
      if (!this.disposed && !this.root.hidden) this.root.dataset.opening = "true";
    });
  }

  private cancelOpeningFrame(): void {
    if (!this.openingFrame) return;
    this.document.defaultView?.cancelAnimationFrame(this.openingFrame);
    this.openingFrame = 0;
  }

  private readonly handleActionClick = (event: MouseEvent): void => {
    const button = event.currentTarget === this.primaryButton
      ? this.primaryButton
      : event.currentTarget === this.secondaryButton
        ? this.secondaryButton
        : null;
    const viewModel = this.viewModel;
    if (button === null
      || this.disposed
      || button.disabled
      || viewModel === null) return;

    const slot = button.dataset.slot === "secondary" ? "secondary" : "primary";
    const action = slot === "primary" ? viewModel.primaryAction : viewModel.secondaryAction;
    const renderedInstanceId = button.dataset.instanceId;
    if (!action
      || button.dataset.actionId !== action.id
      || renderedInstanceId !== viewModel.instanceId) return;

    const detail: ContextualCardActionRequestedDetail = Object.freeze({
      type: "contextual-card.action",
      source: "contextual-node-card",
      instanceId: viewModel.instanceId,
      nodeId: viewModel.nodeId,
      actionId: action.id,
      slot,
      occurredAt: this.document.defaultView?.performance.now() ?? Date.now(),
    });
    const CustomEventConstructor = this.document.defaultView?.CustomEvent ?? CustomEvent;
    const actionEvent = new CustomEventConstructor<ContextualCardActionRequestedDetail>(
      CONTEXTUAL_CARD_EVENT.actionRequested,
      { bubbles: true, cancelable: true, composed: true, detail },
    );
    this.root.dispatchEvent(actionEvent);
    if (!actionEvent.defaultPrevented) this.onActionRequested?.(detail);
  };

  private readonly stopEventPropagation = (event: Event): void => {
    event.stopPropagation();
  };

  private readonly handleOpeningMotionEnd = (event: AnimationEvent): void => {
    if (event.target === this.root && event.animationName === "lp-context-card-enter") {
      this.root.removeAttribute("data-opening");
    }
  };

  private static nextId = 1;
}

function acquireStyles(document: Document): () => void {
  const existing = styleRegistry.get(document);
  if (existing) {
    existing.owners += 1;
    return () => releaseStyles(document);
  }
  const element = document.createElement("style");
  element.setAttribute(STYLE_ATTRIBUTE, "");
  element.textContent = STYLES;
  (document.head ?? document.documentElement).append(element);
  styleRegistry.set(document, { element, owners: 1 });
  return () => releaseStyles(document);
}

function releaseStyles(document: Document): void {
  const entry = styleRegistry.get(document);
  if (!entry) return;
  entry.owners -= 1;
  if (entry.owners > 0) return;
  entry.element.remove();
  styleRegistry.delete(document);
}

function sameViewModel(
  previous: ContextualNodeCardViewModel | null,
  next: ContextualNodeCardViewModel | null,
): boolean {
  if (previous === next) return true;
  if (previous === null || next === null) return false;
  return previous.instanceId === next.instanceId
    && previous.nodeId === next.nodeId
    && previous.kind === next.kind
    && previous.tone === next.tone
    && previous.title === next.title
    && previous.description === next.description
    && previous.eyebrow === next.eyebrow
    && previous.statusLabel === next.statusLabel
    && previous.visible === next.visible
    && sameAction(previous.primaryAction, next.primaryAction)
    && sameAction(previous.secondaryAction, next.secondaryAction);
}

function sameAction(
  previous: ContextualCardActionViewModel | undefined,
  next: ContextualCardActionViewModel | undefined,
): boolean {
  if (previous === next) return true;
  if (!previous || !next) return false;
  return previous.id === next.id
    && previous.label === next.label
    && previous.enabled === next.enabled
    && previous.busy === next.busy
    && previous.ariaLabel === next.ariaLabel;
}

function samePlacement(
  previous: ContextualCardPlacement | null,
  next: ContextualCardPlacement | null,
): boolean {
  if (previous === next) return true;
  if (previous === null || next === null) return false;
  const previousViewport = previous.viewportRect;
  const nextViewport = next.viewportRect;
  return nearlyEqual(previous.anchorClientX, next.anchorClientX)
    && nearlyEqual(previous.anchorClientY, next.anchorClientY)
    && previous.gap === next.gap
    && previous.margin === next.margin
    && previousViewport !== undefined
    && nextViewport !== undefined
    && nearlyEqual(previousViewport.left, nextViewport.left)
    && nearlyEqual(previousViewport.top, nextViewport.top)
    && nearlyEqual(previousViewport.width, nextViewport.width)
    && nearlyEqual(previousViewport.height, nextViewport.height);
}

function nearlyEqual(left: number, right: number): boolean {
  return Math.abs(left - right) < 0.05;
}

function cssPixel(value: number): string {
  return `${Math.round(value * 1000) / 1000}px`;
}
