const DEFAULT_BOTTOM_RESERVED_PIXELS = 132;
const DEFAULT_SHADOW_ALLOWANCE_PIXELS = 14;
const DEFAULT_SIDE_SAFE_MARGIN_PIXELS = 20;

export interface CardSafeAreaLiftInput {
  readonly currentLiftPixels: number;
  readonly cardBottomClientY: number;
  readonly viewportBottomClientY: number;
  readonly maximumLiftPixels: number;
  readonly reservedBottomPixels?: number;
  readonly shadowAllowancePixels?: number;
}

/** Pure composition policy: move the scene, never detach the card from its node. */
export function computeCardSafeAreaLift(input: CardSafeAreaLiftInput): number {
  const reservedBottom = Math.max(
    0,
    input.reservedBottomPixels ?? DEFAULT_BOTTOM_RESERVED_PIXELS,
  );
  const shadowAllowance = Math.max(
    0,
    input.shadowAllowancePixels ?? DEFAULT_SHADOW_ALLOWANCE_PIXELS,
  );
  const safeBottom = input.viewportBottomClientY - reservedBottom;
  const overflow = input.cardBottomClientY + shadowAllowance - safeBottom;
  return Math.min(
    Math.max(0, input.maximumLiftPixels),
    Math.max(0, input.currentLiftPixels + overflow),
  );
}

export interface CardSafeAreaHorizontalOffsetInput {
  readonly currentOffsetPixels: number;
  readonly cardLeftClientX: number;
  readonly cardRightClientX: number;
  readonly viewportLeftClientX: number;
  readonly viewportRightClientX: number;
  readonly maximumOffsetPixels: number;
  readonly safeMarginPixels?: number;
}

/** Horizontal companion to the vertical safe-area policy. */
export function computeCardSafeAreaHorizontalOffset(
  input: CardSafeAreaHorizontalOffsetInput,
): number {
  const maximumOffset = Math.max(0, input.maximumOffsetPixels);
  const safeMargin = Math.max(
    0,
    input.safeMarginPixels ?? DEFAULT_SIDE_SAFE_MARGIN_PIXELS,
  );
  const safeLeft = input.viewportLeftClientX + safeMargin;
  const safeRight = input.viewportRightClientX - safeMargin;
  const leftOverflow = safeLeft - input.cardLeftClientX;
  const rightOverflow = input.cardRightClientX - safeRight;
  let nextOffset = input.currentOffsetPixels;

  if (leftOverflow > 0) {
    nextOffset += leftOverflow;
  } else if (rightOverflow > 0) {
    nextOffset -= rightOverflow;
  } else if (nextOffset > 0) {
    nextOffset = Math.max(0, nextOffset - Math.max(0, input.cardLeftClientX - safeLeft));
  } else if (nextOffset < 0) {
    nextOffset = Math.min(0, nextOffset + Math.max(0, safeRight - input.cardRightClientX));
  }

  return Math.min(maximumOffset, Math.max(-maximumOffset, nextOffset));
}
