export type LearningProgressStorageErrorCode =
  | "aborted"
  | "storage-unavailable"
  | "security-error"
  | "quota-exceeded"
  | "read-failed"
  | "write-failed";

export class LearningProgressStorageError extends Error {
  readonly code: LearningProgressStorageErrorCode;

  constructor(code: LearningProgressStorageErrorCode, message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "LearningProgressStorageError";
    this.code = code;
  }
}

export interface LearningProgressStorageReadRequest {
  readonly key: string;
}

export interface LearningProgressStorageWriteRequest {
  readonly key: string;
  readonly value: string;
}

export interface LearningProgressStorageOperationOptions {
  readonly signal: AbortSignal;
}

/**
 * Host-side durable storage boundary. The port is injected into the machine
 * factory and therefore never enters serializable XState Context.
 */
export interface LearningProgressStoragePort {
  read(
    request: LearningProgressStorageReadRequest,
    options: LearningProgressStorageOperationOptions,
  ): string | null | Promise<string | null>;

  write(
    request: LearningProgressStorageWriteRequest,
    options: LearningProgressStorageOperationOptions,
  ): void | Promise<void>;
}

export function normalizeLearningProgressStorageError(
  error: unknown,
  fallbackCode: "read-failed" | "write-failed",
): Readonly<{
  code: LearningProgressStorageErrorCode;
  message: string;
}> {
  if (error instanceof LearningProgressStorageError) {
    return Object.freeze({ code: error.code, message: error.message });
  }
  return Object.freeze({
    code: fallbackCode,
    message: error instanceof Error ? error.message : String(error),
  });
}
