import type { LearningProgressStoragePort } from '../progression/persistence';

/** Renderer-owned envelope. Scene position is independent of learning completion. */
export async function createScenePositionStorage(storage: LearningProgressStoragePort, key: string, reset = false) {
  const context = { signal: new AbortController().signal };
  const raw = await storage.read({ key }, context);
  let progress: string | null = raw;
  let position: string | null = null;
  let lastLearningNodeId: string | null = null;
  try {
    const value = raw ? JSON.parse(raw) : null;
    if (value?.format === 'learning-path-scene-v1' && (typeof value.progress === 'string' || value.progress === null)) {
      progress = value.progress;
      if (typeof value.lastLearningNodeId === "string" && /^[a-zA-Z][a-zA-Z0-9_-]{0,63}$/.test(value.lastLearningNodeId)) lastLearningNodeId = value.lastLearningNodeId;
      if (typeof value.position === 'string' && /^[a-zA-Z][a-zA-Z0-9_-]{0,63}$/.test(value.position)) position = value.position;
    }
  } catch { /* Legacy progress is validated by the existing progress reader. */ }
  if (reset) { progress = null; position = null; lastLearningNodeId = null; }
  const initialPosition = position;
  let writes = Promise.resolve();
  const save = () => {
    const value = JSON.stringify({ format: 'learning-path-scene-v1', progress, position, lastLearningNodeId });
    const next = writes.catch(() => {}).then(() => storage.write({ key, value }, context)).then(() => {});
    writes = next;
    return next;
  };
  return {
    initialPosition,
    lastLearningNodeId,
    rememberLearningNode(nodeId: string) {
      position = nodeId;
      lastLearningNodeId = nodeId;
      return save();
    },
    progressStorage: {
      read(_request, { signal }) { signal.throwIfAborted(); return progress; },
      write({ value }, { signal }) { signal.throwIfAborted(); progress = value; return save(); },
    } satisfies LearningProgressStoragePort,
    setPosition(nodeId: string) {
      if (position === nodeId) return writes;
      position = nodeId;
      return save();
    },
  };
}
