import { assign, setup } from "xstate";
import type { LearningEntityId } from "../../content";
import type {
  JourneyContext,
  JourneyEvent,
  JourneyMachineDependencies,
  JourneyMachineInput,
  JourneyOutcome,
  JourneyPlan,
  JourneyRequest,
  JourneyTransactionalEventType,
} from "./types";

function immutableRequest(request: JourneyRequest): JourneyRequest {
  return Object.freeze({ ...request });
}

function immutablePlan(plan: JourneyPlan): JourneyPlan {
  return Object.freeze({
    sourceNodeId: plan.sourceNodeId,
    targetNodeId: plan.targetNodeId,
    routeNodeIds: Object.freeze([...plan.routeNodeIds]),
    requiredCompletionNodeIds: Object.freeze([...plan.requiredCompletionNodeIds]),
  });
}

function immutableNodeIds(nodeIds: readonly LearningEntityId[]): readonly LearningEntityId[] {
  return Object.freeze([...nodeIds]);
}

function transactionalEvent(
  event: JourneyEvent,
): event is Extract<JourneyEvent, { readonly transactionId: string }> {
  return "transactionId" in event;
}

function eventNodeId(event: JourneyEvent): LearningEntityId | undefined {
  return event.type === "NODE_TRAVERSED" || event.type === "NODE_ARRIVED"
    ? event.nodeId
    : undefined;
}

function planValidationError(
  plan: JourneyPlan,
  request: JourneyRequest,
  currentNodeId: LearningEntityId,
): string | null {
  if (plan.sourceNodeId !== currentNodeId) return "plan-source-mismatch";
  if (plan.targetNodeId !== request.targetNodeId) return "plan-target-mismatch";
  if (plan.routeNodeIds.length === 0) return "plan-route-empty";
  if (plan.routeNodeIds[0] !== currentNodeId) return "plan-route-must-start-at-current-node";
  if (plan.routeNodeIds.at(-1) !== request.targetNodeId) return "plan-route-must-end-at-target-node";
  return null;
}

function nextExpectedNode(context: JourneyContext): LearningEntityId | null {
  const route = context.plan?.routeNodeIds;
  if (!route) return null;
  const reachedCount = context.reachedNodeIds.length;
  return route[reachedCount] ?? null;
}

function appendedReachedNodes(
  context: JourneyContext,
  nodeId: LearningEntityId,
): readonly LearningEntityId[] {
  return context.reachedNodeIds.at(-1) === nodeId
    ? context.reachedNodeIds
    : immutableNodeIds([...context.reachedNodeIds, nodeId]);
}

/**
 * Owns one navigation transaction from planning through visual settlement.
 * Planning is a pure injected dependency; Three.js movement remains outside
 * the machine and reports only correlated lifecycle events.
 */
export function createJourneyMachine(dependencies: JourneyMachineDependencies) {
  return setup({
    types: {} as {
      context: JourneyContext;
      events: JourneyEvent;
      input: JourneyMachineInput;
    },
    guards: {
      hasPlan: ({ context }) => context.plan !== null,
      activeTransactionMatches: ({ context, event }) => (
        transactionalEvent(event)
        && context.transactionId !== null
        && event.transactionId === context.transactionId
      ),
      staleTransaction: ({ context, event }) => (
        transactionalEvent(event)
        && event.transactionId !== context.transactionId
      ),
      expectedTraversedNode: ({ context, event }) => (
        event.type === "NODE_TRAVERSED"
        && event.transactionId === context.transactionId
        && event.nodeId === nextExpectedNode(context)
        && event.nodeId !== context.plan?.targetNodeId
      ),
      expectedDestinationArrival: ({ context, event }) => (
        event.type === "NODE_ARRIVED"
        && event.transactionId === context.transactionId
        && event.nodeId === context.plan?.targetNodeId
        // Runtime-selected dynamic bridges may legitimately bypass authored
        // route nodes. The callback journal records only physically reached
        // nodes; prerequisite completion remains the Progress actor's concern.
        && (
          event.nodeId === nextExpectedNode(context)
          || context.plan?.routeNodeIds.includes(event.nodeId) === true
        )
      ),
    },
    actions: {
      beginRequest: assign(({ context, event }) => {
        if (event.type !== "REQUESTED") return {};
        const transactionId = dependencies.createTransactionId();
        if (transactionId.length === 0) {
          throw new Error("createTransactionId() must return a non-empty string.");
        }
        return {
          request: immutableRequest(event.request),
          plan: null,
          transactionId,
          reachedNodeIds: immutableNodeIds([context.currentNodeId]),
          lastOutcome: null,
        };
      }),
      buildPlan: assign(({ context }) => {
        const request = context.request;
        const transactionId = context.transactionId;
        if (!request || !transactionId) return {};

        try {
          const result = dependencies.planJourney({
            request,
            currentNodeId: context.currentNodeId,
            transactionId,
          });
          if (!result.accepted) {
            const outcome: JourneyOutcome = Object.freeze({
              type: "rejected",
              transactionId,
              targetNodeId: request.targetNodeId,
              reason: result.reason,
            });
            return { plan: null, transactionId: null, lastOutcome: outcome };
          }

          const plan = immutablePlan(result.plan);
          const error = planValidationError(plan, request, context.currentNodeId);
          if (error) {
            const outcome: JourneyOutcome = Object.freeze({
              type: "rejected",
              transactionId,
              targetNodeId: request.targetNodeId,
              reason: error,
            });
            return { plan: null, transactionId: null, lastOutcome: outcome };
          }
          return { plan, lastOutcome: null };
        } catch (error) {
          const outcome: JourneyOutcome = Object.freeze({
            type: "rejected",
            transactionId,
            targetNodeId: request.targetNodeId,
            reason: error instanceof Error ? error.message : "journey-planner-failed",
          });
          return { plan: null, transactionId: null, lastOutcome: outcome };
        }
      }),
      recordReachedNode: assign(({ context, event }) => {
        if (event.type !== "NODE_TRAVERSED" && event.type !== "NODE_ARRIVED") return {};
        return {
          currentNodeId: event.nodeId,
          reachedNodeIds: appendedReachedNodes(context, event.nodeId),
          lastOutcome: null,
        };
      }),
      settleJourney: assign(({ context, event }) => {
        if (event.type !== "VISUAL_SETTLED" || !context.plan || !context.transactionId) return {};
        const outcome: JourneyOutcome = Object.freeze({
          type: "settled",
          transactionId: context.transactionId,
          targetNodeId: context.plan.targetNodeId,
          reachedNodeIds: immutableNodeIds(context.reachedNodeIds),
        });
        return {
          request: null,
          plan: null,
          transactionId: null,
          lastOutcome: outcome,
        };
      }),
      cancelJourney: assign(({ context, event }) => {
        if (event.type !== "CANCELLED" || !context.plan || !context.transactionId) return {};
        const reachedNodeIds = appendedReachedNodes(context, event.safeNodeId);
        const outcome: JourneyOutcome = Object.freeze({
          type: "cancelled",
          transactionId: context.transactionId,
          targetNodeId: context.plan.targetNodeId,
          safeNodeId: event.safeNodeId,
          reachedNodeIds: immutableNodeIds(reachedNodeIds),
          reason: event.reason,
        });
        return {
          request: null,
          plan: null,
          transactionId: null,
          currentNodeId: event.safeNodeId,
          reachedNodeIds,
          lastOutcome: outcome,
        };
      }),
      recordStaleEvent: assign(({ context, event }) => {
        if (!transactionalEvent(event)) return {};
        const outcome: JourneyOutcome = Object.freeze({
          type: "event-ignored",
          eventType: event.type as JourneyTransactionalEventType,
          transactionId: event.transactionId,
          activeTransactionId: context.transactionId,
          reason: "stale-transaction",
        });
        return { lastOutcome: outcome };
      }),
      recordUnexpectedEvent: assign(({ context, event }) => {
        const outcome: JourneyOutcome = Object.freeze({
          type: "event-rejected",
          eventType: event.type,
          transactionId: transactionalEvent(event) ? event.transactionId : null,
          activeTransactionId: context.transactionId,
          reason: event.type === "REQUESTED" ? "journey-active" : "invalid-state",
          ...(eventNodeId(event) ? { nodeId: eventNodeId(event) } : {}),
        });
        return { lastOutcome: outcome };
      }),
      recordUnexpectedRouteNode: assign(({ context, event }) => {
        const outcome: JourneyOutcome = Object.freeze({
          type: "event-rejected",
          eventType: event.type,
          transactionId: transactionalEvent(event) ? event.transactionId : null,
          activeTransactionId: context.transactionId,
          reason: "unexpected-route-node",
          ...(eventNodeId(event) ? { nodeId: eventNodeId(event) } : {}),
        });
        return { lastOutcome: outcome };
      }),
      resetJourney: assign(({ context }) => ({
        request: null,
        plan: null,
        transactionId: null,
        reachedNodeIds: immutableNodeIds([context.currentNodeId]),
        lastOutcome: null,
      })),
    },
  }).createMachine({
    id: "journey",
    initial: "idle",
    context: ({ input }) => ({
      request: null,
      plan: null,
      transactionId: null,
      currentNodeId: input.currentNodeId,
      reachedNodeIds: immutableNodeIds([input.currentNodeId]),
      lastOutcome: null,
    }),
    on: {
      RESET: { target: ".idle", actions: "resetJourney" },
      REQUESTED: { actions: "recordUnexpectedEvent" },
      MOVEMENT_STARTED: [
        { guard: "staleTransaction", actions: "recordStaleEvent" },
        { actions: "recordUnexpectedEvent" },
      ],
      NODE_TRAVERSED: [
        { guard: "staleTransaction", actions: "recordStaleEvent" },
        { actions: "recordUnexpectedEvent" },
      ],
      NODE_ARRIVED: [
        { guard: "staleTransaction", actions: "recordStaleEvent" },
        { actions: "recordUnexpectedEvent" },
      ],
      VISUAL_SETTLED: [
        { guard: "staleTransaction", actions: "recordStaleEvent" },
        { actions: "recordUnexpectedEvent" },
      ],
      CANCELLED: [
        { guard: "staleTransaction", actions: "recordStaleEvent" },
        { actions: "recordUnexpectedEvent" },
      ],
    },
    states: {
      idle: {
        on: {
          REQUESTED: { target: "planning", actions: "beginRequest" },
        },
      },
      planning: {
        entry: "buildPlan",
        always: [
          { guard: "hasPlan", target: "ready" },
          { target: "rejected" },
        ],
      },
      ready: {
        on: {
          MOVEMENT_STARTED: {
            guard: "activeTransactionMatches",
            target: "moving",
          },
          CANCELLED: {
            guard: "activeTransactionMatches",
            target: "cancelled",
            actions: "cancelJourney",
          },
        },
      },
      moving: {
        on: {
          NODE_TRAVERSED: [
            { guard: "expectedTraversedNode", actions: "recordReachedNode" },
            { guard: "activeTransactionMatches", actions: "recordUnexpectedRouteNode" },
          ],
          NODE_ARRIVED: [
            {
              guard: "expectedDestinationArrival",
              target: "settling",
              actions: "recordReachedNode",
            },
            { guard: "activeTransactionMatches", actions: "recordUnexpectedRouteNode" },
          ],
          CANCELLED: {
            guard: "activeTransactionMatches",
            target: "cancelled",
            actions: "cancelJourney",
          },
        },
      },
      settling: {
        on: {
          VISUAL_SETTLED: {
            guard: "activeTransactionMatches",
            target: "idle",
            actions: "settleJourney",
          },
          CANCELLED: {
            guard: "activeTransactionMatches",
            target: "cancelled",
            actions: "cancelJourney",
          },
        },
      },
      rejected: {
        on: {
          REQUESTED: { target: "planning", actions: "beginRequest" },
        },
      },
      cancelled: {
        on: {
          REQUESTED: { target: "planning", actions: "beginRequest" },
        },
      },
    },
  });
}
