import { compileLearningPathDocument } from "../content/compiler";
import { compileLearningPathRuntime } from "../app/compileLearningPathRuntime";
import { releaseCompiledPageRuntimeData } from "../statecharts/page/runtimeDataRegistry";

export type LearningPathRuntimeValidation =
  | Readonly<{ ok: true }>
  | Readonly<{ ok: false; message: string }>;

/** Runs the actual content and physical compilers without mounting a scene. */
export function preflightLearningPath(input: unknown): LearningPathRuntimeValidation {
  try {
    const source = compileLearningPathDocument(input);
    // Never replace an active page's registry handle while doing a dry run.
    const runtime = compileLearningPathRuntime(source, { revision: `preflight:${crypto.randomUUID()}` });
    releaseCompiledPageRuntimeData(runtime.page.data);
    return { ok: true };
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : "Path runtime compilation failed." };
  }
}
