import type {
  LearningResourceLaunchRequest,
  LearningResourceNavigationResult,
  LearningResourceNavigatorPort,
} from "../../application/learning-resource";

export interface BrowserNavigationWindow {
  readonly location: Pick<Location, "href" | "assign">;
  open(url?: string | URL, target?: string, features?: string): Window | null;
}

function abortError(): DOMException {
  return new DOMException("Learning resource navigation was cancelled.", "AbortError");
}

function resolveAllowedUrl(href: string, baseHref: string): URL | null {
  try {
    const resolved = new URL(href, baseHref);
    return resolved.protocol === "http:" || resolved.protocol === "https:"
      ? resolved
      : null;
  } catch {
    return null;
  }
}

/** Browser-only adapter; application state never imports or stores Window. */
export class BrowserLearningResourceNavigator implements LearningResourceNavigatorPort {
  constructor(private readonly browserWindow: BrowserNavigationWindow = window) {}

  navigate(
    request: LearningResourceLaunchRequest,
    options: Readonly<{ signal: AbortSignal }>,
  ): LearningResourceNavigationResult {
    if (options.signal.aborted) throw abortError();

    const resolved = resolveAllowedUrl(
      request.binding.href,
      this.browserWindow.location.href,
    );
    if (!resolved) {
      return Object.freeze({
        status: "invalid-url",
        message: "Only valid HTTP(S) learning-resource URLs are allowed.",
      });
    }

    try {
      if (request.binding.target === "blank") {
        const popup = this.browserWindow.open(
          resolved.href,
          "_blank",
          "noopener,noreferrer",
        );
        if (popup === null) {
          return Object.freeze({
            status: "popup-blocked",
            resolvedHref: resolved.href,
            message: "The browser blocked the learning-resource window.",
          });
        }
      } else {
        this.browserWindow.location.assign(resolved.href);
      }
      return Object.freeze({ status: "accepted", resolvedHref: resolved.href });
    } catch (error: unknown) {
      return Object.freeze({
        status: "failed",
        resolvedHref: resolved.href,
        message: error instanceof Error ? error.message : "Browser navigation failed.",
      });
    }
  }
}

export function createBrowserLearningResourceNavigator(
  browserWindow?: BrowserNavigationWindow,
): LearningResourceNavigatorPort {
  return new BrowserLearningResourceNavigator(browserWindow);
}

