import { assign, enqueueActions, fromCallback, fromPromise, setup } from "xstate";
import {
  inspectJsonSafety,
  type JsonValue,
} from "../../contracts/json";
import type {
  CompiledLearningPathPage,
  GenerationFailure,
  PageGenerationEvent,
  PageGenerationMachineContext,
  PageGenerationMachineInput,
  PageGenerationServices,
  RevealCharacterCommand,
  RevealPathStepCommand,
} from "./contracts";
import { pathStepIdentity, validateCompiledRevealOrder } from "./revealOrder";
import {
  releaseCompiledPageRuntimeData,
  type CompiledPageRuntimeDataReference,
} from "./runtimeDataRegistry";

const DEFAULT_ACK_TIMEOUT_MS = 8_000;

interface ValidationActorInput {
  readonly template: JsonValue;
  readonly transactionId: string;
}

interface CompilationActorInput {
  readonly validatedTemplate: JsonValue;
  readonly transactionId: string;
}

interface PresentationPreparationActorInput {
  readonly compiledPath: CompiledLearningPathPage;
  readonly transactionId: string;
  readonly revision: string;
}

type RuntimeDataLifetimeEvent = Readonly<{
  type: "RUNTIME_DATA.OWNERSHIP_CHANGED";
  reference: CompiledPageRuntimeDataReference | null;
}>;

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return typeof error === "string" ? error : "Unknown generation error.";
}

function actorOutput(event: unknown): unknown {
  return typeof event === "object" && event !== null && "output" in event
    ? (event as { readonly output: unknown }).output
    : null;
}

function snapshotJsonValue(value: unknown): JsonValue {
  const safety = inspectJsonSafety(value);
  if (!safety.safe) {
    throw new TypeError(
      `Page template is not JSON-safe at ${safety.failure.path}: ${safety.failure.reason}.`,
    );
  }
  if (value === null || typeof value !== "object") return value as JsonValue;
  if (Array.isArray(value)) {
    return Object.freeze(value.map((entry) => snapshotJsonValue(entry)));
  }
  return Object.freeze(Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [key, snapshotJsonValue(entry)]),
  ));
}

function jsonActorOutput(event: unknown): JsonValue | null {
  const output = actorOutput(event);
  return output === null || output === undefined ? null : snapshotJsonValue(output);
}

function failure(
  context: PageGenerationMachineContext,
  kind: GenerationFailure["kind"],
  message: string,
): GenerationFailure {
  return Object.freeze({
    kind,
    transactionId: context.transactionId,
    revision: context.revision,
    message,
  });
}

function selectedTemplate(
  context: PageGenerationMachineContext,
  event: PageGenerationEvent,
): unknown | null {
  if (event.type === "PAGE.GENERATE.REQUESTED" && "template" in event) {
    return event.template ?? null;
  }
  return context.template;
}

function selectedTemplateIsJsonSafe(
  context: PageGenerationMachineContext,
  event: PageGenerationEvent,
): boolean {
  const template = selectedTemplate(context, event);
  return template !== null && inspectJsonSafety(template).safe;
}

function compiledOutput(event: unknown): CompiledLearningPathPage | null {
  const output = actorOutput(event);
  if (typeof output !== "object" || output === null) return null;
  return output as CompiledLearningPathPage;
}

function snapshotCompiledPath(
  compiled: CompiledLearningPathPage,
): CompiledLearningPathPage {
  return Object.freeze({
    revision: compiled.revision,
    initialNodeId: compiled.initialNodeId,
    nodes: Object.freeze(compiled.nodes.map((node) => Object.freeze({ ...node }))),
    edges: Object.freeze(compiled.edges.map((edge) => Object.freeze({ ...edge }))),
    revealOrder: Object.freeze(compiled.revealOrder.map((step) => Object.freeze({ ...step }))),
    ...(compiled.data
      ? { data: Object.freeze({ ...compiled.data }) }
      : {}),
  });
}

function releaseCompiledPathRuntimeData(
  compiled: CompiledLearningPathPage | null,
): void {
  releaseCompiledPageRuntimeData(compiled?.data);
}

function commandMatches(
  context: PageGenerationMachineContext,
  event: PageGenerationEvent,
): boolean {
  const command = context.outstandingCommand;
  if (!command) return false;
  if (event.type !== "PAGE.PATH_STEP.SETTLED"
    && event.type !== "PAGE.CHARACTER.SETTLED"
    && event.type !== "PAGE.PRESENTATION.FAILED") {
    return false;
  }
  return event.transactionId === command.transactionId
    && event.revision === command.revision
    && event.token === command.token;
}

function pathCommand(context: PageGenerationMachineContext): RevealPathStepCommand | null {
  const compiled = context.compiledPath;
  const transactionId = context.transactionId;
  const revision = context.revision;
  const step = compiled?.revealOrder[context.revealIndex];
  if (!compiled || !transactionId || !revision || !step) return null;
  const operationId = `page:reveal:${context.revealIndex}:${pathStepIdentity(step)}`;
  return Object.freeze({
    type: "PAGE.PRESENTATION.REVEAL_PATH_STEP",
    transactionId,
    revision,
    operationId,
    token: `${transactionId}:${revision}:${operationId}`,
    motionPreference: context.reducedMotion ? "reduced" : "animated",
    sequenceIndex: context.revealIndex,
    sequenceLength: compiled.revealOrder.length,
    step,
  });
}

function characterCommand(
  context: PageGenerationMachineContext,
): RevealCharacterCommand | null {
  const compiled = context.compiledPath;
  const transactionId = context.transactionId;
  const revision = context.revision;
  if (!compiled || !transactionId || !revision) return null;
  const operationId = `page:character:${compiled.initialNodeId}`;
  return Object.freeze({
    type: "PAGE.PRESENTATION.REVEAL_CHARACTER",
    transactionId,
    revision,
    operationId,
    token: `${transactionId}:${revision}:${operationId}`,
    motionPreference: context.reducedMotion ? "reduced" : "animated",
    nodeId: compiled.initialNodeId,
  });
}

/**
 * Application/session generation lifecycle. It owns transaction sequencing,
 * while validation, compilation, Three.js presentation, and DOM are injected
 * ports. This machine can therefore run in tests, workers, or a browser host.
 */
export function createPageGenerationMachine(services: PageGenerationServices) {
  return setup({
    types: {} as {
      context: PageGenerationMachineContext;
      events: PageGenerationEvent;
      input: PageGenerationMachineInput;
    },
    actors: {
      runtimeDataLifetime: fromCallback<RuntimeDataLifetimeEvent>(({ receive }) => {
        let currentReference: CompiledPageRuntimeDataReference | null = null;
        receive((event) => {
          currentReference = event.reference;
        });
        return () => {
          releaseCompiledPageRuntimeData(currentReference);
          currentReference = null;
        };
      }),
      validateTemplate: fromPromise<JsonValue, ValidationActorInput>(
        async ({ input, signal }) => snapshotJsonValue(
          await services.validateTemplate({ ...input, signal }),
        ),
      ),
      compilePath: fromPromise<CompiledLearningPathPage, CompilationActorInput>(
        async ({ input, signal }) => services.compilePath({ ...input, signal }),
      ),
      preparePresentation: fromPromise<void, PresentationPreparationActorInput>(
        async ({ input, signal }) => services.preparePresentation({ ...input, signal }),
      ),
    },
    delays: {
      presentationAckTimeout: ({ context }) => context.presentationAckTimeoutMs,
    },
    guards: {
      hasTemplateForRequest: ({ context, event }) => (
        selectedTemplateIsJsonSafe(context, event)
      ),
      hasRetryTemplate: ({ context }) => context.template !== null,
      receivedTemplateIsJsonSafe: ({ event }) => (
        event.type === "PAGE.TEMPLATE.RECEIVED"
        && inspectJsonSafety(event.template).safe
      ),
      compiledContractIsValid: ({ event }) => {
        const compiled = compiledOutput(event);
        if (!compiled) return false;
        try {
          return inspectJsonSafety(compiled).safe
            && (compiled.data === undefined || compiled.data.revision === compiled.revision)
            && validateCompiledRevealOrder(compiled).valid;
        } catch {
          return false;
        }
      },
      hasMorePathSteps: ({ context }) => (
        context.compiledPath !== null
        && context.revealIndex < context.compiledPath.revealOrder.length
      ),
      pathAckMatches: ({ context, event }) => (
        event.type === "PAGE.PATH_STEP.SETTLED"
        && context.outstandingCommand?.type === "PAGE.PRESENTATION.REVEAL_PATH_STEP"
        && commandMatches(context, event)
      ),
      characterAckMatches: ({ context, event }) => (
        event.type === "PAGE.CHARACTER.SETTLED"
        && context.outstandingCommand?.type === "PAGE.PRESENTATION.REVEAL_CHARACTER"
        && commandMatches(context, event)
      ),
      failureMatches: ({ context, event }) => (
        event.type === "PAGE.PRESENTATION.FAILED" && commandMatches(context, event)
      ),
    },
    actions: {
      receiveTemplate: assign(({ event }) => (
        event.type === "PAGE.TEMPLATE.RECEIVED"
          ? { template: snapshotJsonValue(event.template) }
          : {}
      )),
      beginGeneration: assign(({ context, event }) => {
        const selected = selectedTemplate(context, event);
        const template = selected === null ? null : snapshotJsonValue(selected);
        const reducedMotion = event.type === "PAGE.GENERATE.REQUESTED"
          ? event.reducedMotion ?? context.reducedMotion
          : context.reducedMotion;
        return {
          template,
          transactionTemplate: template,
          validatedTemplate: null,
          compiledPath: null,
          transactionId: services.createTransactionId(),
          revision: null,
          revealIndex: 0,
          outstandingCommand: null,
          reducedMotion,
          generationAttempt: context.generationAttempt + 1,
          lastError: null,
        };
      }),
      recordDuplicateGenerateRequest: assign(({ context }) => ({
        duplicateGenerateRequestCount: context.duplicateGenerateRequestCount + 1,
      })),
      recordMissingTemplate: enqueueActions(({ context, enqueue }) => {
        const problem = failure(
          context,
          "missing-template",
          "No learning-path JSON template is available.",
        );
        enqueue.assign({ lastError: problem });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      recordNonJsonTemplate: enqueueActions(({ context, enqueue }) => {
        const problem = failure(
          context,
          "validation",
          "Learning-path template must be a finite, plain JSON document.",
        );
        enqueue.assign({ lastError: problem });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      acceptValidatedTemplate: assign(({ event }) => ({
        validatedTemplate: jsonActorOutput(event),
      })),
      acceptCompiledPath: enqueueActions(({ event, enqueue }) => {
        const compiled = compiledOutput(event);
        const snapshot = compiled ? snapshotCompiledPath(compiled) : null;
        if (compiled && snapshot) {
          enqueue.assign({
            compiledPath: snapshot,
            revision: snapshot?.revision ?? null,
            revealIndex: 0,
            outstandingCommand: null,
          });
          enqueue.sendTo("runtimeDataLifetime", {
            type: "RUNTIME_DATA.OWNERSHIP_CHANGED",
            reference: snapshot.data ?? null,
          });
        }
      }),
      recordValidationFailure: enqueueActions(({ context, event, enqueue }) => {
        const problem = failure(context, "validation", errorMessage(
          typeof event === "object" && event !== null && "error" in event
            ? (event as { readonly error: unknown }).error
            : event,
        ));
        enqueue.assign({ lastError: problem, transactionTemplate: null, validatedTemplate: null });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      recordCompilationFailure: enqueueActions(({ context, event, enqueue }) => {
        const problem = failure(context, "compilation", errorMessage(
          typeof event === "object" && event !== null && "error" in event
            ? (event as { readonly error: unknown }).error
            : event,
        ));
        enqueue.assign({ lastError: problem, transactionTemplate: null, validatedTemplate: null });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      recordCompiledContractFailure: enqueueActions(({ context, event, enqueue }) => {
        const compiled = compiledOutput(event);
        releaseCompiledPathRuntimeData(compiled);
        let message = "Compiler returned an invalid learning-path contract.";
        if (compiled) {
          try {
            message = validateCompiledRevealOrder(compiled).error ?? message;
          } catch (error) {
            message = errorMessage(error);
          }
        }
        const problem = Object.freeze({
          ...failure(context, "compiled-contract", message),
          revision: compiled?.revision ?? context.revision,
        });
        enqueue.assign({
          lastError: problem,
          transactionTemplate: null,
          validatedTemplate: null,
          compiledPath: null,
          revision: compiled?.revision ?? null,
        });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      recordPresentationPreparationFailure: enqueueActions(({ context, event, enqueue }) => {
        releaseCompiledPathRuntimeData(context.compiledPath);
        const problem = failure(context, "presentation-preparation", errorMessage(
          typeof event === "object" && event !== null && "error" in event
            ? (event as { readonly error: unknown }).error
            : event,
        ));
        enqueue.assign({
          lastError: problem,
          transactionTemplate: null,
          validatedTemplate: null,
          compiledPath: null,
          outstandingCommand: null,
        });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      issuePathRevealCommand: enqueueActions(({ context, enqueue }) => {
        const command = pathCommand(context);
        if (!command) return;
        enqueue.assign({ outstandingCommand: command });
        enqueue(() => services.executePresentation(command));
      }),
      commitPathRevealAck: assign(({ context }) => ({
        revealIndex: context.revealIndex + 1,
        outstandingCommand: null,
      })),
      issueCharacterRevealCommand: enqueueActions(({ context, enqueue }) => {
        const command = characterCommand(context);
        if (!command) return;
        enqueue.assign({ outstandingCommand: command });
        enqueue(() => services.executePresentation(command));
      }),
      recordPresentationFailure: enqueueActions(({ context, event, enqueue }) => {
        releaseCompiledPathRuntimeData(context.compiledPath);
        const message = event.type === "PAGE.PRESENTATION.FAILED"
          ? event.error
          : "Presentation command failed.";
        const problem = failure(context, "presentation", message);
        enqueue.assign({ lastError: problem, outstandingCommand: null });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      recordPresentationTimeout: enqueueActions(({ context, enqueue }) => {
        releaseCompiledPathRuntimeData(context.compiledPath);
        const command = context.outstandingCommand;
        const problem = failure(
          context,
          "presentation-timeout",
          command
            ? `Presentation ACK timed out for "${command.operationId}".`
            : "Presentation ACK timed out.",
        );
        enqueue.assign({ lastError: problem, outstandingCommand: null });
        enqueue(() => services.onGenerationFailed?.(problem));
      }),
      completeGeneration: enqueueActions(({ context, enqueue }) => {
        const compiledPath = context.compiledPath;
        const transactionId = context.transactionId;
        const revision = context.revision;
        enqueue.assign({
          outstandingCommand: null,
          transactionTemplate: null,
          validatedTemplate: null,
          lastError: null,
        });
        if (compiledPath && transactionId && revision) {
          const notice = Object.freeze({ transactionId, revision, compiledPath });
          enqueue(() => services.onGenerationReady?.(notice));
          enqueue(() => releaseCompiledPathRuntimeData(compiledPath));
          enqueue.sendTo("runtimeDataLifetime", {
            type: "RUNTIME_DATA.OWNERSHIP_CHANGED",
            reference: null,
          });
        }
      }),
      releaseCurrentCompiledRuntimeData: enqueueActions(({ context, enqueue }) => {
        releaseCompiledPathRuntimeData(context.compiledPath);
        enqueue.sendTo("runtimeDataLifetime", {
          type: "RUNTIME_DATA.OWNERSHIP_CHANGED",
          reference: null,
        });
      }),
    },
  }).createMachine({
    id: "learning-path-page-generation",
    initial: "awaitingGenerate",
    context: ({ input }) => ({
      template: input.initialTemplate === undefined
        ? null
        : snapshotJsonValue(input.initialTemplate),
      transactionTemplate: null,
      validatedTemplate: null,
      compiledPath: null,
      transactionId: null,
      revision: null,
      revealIndex: 0,
      outstandingCommand: null,
      reducedMotion: input.reducedMotion ?? false,
      presentationAckTimeoutMs: Math.max(1, input.presentationAckTimeoutMs ?? DEFAULT_ACK_TIMEOUT_MS),
      generationAttempt: 0,
      duplicateGenerateRequestCount: 0,
      lastError: null,
    }),
    invoke: {
      id: "runtimeDataLifetime",
      src: "runtimeDataLifetime",
    },
    on: {
      "PAGE.TEMPLATE.RECEIVED": [
        { guard: "receivedTemplateIsJsonSafe", actions: "receiveTemplate" },
        { actions: "recordNonJsonTemplate" },
      ],
    },
    states: {
      awaitingGenerate: {
        on: {
          "PAGE.GENERATE.REQUESTED": [
            {
              guard: "hasTemplateForRequest",
              target: "validating",
              actions: ["releaseCurrentCompiledRuntimeData", "beginGeneration"],
            },
            {
              guard: ({ context, event }) => selectedTemplate(context, event) === null,
              actions: "recordMissingTemplate",
            },
            { actions: "recordNonJsonTemplate" },
          ],
          "PAGE.GENERATE.RETRY_REQUESTED": [
            {
              guard: "hasRetryTemplate",
              target: "validating",
              actions: ["releaseCurrentCompiledRuntimeData", "beginGeneration"],
            },
            { actions: "recordMissingTemplate" },
          ],
        },
      },
      validating: {
        invoke: {
          src: "validateTemplate",
          input: ({ context }) => ({
            template: context.transactionTemplate,
            transactionId: context.transactionId ?? "invalid-transaction",
          }),
          onDone: {
            target: "compiling",
            actions: "acceptValidatedTemplate",
          },
          onError: {
            target: "awaitingGenerate",
            actions: "recordValidationFailure",
          },
        },
        on: {
          "PAGE.GENERATE.REQUESTED": { actions: "recordDuplicateGenerateRequest" },
          "PAGE.GENERATE.RETRY_REQUESTED": { actions: "recordDuplicateGenerateRequest" },
        },
      },
      compiling: {
        invoke: {
          src: "compilePath",
          input: ({ context }) => ({
            validatedTemplate: context.validatedTemplate,
            transactionId: context.transactionId ?? "invalid-transaction",
          }),
          onDone: [
            {
              guard: "compiledContractIsValid",
              target: "preparingPresentation",
              actions: "acceptCompiledPath",
            },
            {
              target: "awaitingGenerate",
              actions: "recordCompiledContractFailure",
            },
          ],
          onError: {
            target: "awaitingGenerate",
            actions: "recordCompilationFailure",
          },
        },
        on: {
          "PAGE.GENERATE.REQUESTED": { actions: "recordDuplicateGenerateRequest" },
          "PAGE.GENERATE.RETRY_REQUESTED": { actions: "recordDuplicateGenerateRequest" },
        },
      },
      preparingPresentation: {
        invoke: {
          src: "preparePresentation",
          input: ({ context }) => ({
            compiledPath: context.compiledPath as CompiledLearningPathPage,
            transactionId: context.transactionId ?? "invalid-transaction",
            revision: context.revision ?? "invalid-revision",
          }),
          onDone: {
            target: "revealingPath",
          },
          onError: {
            target: "awaitingGenerate",
            actions: "recordPresentationPreparationFailure",
          },
        },
        on: {
          "PAGE.GENERATE.REQUESTED": { actions: "recordDuplicateGenerateRequest" },
          "PAGE.GENERATE.RETRY_REQUESTED": { actions: "recordDuplicateGenerateRequest" },
        },
      },
      revealingPath: {
        initial: "selecting",
        on: {
          "PAGE.GENERATE.REQUESTED": { actions: "recordDuplicateGenerateRequest" },
          "PAGE.GENERATE.RETRY_REQUESTED": { actions: "recordDuplicateGenerateRequest" },
        },
        states: {
          selecting: {
            always: [
              { guard: "hasMorePathSteps", target: "issuing" },
              { target: "#learning-path-page-generation.revealingCharacter" },
            ],
          },
          issuing: {
            entry: "issuePathRevealCommand",
            on: {
              "PAGE.PATH_STEP.SETTLED": {
                guard: "pathAckMatches",
                target: "selecting",
                actions: "commitPathRevealAck",
              },
              "PAGE.PRESENTATION.FAILED": {
                guard: "failureMatches",
                target: "#learning-path-page-generation.awaitingGenerate",
                actions: "recordPresentationFailure",
              },
            },
            after: {
              presentationAckTimeout: {
                target: "#learning-path-page-generation.awaitingGenerate",
                actions: "recordPresentationTimeout",
              },
            },
          },
        },
      },
      revealingCharacter: {
        entry: "issueCharacterRevealCommand",
        on: {
          "PAGE.GENERATE.REQUESTED": { actions: "recordDuplicateGenerateRequest" },
          "PAGE.GENERATE.RETRY_REQUESTED": { actions: "recordDuplicateGenerateRequest" },
          "PAGE.CHARACTER.SETTLED": {
            guard: "characterAckMatches",
            target: "ready",
            actions: "completeGeneration",
          },
          "PAGE.PRESENTATION.FAILED": {
            guard: "failureMatches",
            target: "awaitingGenerate",
            actions: "recordPresentationFailure",
          },
        },
        after: {
          presentationAckTimeout: {
            target: "awaitingGenerate",
            actions: "recordPresentationTimeout",
          },
        },
      },
      ready: {
        on: {
          "PAGE.GENERATE.REQUESTED": [
            {
              guard: "hasTemplateForRequest",
              target: "validating",
              actions: "beginGeneration",
            },
            { actions: "recordMissingTemplate" },
          ],
        },
      },
    },
  });
}
