import { assign, setup, type SnapshotFrom } from "xstate";
import type {
  CompletionCelebrationContext,
  CompletionCelebrationEvent,
  CompletionCelebrationMachineInput,
} from "./types";

function normalizedCount(value: number | undefined): number {
  return Number.isSafeInteger(value) && (value ?? 0) >= 0 ? value ?? 0 : 0;
}

/**
 * Owns only the ephemeral presentation lifecycle for completion celebration.
 * Progress remains the single owner of the durable `celebrationSeen/count`
 * facts; this actor observes that monotonically increasing counter.
 */
export const completionCelebrationMachine = setup({
  types: {} as {
    context: CompletionCelebrationContext;
    events: CompletionCelebrationEvent;
    input: CompletionCelebrationMachineInput;
  },
  guards: {
    recordsNewCelebration: ({ context, event }) => (
      event.type === "PROGRESS.CELEBRATION_RECORDED"
      && Number.isSafeInteger(event.count)
      && event.count > context.acknowledgedCount
    ),
    acknowledgesActiveCelebration: ({ context, event }) => (
      event.type === "PRESENTATION.ACKNOWLEDGED"
      && context.activeCount !== null
      && event.count === context.activeCount
    ),
    hidesAcknowledgedCelebration: ({ context, event }) => (
      event.type === "PRESENTATION.HIDDEN"
      && context.activeCount !== null
      && event.count === context.activeCount
      && event.count <= context.acknowledgedCount
    ),
  },
  actions: {
    recordCelebration: assign(({ context, event }) => {
      if (event.type !== "PROGRESS.CELEBRATION_RECORDED") return {};
      return {
        observedCount: Math.max(context.observedCount, event.count),
        activeCount: event.count,
      };
    }),
    acknowledgeCelebration: assign(({ context, event }) => {
      if (event.type !== "PRESENTATION.ACKNOWLEDGED") return {};
      return {
        acknowledgedCount: Math.max(context.acknowledgedCount, event.count),
      };
    }),
    clearPresentation: assign({ activeCount: null }),
    resetSession: assign(({ event }) => {
      if (event.type !== "SESSION.RESET") return {};
      const count = normalizedCount(event.restoredCount);
      return {
        observedCount: count,
        activeCount: null,
        acknowledgedCount: count,
      };
    }),
  },
}).createMachine({
  id: "completionCelebration",
  initial: "hidden",
  context: ({ input }) => {
    const count = normalizedCount(input.restoredCount);
    return {
      observedCount: count,
      activeCount: null,
      acknowledgedCount: count,
    };
  },
  on: {
    "SESSION.RESET": {
      target: ".hidden",
      actions: "resetSession",
    },
  },
  states: {
    hidden: {
      on: {
        "PROGRESS.CELEBRATION_RECORDED": {
          guard: "recordsNewCelebration",
          target: "showing",
          actions: "recordCelebration",
        },
      },
    },
    showing: {
      on: {
        "PROGRESS.CELEBRATION_RECORDED": {
          guard: "recordsNewCelebration",
          actions: "recordCelebration",
        },
        "PRESENTATION.ACKNOWLEDGED": {
          guard: "acknowledgesActiveCelebration",
          target: "acknowledged",
          actions: "acknowledgeCelebration",
        },
      },
    },
    acknowledged: {
      on: {
        "PROGRESS.CELEBRATION_RECORDED": {
          guard: "recordsNewCelebration",
          target: "showing",
          actions: "recordCelebration",
        },
        "PRESENTATION.HIDDEN": {
          guard: "hidesAcknowledgedCelebration",
          target: "hidden",
          actions: "clearPresentation",
        },
      },
    },
  },
});

export type CompletionCelebrationMachineLogic = typeof completionCelebrationMachine;
export type CompletionCelebrationMachineSnapshot = SnapshotFrom<CompletionCelebrationMachineLogic>;
