import {
  LEARNING_PATH_PROTOCOL,
  LEARNING_PATH_VERSION,
  type CompiledConceptZone,
  type CompiledLearningPath,
  type CompiledLearningPathEdge,
  type CompiledLearningPathLayer,
  type CompiledLearningPathNode,
  type LearningConceptDefinition,
  type LearningFlowDefinition,
  type LearningFlowGroupDefinition,
  type LearningPathDocument,
  type LearningSubjectDefinition,
} from "./types";
import { assertLearningPathDocument } from "./validator";

const DEFAULT_SUBJECT_GAP = 3.75;
const DEFAULT_LAYER_GAP = 3.5;
const DEFAULT_CONCEPT_GAP = 3.75;
const DEFAULT_CONCEPT_COLUMN_GAP = 4.4;
const NODE_SURFACE_Y = 0.523;

/** Validates and compiles an untrusted JSON value in one bounded operation. */
export function compileLearningPathDocument(input: unknown): CompiledLearningPath {
  return compileValidatedLearningPathDocument(assertLearningPathDocument(input));
}

/**
 * Compiles a previously validated v1 document. This function is deterministic:
 * equivalent input produces identical node order, coordinates, edges and zones.
 */
export function compileValidatedLearningPathDocument(
  document: LearningPathDocument,
): CompiledLearningPath {
  const { subjects, concepts, flow, flowGroups } = document.structure;
  const outgoing = groupFlows(flow, (edge) => edge.fromSubjectId);
  const incoming = groupFlows(flow, (edge) => edge.toSubjectId);
  const topologicalSubjects = topologicalOrder(subjects, outgoing, incoming);
  const layerBySubjectId = computeLayers(topologicalSubjects, incoming);
  const subjectsByLayer = groupSubjectsByLayer(topologicalSubjects, layerBySubjectId);
  const conceptsBySubject = groupConceptsBySubject(concepts);
  const cardById = new Map(document.data.cards.map((card) => [card.id, card] as const));
  const actionById = new Map(document.data.actions.map((action) => [action.id, action] as const));
  const resourceById = new Map(document.data.resources.map((resource) => [resource.id, resource] as const));

  const subjectGap = document.presentation.layout.subjectGap ?? DEFAULT_SUBJECT_GAP;
  const layerGap = document.presentation.layout.layerGap ?? DEFAULT_LAYER_GAP;
  const conceptGap = document.presentation.layout.conceptGap ?? DEFAULT_CONCEPT_GAP;
  const conceptColumnGap = document.presentation.layout.conceptColumnGap ?? DEFAULT_CONCEPT_COLUMN_GAP;
  const maxLayer = Math.max(...layerBySubjectId.values());
  const startZ = -(maxLayer * layerGap) / 2;

  const nodes: CompiledLearningPathNode[] = [];
  let nextConceptNavigationOrder = subjects.length;
  const layers: CompiledLearningPathLayer[] = [];
  const subjectPositionById = new Map<string, { readonly x: number; readonly z: number }>();

  for (let layerIndex = 0; layerIndex <= maxLayer; layerIndex += 1) {
    const layerSubjects = subjectsByLayer.get(layerIndex) ?? [];
    const firstSubjectX = -((layerSubjects.length - 1) * subjectGap) / 2;
    const z = roundCoordinate(startZ + layerIndex * layerGap);
    for (const [index, subject] of layerSubjects.entries()) {
      subjectPositionById.set(subject.id, {
        x: roundCoordinate(firstSubjectX + index * subjectGap),
        z,
      });
    }

    const layerConcepts = layerSubjects.flatMap((subject) => conceptsBySubject.get(subject.id) ?? []);
    const rightmostSubjectX = firstSubjectX + Math.max(0, layerSubjects.length - 1) * subjectGap;
    const firstConceptX = rightmostSubjectX + conceptColumnGap;
    // Concept zones on one subject row are mutually exclusive at runtime, so
    // they deliberately reuse the same right-hand slots. Accumulating hidden
    // concepts from earlier sibling subjects would push later zones farther
    // away for no visible reason and turn an adjacent entry into an oversized
    // bridge. Reusing slots makes the physical span depend only on the active
    // subject's real position: rightmost = straight, middle = shorter bridge,
    // leftmost = longer bridge.
    for (const subject of layerSubjects) {
      const ownedConcepts = conceptsBySubject.get(subject.id) ?? [];
      for (const [conceptIndex, concept] of ownedConcepts.entries()) {
        const card = requireMapValue(cardById, concept.cardRef, "card");
        const action = requireMapValue(actionById, concept.actionRef, "action");
        const resource = requireMapValue(resourceById, action.resourceId, "resource");
        nodes.push(Object.freeze({
          id: concept.id,
          entityId: concept.id,
          entityKind: "concept" as const,
          navigationOrder: nextConceptNavigationOrder,
          label: card.title,
          position: Object.freeze({
            x: roundCoordinate(firstConceptX + conceptIndex * conceptGap),
            z,
          }),
          layer: layerIndex,
          initiallyGreen: false,
          initiallyVisible: false,
          completionPolicy: "preserve-variant" as const,
          activationGroupId: conceptZoneId(concept.subjectId),
          surfaceY: NODE_SURFACE_Y,
          variant: "brown" as const,
          card,
          action: Object.freeze({ ...action, resource }),
          ownerSubjectId: concept.subjectId,
        }));
        nextConceptNavigationOrder += 1;
      }
    }
    layers.push(Object.freeze({
      index: layerIndex,
      subjectNodeIds: Object.freeze(layerSubjects.map((subject) => subject.id)),
      conceptNodeIds: Object.freeze(layerConcepts.map((concept) => concept.id)),
    }));
  }

  const subjectNavigationIndex = new Map(
    topologicalSubjects.map((subject, index) => [subject.id, index] as const),
  );
  const subjectNodes = topologicalSubjects.map((subject): CompiledLearningPathNode => {
    const card = requireMapValue(cardById, subject.cardRef, "card");
    return Object.freeze({
      id: subject.id,
      entityId: subject.id,
      entityKind: "subject",
      navigationOrder: requireMapValue(subjectNavigationIndex, subject.id, "navigation order"),
      label: card.title,
      position: Object.freeze(requireMapValue(subjectPositionById, subject.id, "position")),
      layer: requireMapValue(layerBySubjectId, subject.id, "layer"),
      initiallyGreen: true,
      initiallyVisible: true,
      completionPolicy: "promote-to-green",
      surfaceY: NODE_SURFACE_Y,
      variant: "green",
      card,
    });
  });

  const conceptNodes = nodes;
  const firstConceptNodeBySubjectId = new Map<string, CompiledLearningPathNode>();
  for (const node of conceptNodes) {
    if (node.ownerSubjectId && !firstConceptNodeBySubjectId.has(node.ownerSubjectId)) {
      firstConceptNodeBySubjectId.set(node.ownerSubjectId, node);
    }
  }
  const compiledNodes = Object.freeze([...subjectNodes, ...conceptNodes]);
  const subjectEdges = [...flow]
    .sort(compareFlow)
    .map((edge): CompiledLearningPathEdge => Object.freeze({
      id: edge.id,
      fromNodeId: edge.fromSubjectId,
      toNodeId: edge.toSubjectId,
      pathKind: "straight",
      initiallyVisible: true,
      completionPolicy: "promote-to-green",
      sourceKind: "subject-flow",
      ...(edge.semantics ? { flowSemantics: Object.freeze({ ...edge.semantics }) } : {}),
    }));
  const parallelPeerEdges = createParallelPeerEdges(
    flowGroups,
    flow,
    subjectNodes,
    new Set(subjectEdges.map((edge) => edge.id)),
  );

  const conceptEdges: CompiledLearningPathEdge[] = [];
  const conceptZones: CompiledConceptZone[] = [];
  for (const subject of topologicalSubjects) {
    const ownedConcepts = conceptsBySubject.get(subject.id) ?? [];
    if (ownedConcepts.length === 0) continue;
    const activationPosition = requireMapValue(
      subjectPositionById,
      subject.id,
      "subject position",
    );
    const entryNode = requireMapValue(
      firstConceptNodeBySubjectId,
      subject.id,
      "first concept node",
    );
    const siblingSubjects = subjectsByLayer.get(
      requireMapValue(layerBySubjectId, subject.id, "layer"),
    ) ?? [];
    const hasIntermediateSubjectSlot = siblingSubjects.some((candidate) => {
      if (candidate.id === subject.id) return false;
      const candidatePosition = requireMapValue(
        subjectPositionById,
        candidate.id,
        "sibling subject position",
      );
      return candidatePosition.x > Math.min(activationPosition.x, entryNode.position.x)
        && candidatePosition.x < Math.max(activationPosition.x, entryNode.position.x);
    });
    const zoneId = conceptZoneId(subject.id);
    const memberEdgeIds: string[] = [];
    const revealOrder: Array<
      | { readonly kind: "edge"; readonly id: string }
      | { readonly kind: "node"; readonly id: string }
    > = [{ kind: "node", id: requireArrayValue(ownedConcepts, 0, "first concept").id }];
    for (let index = 1; index < ownedConcepts.length; index += 1) {
      const previous = requireArrayValue(ownedConcepts, index - 1, "previous concept");
      const current = requireArrayValue(ownedConcepts, index, "current concept");
      const edgeId = `concept-flow:${previous.id}:${current.id}`;
      memberEdgeIds.push(edgeId);
      conceptEdges.push(Object.freeze({
        id: edgeId,
        fromNodeId: previous.id,
        toNodeId: current.id,
        pathKind: "straight",
        initiallyVisible: false,
        completionPolicy: "preserve-variant",
        activationGroupId: zoneId,
        sourceKind: "concept-chain",
      }));
      revealOrder.push({ kind: "edge", id: edgeId }, { kind: "node", id: current.id });
    }
    conceptZones.push(Object.freeze({
      id: zoneId,
      activationSubjectNodeId: subject.id,
      entryConnection: Object.freeze({
        fromSubjectNodeId: subject.id,
        toConceptNodeId: requireArrayValue(ownedConcepts, 0, "first concept").id,
        preferredPathKind: hasIntermediateSubjectSlot
          ? "overpass" as const
          : "straight" as const,
      }),
      memberConceptNodeIds: Object.freeze(ownedConcepts.map((concept) => concept.id)),
      memberEdgeIds: Object.freeze(memberEdgeIds),
      revealOrder: Object.freeze(revealOrder.map((step) => Object.freeze(step))),
    }));
  }

  const compiledEdges = Object.freeze([
    ...subjectEdges,
    ...parallelPeerEdges,
    ...conceptEdges,
  ]);
  return Object.freeze({
    protocol: LEARNING_PATH_PROTOCOL,
    version: LEARNING_PATH_VERSION,
    sourceDocumentId: document.id,
    initialNodeId: document.structure.entrySubjectId,
    entryNodeId: document.structure.entrySubjectId,
    goalNodeIds: Object.freeze([...document.structure.goalSubjectIds]),
    nodes: compiledNodes,
    edges: compiledEdges,
    conceptZones: Object.freeze(conceptZones),
    layers: Object.freeze(layers),
    nodeById: new Map(compiledNodes.map((node) => [node.id, node] as const)),
    edgeById: new Map(compiledEdges.map((edge) => [edge.id, edge] as const)),
  });
}

/**
 * A parallel split means its branches may be studied in any order. Adjacent
 * siblings therefore receive one horizontal ground road so the physical map
 * exposes that freedom without adding a dependency edge to the learning DAG.
 */
function createParallelPeerEdges(
  flowGroups: readonly LearningFlowGroupDefinition[],
  flow: readonly LearningFlowDefinition[],
  subjectNodes: readonly CompiledLearningPathNode[],
  usedEdgeIds: Set<string>,
): readonly CompiledLearningPathEdge[] {
  const subjectNodeById = new Map(subjectNodes.map((node) => [node.id, node] as const));
  const result: CompiledLearningPathEdge[] = [];
  // Several predecessor splits can share the same next parallel stage. They
  // retain distinct semantic flow edges, but share one physical sibling road.
  const physicalPairs = new Set<string>();

  for (const group of flowGroups) {
    if (group.type !== "split" || group.policy !== "parallel") continue;
    const siblingNodes = flow
      .filter((edge) => (
        edge.fromSubjectId === group.anchorSubjectId
        && edge.semantics?.splitGroupId === group.id
      ))
      .map((edge) => requireMapValue(subjectNodeById, edge.toSubjectId, "parallel subject"))
      .sort((left, right) => (
        left.position.x - right.position.x
        || left.navigationOrder - right.navigationOrder
        || left.id.localeCompare(right.id)
      ));

    for (let index = 1; index < siblingNodes.length; index += 1) {
      const from = requireArrayValue(siblingNodes, index - 1, "left parallel subject");
      const to = requireArrayValue(siblingNodes, index, "right parallel subject");
      const pair = JSON.stringify([from.id, to.id].sort());
      if (physicalPairs.has(pair)) continue;
      physicalPairs.add(pair);
      const baseId = `parallel-peer:${group.id}:${from.id}:${to.id}`;
      const id = createUniqueCompiledEdgeId(baseId, usedEdgeIds);
      usedEdgeIds.add(id);
      result.push(Object.freeze({
        id,
        fromNodeId: from.id,
        toNodeId: to.id,
        pathKind: "straight" as const,
        initiallyVisible: true,
        completionPolicy: "promote-to-green" as const,
        sourceKind: "parallel-peer" as const,
      }));
    }
  }
  return Object.freeze(result);
}

function createUniqueCompiledEdgeId(baseId: string, usedEdgeIds: ReadonlySet<string>): string {
  if (!usedEdgeIds.has(baseId)) return baseId;
  let suffix = 2;
  while (usedEdgeIds.has(`${baseId}:${suffix}`)) suffix += 1;
  return `${baseId}:${suffix}`;
}

function topologicalOrder(
  subjects: readonly LearningSubjectDefinition[],
  outgoing: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
  incoming: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
): readonly LearningSubjectDefinition[] {
  const subjectById = new Map(subjects.map((subject) => [subject.id, subject] as const));
  const indegree = new Map(subjects.map((subject) => [subject.id, incoming.get(subject.id)?.length ?? 0] as const));
  const queue = subjects.filter((subject) => indegree.get(subject.id) === 0).sort(compareAuthoredOrder);
  const result: LearningSubjectDefinition[] = [];
  while (queue.length > 0) {
    const subject = queue.shift();
    if (!subject) break;
    result.push(subject);
    for (const edge of outgoing.get(subject.id) ?? []) {
      const nextDegree = (indegree.get(edge.toSubjectId) ?? 0) - 1;
      indegree.set(edge.toSubjectId, nextDegree);
      if (nextDegree === 0) {
        const nextSubject = requireMapValue(subjectById, edge.toSubjectId, "subject");
        insertSubjectSorted(queue, nextSubject);
      }
    }
  }
  if (result.length !== subjects.length) {
    throw new Error("Compiler received a cyclic or incomplete document. Validate before compiling.");
  }
  return result;
}

function computeLayers(
  subjects: readonly LearningSubjectDefinition[],
  incoming: ReadonlyMap<string, readonly LearningFlowDefinition[]>,
): ReadonlyMap<string, number> {
  const result = new Map<string, number>();
  for (const subject of subjects) {
    const predecessors = incoming.get(subject.id) ?? [];
    const layer = predecessors.reduce(
      (maximum, edge) => Math.max(maximum, (result.get(edge.fromSubjectId) ?? -1) + 1),
      0,
    );
    result.set(subject.id, layer);
  }
  return result;
}

function groupSubjectsByLayer(
  subjects: readonly LearningSubjectDefinition[],
  layerBySubjectId: ReadonlyMap<string, number>,
): ReadonlyMap<number, readonly LearningSubjectDefinition[]> {
  const groups = new Map<number, LearningSubjectDefinition[]>();
  for (const subject of subjects) {
    appendMapArray(groups, requireMapValue(layerBySubjectId, subject.id, "layer"), subject);
  }
  for (const values of groups.values()) values.sort(compareAuthoredOrder);
  return groups;
}

function groupConceptsBySubject(
  concepts: readonly LearningConceptDefinition[],
): ReadonlyMap<string, readonly LearningConceptDefinition[]> {
  const groups = new Map<string, LearningConceptDefinition[]>();
  for (const concept of concepts) appendMapArray(groups, concept.subjectId, concept);
  for (const values of groups.values()) values.sort(compareAuthoredOrder);
  return groups;
}

function groupFlows(
  flow: readonly LearningFlowDefinition[],
  keyOf: (edge: LearningFlowDefinition) => string,
): ReadonlyMap<string, readonly LearningFlowDefinition[]> {
  const groups = new Map<string, LearningFlowDefinition[]>();
  for (const edge of flow) appendMapArray(groups, keyOf(edge), edge);
  for (const values of groups.values()) values.sort(compareFlow);
  return groups;
}

function compareAuthoredOrder(
  left: { readonly id: string; readonly orderHint?: number },
  right: { readonly id: string; readonly orderHint?: number },
): number {
  return (left.orderHint ?? Number.MAX_SAFE_INTEGER) - (right.orderHint ?? Number.MAX_SAFE_INTEGER)
    || left.id.localeCompare(right.id);
}

function compareFlow(left: LearningFlowDefinition, right: LearningFlowDefinition): number {
  return left.fromSubjectId.localeCompare(right.fromSubjectId)
    || left.toSubjectId.localeCompare(right.toSubjectId)
    || left.id.localeCompare(right.id);
}

function insertSubjectSorted(
  values: LearningSubjectDefinition[],
  value: LearningSubjectDefinition,
): void {
  let index = 0;
  while (index < values.length && compareAuthoredOrder(requireArrayValue(values, index, "queued subject"), value) < 0) {
    index += 1;
  }
  values.splice(index, 0, value);
}

function appendMapArray<K, V>(map: Map<K, V[]>, key: K, value: V): void {
  const values = map.get(key);
  if (values) values.push(value);
  else map.set(key, [value]);
}

function requireMapValue<K, V>(map: ReadonlyMap<K, V>, key: K, label: string): V {
  const value = map.get(key);
  if (value === undefined) throw new Error(`Missing compiled ${label}.`);
  return value;
}

function requireArrayValue<T>(values: readonly T[], index: number, label: string): T {
  const value = values[index];
  if (value === undefined) throw new Error(`Missing compiled ${label}.`);
  return value;
}

function conceptZoneId(subjectId: string): string {
  return `concept-zone:${subjectId}`;
}

function roundCoordinate(value: number): number {
  return Math.round(value * 1_000_000) / 1_000_000;
}
