import type { LearningEntityId } from "../../content";
import type { NodeCardMachineSnapshot } from "./machine";
import type {
  NodeCardActionDiagnostic,
  NodeCardCloseDiagnostic,
  NodeCardInstanceReference,
  NodeCardViewSnapshot,
} from "./types";

export function selectNodeCardVisible(snapshot: NodeCardMachineSnapshot): boolean {
  return snapshot.matches("visible");
}

export function selectNodeCardNodeId(
  snapshot: NodeCardMachineSnapshot,
): LearningEntityId | null {
  return snapshot.context.nodeId;
}

export function selectNodeCardRevision(snapshot: NodeCardMachineSnapshot): number {
  return snapshot.context.revision;
}

export function selectNodeCardInstance(
  snapshot: NodeCardMachineSnapshot,
): NodeCardInstanceReference | null {
  const nodeId = snapshot.context.nodeId;
  if (!snapshot.matches("visible") || nodeId === null) return null;
  return Object.freeze({
    nodeId,
    revision: snapshot.context.revision,
  });
}

export function selectLastNodeCardClose(
  snapshot: NodeCardMachineSnapshot,
): NodeCardCloseDiagnostic | null {
  return snapshot.context.lastClose;
}

export function selectLastNodeCardAction(
  snapshot: NodeCardMachineSnapshot,
): NodeCardActionDiagnostic | null {
  return snapshot.context.lastAction;
}

export function selectNodeCardView(
  snapshot: NodeCardMachineSnapshot,
): NodeCardViewSnapshot {
  const visible = snapshot.matches("visible");
  const instance = selectNodeCardInstance(snapshot);
  return Object.freeze({
    mode: visible ? "visible" : "hidden",
    nodeId: snapshot.context.nodeId,
    revision: snapshot.context.revision,
    instance,
    lastClose: snapshot.context.lastClose,
    lastAction: snapshot.context.lastAction,
  });
}
