import type { ActorRefFrom, SnapshotFrom } from "xstate";
import type { LearningProgressEvent } from "../../progression/domain/types";
import type { createLearningProgressPersistenceMachine } from "../../progression/persistence";
import type { createSceneRuntimeGateway } from "../../runtime/gateway";
import type { createLearningResourceMachine } from "../learning-resource";
import type { createSceneSessionMachine } from "../scene-session";
import type { createPageGenerationMachine } from "../../statecharts/page";
import type { nodeCardMachine } from "../../ui/node-card";
import type { createJourneyMachine } from "../../workflows/journey";
import type { completionCelebrationMachine } from "../../workflows/completion-celebration";
import {
  selectCompletionCelebrationView,
  type CompletionCelebrationViewSnapshot,
} from "../../workflows/completion-celebration";
import type { createRevisionProgressActorLogic } from "./progressChild";
import type { createLearningPathMachine } from "../../statecharts/learningPathMachine";
import type {
  LearningPathApplicationMachine,
  LearningPathApplicationSnapshot,
} from "./machine";
import type { LearningPathApplicationPhase } from "./types";

type ApplicationSnapshot = SnapshotFrom<LearningPathApplicationMachine>;
type PageActor = ActorRefFrom<ReturnType<typeof createPageGenerationMachine>>;
type ProgressActor = ActorRefFrom<ReturnType<typeof createRevisionProgressActorLogic>>;
type JourneyActor = ActorRefFrom<ReturnType<typeof createJourneyMachine>>;
type CompletionCelebrationActor = ActorRefFrom<typeof completionCelebrationMachine>;
type CardActor = ActorRefFrom<typeof nodeCardMachine>;
type GatewayActor = ActorRefFrom<ReturnType<typeof createSceneRuntimeGateway>>;
type SceneSessionActor = ActorRefFrom<ReturnType<typeof createSceneSessionMachine>>;
type LearningResourceActor = ActorRefFrom<ReturnType<typeof createLearningResourceMachine>>;
type PathOrchestrationActor = ActorRefFrom<ReturnType<typeof createLearningPathMachine>>;
type PersistenceActor = ActorRefFrom<
  ReturnType<typeof createLearningProgressPersistenceMachine>
>;

const ROOT_PHASES = Object.freeze([
  "gate",
  "generating",
  "generationFailed",
  "degraded",
] as const);

export function selectLearningPathApplicationPhase(
  snapshot: LearningPathApplicationSnapshot,
): LearningPathApplicationPhase {
  if (snapshot.matches({ active: "interactive" })) return "active";
  if (snapshot.matches({ active: "hydrating" })
    || snapshot.matches({ active: "reconciling" })) {
    return "restoring";
  }
  if (snapshot.matches({ active: "draining" })) return "generating";
  return ROOT_PHASES.find((phase) => snapshot.matches(phase)) ?? "gate";
}

export function selectActiveSessionRevision(
  snapshot: ApplicationSnapshot,
): number | null {
  return snapshot.context.activeExperience?.sessionRevision ?? null;
}

export function selectLastDispatchedJourneyTransactionId(
  snapshot: ApplicationSnapshot,
): string | null {
  return snapshot.context.lastDispatchedJourneyTransactionId;
}

export function selectPageGenerationActor(snapshot: ApplicationSnapshot): PageActor | null {
  return (snapshot.children.pageGeneration as PageActor | undefined) ?? null;
}

export function selectProgressActor(snapshot: ApplicationSnapshot): ProgressActor | null {
  return (snapshot.children.progress as ProgressActor | undefined) ?? null;
}

export function selectJourneyActor(snapshot: ApplicationSnapshot): JourneyActor | null {
  return (snapshot.children.journey as JourneyActor | undefined) ?? null;
}

export function selectNodeCardActor(snapshot: ApplicationSnapshot): CardActor | null {
  return (snapshot.children.nodeCard as CardActor | undefined) ?? null;
}

export function selectCompletionCelebrationActor(
  snapshot: ApplicationSnapshot,
): CompletionCelebrationActor | null {
  return (snapshot.children.completionCelebration as CompletionCelebrationActor | undefined) ?? null;
}

export function selectApplicationCompletionCelebrationView(
  snapshot: ApplicationSnapshot,
): CompletionCelebrationViewSnapshot | null {
  const actor = selectCompletionCelebrationActor(snapshot);
  return actor ? selectCompletionCelebrationView(actor.getSnapshot()) : null;
}

export function selectSceneRuntimeGatewayActor(
  snapshot: ApplicationSnapshot,
): GatewayActor | null {
  const sceneSession = selectSceneSessionActor(snapshot);
  return (sceneSession?.getSnapshot().children.sceneRuntimeGateway as GatewayActor | undefined)
    ?? null;
}

export function selectSceneSessionActor(
  snapshot: ApplicationSnapshot,
): SceneSessionActor | null {
  return (snapshot.children.sceneSession as SceneSessionActor | undefined) ?? null;
}

export function selectLearningResourceActor(
  snapshot: ApplicationSnapshot,
): LearningResourceActor | null {
  return (snapshot.children.learningResource as LearningResourceActor | undefined) ?? null;
}

export function selectPathOrchestrationActor(
  snapshot: ApplicationSnapshot,
): PathOrchestrationActor | null {
  return (snapshot.children.pathOrchestration as PathOrchestrationActor | undefined) ?? null;
}

export function selectPersistenceActor(
  snapshot: ApplicationSnapshot,
): PersistenceActor | null {
  return (snapshot.children.persistence as PersistenceActor | undefined) ?? null;
}

export function selectProgressModel(snapshot: ApplicationSnapshot) {
  return selectProgressActor(snapshot)?.getSnapshot().context.model ?? null;
}

export function selectApplicationActorIds(snapshot: ApplicationSnapshot): readonly string[] {
  return Object.freeze(Object.keys(snapshot.children).sort());
}

/** Type-only assertion ensuring the selected actor accepts domain events. */
export type ApplicationProgressChildEvent = LearningProgressEvent;
