import {
  createRuntimePathBundle,
  type RuntimePathBundle,
} from "../config/createRuntimePathBundle";
import type {
  LearningPathNode,
  NodeId,
  StraightLearningPathEdge,
} from "../config/pathData";
import {
  DYNAMIC_BRIDGE_RULE,
  type DynamicBridgeRuleSpec,
  type SpecialPathZoneSpec,
  type SpecialRevealStep,
  type ZoneEntryConnectionSpec,
} from "../config/pathRules";
import type {
  CompiledConceptZone,
  CompiledLearningPath,
  CompiledLearningPathEdge,
  CompiledLearningPathNode,
  LearningAction,
  LearningResource,
} from "../content/types";
import type {
  CompiledLearningPathPage,
  PathRevealStep,
} from "../statecharts/page/contracts";
import { registerCompiledPageRuntimeData } from "../statecharts/page/runtimeDataRegistry";

export interface CompileLearningPathRuntimeOptions {
  /** Stable revision override for hosts that already own content revisions. */
  readonly revision?: string;
  /** Defaults to the product's validated direct-bridge rule. */
  readonly dynamicBridgeRule?: DynamicBridgeRuleSpec;
  /** Selects one primary runtime goal when the content document has many goals. */
  readonly primaryGoalNodeId?: NodeId;
}

export interface LearningPathActionBinding {
  readonly nodeId: NodeId;
  readonly action: LearningAction;
  readonly resource: LearningResource;
}

/** Immutable allowlisted action registry. It deliberately has no UI shape. */
export interface LearningPathActionRegistry {
  readonly actionByNodeId: ReadonlyMap<NodeId, LearningPathActionBinding>;
  readonly resourceByActionId: ReadonlyMap<string, LearningResource>;
  readonly getAction: (nodeId: NodeId | null) => LearningPathActionBinding | null;
}

export interface LearningPathPageDomainData {
  readonly source: CompiledLearningPath;
  readonly runtimeBundle: RuntimePathBundle;
  readonly specialZones: readonly SpecialPathZoneSpec[];
  readonly dynamicBridgeRule: DynamicBridgeRuleSpec;
  readonly actionRegistry: LearningPathActionRegistry;
  readonly goalNodeIds: readonly NodeId[];
  readonly primaryGoalNodeId: NodeId;
}

export interface CompiledLearningPathRuntime {
  readonly source: CompiledLearningPath;
  readonly runtimeBundle: RuntimePathBundle;
  readonly specialZones: readonly SpecialPathZoneSpec[];
  readonly sessionEntryStraightEdges: readonly StraightLearningPathEdge[];
  readonly dynamicBridgeRule: DynamicBridgeRuleSpec;
  readonly actionRegistry: LearningPathActionRegistry;
  readonly page: CompiledLearningPathPage;
  readonly goalNodeIds: readonly NodeId[];
  readonly primaryGoalNodeId: NodeId;
}

/**
 * Adapts a renderer-independent content compilation into one isolated runtime
 * session. No global path data is mutated and no document IDs are assumed.
 */
export function compileLearningPathRuntime(
  source: CompiledLearningPath,
  options: CompileLearningPathRuntimeOptions = {},
): CompiledLearningPathRuntime {
  const runtimeNodes = Object.freeze(source.nodes.map(toRuntimeNode));
  const authoredStraightEdges = Object.freeze(source.edges.map(toRuntimeEdge));
  const authoredEdgeIds = new Set(authoredStraightEdges.map((edge) => edge.id));
  const usedPhysicalPairKeys = new Set(
    authoredStraightEdges.map((edge) => nodePairKey(edge.fromNodeId, edge.toNodeId)),
  );
  const specialZones: SpecialPathZoneSpec[] = [];
  const sessionEntryStraightEdges: StraightLearningPathEdge[] = [];

  for (const conceptZone of source.conceptZones) {
    const adapted = adaptConceptZone(
      conceptZone,
      source.nodes,
      authoredEdgeIds,
      usedPhysicalPairKeys,
    );
    specialZones.push(adapted.zone);
    if (adapted.sessionEntryStraightEdge) {
      sessionEntryStraightEdges.push(adapted.sessionEntryStraightEdge);
      authoredEdgeIds.add(adapted.sessionEntryStraightEdge.id);
      usedPhysicalPairKeys.add(nodePairKey(
        adapted.sessionEntryStraightEdge.fromNodeId,
        adapted.sessionEntryStraightEdge.toNodeId,
      ));
    }
  }

  const goalNodeIds = Object.freeze([...source.goalNodeIds]);
  const primaryGoalNodeId = resolvePrimaryGoalNodeId(source, options.primaryGoalNodeId);
  const dynamicBridgeRule = options.dynamicBridgeRule ?? DYNAMIC_BRIDGE_RULE;
  const frozenZones = Object.freeze(specialZones);
  const frozenSessionEntryEdges = Object.freeze(sessionEntryStraightEdges);
  const runtimeBundle = createRuntimePathBundle({
    nodes: runtimeNodes,
    authoredStraightEdges,
    sessionEntryStraightEdges: frozenSessionEntryEdges,
    specialZones: frozenZones,
    dynamicBridgeRule,
    initialNodeId: source.initialNodeId,
    entryNodeId: source.entryNodeId,
    goalNodeId: primaryGoalNodeId,
  });
  const actionRegistry = createLearningPathActionRegistry(source);
  const pageNodes = Object.freeze(source.nodes.map((node) => Object.freeze({
    id: node.id,
    initiallyVisible: node.entityKind === "subject" && node.initiallyVisible,
  })));
  const pageEdges = Object.freeze(source.edges.map((edge) => Object.freeze({
    id: edge.id,
    fromNodeId: edge.fromNodeId,
    toNodeId: edge.toNodeId,
    initiallyVisible: (
      edge.sourceKind === "subject-flow" || edge.sourceKind === "parallel-peer"
    ) && edge.initiallyVisible,
  })));
  const revealOrder = createInitialRevealOrder(source);
  const revision = resolveRevision(source, options.revision);

  const pageData: LearningPathPageDomainData = Object.freeze({
    source,
    runtimeBundle,
    specialZones: frozenZones,
    dynamicBridgeRule,
    actionRegistry,
    goalNodeIds,
    primaryGoalNodeId,
  });
  const page = Object.freeze({
    revision,
    initialNodeId: source.initialNodeId,
    nodes: pageNodes,
    edges: pageEdges,
    revealOrder,
    data: registerCompiledPageRuntimeData(revision, pageData),
  });

  return Object.freeze({
    source,
    runtimeBundle,
    specialZones: frozenZones,
    sessionEntryStraightEdges: frozenSessionEntryEdges,
    dynamicBridgeRule,
    actionRegistry,
    page,
    goalNodeIds,
    primaryGoalNodeId,
  });
}

export function isLearningPathPageDomainData(
  value: unknown,
): value is LearningPathPageDomainData {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<LearningPathPageDomainData>;
  return (
    typeof candidate.source === "object"
    && candidate.source !== null
    && typeof candidate.runtimeBundle === "object"
    && candidate.runtimeBundle !== null
    && Array.isArray(candidate.specialZones)
    && typeof candidate.actionRegistry === "object"
    && candidate.actionRegistry !== null
    && Array.isArray(candidate.goalNodeIds)
    && typeof candidate.primaryGoalNodeId === "string"
  );
}

function toRuntimeNode(node: CompiledLearningPathNode): LearningPathNode {
  return Object.freeze({
    id: node.id,
    navigationOrder: node.navigationOrder,
    label: node.label,
    position: Object.freeze({ ...node.position }),
    initiallyGreen: node.initiallyGreen,
    initiallyVisible: node.initiallyVisible,
    completionPolicy: node.completionPolicy,
    ...(node.activationGroupId ? { activationGroupId: node.activationGroupId } : {}),
    surfaceY: node.surfaceY,
    variant: node.variant,
  });
}

function toRuntimeEdge(edge: CompiledLearningPathEdge): StraightLearningPathEdge {
  return Object.freeze({
    id: edge.id,
    fromNodeId: edge.fromNodeId,
    toNodeId: edge.toNodeId,
    pathKind: "straight",
    initiallyVisible: edge.initiallyVisible,
    completionPolicy: edge.completionPolicy,
    ...(edge.activationGroupId ? { activationGroupId: edge.activationGroupId } : {}),
  });
}

function adaptConceptZone(
  conceptZone: CompiledConceptZone,
  allNodes: readonly CompiledLearningPathNode[],
  usedEdgeIds: ReadonlySet<string>,
  usedPhysicalPairKeys: ReadonlySet<string>,
): {
  readonly zone: SpecialPathZoneSpec;
  readonly sessionEntryStraightEdge: StraightLearningPathEdge | null;
} {
  const activationNode = requireNode(
    allNodes,
    conceptZone.activationSubjectNodeId,
    `Concept zone "${conceptZone.id}" activation`,
  );
  const entryNode = requireNode(
    allNodes,
    conceptZone.entryConnection.toConceptNodeId,
    `Concept zone "${conceptZone.id}" entry`,
  );
  const pairKey = nodePairKey(activationNode.id, entryNode.id);
  if (usedPhysicalPairKeys.has(pairKey)) {
    throw new Error(
      `Concept zone "${conceptZone.id}" entry duplicates physical pair "${pairKey}".`,
    );
  }

  let entryConnection: ZoneEntryConnectionSpec;
  let sessionEntryStraightEdge: StraightLearningPathEdge | null = null;
  if (conceptZone.entryConnection.preferredPathKind === "overpass") {
    entryConnection = Object.freeze({
      activationNodeId: activationNode.id,
      kind: "overpass" as const,
    });
  } else {
    const edgeId = createUniqueSessionEdgeId(
      conceptZone.id,
      activationNode.id,
      entryNode.id,
      usedEdgeIds,
    );
    entryConnection = Object.freeze({
      activationNodeId: activationNode.id,
      kind: "straight-edge" as const,
      edgeId,
    });
    sessionEntryStraightEdge = Object.freeze({
      id: edgeId,
      fromNodeId: activationNode.id,
      toNodeId: entryNode.id,
      pathKind: "straight" as const,
      initiallyVisible: false,
      completionPolicy: "preserve-variant" as const,
      activationGroupId: conceptZone.id,
    });
  }

  const revealSequence: readonly SpecialRevealStep[] = Object.freeze([
    Object.freeze({ kind: "session-entry-connector" as const }),
    ...conceptZone.revealOrder.map((step): SpecialRevealStep => (
      step.kind === "node"
        ? Object.freeze({ kind: "node" as const, nodeId: step.id })
        : Object.freeze({ kind: "straight-edge" as const, edgeId: step.id })
    )),
  ]);

  return Object.freeze({
    zone: Object.freeze({
      id: conceptZone.id,
      activationNodeIds: Object.freeze([conceptZone.activationSubjectNodeId]),
      entryNodeId: conceptZone.entryConnection.toConceptNodeId,
      memberNodeIds: Object.freeze([...conceptZone.memberConceptNodeIds]),
      memberStraightEdgeIds: Object.freeze([...conceptZone.memberEdgeIds]),
      entryConnections: Object.freeze([entryConnection]),
      revealSequence,
      entryConnectorRevealPolicy: "first",
      activationTrigger: "idle-at-any-activation-node",
      unlockPolicy: "repeatable-session",
      retention: "retain-inside-session-envelope",
      externalBridgeReplacement: "retire-entry-overpass-before-ensure",
      dismissalTrigger: "departure-from-session-envelope",
      dismissalBridgeOrder: "entry-left-to-right-preclear",
      dismissalConstructOrder: "reverse-reveal-right-to-left",
      lockHiddenMembersAfterDismissal: true,
      // A learning subject owns an ordered concept chain. Selecting a later
      // concept must not skip the adjacent first concept by inventing a direct
      // overpass; the character enters once and continues over the ground
      // roads that communicate that learning order.
      activationMemberRoutingPolicy: "entry-then-existing-chain",
      recomputeRemainingHopsAtEntry: true,
      retainEntryConnectorDuringMemberRoutes: true,
      memberDynamicBridgeLifetime: "retire-at-physical-arrival",
      retainedEntryOverpassCountsTowardOrdinaryLimit: false,
      entryConnectorAffectsAuthoredHopDistance: false,
    }),
    sessionEntryStraightEdge,
  });
}

function createInitialRevealOrder(
  source: CompiledLearningPath,
): readonly PathRevealStep[] {
  const visibleNodes = source.nodes.filter((node) => (
    node.entityKind === "subject" && node.initiallyVisible
  ));
  const visibleNodeIds = new Set(visibleNodes.map((node) => node.id));
  const visibleEdges = source.edges.filter((edge) => (
    (edge.sourceKind === "subject-flow" || edge.sourceKind === "parallel-peer")
    && edge.initiallyVisible
    && visibleNodeIds.has(edge.fromNodeId)
    && visibleNodeIds.has(edge.toNodeId)
  ));
  const dependencyEdges = visibleEdges.filter((edge) => edge.sourceKind === "subject-flow");
  const outgoing = new Map<NodeId, CompiledLearningPathEdge[]>();
  const indegree = new Map<NodeId, number>(
    visibleNodes.map((node) => [node.id, 0] as const),
  );
  for (const edge of dependencyEdges) {
    const list = outgoing.get(edge.fromNodeId) ?? [];
    list.push(edge);
    outgoing.set(edge.fromNodeId, list);
    indegree.set(edge.toNodeId, (indegree.get(edge.toNodeId) ?? 0) + 1);
  }
  for (const list of outgoing.values()) list.sort(compareCompiledEdges);

  const nodeById = new Map(visibleNodes.map((node) => [node.id, node] as const));
  const queue = visibleNodes
    .filter((node) => indegree.get(node.id) === 0)
    .sort((left, right) => compareRevealNodes(left, right, source.initialNodeId));
  const revealedNodeIds = new Set<NodeId>();
  const revealedEdgeIds = new Set<string>();
  const result: PathRevealStep[] = [];

  while (queue.length > 0) {
    const node = queue.shift();
    if (!node) break;
    result.push(Object.freeze({ kind: "node" as const, nodeId: node.id }));
    revealedNodeIds.add(node.id);

    const nowRevealable = visibleEdges
      .filter((edge) => (
        !revealedEdgeIds.has(edge.id)
        && revealedNodeIds.has(edge.fromNodeId)
        && revealedNodeIds.has(edge.toNodeId)
      ))
      .sort(compareCompiledEdges);
    for (const edge of nowRevealable) {
      result.push(Object.freeze({
        kind: "edge" as const,
        edgeId: edge.id,
        fromNodeId: edge.fromNodeId,
        toNodeId: edge.toNodeId,
      }));
      revealedEdgeIds.add(edge.id);
    }

    for (const edge of outgoing.get(node.id) ?? []) {
      const nextDegree = (indegree.get(edge.toNodeId) ?? 0) - 1;
      indegree.set(edge.toNodeId, nextDegree);
      if (nextDegree === 0) {
        const nextNode = nodeById.get(edge.toNodeId);
        if (nextNode) {
          insertSorted(queue, nextNode, (left, right) => (
            compareRevealNodes(left, right, source.initialNodeId)
          ));
        }
      }
    }
  }

  if (result[0]?.kind !== "node" || result[0].nodeId !== source.initialNodeId) {
    throw new Error(
      `Initial reveal order cannot start at compiled entry "${source.initialNodeId}".`,
    );
  }
  if (revealedNodeIds.size !== visibleNodes.length) {
    throw new Error("Initial subject flow is cyclic or disconnected from its entry node.");
  }
  if (revealedEdgeIds.size !== visibleEdges.length) {
    throw new Error("Initial subject reveal omitted one or more visible flow edges.");
  }
  return Object.freeze(result);
}

function createLearningPathActionRegistry(
  source: CompiledLearningPath,
): LearningPathActionRegistry {
  const entries = source.nodes.flatMap((node) => (
    node.action
      ? [[node.id, Object.freeze({
          nodeId: node.id,
          action: node.action,
          resource: node.action.resource,
        })] as const]
      : []
  ));
  const actionByNodeId = new Map<NodeId, LearningPathActionBinding>(entries);
  const resourceByActionId = new Map(
    entries.map(([, binding]) => [binding.action.id, binding.resource] as const),
  );
  return Object.freeze({
    actionByNodeId,
    resourceByActionId,
    getAction: (nodeId: NodeId | null) => (
      nodeId === null ? null : actionByNodeId.get(nodeId) ?? null
    ),
  });
}

function resolvePrimaryGoalNodeId(
  source: CompiledLearningPath,
  requestedGoalNodeId: NodeId | undefined,
): NodeId {
  if (requestedGoalNodeId !== undefined) {
    if (!source.goalNodeIds.includes(requestedGoalNodeId)) {
      throw new Error(`Requested primary goal "${requestedGoalNodeId}" is not a compiled goal.`);
    }
    return requestedGoalNodeId;
  }
  const goals = source.goalNodeIds
    .map((nodeId) => requireNode(source.nodes, nodeId, "Compiled goal"))
    .sort(compareRuntimeNodes);
  const first = goals[0];
  if (!first) throw new Error("Compiled learning path must declare at least one goal node.");
  return first.id;
}

function resolveRevision(source: CompiledLearningPath, requested: string | undefined): string {
  if (requested !== undefined) {
    const revision = requested.trim();
    if (revision.length === 0) throw new Error("Learning path revision cannot be empty.");
    return revision;
  }
  const fingerprintSource = [
    source.protocol,
    source.version,
    source.sourceDocumentId,
    source.initialNodeId,
    ...source.nodes.flatMap((node) => [
      node.id,
      node.entityKind,
      String(node.navigationOrder),
      String(node.position.x),
      String(node.position.z),
      node.card.title,
      node.action?.id ?? "",
      node.action?.resource.id ?? "",
    ]),
    ...source.edges.flatMap((edge) => [
      edge.id,
      edge.fromNodeId,
      edge.toNodeId,
      edge.sourceKind,
    ]),
  ].join("\u001f");
  return `${source.sourceDocumentId}@${source.version}-${fnv1a(fingerprintSource)}`;
}

function fnv1a(value: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function createUniqueSessionEdgeId(
  zoneId: string,
  activationNodeId: NodeId,
  entryNodeId: NodeId,
  usedIds: ReadonlySet<string>,
): string {
  const base = `session-entry:${encodeURIComponent(zoneId)}:${encodeURIComponent(activationNodeId)}:${encodeURIComponent(entryNodeId)}`;
  if (!usedIds.has(base)) return base;
  let suffix = 2;
  while (usedIds.has(`${base}:${suffix}`)) suffix += 1;
  return `${base}:${suffix}`;
}

function requireNode(
  nodes: readonly CompiledLearningPathNode[],
  nodeId: NodeId,
  context: string,
): CompiledLearningPathNode {
  const node = nodes.find((candidate) => candidate.id === nodeId);
  if (!node) throw new Error(`${context} references missing node "${nodeId}".`);
  return node;
}

function compareRevealNodes(
  left: CompiledLearningPathNode,
  right: CompiledLearningPathNode,
  initialNodeId: NodeId,
): number {
  if (left.id === initialNodeId) return right.id === initialNodeId ? 0 : -1;
  if (right.id === initialNodeId) return 1;
  return compareRuntimeNodes(left, right);
}

function compareRuntimeNodes(
  left: CompiledLearningPathNode,
  right: CompiledLearningPathNode,
): number {
  return left.navigationOrder - right.navigationOrder || compareStrings(left.id, right.id);
}

function compareCompiledEdges(
  left: CompiledLearningPathEdge,
  right: CompiledLearningPathEdge,
): number {
  return compareStrings(left.id, right.id);
}

function insertSorted<T>(
  values: T[],
  value: T,
  compare: (left: T, right: T) => number,
): void {
  let index = 0;
  while (index < values.length && compare(values[index]!, value) <= 0) index += 1;
  values.splice(index, 0, value);
}

function nodePairKey(first: NodeId, second: NodeId): string {
  return compareStrings(first, second) <= 0
    ? `${first}\u001f${second}`
    : `${second}\u001f${first}`;
}

function compareStrings(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}
