import type { LearningEntityId } from "../../content";
import type {
  ConceptProgressStatus,
  LearningProgressContext,
  SubjectProgressStatus,
} from "../domain/types";

export const LEARNING_PROGRESS_PERSISTENCE_SCHEMA = "learning-progress" as const;
export const LEARNING_PROGRESS_PERSISTENCE_VERSION = 2 as const;

export interface LearningProgressPersistenceV1 {
  readonly schema: typeof LEARNING_PROGRESS_PERSISTENCE_SCHEMA;
  readonly version: 1;
  readonly pathRevision: string;
  readonly lastSafeNodeId: LearningEntityId;
  readonly subjectStatusById: Readonly<Record<LearningEntityId, SubjectProgressStatus>>;
  readonly conceptStatusById: Readonly<Record<LearningEntityId, ConceptProgressStatus>>;
  /** V1 encoded visits as a sparse boolean record. */
  readonly visitedNodeIds: Readonly<Record<LearningEntityId, true>>;
  readonly celebrationSeen: boolean;
  readonly celebrationCount: number;
}

export interface LearningProgressPersistenceV2 {
  readonly schema: typeof LEARNING_PROGRESS_PERSISTENCE_SCHEMA;
  readonly version: typeof LEARNING_PROGRESS_PERSISTENCE_VERSION;
  readonly pathRevision: string;
  readonly lastSafeNodeId: LearningEntityId;
  readonly subjectStatusById: Readonly<Record<LearningEntityId, SubjectProgressStatus>>;
  readonly conceptStatusById: Readonly<Record<LearningEntityId, ConceptProgressStatus>>;
  /** V2 uses a stable, duplicate-free list rather than serializing a lookup table. */
  readonly visitedNodeIds: readonly LearningEntityId[];
  readonly celebrationSeen: boolean;
  readonly celebrationCount: number;
}

export type LearningProgressPersistenceDocument =
  | LearningProgressPersistenceV1
  | LearningProgressPersistenceV2;

export interface SerializeLearningProgressOptions {
  readonly pathRevision: string;
  /**
   * The last node acknowledged as safe by the journey/recovery owner. Never
   * infer this from a possibly moving actor snapshot.
   */
  readonly lastSafeNodeId: LearningEntityId;
}

export type LearningProgressMigrationFailureReason =
  | "invalid-document"
  | "unknown-version";

export type LearningProgressMigrationResult =
  | {
      readonly ok: true;
      readonly document: LearningProgressPersistenceV2;
      readonly migratedFromVersion: 1 | null;
    }
  | {
      readonly ok: false;
      readonly reason: LearningProgressMigrationFailureReason;
    };

export interface RestoreLearningProgressOptions {
  readonly pathRevision: string;
  /** A freshly-created context for the currently compiled path. */
  readonly fallbackContext: LearningProgressContext;
  /** Optional recovery-owned safe node for an invalid persistence payload. */
  readonly fallbackSafeNodeId?: LearningEntityId;
}

export type LearningProgressRestoreFailureReason =
  | "empty"
  | "corrupt-json"
  | LearningProgressMigrationFailureReason
  | "path-revision-mismatch"
  | "path-shape-mismatch";

export type LearningProgressRestoreResult =
  | {
      readonly status: "restored";
      readonly context: LearningProgressContext;
      readonly document: LearningProgressPersistenceV2;
      readonly migratedFromVersion: 1 | null;
    }
  | {
      readonly status: "fallback";
      readonly context: LearningProgressContext;
      readonly reason: LearningProgressRestoreFailureReason;
    };

