import type { LearningEntityId } from "../../content";
import { freezeRecord } from "./policies";
import type { LearningProgressMachineSnapshot } from "./progressActor";
import type {
  CatchUpResult,
  LearningNodeProgressStatus,
  LearningProgressContext,
  LearningProgressViewSnapshot,
  NavigationDecision,
  NodeLearningState,
} from "./types";

function readContext(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
): LearningProgressContext {
  return "context" in source ? source.context : source;
}

/** Produces a detached immutable snapshot safe to hand to any UI adapter. */
export function selectLearningProgressView(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
): LearningProgressViewSnapshot {
  const context = readContext(source);
  const nodeStatusById = Object.freeze({
    ...context.subjectStatusById,
    ...context.conceptStatusById,
  });
  const goalIds = new Set(context.goalNodeIds);
  const nodeLearningStateById: Record<LearningEntityId, NodeLearningState> = {};
  for (const [nodeId, status] of Object.entries(context.subjectStatusById)) {
    nodeLearningStateById[nodeId] = Object.freeze({
      kind: goalIds.has(nodeId) ? "goal" : "subject",
      status,
    });
  }
  for (const [nodeId, status] of Object.entries(context.conceptStatusById)) {
    nodeLearningStateById[nodeId] = Object.freeze({ kind: "concept", status });
  }
  return Object.freeze({
    currentNodeId: context.currentNodeId,
    nodeStatusById,
    nodeLearningStateById: Object.freeze(nodeLearningStateById),
    subjectStatusById: freezeRecord({ ...context.subjectStatusById }),
    conceptStatusById: freezeRecord({ ...context.conceptStatusById }),
    celebration: Object.freeze({
      seen: context.celebrationSeen,
      count: context.celebrationCount,
    }),
    lastNavigationDecision: context.lastNavigationDecision,
    lastCatchUpResult: context.lastCatchUpResult,
    lastConceptAction: context.lastConceptAction,
    pendingLearningIntent: context.pendingLearningIntent,
    lastLearningLaunch: context.lastLearningLaunch,
    pendingUnlockCommit: context.pendingUnlockCommit,
    lastMovementCancellation: context.lastMovementCancellation,
    lastRejection: context.lastRejection,
  });
}

export function selectNodeProgressStatus(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
  nodeId: LearningEntityId,
): LearningNodeProgressStatus | null {
  const context = readContext(source);
  return context.subjectStatusById[nodeId] ?? context.conceptStatusById[nodeId] ?? null;
}

export function selectCanNavigateTo(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
  nodeId: LearningEntityId,
): boolean {
  const status = selectNodeProgressStatus(source, nodeId);
  return status !== null && status !== "locked";
}

export function selectLastNavigationDecision(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
): NavigationDecision | null {
  return readContext(source).lastNavigationDecision;
}

export function selectLastCatchUpResult(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
): CatchUpResult | null {
  return readContext(source).lastCatchUpResult;
}

export function selectNodeLearningState(
  source: LearningProgressContext | LearningProgressMachineSnapshot,
  nodeId: LearningEntityId,
): NodeLearningState | null {
  const context = readContext(source);
  const conceptStatus = context.conceptStatusById[nodeId];
  if (conceptStatus) return Object.freeze({ kind: "concept", status: conceptStatus });
  const subjectStatus = context.subjectStatusById[nodeId];
  if (!subjectStatus) return null;
  return Object.freeze({
    kind: context.goalNodeIds.includes(nodeId) ? "goal" : "subject",
    status: subjectStatus,
  });
}
