import {
  COMPLETION_CELEBRATION_EVENT,
  type CompletionCelebrationSettledDetail,
  type CompletionCelebrationViewModel,
} from "./ContextualCardContracts";

const STYLE_ATTRIBUTE = "data-learning-path-celebration-styles";
const styleRegistry = new WeakMap<Document, { element: HTMLStyleElement; owners: number }>();
const CONFETTI_COLORS = ["#ffd33d", "#42d66b", "#ffffff", "#d78224", "#73c8ff"] as const;
const CONFETTI_COUNT = 26;

const STYLES = `
[data-learning-path-root] .lp-completion-celebration {
  position: absolute;
  z-index: 20;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  pointer-events: none;
  font-family: Inter, ui-rounded, "SF Pro Rounded", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
}
[data-learning-path-root] .lp-completion-celebration[hidden] { display: none; }
[data-learning-path-root] .lp-completion-celebration__halo {
  position: absolute;
  width: min(66%, 570px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, rgb(255 215 59 / 26%), rgb(255 215 59 / 7%) 43%, transparent 69%);
  opacity: 0;
}
[data-learning-path-root] .lp-completion-celebration__message {
  position: relative;
  max-width: min(470px, calc(100% - 32px));
  border: 1px solid rgb(255 255 255 / 86%);
  border-radius: 24px;
  padding: 22px 27px 24px;
  color: #27352c;
  background: rgb(255 255 255 / 92%);
  box-shadow: 0 22px 60px rgb(42 66 49 / 20%), 0 7px 0 rgb(223 229 224 / 92%);
  opacity: 0;
  text-align: center;
  backdrop-filter: blur(18px) saturate(1.08);
}
[data-learning-path-root] .lp-completion-celebration__mark {
  display: grid;
  width: 58px;
  height: 58px;
  margin: -51px auto 12px;
  place-items: center;
  border: 5px solid #fff;
  border-radius: 50%;
  color: #fff;
  background: linear-gradient(180deg, #48d96e, #21af4d);
  box-shadow: 0 7px 0 #12883a, 0 12px 22px rgb(25 138 62 / 28%);
  font-size: 30px;
  font-weight: 900;
}
[data-learning-path-root] .lp-completion-celebration__title { margin: 0; font-size: clamp(25px, 4cqw, 38px); font-weight: 900; letter-spacing: -.035em; line-height: 1.13; }
[data-learning-path-root] .lp-completion-celebration__body { margin: 9px 0 0; color: #667168; font-size: 14px; font-weight: 620; line-height: 1.55; }
[data-learning-path-root] .lp-completion-celebration__body[hidden] { display: none; }
[data-learning-path-root] .lp-completion-celebration__confetti {
  position: absolute;
  top: -8cqh;
  left: var(--lp-confetti-x);
  width: var(--lp-confetti-w);
  height: var(--lp-confetti-h);
  border-radius: 2px;
  background: var(--lp-confetti-color);
  opacity: 0;
  transform: translate3d(0, -8cqh, 0) rotate(var(--lp-confetti-turn));
}
[data-learning-path-root] .lp-completion-celebration[data-active="true"] .lp-completion-celebration__halo { animation: lp-celebration-halo 1450ms cubic-bezier(.16,.8,.24,1) both; }
[data-learning-path-root] .lp-completion-celebration[data-active="true"] .lp-completion-celebration__message { animation: lp-celebration-message 1700ms cubic-bezier(.16,.82,.24,1) both; }
[data-learning-path-root] .lp-completion-celebration[data-active="true"] .lp-completion-celebration__confetti { animation: lp-celebration-confetti 1540ms cubic-bezier(.18,.72,.28,1) var(--lp-confetti-delay) both; }
@keyframes lp-celebration-halo {
  0% { opacity: 0; transform: scale(.35); }
  27% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.22); }
}
@keyframes lp-celebration-message {
  0% { opacity: 0; transform: translate3d(0, 18px, 0) scale(.84); }
  18%, 76% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
  100% { opacity: 0; transform: translate3d(0, -9px, 0) scale(.985); }
}
@keyframes lp-celebration-confetti {
  0% { opacity: 0; transform: translate3d(0, -8cqh, 0) rotate(0); }
  9% { opacity: 1; }
  100% { opacity: 0; transform: translate3d(var(--lp-confetti-drift), 112cqh, 0) rotate(var(--lp-confetti-spin)); }
}
[data-learning-path-root] .lp-completion-celebration[data-reduced-motion="true"] .lp-completion-celebration__confetti { display: none; }
[data-learning-path-root] .lp-completion-celebration[data-reduced-motion="true"][data-active="true"] .lp-completion-celebration__halo { animation: lp-celebration-halo-reduced 700ms ease-out both; }
[data-learning-path-root] .lp-completion-celebration[data-reduced-motion="true"][data-active="true"] .lp-completion-celebration__message { animation: lp-celebration-message-reduced 700ms ease-out both; }
@keyframes lp-celebration-halo-reduced { 0%, 100% { opacity: 0; } 20%, 80% { opacity: .65; } }
@keyframes lp-celebration-message-reduced { 0%, 100% { opacity: 0; } 14%, 82% { opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  [data-learning-path-root] .lp-completion-celebration__confetti { display: none; }
  [data-learning-path-root] .lp-completion-celebration[data-active="true"] .lp-completion-celebration__halo { animation: lp-celebration-halo-reduced 700ms ease-out both; }
  [data-learning-path-root] .lp-completion-celebration[data-active="true"] .lp-completion-celebration__message { animation: lp-celebration-message-reduced 700ms ease-out both; }
}
`;

export interface CompletionCelebrationViewOptions {
  readonly onSettled?: (detail: CompletionCelebrationSettledDetail) => void;
}

export class CompletionCelebrationView {
  private readonly document: Document;
  private readonly root: HTMLDivElement;
  private readonly title: HTMLHeadingElement;
  private readonly message: HTMLParagraphElement;
  private readonly releaseStyles: () => void;
  private readonly onSettled?: (detail: CompletionCelebrationSettledDetail) => void;
  private lastPlayCount = -1;
  private activePlayCount = -1;
  private activationFrame = 0;
  private settleTimer = 0;
  private disposed = false;

  public constructor(mount: HTMLElement, options: CompletionCelebrationViewOptions = {}) {
    this.document = mount.ownerDocument;
    this.releaseStyles = acquireStyles(this.document);
    this.onSettled = options.onSettled;
    this.root = this.document.createElement("div");
    this.root.className = "lp-completion-celebration";
    this.root.hidden = true;
    this.root.setAttribute("role", "status");
    this.root.setAttribute("aria-live", "assertive");
    this.root.setAttribute("aria-atomic", "true");

    const halo = this.document.createElement("div");
    halo.className = "lp-completion-celebration__halo";
    halo.setAttribute("aria-hidden", "true");
    const copy = this.document.createElement("section");
    copy.className = "lp-completion-celebration__message";
    const mark = this.document.createElement("span");
    mark.className = "lp-completion-celebration__mark";
    mark.textContent = "✓";
    mark.setAttribute("aria-hidden", "true");
    this.title = this.document.createElement("h2");
    this.title.className = "lp-completion-celebration__title";
    this.message = this.document.createElement("p");
    this.message.className = "lp-completion-celebration__body";
    copy.append(mark, this.title, this.message);
    this.root.append(halo, ...this.createConfetti(), copy);
    mount.append(this.root);
  }

  public setViewModel(viewModel: CompletionCelebrationViewModel | null): void {
    if (this.disposed) return;
    if (viewModel === null || viewModel.visible === false) {
      this.hide();
      return;
    }
    if (!Number.isSafeInteger(viewModel.playCount) || viewModel.playCount < 0) return;
    if (viewModel.playCount <= this.lastPlayCount) return;

    this.lastPlayCount = viewModel.playCount;
    this.activePlayCount = viewModel.playCount;
    this.title.textContent = viewModel.title;
    const message = viewModel.message?.trim() ?? "";
    this.message.textContent = message;
    this.message.hidden = message.length === 0;
    const mediaReduced = this.document.defaultView
      ?.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
    const reducedMotion = viewModel.reducedMotion === true || mediaReduced;
    this.root.dataset.reducedMotion = String(reducedMotion);
    this.root.dataset.playCount = String(viewModel.playCount);
    this.root.hidden = false;
    this.root.removeAttribute("data-active");
    this.clearPlaybackHandles();

    const window = this.document.defaultView;
    if (!window) {
      this.root.dataset.active = "true";
      return;
    }
    this.activationFrame = window.requestAnimationFrame(() => {
      this.activationFrame = 0;
      if (!this.disposed && !this.root.hidden) this.root.dataset.active = "true";
    });
    this.settleTimer = window.setTimeout(
      () => this.settle(viewModel.playCount),
      reducedMotion ? 740 : 1900,
    );
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.clearPlaybackHandles();
    this.root.remove();
    this.releaseStyles();
  }

  private createConfetti(): HTMLElement[] {
    const pieces: HTMLElement[] = [];
    for (let index = 0; index < CONFETTI_COUNT; index += 1) {
      const piece = this.document.createElement("i");
      piece.className = "lp-completion-celebration__confetti";
      piece.setAttribute("aria-hidden", "true");
      piece.style.setProperty("--lp-confetti-x", `${3 + ((index * 37) % 94)}%`);
      piece.style.setProperty("--lp-confetti-w", `${6 + (index % 4) * 2}px`);
      piece.style.setProperty("--lp-confetti-h", `${10 + (index % 3) * 3}px`);
      piece.style.setProperty("--lp-confetti-color", CONFETTI_COLORS[index % CONFETTI_COLORS.length] ?? "#fff");
      piece.style.setProperty("--lp-confetti-delay", `${(index % 7) * 26}ms`);
      piece.style.setProperty("--lp-confetti-drift", `${-84 + ((index * 53) % 168)}px`);
      piece.style.setProperty("--lp-confetti-turn", `${(index * 31) % 180}deg`);
      piece.style.setProperty("--lp-confetti-spin", `${440 + (index % 6) * 126}deg`);
      pieces.push(piece);
    }
    return pieces;
  }

  private settle(playCount: number): void {
    if (this.disposed || playCount !== this.activePlayCount) return;
    this.settleTimer = 0;
    this.root.hidden = true;
    this.root.removeAttribute("data-active");
    const detail: CompletionCelebrationSettledDetail = Object.freeze({
      type: "completion-celebration.settled",
      playCount,
      occurredAt: this.document.defaultView?.performance.now() ?? Date.now(),
    });
    const CustomEventConstructor = this.document.defaultView?.CustomEvent ?? CustomEvent;
    this.root.dispatchEvent(new CustomEventConstructor<CompletionCelebrationSettledDetail>(
      COMPLETION_CELEBRATION_EVENT.settled,
      { bubbles: true, composed: true, detail },
    ));
    this.onSettled?.(detail);
  }

  private hide(): void {
    this.clearPlaybackHandles();
    this.activePlayCount = -1;
    this.root.hidden = true;
    this.root.removeAttribute("data-active");
  }

  private clearPlaybackHandles(): void {
    const window = this.document.defaultView;
    if (this.activationFrame) window?.cancelAnimationFrame(this.activationFrame);
    if (this.settleTimer) window?.clearTimeout(this.settleTimer);
    this.activationFrame = 0;
    this.settleTimer = 0;
  }
}

function acquireStyles(document: Document): () => void {
  const existing = styleRegistry.get(document);
  if (existing) {
    existing.owners += 1;
    return () => releaseStyles(document);
  }
  const element = document.createElement("style");
  element.setAttribute(STYLE_ATTRIBUTE, "");
  element.textContent = STYLES;
  (document.head ?? document.documentElement).append(element);
  styleRegistry.set(document, { element, owners: 1 });
  return () => releaseStyles(document);
}

function releaseStyles(document: Document): void {
  const entry = styleRegistry.get(document);
  if (!entry) return;
  entry.owners -= 1;
  if (entry.owners > 0) return;
  entry.element.remove();
  styleRegistry.delete(document);
}
