export const LEARNING_PATH_HOST_CONFIG_KEY = "__LEARNING_PATH_PAGE_CONFIG__" as const;
export const LEARNING_PATH_HOST_PROTOCOL = "learning-path-page" as const;
export const LEARNING_PATH_HOST_VERSION = "1.0" as const;

export interface LearningPathDocumentProviderContext {
  readonly signal: AbortSignal;
}

export type LearningPathDocumentProvider = (
  context: LearningPathDocumentProviderContext,
) => unknown | Promise<unknown>;

interface LearningPathBootstrapBaseOptions {
  /** Cross-origin JSON stays blocked unless a trusted programmatic embedder opts in. */
  readonly allowedDocumentOrigins?: readonly string[];
}

/** Exactly one explicit source is accepted. With none, window injection then the bundled JSON are used. */
export type LearningPathBootstrapOptions = LearningPathBootstrapBaseOptions & (
  | {
      readonly document: unknown;
      readonly documentUrl?: never;
      readonly documentProvider?: never;
    }
  | {
      readonly document?: never;
      readonly documentUrl: string;
      readonly documentProvider?: never;
    }
  | {
      readonly document?: never;
      readonly documentUrl?: never;
      readonly documentProvider: LearningPathDocumentProvider;
    }
  | {
      readonly document?: never;
      readonly documentUrl?: never;
      readonly documentProvider?: never;
    }
);

export interface LearningPathWindowHostConfig {
  readonly protocol: typeof LEARNING_PATH_HOST_PROTOCOL;
  readonly version: typeof LEARNING_PATH_HOST_VERSION;
  readonly source:
    | { readonly kind: "document"; readonly document: unknown }
    | { readonly kind: "url"; readonly documentUrl: string };
}

export interface LearningPathTemplateLoadContext {
  readonly signal: AbortSignal;
  readonly baseUrl: string;
  readonly defaultDocumentUrl: string;
  readonly fetcher?: typeof fetch;
}

declare global {
  interface Window {
    /** Data-only host contract. Callbacks are intentionally excluded. */
    __LEARNING_PATH_PAGE_CONFIG__?: LearningPathWindowHostConfig;
  }
}
