import type { LearningEntityId } from "../../content";
import type { PendingUnlockCommit } from "./types";

/**
 * Creates the minimal durable mutation contract after Journey has accepted a
 * plan. Route, reached nodes and lifecycle phase deliberately remain in
 * Journey and are never copied into Progress.
 */
export function createPendingUnlockCommit(input: {
  readonly targetNodeId: LearningEntityId;
  readonly transactionId: string;
  readonly requiredCompletionNodeIds: readonly LearningEntityId[];
}): PendingUnlockCommit {
  const transactionId = input.transactionId.trim();
  if (transactionId.length === 0) {
    throw new TypeError("Pending unlock commit requires a non-empty Journey transaction id.");
  }
  return Object.freeze({
    targetNodeId: input.targetNodeId,
    transactionId,
    requiredCompletionNodeIds: Object.freeze([...input.requiredCompletionNodeIds]),
  });
}
