import type {
  ContextualCardLayoutMetrics,
  ContextualCardPlacement,
} from "../ContextualCardContracts";
import {
  type NodeOverlayAnchorProjection,
  type NodeOverlayViewportRect,
} from "../NodeOverlayAnchorProjector";
import {
  computeCardSafeAreaHorizontalOffset,
  computeCardSafeAreaLift,
} from "./cardPlacementPolicy";

export interface NodeCardPlacementViewPort {
  setCardPlacement(placement: ContextualCardPlacement | null): void;
  getCardLayoutMetrics(): ContextualCardLayoutMetrics;
}

export interface NodeCardOverlayComposition {
  readonly horizontalOffsetPixels: number;
  readonly verticalOffsetPixels: number;
}

export interface NodeCardOverlayCompositionUpdate {
  readonly horizontalOffsetPixels: number;
  readonly verticalOffsetPixels: number;
  readonly fovBonusDegrees: number;
}

/**
 * Narrow render-boundary contract used by the DOM card layer. The owner of
 * the Three.js scene performs projection and composition internally, so this
 * controller never receives a camera, scene graph, or node lookup.
 */
export interface NodeCardOverlayPort {
  projectNodeAnchor(
    nodeId: string,
    viewportRect: NodeOverlayViewportRect,
  ): NodeOverlayAnchorProjection | null;
  getOverlayComposition(): NodeCardOverlayComposition;
  setOverlayComposition(
    update: NodeCardOverlayCompositionUpdate,
    reducedMotion?: boolean,
  ): void;
}

export interface NodeCardPlacementContext {
  readonly overlay: NodeCardOverlayPort;
  readonly reducedMotion: boolean;
}

export interface AnimationFrameScheduler {
  requestAnimationFrame(callback: FrameRequestCallback): number;
  cancelAnimationFrame(handle: number): void;
  addEventListener(type: "resize", listener: EventListener): void;
  removeEventListener(type: "resize", listener: EventListener): void;
}

export interface NodeCardPlacementControllerOptions {
  readonly viewport: Pick<HTMLElement, "getBoundingClientRect" | "ownerDocument">;
  readonly view: NodeCardPlacementViewPort;
  readonly resolveContext: (nodeId: string) => NodeCardPlacementContext | null;
  readonly scheduler?: AnimationFrameScheduler;
}

/**
 * Owns the card-projection render task. No card means no animation frame: the
 * loop exists only while one node card is visible and is cancelled eagerly on
 * close, session reset, or disposal.
 */
export class NodeCardPlacementController {
  private readonly viewport: NodeCardPlacementControllerOptions["viewport"];
  private readonly view: NodeCardPlacementViewPort;
  private readonly resolveContext: NodeCardPlacementControllerOptions["resolveContext"];
  private readonly scheduler: AnimationFrameScheduler;
  private nodeId: string | null = null;
  private frameHandle = 0;
  private disposed = false;
  private lastOverlay: NodeCardOverlayPort | null = null;

  public constructor(options: NodeCardPlacementControllerOptions) {
    const scheduler = options.scheduler
      ?? options.viewport.ownerDocument.defaultView;
    if (!scheduler) throw new Error("Node-card placement requires a browser frame scheduler.");
    this.viewport = options.viewport;
    this.view = options.view;
    this.resolveContext = options.resolveContext;
    this.scheduler = scheduler;
    this.scheduler.addEventListener("resize", this.handleResize);
  }

  /** Replaces the active projection target. Passing null stops all future RAF work. */
  public setNodeId(nodeId: string | null): void {
    if (this.disposed) return;
    const normalized = nodeId?.trim() || null;
    if (this.nodeId === normalized) {
      if (normalized !== null) this.schedule();
      return;
    }
    this.nodeId = normalized;
    if (normalized === null) {
      this.cancelFrame();
      this.clearPlacement();
      return;
    }
    this.schedule();
  }

  /** Allows host adapters to coalesce known camera or layout changes. */
  public requestUpdate(): void {
    if (this.disposed || this.nodeId === null) return;
    this.schedule();
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.nodeId = null;
    this.scheduler.removeEventListener("resize", this.handleResize);
    this.cancelFrame();
    this.clearPlacement();
  }

  private readonly handleResize: EventListener = () => this.requestUpdate();

  private readonly update = (): void => {
    this.frameHandle = 0;
    if (this.disposed || this.nodeId === null) return;
    const nodeId = this.nodeId;
    const context = this.resolveContext(nodeId);
    if (!context) {
      this.nodeId = null;
      this.clearPlacement();
      return;
    }
    this.lastOverlay = context.overlay;
    const rect = this.viewport.getBoundingClientRect();
    const projection = context.overlay.projectNodeAnchor(nodeId, rect);
    this.view.setCardPlacement(projection?.visible ? {
      anchorClientX: projection.anchorClientX,
      anchorClientY: projection.anchorClientY,
      viewportRect: rect,
    } : null);
    this.applySafeArea(context, rect, projection);

    // Camera panning and the scene's eased composition offsets are imperative
    // render state. Keep projecting while the card exists, but never otherwise.
    if (!this.disposed && this.nodeId === nodeId) this.schedule();
  };

  private applySafeArea(
    context: NodeCardPlacementContext,
    rect: DOMRectReadOnly,
    projection: NodeOverlayAnchorProjection | null,
  ): void {
    const metrics = this.view.getCardLayoutMetrics();
    const overlay = context.overlay;
    const composition = overlay.getOverlayComposition();
    if (projection?.visible && metrics.visible && metrics.placed) {
      const horizontalOffset = computeCardSafeAreaHorizontalOffset({
        currentOffsetPixels: composition.horizontalOffsetPixels,
        cardLeftClientX: metrics.centerX - metrics.width / 2,
        cardRightClientX: metrics.centerX + metrics.width / 2,
        viewportLeftClientX: rect.left,
        viewportRightClientX: rect.right,
        maximumOffsetPixels: rect.width * 0.8,
      });
      const verticalOffset = computeCardSafeAreaLift({
        currentLiftPixels: composition.verticalOffsetPixels,
        cardBottomClientY: metrics.bottom,
        viewportBottomClientY: rect.bottom,
        maximumLiftPixels: rect.height * 0.72,
      });
      overlay.setOverlayComposition({
        horizontalOffsetPixels: horizontalOffset,
        verticalOffsetPixels: verticalOffset,
        fovBonusDegrees: 0,
      }, context.reducedMotion);
      return;
    }
    resetOverlayComposition(overlay, context.reducedMotion);
  }

  private schedule(): void {
    if (this.frameHandle !== 0 || this.disposed || this.nodeId === null) return;
    this.frameHandle = this.scheduler.requestAnimationFrame(this.update);
  }

  private cancelFrame(): void {
    if (this.frameHandle === 0) return;
    this.scheduler.cancelAnimationFrame(this.frameHandle);
    this.frameHandle = 0;
  }

  private clearPlacement(): void {
    this.view.setCardPlacement(null);
    if (this.lastOverlay) resetOverlayComposition(this.lastOverlay, false);
    this.lastOverlay = null;
  }
}

function resetOverlayComposition(
  overlay: NodeCardOverlayPort,
  reducedMotion: boolean,
): void {
  overlay.setOverlayComposition({
    horizontalOffsetPixels: 0,
    verticalOffsetPixels: 0,
    fovBonusDegrees: 0,
  }, reducedMotion);
}
