import type { CompletionCelebrationMachineSnapshot } from "./machine";
import type {
  CompletionCelebrationPhase,
  CompletionCelebrationViewSnapshot,
} from "./types";

const PHASES: readonly CompletionCelebrationPhase[] = Object.freeze([
  "hidden",
  "showing",
  "acknowledged",
]);

export function selectCompletionCelebrationPhase(
  snapshot: CompletionCelebrationMachineSnapshot,
): CompletionCelebrationPhase {
  return PHASES.find((phase) => snapshot.matches(phase)) ?? "hidden";
}

export function selectCompletionCelebrationVisible(
  snapshot: CompletionCelebrationMachineSnapshot,
): boolean {
  return snapshot.matches("showing");
}

export function selectCompletionCelebrationView(
  snapshot: CompletionCelebrationMachineSnapshot,
): CompletionCelebrationViewSnapshot {
  const phase = selectCompletionCelebrationPhase(snapshot);
  return Object.freeze({
    phase,
    visible: phase === "showing",
    activeCount: snapshot.context.activeCount,
    acknowledgedCount: snapshot.context.acknowledgedCount,
  });
}
