import {
  LearningProgressStorageError,
  type LearningProgressStorageOperationOptions,
  type LearningProgressStoragePort,
  type LearningProgressStorageReadRequest,
  type LearningProgressStorageWriteRequest,
} from "../../progression/persistence";

export interface BrowserStorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export type BrowserStorageResolver = () => BrowserStorageLike;

function aborted(): LearningProgressStorageError {
  return new LearningProgressStorageError("aborted", "Learning progress storage operation was aborted.");
}

function storageError(
  error: unknown,
  operation: "read" | "write",
): LearningProgressStorageError {
  if (error instanceof LearningProgressStorageError) return error;
  const name = typeof error === "object" && error !== null && "name" in error
    ? String((error as Readonly<{ name?: unknown }>).name)
    : "";
  if (name === "SecurityError") {
    return new LearningProgressStorageError(
      "security-error",
      "Browser storage access was denied.",
      { cause: error },
    );
  }
  if (name === "QuotaExceededError" || name === "NS_ERROR_DOM_QUOTA_REACHED") {
    return new LearningProgressStorageError(
      "quota-exceeded",
      "Browser storage quota was exceeded.",
      { cause: error },
    );
  }
  return new LearningProgressStorageError(
    operation === "read" ? "read-failed" : "write-failed",
    `Browser storage ${operation} failed.`,
    { cause: error },
  );
}

/** Abort-aware localStorage adapter with stable, UI-safe error codes. */
export class BrowserLearningProgressStorage implements LearningProgressStoragePort {
  readonly #resolveStorage: BrowserStorageResolver;

  constructor(resolveStorage: BrowserStorageResolver = () => {
    if (typeof globalThis.localStorage === "undefined") {
      throw new LearningProgressStorageError(
        "storage-unavailable",
        "Browser localStorage is unavailable.",
      );
    }
    return globalThis.localStorage;
  }) {
    this.#resolveStorage = resolveStorage;
  }

  read(
    request: LearningProgressStorageReadRequest,
    options: LearningProgressStorageOperationOptions,
  ): string | null {
    if (options.signal.aborted) throw aborted();
    try {
      const value = this.#resolveStorage().getItem(request.key);
      if (options.signal.aborted) throw aborted();
      return value;
    } catch (error: unknown) {
      throw storageError(error, "read");
    }
  }

  write(
    request: LearningProgressStorageWriteRequest,
    options: LearningProgressStorageOperationOptions,
  ): void {
    if (options.signal.aborted) throw aborted();
    try {
      this.#resolveStorage().setItem(request.key, request.value);
      if (options.signal.aborted) throw aborted();
    } catch (error: unknown) {
      throw storageError(error, "write");
    }
  }
}
