const STYLE_ATTRIBUTE = "data-learning-path-ui-styles";
const styleRegistry = new WeakMap<Document, { element: HTMLStyleElement; owners: number }>();

const LEARNING_PATH_UI_STYLES = `
[data-learning-path-root] .lp-ui-shell {
  position: absolute;
  z-index: 8;
  inset: 0;
  color: #27302a;
  pointer-events: none;
  font-family: Inter, ui-rounded, "SF Pro Rounded", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
}
[data-learning-path-root] .lp-ui-shell button { font: inherit; }
[data-learning-path-root] .lp-ui-shell__gate,
[data-learning-path-root] .lp-ui-shell__context-card,
[data-learning-path-root] .lp-ui-shell__celebration { position: absolute; inset: 0; pointer-events: none; }
[data-learning-path-root] .lp-ui-generation-gate {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: auto;
  background: rgb(250 252 250 / 78%);
  backdrop-filter: blur(14px) saturate(.9);
}
[data-learning-path-root] .lp-ui-generation-gate[hidden] { display: none; }
[data-learning-path-root] .lp-ui-generation-gate__panel {
  width: min(440px, calc(100% - 36px));
  box-sizing: border-box;
  padding: 34px;
  border: 1px solid rgb(27 70 42 / 10%);
  border-radius: 28px;
  background: rgb(255 255 255 / 94%);
  box-shadow: 0 24px 70px rgb(38 72 48 / 16%), inset 0 1px 0 #fff;
}
[data-learning-path-root] .lp-ui-generation-gate__title {
  margin: 0;
  color: #203628;
  font-size: clamp(26px, 4cqw, 34px);
  line-height: 1.15;
  letter-spacing: -.025em;
}
[data-learning-path-root] .lp-ui-generation-gate__description {
  margin: 12px 0 24px;
  color: #657169;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.65;
}
[data-learning-path-root] .lp-ui-generation-gate__actions { display: grid; gap: 14px; }
[data-learning-path-root] .lp-ui-generation-gate__button {
  width: 100%;
  min-height: 50px;
  border: 1px solid rgb(13 121 50 / 14%);
  border-radius: 999px;
  padding: 13px 24px;
  color: #fff;
  background: linear-gradient(180deg, #35d56c, #1caf4e);
  box-shadow: 0 7px 0 #128c3e, 0 18px 34px rgb(27 171 75 / 24%), inset 0 1px 0 rgb(255 255 255 / 35%);
  cursor: pointer;
  font-weight: 800;
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}
[data-learning-path-root] .lp-ui-generation-gate__button[data-tone="secondary"] {
  color: #176b36;
  background: #f2fff6;
  border-color: rgb(23 107 54 / 22%);
  box-shadow: 0 5px 0 #cbeed6, 0 12px 24px rgb(31 137 69 / 10%);
}
[data-learning-path-root] .lp-ui-generation-gate__button[data-tone="quiet"] {
  color: #56615a;
  background: #f1f3f1;
  border-color: rgb(65 76 68 / 12%);
  box-shadow: 0 5px 0 #d8ddda, 0 10px 20px rgb(45 59 50 / 8%);
}
[data-learning-path-root] .lp-ui-generation-gate__button:hover:not(:disabled) { transform: translateY(-2px); filter: saturate(1.06); }
[data-learning-path-root] .lp-ui-generation-gate__button:active:not(:disabled) { transform: translateY(4px); box-shadow: 0 2px 0 #128c3e; }
[data-learning-path-root] .lp-ui-generation-gate__button:focus-visible { outline: 3px solid #176b36; outline-offset: 4px; }
[data-learning-path-root] .lp-ui-generation-gate__button:disabled { cursor: wait; filter: grayscale(.16); opacity: .72; }
[data-learning-path-root] .lp-ui-generation-gate[data-phase="error"] .lp-ui-generation-gate__button { background: linear-gradient(180deg, #68716b, #505852); box-shadow: 0 7px 0 #3e4540; }
[data-learning-path-root] .lp-ui-generation-gate__error {
  margin: 20px 0 0;
  color: #8a3838;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.5;
  text-align: center;
}
@media (prefers-reduced-motion: reduce) {
  [data-learning-path-root] .lp-ui-generation-gate__button { transition: none; }
}
`;

export function acquireLearningPathUIStyles(document: Document): () => void {
  const existing = styleRegistry.get(document);
  if (existing) {
    existing.owners += 1;
    return () => releaseLearningPathUIStyles(document);
  }
  const element = document.createElement("style");
  element.setAttribute(STYLE_ATTRIBUTE, "");
  element.textContent = LEARNING_PATH_UI_STYLES;
  (document.head ?? document.documentElement).append(element);
  styleRegistry.set(document, { element, owners: 1 });
  return () => releaseLearningPathUIStyles(document);
}

function releaseLearningPathUIStyles(document: Document): void {
  const entry = styleRegistry.get(document);
  if (!entry) return;
  entry.owners -= 1;
  if (entry.owners > 0) return;
  entry.element.remove();
  styleRegistry.delete(document);
}

export function nowTimestamp(document: Document): number {
  return document.defaultView?.performance.now() ?? Date.now();
}

export function dispatchViewEvent<T>(
  target: EventTarget,
  document: Document,
  eventName: string,
  detail: T,
): CustomEvent<T> {
  const CustomEventConstructor = document.defaultView?.CustomEvent ?? CustomEvent;
  const event = new CustomEventConstructor<T>(eventName, {
    bubbles: true,
    cancelable: true,
    composed: true,
    detail,
  });
  target.dispatchEvent(event);
  return event;
}
